/* MDCU78 RoC — 78CQ (78C_GenSx_AC_rotate_C.pdf) + 78CK (Key_78C_Gen_Sx_AC78_RoC_MCQ_Gen_Sx.pdf) ; rid 681–774 (ข้อลำดับ n ในชุด = rid n+680) */
QB.push(
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":2,"page2":3,"orig":"Pre-Op/Post-Op 1","stem":"In which patient is a preoperative 12-lead ECG most appropriate before elective surgery?","gray":"Pre-Op EKG ทำในใครดีที่สุด — A. คนแก่ U/D HT B. อายุน้อย Healthy","opts":["Elderly patient with underlying hypertension","Young healthy patient","Healthy 25-year-old before excision of a skin lipoma","Healthy 30-year-old before inguinal hernia repair","Healthy 20-year-old before cataract surgery"],"ans":0,"key":"A คนแก่ U/D HT (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ถามว่า <b>ECG ก่อนผ่าตัด</b> มีประโยชน์ในผู้ป่วยกลุ่มใด — หลักคือการส่งตรวจก่อนผ่าตัดทำตาม <b>ข้อบ่งชี้</b> (อายุ โรคประจำตัว ชนิดและขนาดของการผ่าตัด) ไม่ได้ทำ routine ทุกคน","why":"ผู้สูงอายุที่มี <b>hypertension</b> มีโอกาสมีโรคหัวใจแฝง (LVH, ischemia, arrhythmia) และเป็นกลุ่มที่ ECG ช่วยเป็น baseline สำหรับเทียบหลังผ่าตัด — <b>NICE NG45</b>: พิจารณา ECG ใน ASA ≥2 ที่มีโรคหัวใจหลอดเลือด ไต หรือเบาหวาน ก่อนผ่าตัด intermediate ขึ้นไป และในอายุ &gt;65 ปีก่อนผ่าตัดใหญ่; <b>ESC/ESAIC 2022</b>: แนะนำ ECG ก่อนผ่าตัด intermediate หรือ high risk ในผู้ที่มี cardiovascular risk factor หรืออายุ ≥65 ปี; ส่วนผู้ป่วยอายุน้อยสุขภาพดีที่ผ่าตัดเล็ก ECG ไม่เปลี่ยนการดูแล","wrong":{"B":"คนอายุน้อยสุขภาพดีไม่มีอาการและไม่มี risk factor → ECG แทบไม่พบความผิดปกติที่เปลี่ยนการดูแล และอาจเจอ false positive ทำให้เลื่อนผ่าตัดโดยไม่จำเป็น; จะถูกถ้ามีอาการทางหัวใจ (เจ็บหน้าอก ใจสั่น หมดสติ) หรือตรวจพบ murmur","C":"Excision ของ lipoma ที่ผิวหนังเป็น <b>low-risk surgery</b> ภายใต้ local anesthesia ในคนอายุ 25 ปีที่แข็งแรง → ไม่ต้องตรวจเพิ่มเติมใด ๆ; จะถูกถ้าผู้ป่วยมีโรคหัวใจหรือประวัติชวนสงสัย","D":"Inguinal hernia repair ในคนอายุ 30 ปีที่แข็งแรง (ASA 1) → NICE ไม่แนะนำ ECG ก่อนผ่าตัดระดับ intermediate ใน ASA 1 ที่อายุน้อย; จะถูกถ้าเป็นผู้สูงอายุที่มีโรคหัวใจ ไต หรือเบาหวาน","E":"Cataract surgery เป็น <b>very low-risk</b> procedure — การศึกษาพบว่า routine preoperative testing ไม่ลด complication; คนอายุ 20 ปีที่แข็งแรงไม่ต้องตรวจ ECG; จะถูกถ้ามีอาการหรือโรคหัวใจที่ยังไม่ได้ประเมิน"},"trap":"คิดว่า \"ก่อนผ่าตัดทุกคนต้องทำ CBC, CXR, ECG\" — แนวทางปัจจุบันไม่ทำ routine; ส่งตรวจตามประวัติ ตรวจร่างกาย อายุ โรคร่วม และ surgical risk เท่านั้น","summary":["การส่งตรวจก่อนผ่าตัดยึด <b>history + physical examination</b> เป็นหลัก ไม่ทำ routine test ทุกคน (ไม่ลด complication เพิ่มค่าใช้จ่ายและการเลื่อนผ่าตัด)","ECG: พิจารณาเมื่อมีโรคหัวใจหลอดเลือด ไต เบาหวาน หรือ cardiovascular risk factor ร่วมกับการผ่าตัด intermediate ถึง high risk, หรืออายุ ≥65 ปี (ESC/ESAIC 2022), อายุ &gt;65 ปีก่อนผ่าตัดใหญ่ (NICE NG45)","ไม่ต้องทำ ECG ในผู้ป่วยไม่มีอาการ ไม่มี risk factor ที่ผ่าตัด low risk (ผ่าตัดผิวหนัง ตา เต้านมเล็กน้อย endoscopy)","ประเมิน cardiac risk ด้วย <b>RCRI</b>: high-risk surgery, ischemic heart disease, heart failure, cerebrovascular disease, insulin-treated DM, creatinine &gt;2 mg/dL","Functional capacity ≥4 METs (ขึ้นบันได 2 ชั้นได้) ไปผ่าตัดได้โดยไม่ต้อง stress test","CXR ไม่ทำ routine — ทำเมื่อมีอาการหรือโรคปอดหัวใจที่ไม่คงที่; CBC ทำเมื่อผ่าตัดใหญ่ที่คาดว่าเสียเลือดหรือสงสัย anemia","ดูข้อ 682, 683, 684 (perioperative care)"],"notes":"ไฟล์เฉลย บท Pre-Op/ Post-Op แถว 1: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับจดช้อยไว้แค่ 2 ตัว (A. คนแก่ U/D HT, B. อายุน้อย Healthy) — ช้อย C–E แต่งเพิ่ม; ต้นฉบับเขียน \"EKG\" (= ECG)","mnemonic":"","guide":"NICE NG45 Routine preoperative tests 2016; ESC/ESAIC Guidelines on cardiovascular assessment for non-cardiac surgery 2022","variants":["ชายอายุ 70 ปี เป็น DM และ CKD นัดผ่าตัด open colectomy — ควรส่ง ECG ก่อนผ่าตัดหรือไม่ → ควรส่ง (อายุมาก มีโรคร่วม ผ่าตัด high risk)","หญิงอายุ 22 ปี แข็งแรง จะตัด sebaceous cyst ที่หลังภายใต้ local anesthesia — ต้องตรวจอะไรก่อนผ่าตัด → ไม่ต้องส่งตรวจเพิ่ม ซักประวัติตรวจร่างกายพอ","ชายอายุ 45 ปี มีอาการเจ็บหน้าอกเวลาออกแรง 2 เดือน นัดผ่าตัด laparoscopic cholecystectomy — ต้องทำอะไรก่อน → ประเมินโรคหัวใจตามอาการ (ECG และส่งพบอายุรแพทย์) ก่อนผ่าตัด elective"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ C ความมั่นใจปานกลางถึงสูง — ตาม timeline และการตัดตัวเลือกอื่นด้วยข้อมูลในโจทย์ wound infection เหมาะสุด แม้แผลยังไม่แดงไม่มีหนอง (ต้องตีความว่าเป็นระยะแรกหรือ deep incisional SSI); ไฟล์เฉลยเองระบุว่าตอบตามที่ อ.ชัยสิทธิ์สอน","page":2,"page2":3,"orig":"Pre-Op/Post-Op 2","flag":"⚠ เล็กน้อย: แผลยังไม่แดงไม่มีหนอง — คีย์ตอบตามที่อาจารย์ชัยสิทธิ์สอน (day 5 = wound infection)","stem":"On postoperative day 5 after appendectomy, a patient whose Foley catheter was removed on day 2 is walking normally but has severe wound pain. The wound shows no pus and no redness. What is the most likely diagnosis?","gray":"Post-Op day 5 ของการผ่าไส้ติ่ง คนไข้ถอด foley day 2 เดินได้ปกติ แต่เจ็บแผลมาก แต่แผลไม่มีหนอง ไม่มีแดง ถามว่าเป็นไร — A. Pneumonia B. Thrombophlebitis C. Wound infection D. UTI","opts":["Pneumonia","Thrombophlebitis","Wound infection","Urinary tract infection","Atelectasis"],"ans":2,"key":"C Wound infection (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"โจทย์ให้ <b>เวลา (POD 5)</b> + ตัดสาเหตุอื่นทิ้งด้วยข้อมูล (ถอด Foley ตั้งแต่ day 2, เดินได้ปกติ, ไม่มีอาการทางเดินหายใจ) แล้วเหลืออาการเด่นคือ <b>ปวดแผลมาก</b> — ต้องใช้ timeline ภาวะแทรกซ้อนหลังผ่าตัด (5W) ตอบ","why":"Surgical site infection มักเกิด <b>POD 5–7</b> และอาการแรกที่พบบ่อยคือ <b>ปวดแผลมากผิดสัดส่วน</b> (ปวดมากขึ้นแทนที่จะดีขึ้น) ก่อนเห็นแดงหรือหนอง โดยเฉพาะ infection ระดับลึก (deep incisional) ที่อยู่ใต้ผิวหนังยังไม่โผล่ให้เห็น → ต้องตรวจแผล กดหา fluctuation และเปิดแผลบางส่วนเพื่อระบาย; appendectomy (โดยเฉพาะ complicated) เป็นแผล contaminated ถึง dirty ที่ SSI สูง; ไฟล์เฉลยเขียนว่าคำตอบนี้ <b>ตาม อ.ชัยสิทธิ์</b> (สอน day 5 = wound)","wrong":{"A":"Pneumonia หลังผ่าตัดเกิดได้ช่วง POD 3–5 แต่ต้องมีไข้ ไอ เสมหะ หายใจเร็ว และไม่ทำให้ <b>ปวดแผล</b>; โจทย์ไม่มีอาการทางเดินหายใจ; จะถูกถ้ามีไข้ ไอมีเสมหะ crepitation และ infiltrate ใน CXR","B":"Thrombophlebitis (ทั้ง superficial ที่ตำแหน่ง IV line หรือ DVT) มักพบ POD 7 ขึ้นไป ปวด บวม แดงที่แขนหรือขา ไม่ใช่ที่แผล และผู้ป่วยเดินได้ปกติ (ความเสี่ยงต่ำ); จะถูกถ้ามีเส้นเลือดดำแข็งแดงเป็นลำตามแนว IV line หรือขาบวมข้างเดียว","D":"UTI เกิดช่วง POD 3–5 แต่สัมพันธ์กับ Foley catheter — รายนี้ <b>ถอดสายตั้งแต่ day 2</b> และอาการคือปวดแผลไม่ใช่ปัสสาวะแสบขัดหรือปวดท้องน้อย; จะถูกถ้ายังคาสายอยู่หรือมี dysuria, frequency, pyuria","E":"Atelectasis เป็นสาเหตุไข้ช่วง POD 1–2 (wind) ไม่ทำให้ปวดแผล และผู้ป่วยเดินได้ปกติ (ambulation ช่วยป้องกัน); จะถูกถ้าไข้ต่ำ ๆ ในวันแรกหลังผ่าตัด หายใจตื้น เสียงหายใจลดที่ฐานปอด"},"trap":"คิดว่า wound infection ต้องเห็นแดงหรือหนองก่อน — ระยะแรกหรือ infection ที่ลึกอาจมีแค่ปวดแผลมาก (บางรายมี induration หรือ crepitus); และ <b>ปวดแผลรุนแรงผิดปกติเร็ว ๆ (ภายใน 24–48 ชม.)</b> ต้องคิดถึง necrotizing infection จาก Streptococcus group A หรือ Clostridium","summary":["ภาวะแทรกซ้อนหลังผ่าตัดตามเวลา (<b>5W</b>): Wind (atelectasis, pneumonia) POD 1–3, Water (UTI) POD 3–5, Wound (SSI) POD 5–7, Walking (DVT, thrombophlebitis) POD 7 ขึ้นไป, Wonder drugs (drug fever) เมื่อไรก็ได้","ไข้ภายใน 48 ชม. แรกส่วนใหญ่เป็น inflammatory response จากการผ่าตัด; ยกเว้นต้องคิดถึง necrotizing soft tissue infection, anastomotic leak ระยะแรก และ aspiration","SSI แบ่งตาม CDC NHSN: superficial incisional (ผิวหนังและ subcutaneous), deep incisional (fascia และกล้ามเนื้อ), organ/space (intra-abdominal abscess) — เกิดภายใน 30 วัน (90 วันถ้าใส่ implant ในบาง procedure)","อาการ SSI: ปวดแผลมากขึ้น บวม แดง ร้อน มีหนองหรือ discharge ขุ่น ไข้; ปวดผิดสัดส่วนอาจนำหน้าอาการเฉพาะที่","การรักษา superficial SSI หลัก = <b>เปิดแผลระบาย</b> + ทำแผล; ให้ antibiotic เมื่อมี cellulitis รอบแผลกว้าง หรือมี systemic sign","UTI หลังผ่าตัดสัมพันธ์กับระยะเวลาคาสาย — ถอด Foley เร็วที่สุด (ภายใน 24–48 ชม. ในผ่าตัดส่วนใหญ่)","ดูข้อ 681, 696, 697, 698 (perioperative care และ SSI)"],"notes":"ไฟล์เฉลย บท Pre-Op/ Post-Op แถว 2: <b>C</b> คำอธิบายเขียนว่า <b>\"ตามอจ ชัยสิทธิ์\"</b><br>ต้นฉบับจดช้อย 4 ตัว (A–D) — ช้อย E (Atelectasis) แต่งเพิ่ม; ช้อย D ต้นฉบับเขียน \"UTI\" เราเขียนเต็มว่า Urinary tract infection; โจทย์ต้นฉบับลงท้าย \"ถามว่าเป็นไร\"","mnemonic":"<b>5W</b> ตามวันหลังผ่าตัด: Wind 1–2 → Water 3–5 → <b>Wound 5–7</b> → Walking 7+ → Wonder drugs ทุกเมื่อ","guide":"Sabiston Textbook of Surgery 21st ed.; CDC NHSN Surgical Site Infection Event definitions 2024","variants":["หลังผ่าตัด laparotomy POD 1 ผู้ป่วยมีไข้ 38.0°C หายใจตื้น ฟังเสียงหายใจลดที่ฐานปอดขวา — สาเหตุน่าจะเป็นอะไร → atelectasis (ให้ incentive spirometry และ early ambulation)","หลังผ่าตัด POD 4 ผู้ป่วยยังคาสาย Foley มีไข้ ปัสสาวะขุ่น — น่าจะเป็นอะไร → catheter-associated UTI (ถอดหรือเปลี่ยนสาย ส่ง urine culture)","หลังผ่าตัด POD 6 แผลบวมแดงกดเจ็บ มีหนองซึม — ควรทำอะไรก่อน → เปิดแผลระบายหนองและทำแผล ส่ง culture"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"ไม่มีคีย์ — เราตอบ C (LMWH) ความมั่นใจสูงสำหรับ stem ที่เติม (Caprini 9, bleeding risk ต่ำ, ผ่าตัดมะเร็ง) และตรงกับคำอธิบายในไฟล์เฉลยที่ว่าผู้ที่เคยเป็น DVT ตอบ LMWH; ถ้าโจทย์จริงเป็นผู้ป่วยผ่าตัดทั่วไป VTE risk ต่ำถึงปานกลาง คำตอบจะเป็น IPC (A) หรือ ambulation (B) ตามที่ไฟล์เฉลยเขียน — จึงต้องเติมเคสให้เหลือคำตอบเดียว; สอดคล้องกับข้อสอบชุด 77A (high risk → LMWH) และชุด 76A, 76C (mechanical เมื่อเลือดออกง่ายหรือระหว่างผ่าตัด)","page":2,"page2":3,"orig":"Pre-Op/Post-Op 3","flag":"⚠ ไม่มีคำตอบในไฟล์เฉลย และต้นฉบับจดแค่หัวข้อ — เติมเคสใน stem (ผู้ป่วยเคยเป็น DVT + ผ่าตัดมะเร็งช่องท้อง + bleeding risk ต่ำ) ตามแนวคำอธิบายในไฟล์เฉลย","stem":"A 65-year-old man with a history of deep vein thrombosis 3 years ago is scheduled for elective open colectomy for colon cancer. His bleeding risk is low. What is the most appropriate DVT prophylaxis?","gray":"DVT prophylaxis — 1. Pneumatic intermittent compression 2. Aggressive ambulation 3. LMWH","opts":["Intermittent pneumatic compression alone","Early aggressive ambulation alone","Low-molecular-weight heparin","Aspirin alone","Prophylactic IVC filter"],"ans":2,"key":"ไม่มีเฉลยในไฟล์ (เฉลยโดย Claude) — ช่องคำตอบว่าง คำอธิบายเขียนว่าโจทย์ไม่ครบ ดู Caprini ตอบ A หรือ B แล้วแต่สถานการณ์ ถ้าเคยเป็น DVT ตอบ LMWH","interp":"ต้นฉบับจดแค่ \"DVT prophylaxis\" — การเลือกวิธีป้องกันขึ้นกับ <b>VTE risk (Caprini score)</b> และ <b>bleeding risk</b>; เราเติมเคสที่ VTE risk สูง (เคยเป็น DVT + มะเร็ง + ผ่าตัดใหญ่ + อายุ) และ bleeding risk ต่ำ ตามที่ไฟล์เฉลยบอกว่า \"ถ้าเคยเป็น DVT ตอบ LMWH\"","why":"Caprini ของผู้ป่วยรายนี้: อายุ 61–74 ปี (2) + major open surgery &gt;45 นาที (2) + malignancy (2) + history of VTE (3) = <b>9 → high risk</b> (≥5) → ACCP 2012 แนะนำ <b>pharmacologic prophylaxis (LMWH หรือ low-dose UFH) ร่วมกับ mechanical</b> (IPC หรือ elastic stocking) เมื่อ bleeding risk ไม่สูง; ผ่าตัดมะเร็งช่องท้องหรืออุ้งเชิงกรานให้ <b>extended-duration LMWH 4 สัปดาห์</b> หลังผ่าตัด; enoxaparin 40 mg SC วันละครั้ง เริ่ม 12 ชม. ก่อนหรือ 6–12 ชม. หลังผ่าตัด","wrong":{"A":"IPC alone เป็น mechanical prophylaxis ที่ใช้เมื่อ <b>bleeding risk สูง</b> หรือมีข้อห้ามยา anticoagulant, หรือใน Caprini 3–4 (moderate risk) ทดแทนยาได้; ในผู้ป่วย high risk ที่เลือดออกไม่ง่าย IPC อย่างเดียวไม่พอ ใช้เสริมยา; จะถูกถ้าโจทย์บอกว่ามีเลือดออกหรือเสี่ยงเลือดออกสูง (ไฟล์เฉลยเขียนว่าผู้ป่วยผ่าตัดทั่วไปตอบ A หรือ B แล้วแต่สถานการณ์)","B":"Early ambulation อย่างเดียวพอสำหรับ <b>very low risk</b> (Caprini 0) เช่นคนอายุน้อยผ่าตัดเล็กแบบ day surgery; ในผู้ป่วย high risk ต้องให้ยา; จะถูกถ้าเป็นผู้ป่วยอายุน้อยไม่มี risk factor ผ่าตัดเล็ก","D":"Aspirin มีที่ใช้ในการป้องกัน VTE หลังผ่าตัด orthopedic บางกรณี (hip, knee arthroplasty) แต่ไม่ใช่ยามาตรฐานใน general/abdominal surgery ที่ high risk; จะถูกถ้าเป็นหลังผ่าตัดเปลี่ยนข้อเข่าตามแนวทาง orthopedic","E":"IVC filter <b>ไม่ใช้เป็น primary prophylaxis</b> (ACCP แนะนำไม่ใช้) — ใช้เมื่อมี acute proximal DVT หรือ PE ที่ให้ anticoagulant ไม่ได้ หรือเกิดซ้ำแม้ให้ยาเต็มที่; จะถูกถ้าผู้ป่วยมี DVT ขณะนี้และห้ามให้ anticoagulant"},"trap":"เลือก IPC เพราะคิดว่าปลอดภัยกว่า — mechanical อย่างเดียวเหมาะกับ bleeding risk สูง; ประวัติ VTE ได้ 3 คะแนนทันที และมะเร็งช่องท้องต้องให้ LMWH ต่อหลังกลับบ้านนาน 4 สัปดาห์","summary":["ประเมิน VTE risk ด้วย <b>Caprini</b>: 1 คะแนน (อายุ 41–60, minor surgery, BMI &gt;25, varicose vein), 2 คะแนน (อายุ 61–74, major surgery &gt;45 นาที, laparoscopy &gt;45 นาที, malignancy, bed rest &gt;72 ชม.), 3 คะแนน (อายุ ≥75, history of VTE, family history, thrombophilia), 5 คะแนน (stroke, arthroplasty, hip/pelvis/leg fracture, spinal cord injury ภายใน 1 เดือน)","Very low (0) → early ambulation; Low (1–2) → mechanical (IPC); Moderate (3–4) → LMWH หรือ LDUH หรือ IPC; High (≥5) → LMWH หรือ LDUH + mechanical","Bleeding risk สูง → mechanical (IPC) ก่อน แล้วเริ่มยาเมื่อเลือดหยุดและความเสี่ยงลดลง","ผ่าตัดมะเร็งช่องท้องหรืออุ้งเชิงกราน high risk → <b>extended LMWH 4 สัปดาห์</b>","ยา: enoxaparin 40 mg SC วันละครั้ง, UFH 5,000 units SC ทุก 8–12 ชม. (เลือกใน CrCl &lt;30); ติดตาม platelet เฝ้าระวัง HIT","IVC filter ไม่ใช้ป้องกันแบบ primary; ใช้เมื่อมี VTE แล้วให้ anticoagulant ไม่ได้","ดูข้อ 681, 682, 684, 687 (perioperative care และ heparin)"],"notes":"ไฟล์เฉลย บท Pre-Op/ Post-Op แถว 3: <b>ช่องคำตอบว่าง</b> คำอธิบายเขียนว่า <b>\"โจทย์ไม่ครบ ถ้า DVT ในคนไข้ผ่าตัดต้องดูตาม caprini criteria ตอบ A/B แล้วแต่สถานการณ์, ถ้าเป็น DVT ในคนที่เคยเป็นตอบ LMWH\"</b><br>ต้นฉบับจดโจทย์แค่ \"DVT prophylaxis\" และช้อยเป็นเลข 1–3 (1. Pneumatic intermittent compression 2. Aggressive ambulation 3. LMWH) — เราเรียงเป็น A–C ตามลำดับเดิม แต่งเพิ่ม D (Aspirin alone) และ E (Prophylactic IVC filter) และเติมเคสใน stem ทั้งหมด (อายุ 65, ประวัติ DVT 3 ปีก่อน, open colectomy จากมะเร็งลำไส้ใหญ่, bleeding risk ต่ำ)","mnemonic":"<b>Caprini 3 คะแนน = 3 อย่างที่เป็นเรื่องเลือดแข็งตัวในตัวคนไข้เอง</b>: เคยเป็น VTE, ญาติเป็น VTE, thrombophilia (+ อายุ ≥75)","guide":"ACCP Antithrombotic Therapy and Prevention of Thrombosis 9th ed. 2012 (non-orthopedic surgical patients); ASCO VTE prophylaxis and treatment in cancer 2023","variants":["หญิงอายุ 35 ปี แข็งแรง ผ่าตัด laparoscopic cholecystectomy 40 นาที — DVT prophylaxis ที่เหมาะสม → early ambulation (Caprini ต่ำ)","ชายอายุ 70 ปี ผ่าตัด Whipple จากมะเร็งตับอ่อน ระหว่างผ่าตัดเสียเลือดมาก ยังมีเลือดซึมทาง drain — DVT prophylaxis ช่วงแรก → IPC ก่อน แล้วเริ่ม LMWH เมื่อเลือดหยุด","หญิงอายุ 60 ปี ผ่าตัด total abdominal hysterectomy จากมะเร็งรังไข่ ไม่มีเลือดออกผิดปกติ — ควรให้ LMWH นานเท่าไร → extended prophylaxis 4 สัปดาห์หลังผ่าตัด"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":2,"page2":3,"orig":"Pre-Op/Post-Op 4","stem":"A patient involved in a car accident received fluid resuscitation. A nasogastric tube and a Foley catheter were placed in the emergency department, and he has now been admitted to the ICU. His urine output over the last 3 hours was 50 mL, 0 mL and 0 mL. His BP has been 120/80 mmHg and HR 80/min throughout. What is the first, most appropriate management?","gray":"Patient has car accident. Was fluid resuscitated. Was put Ng and Foley from ER, now was admitted to ICU. Now Urine output @3,2,1 hr = 50ml 0ml 0 ml, BP 120/80 HR 80 bpm for 3 hours. what is the first most appropriate initial management — A. check foley catheter if it was blocked B. Observe for more 1 hour C. Increase fluid resus STAT","opts":["Check whether the Foley catheter is blocked","Observe for 1 more hour","Increase fluid resuscitation immediately","Give intravenous furosemide","Start low-dose dopamine infusion"],"ans":0,"key":"A check foley catheter if it was blocked (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ปัสสาวะลดจาก 50 mL เป็น <b>0 mL ทันที</b> สองชั่วโมงติด ขณะที่ BP และ HR ปกติคงที่ — ถามสิ่งที่ต้องทำ <b>อันดับแรก</b> ก่อนจะสรุปว่าเป็น oliguria จาก hypovolemia หรือไต","why":"Anuria ที่เกิดขึ้น <b>ทันที</b> (ไม่ได้ค่อย ๆ ลด) ในผู้ป่วยที่ hemodynamics ปกติ ให้คิดถึง <b>สาเหตุทางกล</b> ก่อนเสมอ — สายพับ สายหลุดตำแหน่ง ลิ่มเลือดหรือตะกอนอุด ถุงแขวนสูงกว่ากระเพาะปัสสาวะ → ตรวจแนวสาย <b>flush สาย</b> หรือเปลี่ยนสาย และทำ <b>bladder scan</b> หรือคลำ/เคาะ bladder; การแก้ทำได้เร็ว ไม่เสี่ยง และถ้าไม่ทำอาจให้ fluid เกินหรือให้ยาโดยไม่จำเป็น; ในผู้ป่วย trauma ถ้าสายไม่อุดต้องคิดต่อถึง urethral หรือ bladder injury, rhabdomyolysis และ abdominal compartment syndrome","wrong":{"B":"การรอดูอีก 1 ชั่วโมงเสียเวลาโดยไม่ได้หาสาเหตุ — 0 mL สองชั่วโมงติดต่อกันเป็นความผิดปกติที่ต้องประเมินทันที; จะถูกถ้าปัสสาวะลดลงเล็กน้อยแต่ยังออกอยู่ใกล้เป้าหมาย 0.5 mL/kg/hr และ hemodynamics ดี","C":"Fluid bolus เหมาะเมื่อมีหลักฐาน <b>hypovolemia</b> (HR เร็ว BP ต่ำ capillary refill ช้า lactate สูง ปัสสาวะค่อย ๆ ลด) — รายนี้ BP 120/80 HR 80 คงที่ ให้ fluid เพิ่มโดยไม่ตรวจสายก่อนเสี่ยง fluid overload; จะถูกถ้าสายไม่อุด bladder ว่าง และมี sign ของ hypoperfusion","D":"Furosemide ไม่รักษาหรือป้องกัน AKI และอาจทำให้ volume depletion แย่ลง; การบังคับให้ปัสสาวะออกไม่ได้แก้สาเหตุ; จะถูกถ้ามี fluid overload (pulmonary edema) ในผู้ป่วยที่ volume เกินชัดเจน","E":"Low-dose (\"renal-dose\") dopamine ไม่ป้องกันหรือรักษา AKI (KDIGO แนะนำไม่ใช้) และเพิ่ม arrhythmia; ไม่มีบริบทที่ถูก — vasopressor ใช้เมื่อ shock ที่ไม่ตอบสนองต่อ fluid"},"trap":"เห็น urine output 0 แล้วรีบให้ fluid หรือ furosemide ทันที — ปัสสาวะที่หายไปทันทีในขณะที่สัญญาณชีพปกติ ให้ <b>ตรวจสายก่อน</b> เสมอ (สิ่งที่ง่ายที่สุดและพบบ่อยที่สุด)","summary":["เป้าหมาย urine output ผู้ใหญ่ <b>0.5–1 mL/kg/hr</b> (เด็ก 1 mL/kg/hr, ทารก 2 mL/kg/hr)","Oliguria หลังผ่าตัดหรือ trauma: ขั้นแรกตรวจ <b>catheter</b> (พับ อุด หลุด) + bladder scan → แล้วประเมิน volume status (HR, BP, CRT, lactate, ดู fluid balance) → ถ้า hypovolemia ให้ fluid challenge 250–500 mL แล้วประเมินซ้ำ","แบ่งสาเหตุ: pre-renal (hypovolemia, ช็อก, abdominal compartment), renal (ATN, contrast, rhabdomyolysis, nephrotoxic drug), post-renal (สายอุด, urethral injury, ureteric injury)","KDIGO AKI: creatinine เพิ่ม ≥0.3 mg/dL ใน 48 ชม. หรือ ≥1.5 เท่าใน 7 วัน หรือ urine &lt;0.5 mL/kg/hr นาน ≥6 ชม.","Trauma: เลือดที่ meatus, scrotal hematoma, high-riding prostate → สงสัย urethral injury ห้ามใส่ Foley ก่อนทำ retrograde urethrogram; ปัสสาวะสีโคล่า → rhabdomyolysis เป้าหมาย urine 1–2 mL/kg/hr","Furosemide และ low-dose dopamine ไม่ป้องกันหรือรักษา AKI","ดูข้อ 690 (urine output เป้าหมาย), ข้อ 688 (fluid resuscitation ใน trauma)"],"notes":"ไฟล์เฉลย บท Pre-Op/ Post-Op แถว 4: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับเป็นภาษาอังกฤษ จดช้อย 3 ตัว (A–C) — ช้อย D, E แต่งเพิ่ม; ต้นฉบับเขียน urine output \"@3,2,1 hr = 50ml 0ml 0 ml\" (ชั่วโมงที่ 3, 2, 1 ก่อนหน้า) และ \"Ng\" (= NG tube); ในไฟล์โจทย์บทนี้มีแถวข้อ 5 ว่าง (ไม่ใช่ข้อ)","mnemonic":"<b>Urine หายทันที = ดูสายก่อน</b>; urine ค่อย ๆ ลด = ดู volume","guide":"ATLS Advanced Trauma Life Support 10th ed. 2018; KDIGO Clinical Practice Guideline for Acute Kidney Injury 2012","variants":["ผู้ป่วยหลังผ่าตัด laparotomy 6 ชม. ปัสสาวะค่อย ๆ ลดจาก 40 เป็น 15 mL/hr HR 115 BP 95/60 สายไม่อุด — ทำอะไรต่อ → fluid challenge แล้วประเมินซ้ำ","ผู้ป่วยรถชนมีเลือดออกที่รูเปิดท่อปัสสาวะและ scrotal hematoma — ก่อนใส่ Foley ต้องทำอะไร → retrograde urethrogram","ผู้ป่วยถูกตึกถล่มทับขานาน 6 ชม. ปัสสาวะสีโคล่า CK สูงมาก — เป้าหมาย urine output → 1–2 mL/kg/hr (ประมาณ 200–300 mL/hr) ด้วย crystalloid ปริมาณมาก"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"คีย์ตอบ A ซึ่งเป็นช้อยเดียวที่ผู้จดพิมพ์ไว้ (inflammation → hemostasis → proliferation → modeling) ลำดับนี้ผิดตามตำรา — น่าจะเป็นการพิมพ์สลับตอนจด recall; เราเชื่อว่าข้อสอบจริงตอบลำดับ hemostasis → inflammation → proliferation → remodeling ความมั่นใจสูงมาก จึงใส่ลำดับที่ถูกเป็นช้อย A และใช้ข้อความต้นฉบับเป็นช้อย B (คีย์ตามตัวอักษรของเรา = B)","page":2,"page2":3,"orig":"Hemostasis 1","flag":"⚠ ตอบต่างจากคีย์ตามตัวอักษร: ช้อยเดียวที่ผู้จดพิมพ์ (และคีย์ตอบ A) เรียง inflammation ก่อน hemostasis ซึ่งผิดลำดับ — น่าจะพิมพ์สลับ; เราตอบลำดับที่ถูก hemostasis → inflammation → proliferation → remodeling และใช้ข้อความต้นฉบับเป็นช้อย B","stem":"Which sequence correctly describes the phases of the wound healing response after injury?","gray":"ให้เรียง response ต่อแผล — A. Inflammation -&gt; Hemostasis -&gt; Proliferation -&gt; Modeling","opts":["Hemostasis, inflammation, proliferation, remodeling","Inflammation, hemostasis, proliferation, remodeling","Hemostasis, proliferation, inflammation, remodeling","Inflammation, proliferation, hemostasis, remodeling","Proliferation, hemostasis, inflammation, remodeling"],"ans":0,"key":"B Inflammation -&gt; Hemostasis -&gt; Proliferation -&gt; Modeling (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ถามลำดับ <b>phase ของ wound healing</b> — ต้องรู้ว่าอะไรเกิดก่อน (หยุดเลือดก่อนเสมอ) และแต่ละ phase กินเวลาเท่าไร มีเซลล์อะไรเด่น","why":"<b>1) Hemostasis</b> (นาทีแรก): vasoconstriction, platelet adhesion และ aggregation, coagulation cascade → fibrin clot ซึ่งเป็นโครงให้เซลล์เข้ามา และ platelet ปล่อย PDGF, TGF-β เรียกเซลล์ → <b>2) Inflammation</b> (วัน 1–4): neutrophil เด่นใน 24–48 ชม. ตามด้วย <b>macrophage 48–96 ชม.</b> (เซลล์สำคัญที่สุด ขาดไม่ได้ ควบคุม phase ต่อไป) → <b>3) Proliferation</b> (วัน 4–21): fibroblast สร้าง collagen type III, angiogenesis, granulation tissue, epithelialization, wound contraction โดย myofibroblast → <b>4) Remodeling/maturation</b> (วัน 21 ถึง 1 ปี): collagen type III ถูกแทนด้วย type I, cross-linking, tensile strength สูงสุดราว <b>80%</b> ของผิวหนังเดิม","wrong":{"B":"เรียง inflammation ก่อน hemostasis — ผิดเพราะการบาดเจ็บทำให้เลือดออก ร่างกายต้องหยุดเลือดก่อน และ platelet ใน clot เป็นตัวปล่อย cytokine ที่เรียก inflammatory cell เข้ามา; นี่คือช้อยที่ผู้จดพิมพ์และคีย์ตอบ (น่าจะพิมพ์สลับ); ไม่มีบริบทที่ลำดับนี้ถูก","C":"เอา proliferation มาก่อน inflammation — ผิดเพราะ fibroblast และ angiogenesis ต้องอาศัย growth factor จาก macrophage ใน inflammatory phase; ไม่มีบริบทที่ลำดับนี้ถูก","D":"เริ่มที่ inflammation และเอา hemostasis ไว้หลัง proliferation — ผิดทั้งสองจุด; ไม่มีบริบทที่ลำดับนี้ถูก","E":"เริ่มที่ proliferation — ผิดเพราะต้องมี fibrin matrix จาก hemostasis และ cytokine จาก inflammation ก่อนเซลล์จะ proliferate; ไม่มีบริบทที่ลำดับนี้ถูก"},"trap":"ช้อยที่ผู้จดพิมพ์ขึ้นต้นด้วย inflammation — ระวังจำผิดตาม; บางตำราแบ่ง 3 phase (inflammatory ที่รวม hemostasis, proliferative, maturation) แต่ถ้าแยก hemostasis ออกมา ต้องมาก่อน inflammation เสมอ","summary":["4 phase: <b>Hemostasis → Inflammation → Proliferation → Remodeling</b> (overlap กันได้)","Hemostasis: vasoconstriction, platelet plug, fibrin clot; platelet ปล่อย PDGF, TGF-β","Inflammation วัน 1–4: neutrophil 24–48 ชม. (ฆ่าเชื้อ เก็บกวาด), <b>macrophage 48–96 ชม. = เซลล์ที่ขาดไม่ได้</b>; lymphocyte ตามมา","Proliferation วัน 4–21: fibroblast + collagen type III, angiogenesis (VEGF), granulation tissue, epithelialization, contraction โดย myofibroblast","Remodeling วัน 21 ถึง 1 ปี: collagen III → I, cross-linking; tensile strength ราว 20% ที่ 3 สัปดาห์ และสูงสุดราว 80% ไม่กลับเท่าเดิม","ปัจจัยที่ทำให้แผลหายช้า: infection, ischemia, เบาหวาน, steroid (ขัด inflammation แก้ด้วย vitamin A), malnutrition (protein, vitamin C, zinc), สูบบุหรี่, radiation","ดูข้อ 694, 695 (การเลือกไหมเย็บ)"],"notes":"ไฟล์เฉลย บท Hemostasis แถว 1: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับจดช้อยไว้ <b>ตัวเดียว</b> \"A. Inflammation -&gt; Hemostasis -&gt; Proliferation -&gt; Modeling\" (ผู้จดพิมพ์ inflammation ก่อน hemostasis และเขียน \"Modeling\" = remodeling) — ช้อยนี้คือช้อย B ของเรา; ช้อย A (ลำดับที่ถูก) และ C–E แต่งเพิ่ม","mnemonic":"<b>\"Hi Pro Rem\" ก่อนต้อง \"Hemo\"</b>: Hemostasis → Inflammation → Proliferation → Remodeling (เลือดหยุด → อักเสบ → สร้าง → ปรับ)","guide":"Sabiston Textbook of Surgery 21st ed.; Schwartz's Principles of Surgery 11th ed.","variants":["เซลล์ใดสำคัญที่สุดและขาดไม่ได้ในกระบวนการหายของแผล → macrophage","แผลผ่าตัดหน้าท้องหลังเย็บ 3 สัปดาห์ มี tensile strength ราวกี่เปอร์เซ็นต์ของเดิม → ประมาณ 20% (สูงสุดราว 80% หลังหลายเดือน)","ผู้ป่วยกิน prednisolone ระยะยาว แผลหายช้า — วิตามินใดช่วยแก้ฤทธิ์ steroid ต่อการหายของแผล → vitamin A"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":3,"page2":3,"orig":"Hemostasis 2","stem":"Warfarin reduces the activity of which coagulation factor?","gray":"ให้ Warfarin โดน Factor อะไร — A. Factor 1 B. Factor 5 C. Factor 9 D. Factor 11","opts":["Factor I","Factor V","Factor IX","Factor XI","Factor VIII"],"ans":2,"key":"C Factor 9 (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ถามกลไกของ <b>warfarin</b> — ยาออกฤทธิ์ต่อ factor ที่ต้องอาศัย vitamin K (II, VII, IX, X) ให้หาตัวที่อยู่ในกลุ่มนี้","why":"Warfarin เป็น <b>vitamin K antagonist</b> ยับยั้ง vitamin K epoxide reductase (<b>VKORC1</b>) → ไม่มี reduced vitamin K สำหรับ γ-carboxylation ของ glutamate บน <b>factor II, VII, IX, X</b> และ protein C, S → factor ที่สร้างออกมาจับ Ca²⁺ และ phospholipid ไม่ได้ ทำงานไม่ได้; ในช้อยมีแค่ <b>factor IX</b> ที่อยู่ในกลุ่มนี้; factor VII half-life สั้นสุด (~6 ชม.) จึงทำให้ PT/INR ยืดก่อน แต่ฤทธิ์ต้านการแข็งตัวเต็มที่ต้องรอ prothrombin (half-life ~60 ชม.) ลด ใช้เวลา 5 วัน","wrong":{"A":"Factor I (fibrinogen) สร้างที่ตับแต่ <b>ไม่ต้องอาศัย vitamin K</b>; ลดลงใน DIC, massive transfusion, ตับวายรุนแรง หรือยา fibrinolytic; จะถูกถ้าถามเรื่อง cryoprecipitate หรือ fibrinogen concentrate","B":"Factor V ไม่ต้องอาศัย vitamin K (เป็น labile factor ลดในเลือดที่เก็บนาน); factor V Leiden คือการกลายพันธุ์ที่ต้าน activated protein C ทำให้เลือดแข็งง่าย; จะถูกถ้าถามสาเหตุ inherited thrombophilia ที่พบบ่อยในคนผิวขาว","D":"Factor XI อยู่ใน intrinsic pathway ไม่ต้องอาศัย vitamin K; ขาดแล้วเป็น hemophilia C (aPTT ยืด); จะถูกถ้าถามโรคเลือดออกง่ายที่ aPTT ยืดและพบบ่อยใน Ashkenazi Jew","E":"Factor VIII สร้างจาก endothelium (sinusoidal) ไม่ต้องอาศัย vitamin K; ขาดแล้วเป็น hemophilia A; จะถูกถ้าถามสาเหตุ aPTT ยืดในเด็กชายที่มี hemarthrosis"},"trap":"จำว่า warfarin ทำให้ PT ยืดแล้วไปเลือก factor ของ extrinsic pathway อย่างเดียว — vitamin K-dependent factor ได้แก่ <b>2, 7, 9, 10</b> (มี IX ของ intrinsic ด้วย) + protein C, S; ช่วงแรกที่เริ่มยา protein C ลดก่อน → hypercoagulable จึงต้อง bridge ด้วย heparin","summary":["Vitamin K-dependent: <b>factor II, VII, IX, X + protein C, S</b>; warfarin ยับยั้ง VKORC1","ติดตามด้วย <b>PT/INR</b> (เป้า 2–3 สำหรับ AF, VTE; 2.5–3.5 สำหรับ mechanical mitral valve บางชนิด)","เริ่มยา: protein C half-life สั้น ลดก่อน → hypercoagulable ช่วงแรก (warfarin skin necrosis ใน protein C deficiency) → bridge ด้วย heparin อย่างน้อย 5 วันจน INR อยู่ในเป้า 24 ชม.","ก่อนผ่าตัด elective: หยุด warfarin 5 วัน ตรวจ INR ก่อนผ่าตัด; bridging เฉพาะ thrombotic risk สูง","Reversal เลือดออกรุนแรงหรือผ่าตัดฉุกเฉิน: <b>vitamin K 5–10 mg IV + 4-factor PCC</b> (FFP ถ้าไม่มี PCC); INR สูงไม่มีเลือดออก → หยุดยา ± vitamin K กิน","ยาเสริมฤทธิ์ warfarin: metronidazole, fluconazole, amiodarone, cotrimoxazole; ยาลดฤทธิ์: rifampicin, carbamazepine","ดูข้อ 687, 689 (การแปลผล coagulation test)"],"notes":"ไฟล์เฉลย บท Hemostasis แถว 2: <b>C</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับจดช้อย 4 ตัวเป็นเลขอารบิก (Factor 1, 5, 9, 11) — เราเขียนเป็นเลขโรมัน; ช้อย E (Factor VIII) แต่งเพิ่ม","mnemonic":"<b>1972</b> (เลข 10, 9, 7, 2) = factor ที่ต้องใช้ vitamin K; PT ยืดจาก warfarin = <b>\"WEPT\"</b> (Warfarin, Extrinsic, PT)","guide":"ACCP Antithrombotic Therapy 9th ed. 2012; ACC Expert Consensus Decision Pathway on Management of Bleeding in Patients on Oral Anticoagulants 2020","variants":["ผู้ป่วย AF กิน warfarin INR 8 มี GI bleeding และช็อก — การแก้ฤทธิ์ยาที่เร็วที่สุด → vitamin K IV + 4-factor PCC","ผู้ป่วยเริ่ม warfarin โดยไม่ได้ bridge วันที่ 3 มีผิวหนังเป็น purpura และเนื้อตายที่เต้านมและต้นขา — กลไกคืออะไร → protein C ลดก่อน factor อื่นทำให้ hypercoagulable (warfarin skin necrosis)","ผู้ป่วยกิน warfarin นัดผ่าตัด hernia elective — ควรหยุดยาก่อนกี่วัน → 5 วัน ตรวจ INR ก่อนผ่าตัด"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":3,"page2":3,"orig":"Hemostasis 3","stem":"A patient is started on a continuous intravenous unfractionated heparin infusion. Which test is used to monitor its effect?","gray":"Heparin monitor — A. aPTT B. PT","opts":["aPTT","PT","Bleeding time","Platelet count","D-dimer"],"ans":0,"key":"A aPTT (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ถามการติดตามฤทธิ์ <b>unfractionated heparin</b> แบบหยดต่อเนื่อง — ต้องรู้ว่า heparin กระทบ pathway ไหนและการทดสอบไหนวัด pathway นั้น","why":"UFH จับ <b>antithrombin</b> เร่งฤทธิ์ยับยั้ง <b>thrombin (IIa)</b> และ <b>factor Xa</b> (รวมถึง IXa, XIa, XIIa) ซึ่งอยู่ใน intrinsic และ common pathway → วัดด้วย <b>aPTT</b> เป้าหมาย <b>1.5–2.5 เท่า</b> ของค่าควบคุม (หรือ anti-Xa 0.3–0.7 IU/mL); ตรวจ aPTT ทุก 6 ชม. หลังเริ่มหรือปรับขนาดยาจนคงที่; UFH half-life สั้น (60–90 นาที) แก้ด้วย <b>protamine sulfate</b> 1 mg ต่อ heparin 100 units","wrong":{"B":"PT/INR ใช้ติดตาม <b>warfarin</b> (extrinsic pathway, factor VII); heparin ขนาดรักษาอาจยืด PT เล็กน้อยแต่ไม่ใช้ติดตาม; จะถูกถ้าโจทย์ถามการติดตาม warfarin","C":"Bleeding time วัด <b>platelet function</b> และผนังหลอดเลือด ไม่ไวต่อ heparin; จะถูกถ้าถามการประเมิน uremic platelet dysfunction หรือ von Willebrand disease (ปัจจุบันใช้ PFA-100 แทน)","D":"Platelet count ใช้เฝ้าระวัง <b>heparin-induced thrombocytopenia</b> (platelet ลด &gt;50% วันที่ 5–10) ไม่ได้วัดฤทธิ์ต้านการแข็งตัว; จะถูกถ้าถามสิ่งที่ต้องตรวจเป็นระยะเพื่อดู adverse effect ของ heparin","E":"D-dimer เป็น fibrin degradation product ใช้ <b>rule out VTE</b> เมื่อ pretest probability ต่ำ หรือประกอบการวินิจฉัย DIC ไม่ใช้ปรับขนาดยา; จะถูกถ้าถามการตรวจคัดกรอง DVT ใน Wells score ต่ำ"},"trap":"สับสน <b>heparin = aPTT</b> กับ <b>warfarin = PT</b>; และ LMWH ไม่ต้องติดตาม routine (ถ้าจำเป็นใช้ anti-Xa ไม่ใช่ aPTT) ในไตวาย อ้วนมาก ตั้งครรภ์ เด็ก","summary":["UFH: antithrombin-mediated ยับยั้ง IIa = Xa → ติดตาม <b>aPTT 1.5–2.5 เท่า</b> หรือ anti-Xa 0.3–0.7 IU/mL","UFH ขนาดรักษา: bolus 80 units/kg แล้ว 18 units/kg/hr ปรับตาม nomogram; ข้อดีคือ half-life สั้น แก้ฤทธิ์ได้หมดด้วย protamine เหมาะกับไตวายและผู้ป่วยที่อาจต้องผ่าตัด","LMWH (enoxaparin): ยับยั้ง Xa มากกว่า IIa ไม่ต้องติดตาม routine; anti-Xa ในไตวาย อ้วน ตั้งครรภ์; protamine แก้ได้บางส่วน","Warfarin → PT/INR; Dabigatran → แก้ด้วย idarucizumab; rivaroxaban, apixaban → andexanet alfa หรือ 4F-PCC","HIT: platelet ลด &gt;50% วัน 5–10 พร้อม thrombosis → หยุด heparin ทุกชนิด ให้ non-heparin anticoagulant (argatroban, fondaparinux) ห้ามให้ platelet transfusion","ดูข้อ 686, 689 (coagulation test), ข้อ 683 (DVT prophylaxis)"],"notes":"ไฟล์เฉลย บท Hemostasis แถว 3: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับจดโจทย์แค่ \"Heparin monitor\" และช้อย 2 ตัว (A. aPTT B. PT) — ช้อย C–E แต่งเพิ่ม, stem ขยายเป็นประโยคเต็มโดยไม่เปลี่ยนสิ่งที่ถาม; ในไฟล์โจทย์เลขข้อเขียนว่า \"3\" (ไม่มีจุด)","mnemonic":"<b>\"HIP\" vs \"WEPT\"</b>: Heparin = Intrinsic = PTT; Warfarin = Extrinsic = PT","guide":"ACCP Antithrombotic Therapy 9th ed. 2012","variants":["ผู้ป่วย PE ได้ UFH infusion aPTT 4 เท่าของค่าควบคุม มีเลือดออกจากแผล — ยาแก้ฤทธิ์คืออะไร → protamine sulfate","ผู้ป่วยได้ UFH วันที่ 7 platelet ลดจาก 250,000 เป็น 90,000 และเกิด DVT ใหม่ — ทำอะไร → หยุด heparin ทั้งหมด ให้ argatroban หรือ fondaparinux ส่ง anti-PF4 antibody","หญิงตั้งครรภ์ได้ enoxaparin ขนาดรักษา ต้องการติดตามระดับยา — ตรวจอะไร → anti-Xa level"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A ความมั่นใจปานกลางถึงสูง — ต้นฉบับไม่ได้บอกความรุนแรงของการเสียเลือด; ถ้าข้อสอบจริงให้ข้อมูลว่าเป็น class III–IV หรือให้ crystalloid ไปแล้วไม่ตอบสนอง คำตอบควรเป็นการให้เลือด (ช้อย C) จึงเติมใน stem ว่าเลือดยังเตรียมไม่เสร็จ; สอดคล้องกับข้อสอบชุด 77C (LRS ระหว่างรอเลือด) และชุด 76D (RL 3 L แล้วยังช็อก → PRC + FFP)","page":3,"page2":3,"orig":"Hemostasis 4","flag":"⚠ เล็กน้อย: เติม \"while blood products are being prepared\" ใน stem — ถ้าโจทย์บอก class III–IV hemorrhage หรือไม่ตอบสนองต่อ crystalloid ต้องให้เลือด (ช้อย C)","stem":"After a car accident, a patient arrives hypotensive. While blood products are being prepared, which fluid should be given first for resuscitation?","gray":"car accident, hypotension resuscitation fluid ? — A. ringer acetate B. Dextrose C. Prc + nss","opts":["Ringer's acetate","5% dextrose in water","Packed red cells with normal saline","Hydroxyethyl starch","0.45% NaCl"],"ans":0,"key":"A ringer acetate (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ผู้ป่วย trauma ที่ hypotension ถามสารน้ำที่ให้ <b>ก่อน</b> ในช่วงที่ยังไม่มีเลือด — ต้องเลือก <b>isotonic crystalloid</b> ที่อยู่ใน intravascular space ได้ดี (ข้อมูล \"ระหว่างรอเลือด\" เราเติมให้เหลือคำตอบเดียว)","why":"ATLS 10th ed.: initial fluid ใน hemorrhagic shock = <b>warmed isotonic crystalloid 1 L</b> ในผู้ใหญ่ (เด็ก 20 mL/kg) ผ่าน large-bore IV 2 เส้น แล้วประเมิน response (rapid, transient, non-responder); balanced crystalloid อย่าง <b>Ringer's acetate หรือ lactated Ringer's</b> มี Cl ใกล้ plasma ลด hyperchloremic metabolic acidosis เมื่อเทียบ NSS ปริมาณมาก; ถ้าเป็น transient หรือ non-responder หรือ class III–IV → ให้เลือดเร็ว (O-negative ระหว่างรอ crossmatch) ตาม massive transfusion protocol และ <b>หลีกเลี่ยง crystalloid ปริมาณมาก</b>","wrong":{"B":"D5W เป็น <b>free water</b> เมื่อ glucose ถูก metabolize แล้ว กระจายทั่ว total body water เหลือใน intravascular แค่ราว 1/12 ไม่ช่วยเพิ่ม volume และทำให้ hyperglycemia, hyponatremia, สมองบวมในผู้ป่วย head injury; จะถูกถ้าโจทย์ถามสารน้ำสำหรับแก้ hypernatremia หรือ maintenance ร่วมกับ electrolyte","C":"PRC + NSS คือการให้เลือด — ถูกต้องเมื่อมี <b>class III–IV hemorrhage</b> หรือไม่ตอบสนองต่อ crystalloid 1 L และต้องให้ร่วมกับ plasma และ platelet (1:1:1) ไม่ใช่ PRC อย่างเดียว; เราเติม stem ว่าเลือดยังเตรียมไม่เสร็จจึงไม่ใช่คำตอบ; จะถูกถ้าโจทย์บอกว่าให้ crystalloid แล้วยังช็อกหรือเลือดพร้อมแล้ว","D":"Hydroxyethyl starch เพิ่ม <b>AKI, ความต้องการ renal replacement และ coagulopathy</b> ไม่ลดการเสียชีวิต — ไม่แนะนำใน trauma และ sepsis; ไม่มีบริบทที่ถูกในปัจจุบัน","E":"0.45% NaCl เป็น <b>hypotonic</b> อยู่ใน intravascular น้อย เพิ่มสมองบวม; ใช้เป็น maintenance fluid ร่วมกับ dextrose; จะถูกถ้าถามสารน้ำ maintenance หรือแก้ hypernatremia บางกรณี"},"trap":"คิดว่าให้ crystalloid ไปเรื่อย ๆ จน BP ปกติ — ใน hemorrhagic shock ให้ crystalloid แค่ 1 L แล้วประเมิน ถ้าไม่ตอบสนองต้องให้เลือดและหยุดเลือด (crystalloid มากเกิน → dilutional coagulopathy, hypothermia, acidosis = lethal triad)","summary":["Hemorrhagic shock class: I &lt;15% (HR ปกติ), II 15–30% (HR เร็ว pulse pressure แคบ), III 31–40% (BP ลด สับสน urine ลด), IV &gt;40% (BP ต่ำมาก ซึม ไม่มีปัสสาวะ)","เริ่ม: 2 large-bore IV + warmed isotonic crystalloid <b>1 L</b> (เด็ก 20 mL/kg) แล้วดู response","Rapid responder → ติดตาม; transient responder → ให้เลือด หาแหล่งเลือดออก; non-responder → เลือด + หยุดเลือดทันที (OR, angioembolization)","Massive transfusion: PRC : FFP : platelet = <b>1:1:1</b>, ให้ <b>tranexamic acid ภายใน 3 ชม.</b> (1 g ใน 10 นาที แล้ว 1 g ใน 8 ชม.), แก้ hypothermia, calcium","Permissive hypotension (SBP ~80–90 mmHg) จนกว่าจะหยุดเลือดได้ ยกเว้น traumatic brain injury (ต้องการ SBP ≥100–110)","หลีกเลี่ยง D5W, hypotonic fluid และ starch ใน trauma resuscitation","ดูข้อ 773 (เลือดฉุกเฉินเมื่อไม่ทราบหมู่เลือด), ข้อ 684 (urine output หลัง resuscitation)"],"notes":"ไฟล์เฉลย บท Hemostasis แถว 4: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับจดโจทย์สั้น ๆ ลงท้ายด้วย \"?\" (\"car accident, hypotension resuscitation fluid ?\") และช้อย 3 ตัว (A. ringer acetate B. Dextrose C. Prc + nss) — เราเติมใน stem ว่า \"ระหว่างรอเตรียมเลือด\" และแต่งช้อย D, E; ช้อย B ต้นฉบับเขียนแค่ \"Dextrose\" เราเขียนเป็น 5% dextrose in water","mnemonic":"<b>1 L แล้วดูผล</b> — ไม่ดีขึ้นให้ <b>1:1:1 + TXA</b> ภายใน 3 ชม.","guide":"ATLS Advanced Trauma Life Support 10th ed. 2018","variants":["ผู้ป่วยรถชน BP 80/50 HR 130 ได้ LRS 1 L แล้ว BP ขึ้นเป็น 100/60 สักพักลดลงเป็น 80/50 อีก — ทำอะไรต่อ → transient responder ให้เลือด (MTP 1:1:1) และหาแหล่งเลือดออกเพื่อหยุดเลือด","ผู้ป่วย trauma ที่ต้องได้เลือดปริมาณมาก ยาใดที่ควรให้ภายใน 3 ชั่วโมงหลังบาดเจ็บ → tranexamic acid","ผู้ป่วย trauma มี head injury รุนแรงร่วมกับเลือดออกในช่องท้อง — เป้าหมาย BP ระหว่าง resuscitation → ไม่ทำ permissive hypotension รักษา SBP ≥100–110 mmHg"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":3,"page2":3,"orig":"Hemostasis 5","stem":"A patient with end-stage renal disease has normal aPTT and PT, a prolonged bleeding time and a normal platelet count. What is the most likely cause?","gray":"คนไข้ esrd normal aptt pt, prolonged bleeding time, platelet normal ถามว่าเป็นรัย — A. Uremic platelet function B. Thrombocytopenia","opts":["Uremic platelet dysfunction","Thrombocytopenia","Hemophilia A","Vitamin K deficiency","Disseminated intravascular coagulation"],"ans":0,"key":"A Uremic platelet function (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"แปลผล coagulation profile: <b>PT, aPTT ปกติ</b> (coagulation factor ปกติ), <b>platelet count ปกติ</b>, แต่ <b>bleeding time ยืด</b> → ปัญหาอยู่ที่ <b>การทำงานของ platelet</b> ในผู้ป่วย ESRD","why":"Uremia: uremic toxin (guanidinosuccinic acid, phenolic acid) และ nitric oxide ที่เพิ่มขึ้น ทำให้ <b>platelet adhesion และ aggregation บกพร่อง</b> (การทำงานของ GP IIb/IIIa และการจับ vWF ลด) ร่วมกับ anemia (RBC น้อยทำให้ platelet ไม่ถูกดันไปชิดผนังหลอดเลือด) → bleeding time ยืดแม้จำนวน platelet ปกติ; รักษาเมื่อมีเลือดออกหรือก่อนหัตถการ: <b>dialysis</b>, <b>desmopressin (DDAVP) 0.3 µg/kg IV</b> (ออกฤทธิ์ภายใน ~1 ชม. นาน 4–8 ชม. เพิ่ม vWF, factor VIII จาก endothelium; ให้ซ้ำแล้ว tachyphylaxis), cryoprecipitate, conjugated estrogen (ออกฤทธิ์ช้าแต่นาน), แก้ anemia ให้ Hct ราว 30% (EPO หรือ PRC)","wrong":{"B":"Thrombocytopenia ทำให้ bleeding time ยืดได้แต่ต้องมี <b>platelet count ต่ำ</b> — โจทย์บอก platelet ปกติ; จะถูกถ้า platelet &lt;100,000 และมักมีเลือดออกเมื่อ &lt;50,000","C":"Hemophilia A (factor VIII deficiency) ทำให้ <b>aPTT ยืด</b> PT และ bleeding time ปกติ อาการเลือดออกในข้อและกล้ามเนื้อ; จะถูกถ้าเด็กชายมี hemarthrosis และ aPTT ยืดแก้ได้ด้วย mixing study","D":"Vitamin K deficiency ทำให้ <b>PT ยืดก่อน</b> (factor VII half-life สั้น) และ aPTT ยืดเมื่อรุนแรง bleeding time ปกติ; จะถูกถ้าผู้ป่วยกินไม่ได้นาน ได้ antibiotic, obstructive jaundice หรือ malabsorption","E":"DIC ทำให้ <b>ทุกค่าผิดปกติ</b>: PT, aPTT ยืด, platelet ต่ำ, fibrinogen ต่ำ, D-dimer สูง; จะถูกถ้ามี sepsis หรือ trauma รุนแรงร่วมกับเลือดออกหลายตำแหน่ง"},"trap":"เห็น ESRD แล้วนึกถึง heparin ที่ได้ระหว่าง hemodialysis (aPTT จะยืด) — โจทย์บอก aPTT ปกติ; ESRD ที่มี bleeding time ยืดแต่ platelet ปกติ = <b>qualitative platelet defect</b>","summary":["แปลผล: PT ยืดอย่างเดียว → extrinsic (factor VII, warfarin, vitamin K deficiency, ตับ); aPTT ยืดอย่างเดียว → intrinsic (VIII, IX, XI, XII, heparin, lupus anticoagulant); ทั้งคู่ยืด → common pathway, DIC, ตับวายรุนแรง","Bleeding time ยืด + platelet ปกติ + PT/aPTT ปกติ → <b>platelet dysfunction</b>: uremia, aspirin, clopidogrel, von Willebrand disease (aPTT อาจยืด), Glanzmann, Bernard-Soulier","Uremic bleeding รักษา: dialysis, <b>DDAVP 0.3 µg/kg</b>, cryoprecipitate, conjugated estrogen, แก้ anemia (Hct ~30%)","ก่อนผ่าตัดในผู้ป่วย ESRD: dialysis ภายใน 24 ชม. ก่อนผ่าตัด (แก้ K, volume, uremia) และระวังการให้ heparin ระหว่าง dialysis","Aspirin ยับยั้ง COX-1 แบบถาวร ฤทธิ์อยู่ตลอดอายุ platelet 7–10 วัน; หยุด 7 วันก่อนผ่าตัดที่เสี่ยงเลือดออกสูง","ดูข้อ 686, 687 (coagulation test และยา anticoagulant)"],"notes":"ไฟล์เฉลย บท Hemostasis แถว 5: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับลงท้ายโจทย์ว่า \"ถามว่าเป็นรัย\" (ภาษาพูด) และจดช้อย 2 ตัว (A. Uremic platelet function B. Thrombocytopenia) — เราเขียนช้อย A เป็น Uremic platelet dysfunction และแต่งช้อย C–E","mnemonic":"<b>\"DDAVP + Dialysis + Cryo + Estrogen + EPO\"</b> = 5 ทางรักษา uremic bleeding","guide":"Schwartz's Principles of Surgery 11th ed.","variants":["ผู้ป่วย ESRD จะทำ tunneled catheter แต่ bleeding time ยืด platelet ปกติ — ยาที่ออกฤทธิ์เร็วที่สุดเพื่อลดเลือดออก → desmopressin 0.3 µg/kg IV","ผู้ป่วยมี obstructive jaundice นาน 1 เดือน PT ยืด aPTT ปกติ — สาเหตุและการแก้ → vitamin K deficiency ให้ vitamin K parenteral","ชายอายุ 20 ปี เลือดออกนานหลังถอนฟัน aPTT ยืด PT ปกติ bleeding time ยืด platelet ปกติ — นึกถึงโรคใด → von Willebrand disease"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A ความมั่นใจสูง — สอดคล้องกับข้อสอบชุด 77C เรื่องเดียวกัน (60 kg → 30–60 mL/hr) และชุด 76A (50 kg → 30–50 mL/hr)","page":3,"page2":3,"orig":"Fluid and Electrolyte 1","stem":"What is the target urine output for a 60-kg adult patient?","gray":"คนไข้หนัก 60 kg, urine output เท่าไหร่ดี — A. 30-60 cc/hr B. 5-10 cc/kg/hr C. 5-10 cc/hr","opts":["30–60 mL/hr","5–10 mL/kg/hr","5–10 mL/hr","100–150 mL/hr","200–300 mL/hr"],"ans":0,"key":"A 30-60 cc/hr (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ถามเป้าหมาย <b>urine output ของผู้ใหญ่</b> คิดจากน้ำหนัก — สูตร 0.5–1 mL/kg/hr","why":"ผู้ใหญ่เป้าหมาย <b>0.5–1 mL/kg/hr</b> → 60 kg × 0.5–1 = <b>30–60 mL/hr</b> ซึ่งสะท้อนว่า renal perfusion และ end-organ perfusion เพียงพอ ใช้เป็นตัวชี้วัด resuscitation ที่สำคัญร่วมกับ HR, BP, mental status, capillary refill และ lactate; ต่ำกว่า 0.5 mL/kg/hr นาน ≥6 ชม. เข้าเกณฑ์ <b>KDIGO AKI stage 1</b>","wrong":{"B":"5–10 mL/kg/hr = 300–600 mL/hr ใน 60 kg สูงเกินจริงมาก (เป็น polyuria) — พบใน diabetes insipidus, osmotic diuresis หรือระยะ diuretic ของ ATN; ไม่มีบริบทที่เป็นเป้าหมาย","C":"5–10 mL/hr ต่ำกว่าเกณฑ์มาก = <b>oliguria</b> (&lt;0.5 mL/kg/hr) ต้องประเมินหาสาเหตุทันที; จะถูกถ้าถามค่าที่เข้าเกณฑ์ oliguria หรือ AKI","D":"100–150 mL/hr ราว 1.7–2.5 mL/kg/hr สูงกว่าเป้าหมายมาตรฐาน — เป็นเป้าหมายใน <b>rhabdomyolysis</b> หรือ electrical burn ที่มี myoglobinuria (ผู้ใหญ่ราว 75–100 mL/hr ขึ้นไป); จะถูกถ้าโจทย์เป็นผู้ป่วยถูกไฟฟ้าแรงสูงหรือ crush injury","E":"200–300 mL/hr = 3–5 mL/kg/hr สูงเกิน แสดงถึงการให้สารน้ำมากเกินหรือ polyuria; เป้าหมายใน crush syndrome บางแนวทาง (ปัสสาวะ ~200–300 mL/hr ระยะแรก) แต่ไม่ใช่เป้าหมายผู้ป่วยทั่วไป; จะถูกถ้าโจทย์เป็น crush syndrome ที่ต้องการ forced diuresis"},"trap":"จำหน่วยสลับ (mL/kg/hr กับ mL/hr) — <b>ผู้ใหญ่ 0.5 mL/kg/hr</b>, เด็ก 1 mL/kg/hr, ทารก 1–2 mL/kg/hr; ต้องคูณน้ำหนักก่อนเทียบช้อย","summary":["Urine output เป้าหมาย: ผู้ใหญ่ <b>0.5–1 mL/kg/hr</b> (ประมาณ 30–50 mL/hr ในคน 60–70 kg), เด็ก 1 mL/kg/hr, ทารก &lt;1 ปี 1–2 mL/kg/hr","Burn ผู้ใหญ่: 0.5 mL/kg/hr (30–50 mL/hr); เด็ก ≤30 kg 1 mL/kg/hr; electrical burn หรือ myoglobinuria: 1 mL/kg/hr (75–100 mL/hr) จนปัสสาวะใส","KDIGO AKI ตาม urine: stage 1 &lt;0.5 mL/kg/hr 6–12 ชม., stage 2 &lt;0.5 ≥12 ชม., stage 3 &lt;0.3 ≥24 ชม. หรือ anuria ≥12 ชม.","Maintenance fluid ผู้ใหญ่ราว 25–30 mL/kg/วัน หรือสูตร 4-2-1 (100 mL/hr ใน 60 kg)","Urine output ลดทันที → ตรวจสาย Foley ก่อน; ลดค่อยเป็นค่อยไป → ประเมิน volume","ดูข้อ 684 (oliguria ใน ICU), ข้อ 691, 692, 693 (fluid และ electrolyte)"],"notes":"ไฟล์เฉลย บท Fluid and Electrolyte แถว 1: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับใช้หน่วย cc (= mL) และจดช้อย 3 ตัว (A. 30-60 cc/hr B. 5-10 cc/kg/hr C. 5-10 cc/hr) — ช้อย D, E แต่งเพิ่ม","mnemonic":"<b>\"ผู้ใหญ่ครึ่ง เด็กหนึ่ง ทารกสอง\"</b> (mL/kg/hr)","guide":"KDIGO Clinical Practice Guideline for Acute Kidney Injury 2012; ATLS Advanced Trauma Life Support 10th ed. 2018","variants":["ผู้ป่วยหนัก 80 kg ถูกไฟไหม้ 40% TBSA — เป้าหมาย urine output ระหว่าง resuscitation → 0.5 mL/kg/hr คือ 40 mL/hr (ช่วง 30–50)","เด็กหนัก 20 kg หลังผ่าตัด ปัสสาวะ 10 mL/hr — เพียงพอหรือไม่ → ไม่พอ (เป้าหมาย 1 mL/kg/hr = 20 mL/hr)","ผู้ป่วย 70 kg ถูกไฟฟ้าแรงสูง ปัสสาวะสีแดงเข้ม — เป้าหมาย urine output → ราว 1 mL/kg/hr (75–100 mL/hr) จนปัสสาวะใส"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ D ความมั่นใจสูง — สอดคล้องกับข้อสอบชุด 77A และ 77D เรื่อง vomiting → metabolic alkalosis","page":3,"page2":3,"orig":"Fluid and Electrolyte 2","stem":"In which condition is metabolic alkalosis LEAST likely to be found?","gray":"Which is LEAST likely to find metabolic alkalosis — A. vomiting B. Diuretics C. HypoK D. Hemorrhagic shock E. Volume depletion","opts":["Vomiting","Diuretic use","Hypokalemia","Hemorrhagic shock","Volume depletion"],"ans":3,"key":"D Hemorrhagic shock (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"คำถามปฏิเสธ (<b>LEAST likely</b>) — หาภาวะที่ทำให้เกิด acid-base แบบอื่น ไม่ใช่ metabolic alkalosis","why":"Hemorrhagic shock → tissue hypoperfusion → anaerobic metabolism → <b>lactic acidosis (high anion gap metabolic acidosis)</b> ซึ่งเป็นตัวบ่งชี้ความรุนแรงของช็อก (lactate, base deficit) ใช้ติดตาม resuscitation; ช้อยอื่นทั้งหมดเป็นสาเหตุหรือตัวคงสภาพของ metabolic alkalosis","wrong":{"A":"Vomiting หรือ NG suction เสีย <b>HCl</b> → hypochloremic hypokalemic metabolic alkalosis; volume depletion กระตุ้น aldosterone ไตดูด Na แลก K และ H⁺ → <b>paradoxical aciduria</b>; เป็นสาเหตุคลาสสิก (gastric outlet obstruction, pyloric stenosis)","B":"Loop และ thiazide diuretics → เสีย NaCl และน้ำ (<b>contraction alkalosis</b>), เพิ่ม aldosterone, เสีย K และ H⁺ ทางปัสสาวะ → metabolic alkalosis; จะไม่ใช่ถ้าเป็น acetazolamide หรือ spironolactone (ทำให้ acidosis)","C":"Hypokalemia → K ออกจากเซลล์แลก H⁺ เข้าเซลล์, ไตเพิ่ม H⁺ secretion และ HCO₃⁻ reabsorption และสร้าง ammonium มากขึ้น → <b>คงสภาพ metabolic alkalosis</b>; ต้องแก้ K ร่วมด้วยจึงหาย","E":"Volume depletion (chloride depletion) → ไตดูด Na และ HCO₃⁻ กลับมากขึ้น เพิ่ม aldosterone → <b>contraction alkalosis</b> และคงสภาพ alkalosis; แก้ด้วย 0.9% NaCl (chloride-responsive)"},"trap":"เห็น \"volume depletion\" กับ \"hemorrhagic shock\" แล้วคิดว่าเหมือนกัน — volume depletion แบบเสียน้ำและ Cl (ไม่ช็อก) → alkalosis แต่ hemorrhagic shock ที่ perfusion ไม่พอ → <b>lactic acidosis</b>; หลังได้เลือดปริมาณมาก citrate ถูกเปลี่ยนเป็น HCO₃⁻ จึงเกิด metabolic alkalosis ภายหลังได้","summary":["Metabolic alkalosis แบ่งตาม urine Cl: <b>chloride-responsive</b> (urine Cl &lt;20: vomiting, NG suction, diuretic ที่หยุดแล้ว, contraction) → ให้ 0.9% NaCl + KCl; <b>chloride-resistant</b> (urine Cl &gt;20: hyperaldosteronism, Cushing, Bartter, Gitelman, diuretic ที่ยังใช้อยู่)","Vomiting หรือ gastric outlet obstruction: <b>hypochloremic hypokalemic metabolic alkalosis + paradoxical aciduria</b>","ปัจจัยคงสภาพ alkalosis: volume depletion, Cl depletion, hypokalemia, aldosterone สูง","Shock ทุกชนิดที่ hypoperfusion → lactic acidosis (HAGMA); lactate &gt;2 mmol/L ผิดปกติ, &gt;4 รุนแรง; base deficit ใช้แบ่งระดับช็อก","หลัง massive transfusion: citrate → HCO₃⁻ เกิด metabolic alkalosis ได้ และ citrate จับ Ca → hypocalcemia","ดูข้อ 690, 692, 693 (fluid และ electrolyte), ข้อ 688 (hemorrhagic shock)"],"notes":"ไฟล์เฉลย บท Fluid and Electrolyte แถว 2: <b>D</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับจดครบ 5 ช้อย เป็นภาษาอังกฤษ; ช้อย C ต้นฉบับเขียน \"HypoK\" (= hypokalemia), ช้อย B \"Diuretics\" เราเขียนเป็น Diuretic use","mnemonic":"<b>\"อาเจียน ขับปัสสาวะ K ต่ำ ขาดน้ำ = ด่าง; ช็อก = กรด (lactate)\"</b>","guide":"Schwartz's Principles of Surgery 11th ed.","variants":["ชายอายุ 60 ปี มี gastric outlet obstruction อาเจียนมา 1 สัปดาห์ — คาดว่าจะพบ acid-base แบบใด → hypochloremic hypokalemic metabolic alkalosis ร่วมกับ paradoxical aciduria","ผู้ป่วย trauma ช็อกนาน 2 ชั่วโมงก่อนถึงโรงพยาบาล — blood gas คาดว่าจะพบอะไร → high anion gap metabolic acidosis จาก lactate","ผู้ป่วย metabolic alkalosis จาก NG suction ควรให้สารน้ำใด → 0.9% NaCl ร่วมกับ KCl"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":4,"page2":3,"orig":"Fluid and Electrolyte 3","stem":"Which of the following is NOT a third-space fluid loss?","gray":"Which one is not 3rd space loss — A. Ascites B. Pleural effusion C. Peripheral edema D. Oozing burn E. Fluid leak in small bowel","opts":["Ascites","Pleural effusion","Peripheral edema","Oozing from a burn wound","Fluid leak into the small bowel"],"ans":3,"key":"D Oozing burn (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"คำถามปฏิเสธ — แยก <b>third-space loss</b> (สารน้ำยังอยู่ในร่างกายแต่ไม่อยู่ใน functional ECF) ออกจาก <b>external loss</b> (สารน้ำออกนอกร่างกาย)","why":"Third space = ECF ที่ย้ายออกจาก intravascular และ functional interstitial ไปอยู่ในช่องที่ไม่แลกเปลี่ยนกับ circulation (interstitial edema, ช่องท้อง, ช่องอก, lumen และผนังลำไส้ใน obstruction หรือ ileus, retroperitoneum ใน pancreatitis, tissue edema ใน burn หรือ crush) — สารน้ำ <b>ยังอยู่ในร่างกาย</b> และกลับคืนสู่ circulation ระยะ mobilization (ราววันที่ 3–5 หลังผ่าตัดทำให้ปัสสาวะออกมาก); ส่วน <b>สารน้ำที่ซึมออกจากผิวแผลไหม้</b> (exudate และ evaporative loss) ออกนอกร่างกายแล้ว = <b>external loss</b> ไม่ใช่ third space","wrong":{"A":"Ascites คือสารน้ำสะสมในช่องท้อง (peritonitis, ตับแข็ง, หลังผ่าตัดใหญ่) ยังอยู่ในร่างกายแต่ไม่ได้อยู่ใน functional ECF = <b>third space</b>","B":"Pleural effusion สารน้ำสะสมในช่องเยื่อหุ้มปอด = <b>third space</b> (เป็นช่องที่ไม่มีส่วนร่วมใน circulation)","C":"Peripheral edema = สารน้ำรั่วเข้า interstitial space มากเกินจาก capillary leak (sepsis, burn, ผ่าตัดใหญ่) หรือ oncotic pressure ต่ำ = <b>third space</b>","E":"Fluid ที่รั่วเข้าใน lumen และผนังของลำไส้ใน bowel obstruction หรือ ileus = <b>third space</b> คลาสสิก (ลำไส้ที่อุดตันสะสมน้ำได้หลายลิตร) แม้จะอยู่ใน lumen แต่ยังไม่ออกนอกร่างกาย; จะเป็น external loss เมื่ออาเจียนหรือดูดออกทาง NG"},"trap":"Burn เกี่ยวข้องทั้งสองแบบ — <b>edema ในเนื้อเยื่อที่ไหม้ = third space</b> แต่ <b>น้ำที่ซึมหรือระเหยออกจากผิวแผล = external loss</b>; โจทย์ถาม \"oozing\" จึงเป็น external","summary":["Body water: TBW ราว 60% ของน้ำหนักชาย (หญิง 50%) = ICF 2/3 (40%) + ECF 1/3 (20%) แบ่งเป็น interstitial 15% และ plasma 5%","Third space: สารน้ำอยู่ในร่างกายแต่ไม่ functional — interstitial edema, ascites, pleural effusion, bowel obstruction, ileus, pancreatitis, peritonitis, crush และ burn tissue edema, ผ่าตัดใหญ่","External loss: vomiting, NG suction, diarrhea, fistula, stoma, เลือดออก, evaporation จากแผลไหม้และการหายใจ, เหงื่อ","Third space ทำให้ intravascular volume ลดได้ แม้น้ำหนักตัวไม่ลด → ต้องทดแทนด้วย isotonic crystalloid (LRS)","Mobilization ของ third-space fluid ราววันที่ 3–5 หลังผ่าตัด → ปัสสาวะออกมาก ต้องลด IV fluid ไม่เช่นนั้นเกิด fluid overload โดยเฉพาะผู้ป่วยโรคหัวใจหรือไต","ดูข้อ 690, 691, 693 (fluid และ electrolyte)"],"notes":"ไฟล์เฉลย บท Fluid and Electrolyte แถว 3: <b>D</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับจดครบ 5 ช้อยเป็นภาษาอังกฤษ; ช้อย D ต้นฉบับเขียน \"Oozing burn\" เราเขียนเป็น Oozing from a burn wound, ช้อย E \"Fluid leak in small bowel\" เขียนเป็น Fluid leak into the small bowel","mnemonic":"<b>\"ยังอยู่ในตัว = third space; ออกนอกตัว = external\"</b>","guide":"Schwartz's Principles of Surgery 11th ed.","variants":["ผู้ป่วย small bowel obstruction อาเจียนไม่มาก แต่ HR เร็ว ปัสสาวะออกน้อย — สารน้ำไปอยู่ที่ใด → third space ในผนังและ lumen ของลำไส้ ทดแทนด้วย isotonic crystalloid","ผู้ป่วยหลังผ่าตัด Whipple วันที่ 4 ปัสสาวะออกมากขึ้นเองโดยไม่ได้ให้ยาขับปัสสาวะ — อธิบายอย่างไร → mobilization ของ third-space fluid ควรลด IV fluid","ผู้ป่วย severe acute pancreatitis ต้องการสารน้ำมากในวันแรก — สาเหตุหลักของการเสียสารน้ำ → third space ใน retroperitoneum และ capillary leak"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A ความมั่นใจสูง — ตรงกับข้อสอบชุด 77D เรื่องเดียวกัน (แก้ Na เร็วเกิน → CPM)","page":4,"page2":3,"orig":"Fluid and Electrolyte 4","stem":"A patient with chronic hyponatremia receives sodium correction that is too rapid. Which complication may occur?","gray":"ให้ Na ไวเกินไป เกิดอะไรขึ้น — A. Cerebral Pontine myelinolysis","opts":["Central pontine myelinolysis","Cerebral edema","Acute kidney injury","Generalized muscle weakness","Hyperkalemia"],"ans":0,"key":"A Cerebral Pontine myelinolysis (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ถามภาวะแทรกซ้อนจากการ <b>แก้ hyponatremia เร็วเกินไป</b> — ทิศทางการแก้ (Na ขึ้นเร็ว) เป็นตัวตัดสิน","why":"ใน <b>chronic hyponatremia (&gt;48 ชม.)</b> เซลล์สมองปรับตัวโดยขับ osmolyte (glutamate, myo-inositol, taurine) ออกเพื่อลดบวม — ถ้าเพิ่ม serum Na เร็ว extracellular osmolality ขึ้นเร็วกว่าที่เซลล์จะสร้าง osmolyte กลับ น้ำจึงออกจากเซลล์ → oligodendrocyte เสียหาย → <b>osmotic demyelination syndrome</b> (central pontine และ extrapontine myelinolysis); อาการล่าช้า <b>2–6 วัน</b> หลังแก้: dysarthria, dysphagia, quadriparesis, behavioral change, locked-in syndrome; เสี่ยงสูงใน Na ≤105, alcoholism, malnutrition, hypokalemia, liver disease","wrong":{"B":"Cerebral edema เกิดจากการ <b>ลด Na เร็วเกิน</b> (แก้ hypernatremia เร็วด้วยน้ำ) หรือ acute hyponatremia ที่ไม่ได้รักษา — ทิศทางตรงข้ามกับโจทย์; จะถูกถ้าโจทย์ถามผลของการให้ D5W เร็วในผู้ป่วย hypernatremia เรื้อรัง","C":"AKI ไม่ใช่ผลของการแก้ Na เร็ว; จะถูกถ้าโจทย์เป็น rhabdomyolysis, hypovolemia หรือ nephrotoxic drug","D":"Weakness ทั่วไปเป็นอาการของ electrolyte ผิดปกติหลายชนิด (hypokalemia, hypophosphatemia, hypermagnesemia) ไม่จำเพาะ — ODS ทำให้ quadriparesis จาก pons แต่ช้อยนี้ไม่ได้ระบุกลไก; จะถูกถ้าโจทย์ถามอาการของ hypokalemia","E":"Hyperkalemia ไม่สัมพันธ์กับการแก้ Na; จะถูกถ้าโจทย์เป็น AKI, rhabdomyolysis, succinylcholine ใน burn หรือ massive transfusion"},"trap":"สับสนทิศทาง — <b>\"Low to high, pons will die; high to low, brains will blow\"</b>; ต้นฉบับเขียน \"Cerebral\" pontine myelinolysis แต่ชื่อจริงคือ <b>Central</b> pontine myelinolysis","summary":["Hyponatremia อาการรุนแรง (ชัก ซึม) → 3% NaCl 100–150 mL IV ใน 10–20 นาที ซ้ำได้ เป้าเพิ่ม Na 4–6 mEq/L ใน 1–2 ชม. แรกเพื่อหยุดอาการ","เพดานการแก้: European 2014 ≤10 mmol/L ใน 24 ชม.แรก และ ≤8 ในแต่ละ 24 ชม.ต่อมา; US 2013 เพดาน 10–12 mEq/L ต่อ 24 ชม. (กลุ่มเสี่ยงสูง ≤8)","กลุ่มเสี่ยง ODS: chronic &gt;48 ชม., Na ≤105, alcoholism, malnutrition, hypokalemia, liver disease","ODS อาการล่าช้า 2–6 วัน: dysarthria, dysphagia, quadriparesis, locked-in; MRI พบ T2 hyperintensity ที่ pons","ถ้าแก้เกินเพดาน → re-lower ด้วย D5W ± desmopressin","Hypernatremia: แก้ช้า ≤10–12 mEq/L ต่อวัน ถ้าลดเร็วเกินในรายเรื้อรัง → cerebral edema","ดูข้อ 690, 691, 692 (fluid และ electrolyte)"],"notes":"ไฟล์เฉลย บท Fluid and Electrolyte แถว 4: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับจดช้อยไว้ <b>ตัวเดียว</b> \"A. Cerebral Pontine myelinolysis\" — ชื่อที่ถูกคือ <b>Central</b> pontine myelinolysis (ปัจจุบันเรียก osmotic demyelination syndrome); ช้อย B–E แต่งเพิ่ม; stem เติมคำว่า chronic hyponatremia เพื่อให้เป็นประโยคเต็ม; ในไฟล์โจทย์บทนี้มีแถวข้อ 5 ว่าง (ไม่ใช่ข้อ)","mnemonic":"<b>\"From low to high, the pons will die; from high to low, the brains will blow\"</b>","guide":"European Clinical Practice Guideline on diagnosis and treatment of hyponatraemia 2014; US Expert Panel Recommendations on hyponatremia 2013","variants":["หญิงอายุ 70 ปี Na 112 จาก thiazide มา 1 สัปดาห์ ไม่มีอาการรุนแรง — ใน 24 ชม.แรกควรเพิ่ม Na ไม่เกินเท่าไร → ราว 8 mEq/L (กลุ่มเสี่ยงสูง)","ผู้ป่วยติดสุรา Na 108 ได้ 3% NaCl Na ขึ้นเป็น 125 ใน 24 ชม. 4 วันต่อมาพูดไม่ชัด กลืนลำบาก แขนขาอ่อนแรง — วินิจฉัยอะไร → osmotic demyelination syndrome","ผู้ป่วยแก้ Na เกินเพดานภายใน 12 ชม. — ควรทำอะไร → re-lower ด้วย D5W ร่วมกับ desmopressin"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ D ความมั่นใจปานกลาง — ต้นฉบับถามกว้าง ๆ ว่าเย็บ tendon ใช้ไหมอะไร ซึ่ง polyester (E) ก็เป็นไหม core suture ที่ใช้มากในทางปฏิบัติ จึงเติม stem ให้ถามเฉพาะ epitendinous suture ที่ต้องเป็น monofilament ลื่น (nylon) ให้เหลือคำตอบเดียวตามคีย์; ถ้าข้อสอบจริงถาม core suture จะตอบได้ทั้ง D และ E","page":4,"page2":3,"orig":"Plastic surgery 1","flag":"⚠ ต้นฉบับถามแค่ \"เย็บ tendon\" — core suture มาตรฐานใช้ได้ทั้ง braided polyester (Ethibond) และ nylon (polyamide) → เติมใน stem ว่าเป็น running epitendinous suture (ใช้ monofilament nylon 6-0 หรือ polypropylene) ให้เหลือคำตอบเดียว; ถ้าถาม core suture ช้อย E ก็ถูก","stem":"During flexor tendon repair in the hand, the surgeon places a fine running epitendinous suture after the core suture. Which suture material is most appropriate for it?","gray":"เย็บ tendon — A. Silk B. catgut C. Polyglactin D. Polyamide E. Polyester","opts":["Silk","Catgut","Polyglactin","Polyamide","Polyester"],"ans":3,"key":"D Polyamide (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ถามไหมสำหรับเย็บ <b>เอ็น</b> — tendon หายช้าและต้องทนแรงดึงและ glide ได้ ต้องเลือกไหม <b>non-absorbable</b> แรงดึงสูง reactivity ต่ำ; เราเติมว่าเป็น <b>epitendinous suture</b> เพื่อให้เหลือคำตอบเดียวระหว่าง nylon กับ polyester","why":"Tendon หายช้า (strength กลับราว <b>12 สัปดาห์</b>) ต้องใช้ไหม <b>non-absorbable synthetic</b> ที่คงแรงดึงนาน เนื้อเยื่อตอบสนองน้อย; <b>Polyamide (nylon) monofilament</b> ผิวเรียบ ลื่น ไม่ทำให้ tendon ติดกับ sheath — ใช้เป็น <b>running epitendinous suture ขนาด 6-0</b> (ร่วมกับ polypropylene) ซึ่งช่วยเพิ่มแรงต้านการแยกของรอยเย็บและทำให้ผิวเอ็นเรียบ glide ได้; nylon แบบ looped ยังใช้เป็น core suture ได้ด้วย","wrong":{"A":"Silk เป็น natural protein (braided) <b>tissue reaction สูง</b> แรงดึงลดลงตามเวลา (ถือเป็น non-absorbable แต่ค่อย ๆ ถูกย่อยในเวลาหลายปี) มีช่องให้แบคทีเรียอยู่; จะถูกถ้าถามไหมผูกหลอดเลือดหรือยึด drain ที่ผิวหนัง","B":"Catgut (plain หรือ chromic) เป็น natural absorbable ถูกย่อยด้วย proteolysis เร็ว (plain 7–10 วัน) reaction สูง — ไม่พอสำหรับ tendon ที่ต้องการแรงดึงหลายสัปดาห์; จะถูกถ้าถามไหมเย็บ mucosa หรือเนื้อเยื่อที่หายเร็ว","C":"Polyglactin 910 (Vicryl) เป็น synthetic absorbable แบบ braided คงแรงดึงราว 50–75% ที่ 2 สัปดาห์และถูกดูดซึมหมด 56–70 วัน — เสียแรงดึงก่อน tendon หาย; จะถูกถ้าถามไหมเย็บ subcutaneous หรือ bowel anastomosis","E":"Polyester braided (Ethibond) แรงดึงสูงมาก ใช้เป็น <b>core suture</b> (3-0 หรือ 4-0) ได้ดี — แต่ braided มี friction สูงกว่า ไม่เหมาะเป็น epitendinous suture ที่ต้องการผิวลื่น; จะถูกถ้าโจทย์ถามไหม core suture ของ flexor tendon repair"},"trap":"เลือก absorbable เพราะคิดว่าเย็บข้างในร่างกายต้องละลายได้ — tendon ต้องใช้ <b>non-absorbable</b> เสมอ; และจำว่า epitendinous = monofilament เล็ก (6-0 nylon หรือ prolene) ส่วน core = braided polyester หรือ looped nylon","summary":["Tendon repair ใช้ไหม <b>non-absorbable synthetic</b>: core suture (polyester braided 3-0 หรือ 4-0, looped nylon) + <b>epitendinous running suture 6-0 nylon หรือ polypropylene</b>","Repair strength ขึ้นกับจำนวน strand ที่ข้ามรอยต่อ (4–6 strand) มากกว่าชนิดไหมอย่างเดียว; epitendinous suture เพิ่มแรงต้านการแยกและ glide","หลังผ่าตัด flexor tendon ต้องทำ early protected mobilization ลด adhesion; strength กลับราว 12 สัปดาห์","Absorbable: catgut (plain 7–10 วัน, chromic 10–14 วัน), polyglactin (Vicryl), polyglecaprone (Monocryl), PDS (คงแรงดึงนานสุดในกลุ่ม absorbable)","Non-absorbable: silk (reaction สูง), nylon (polyamide), polypropylene (Prolene: reaction ต่ำสุด ใช้หลอดเลือด, hernia), polyester (Ethibond), steel","ดูข้อ 695 (ไหมเย็บผิวหนัง), ข้อ 685 (wound healing)"],"notes":"ไฟล์เฉลย บท Plastic surgery แถว 1: <b>D</b> (ช่องคำอธิบายว่าง)<br>ในไฟล์โจทย์หัวบทพิมพ์ <b>สีแดง</b> ว่า <b>\"Plastic surgery (kuy) isus\"</b> (ผู้จดเขียนเอง); ต้นฉบับจดโจทย์แค่ \"เย็บ tendon\" ครบ 5 ช้อย — เราเติมใน stem ว่าเป็น flexor tendon repair และถามไหมสำหรับ running epitendinous suture หลังเย็บ core suture แล้ว; ช้อย B ต้นฉบับเขียน \"catgut\" ตัวพิมพ์เล็ก","mnemonic":"<b>\"Core = แข็ง (Ethibond), Epi = ลื่น (nylon 6-0)\"</b>","guide":"Green's Operative Hand Surgery 8th ed. 2022; Sabiston Textbook of Surgery 21st ed.","variants":["ผู้ป่วยถูกมีดบาด flexor digitorum profundus ขาดที่ zone II — ไหมที่ใช้เย็บ core suture → non-absorbable braided polyester 3-0 หรือ 4-0 (หรือ looped nylon) แบบ multistrand","หลังเย็บ flexor tendon ควรทำอะไรเพื่อลด adhesion → early protected mobilization ภายใต้ splint","ไหม absorbable ชนิดใดคงแรงดึงนานที่สุดเหมาะกับการเย็บ fascia → polydioxanone (PDS)"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":4,"page2":3,"orig":"Plastic surgery 2","stem":"For skin closure, which suture material is associated with the lowest risk of wound infection?","gray":"เย็บสกิน ไหมไหนช่วยลด infection — A. polyamide B. Polyester","opts":["Polyamide","Polyester","Silk","Catgut","Polyglactin"],"ans":0,"key":"A polyamide (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ถามคุณสมบัติไหมที่ลด infection — ประเด็นหลักคือ <b>monofilament vs multifilament (braided)</b> และ <b>synthetic vs natural</b>","why":"<b>Polyamide (nylon) monofilament</b> ผิวเรียบ ไม่มีช่องว่างระหว่างเส้นใยให้แบคทีเรียซ่อนจากเม็ดเลือดขาว และไม่มี <b>capillarity</b> (ไม่ดูดซับของเหลวและแบคทีเรียเข้าไปตามเส้นไหม) + เป็น synthetic ที่ tissue reaction ต่ำ → ความเสี่ยง infection ต่ำ; ใช้เย็บผิวหนังทั่วไป (4-0 ถึง 6-0) ตัดไหม 5–14 วันตามตำแหน่ง","wrong":{"B":"Polyester เป็น <b>braided multifilament</b> → มีช่องให้แบคทีเรียอยู่และ wick เชื้อเข้าไปตามเส้นไหม เพิ่ม infection; ใช้ในงานที่ต้องการแรงดึงสูง (tendon core suture, valve); จะถูกถ้าถามไหมแรงดึงสูงสำหรับเย็บ tendon core","C":"Silk เป็น natural braided <b>reaction สูงที่สุดตัวหนึ่ง</b> + มี capillarity → infection สูง (ใช้น้อยลงในการเย็บผิวหนัง); จะถูกถ้าถามไหมที่ผูกง่าย knot security ดีที่ใช้ยึด drain หรือผูกหลอดเลือด","D":"Catgut เป็น natural absorbable ถูกย่อยด้วย proteolysis → <b>inflammation มาก</b> ไม่เหมาะเย็บผิวหนังที่ต้องการลด infection; จะถูกถ้าถามไหมละลายเร็วสำหรับเย็บ mucosa","E":"Polyglactin (Vicryl) เป็น synthetic absorbable แบบ braided — มี capillarity มากกว่า monofilament (มีรุ่นเคลือบ triclosan ที่ลด SSI แต่ช้อยไม่ได้ระบุ); จะถูกถ้าถามไหมเย็บ subcuticular หรือ subcutaneous แบบละลาย"},"trap":"คิดว่าไหมละลายลด infection เพราะไม่ค้างในร่างกาย — สิ่งที่ลด infection คือ <b>monofilament + synthetic</b>; ในช้อยไม่มี polypropylene (Prolene) ซึ่ง reaction และ infection ต่ำที่สุด","summary":["Monofilament (nylon, polypropylene, PDS, poliglecaprone): ผิวเรียบ ลอดเนื้อเยื่อง่าย infection ต่ำ แต่ knot security ต่ำกว่า ต้องผูกหลายปม และมี memory","Multifilament braided (silk, polyester, polyglactin): ผูกง่าย knot security ดี แต่มี capillarity และช่องให้แบคทีเรียอยู่ → infection สูงกว่า ไม่ควรใช้ในแผลปนเปื้อน","Natural (silk, catgut): tissue reaction สูง; synthetic: reaction ต่ำ (polypropylene ต่ำสุด)","เย็บผิวหนัง: nylon 4-0 ถึง 6-0; ตัดไหม หน้า 3–5 วัน, หนังศีรษะ 7–10 วัน, ลำตัวและแขน 7–10 วัน, ขาและข้อต่อ 10–14 วัน","<b>Triclosan-coated suture</b> ลด SSI (WHO 2018 conditional recommendation ทุก wound class)","แผลปนเปื้อนมากหรือ dirty: ไม่ใช้ braided suture ในชั้นลึก หลีกเลี่ยงการปิดผิวหนังทันที","ดูข้อ 694 (ไหมเย็บ tendon), ข้อ 696, 697, 698 (การป้องกัน SSI)"],"notes":"ไฟล์เฉลย บท Plastic surgery แถว 2: <b>A</b> (ช่องคำอธิบายว่าง)<br>หัวบทในไฟล์โจทย์พิมพ์สีแดงว่า \"Plastic surgery (kuy) isus\"; ต้นฉบับจดช้อย 2 ตัว (A. polyamide B. Polyester) — ช้อย C–E แต่งเพิ่ม; ในไฟล์โจทย์บทนี้มีแถวข้อ 3, 4, 5 ว่าง (ไม่ใช่ข้อ)","mnemonic":"<b>\"เส้นเดียวเรียบ เชื้อไม่เกาะ; ถักเปีย เชื้อซ่อน\"</b>","guide":"WHO Global Guidelines for the Prevention of Surgical Site Infection 2nd ed. 2018; Schwartz's Principles of Surgery 11th ed.","variants":["แผลฉีกขาดที่ใบหน้าเด็กอายุ 6 ปี ไหมที่เหมาะสมเย็บผิวหนังและนัดตัดไหมเมื่อไร → nylon 6-0 ตัดไหม 3–5 วัน","ไหมชนิดใดมี tissue reaction ต่ำที่สุดเหมาะกับการเย็บหลอดเลือดและ hernia mesh → polypropylene","ศัลยแพทย์ต้องการไหมที่ช่วยลด SSI ในการปิดแผลหน้าท้องตามคำแนะนำ WHO → triclosan-coated suture"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A ความมั่นใจปานกลาง — เป็นคำตอบคลาสสิกในตำราสำหรับแผล dirty; ข้อควรรู้คือ RCT ไทยปี 2018 และ WSES 2020 พบว่า delayed primary closure ไม่ได้ลด SSI ชัดเจนใน complicated appendicitis เมื่อเทียบการปิดทันที และ triclosan-coated suture (E) มี conditional recommendation จาก WHO — แต่ในบรรดาช้อยที่ให้ A ยังเป็นมาตรการที่ตรงกับหลักการจัดการแผล dirty มากที่สุด; สอดคล้องกับข้อสอบชุด 77C (gangrenous ไม่แตก → primary closure)","page":5,"page2":3,"orig":"Surgical infection 1","flag":"⚠ เล็กน้อย: หลักฐานใหม่ (RCT ไทย Siribumrungwong 2018, WSES 2020) พบ delayed primary closure ไม่ลด SSI ชัดเจนเทียบ primary closure ใน complicated appendicitis และ triclosan-coated suture (ช้อย E) มี conditional recommendation จาก WHO 2018 — คงคีย์เพราะเป็นมาตรการคลาสสิกสำหรับแผล dirty (class IV) ในตำรา","stem":"After appendectomy for ruptured appendicitis, what is the most important measure to reduce superficial incisional surgical site infection?","gray":"ruptured appendicitis อะไรสำคัญที่สุดเพื่อลด superficial surgical site infection — A. Delayed wound closure with wet dressing B. Post antibiotics 10-14 day C. Soak แผลด้วยน้ำเกลืออย่างชุ่มโชคก่อนปิดแผล D. ทา Iodine เยอะๆก่อนปิดแผล E. ใช้ไหมเคลือบ ABX เย็บแผล","opts":["Delayed wound closure with wet dressing","Postoperative antibiotics for 10 to 14 days","Soaking the wound with saline before closure","Applying generous iodine before closure","Closing the wound with antibiotic-coated sutures"],"ans":0,"key":"A Delayed wound closure with wet dressing (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"Ruptured appendicitis = แผล <b>dirty (class IV)</b> ถามมาตรการที่สำคัญที่สุดเพื่อลด <b>superficial incisional SSI</b> (ระดับผิวหนังและ subcutaneous)","why":"แผล dirty ที่ปิดผิวหนังทันทีมีโอกาส SSI สูง (ตำราเดิมราว 30–40%) เพราะแบคทีเรียที่ปนเปื้อนชั้น subcutaneous ถูกขังไว้ในช่องปิด → หลักคลาสสิกคือ <b>เย็บปิด fascia แต่เปิดผิวหนังและ subcutaneous ไว้</b> ปิดด้วย wet (saline) dressing เปลี่ยนวันละ 2 ครั้ง แล้วทำ <b>delayed primary closure ราววันที่ 3–5</b> เมื่อแผลสะอาด มี granulation (หรือปล่อยหายเองแบบ secondary intention) → ลด superficial SSI ได้มากที่สุดในทางทฤษฎี; อย่างไรก็ตาม RCT ไทย (Siribumrungwong 2018) และ WSES 2020 พบว่าใน complicated appendicitis การปิดแผลทันทีไม่ได้เพิ่ม SSI อย่างมีนัยสำคัญ และหายเร็วกว่า","wrong":{"B":"Antibiotic หลังผ่าตัด 10–14 วัน <b>นานเกินจำเป็น</b> — complicated intra-abdominal infection ที่ source control ได้ ให้ <b>4 วัน</b> พอ (STOP-IT trial: fixed 4 วัน ผลเท่ากับให้จนไข้และ WBC หาย); ให้นานเพิ่ม resistance และ C. difficile; จะถูกถ้าคุม source ไม่ได้หรือมี bacteremia จากเชื้อบางชนิด","C":"WHO 2018 ระบุว่า <b>หลักฐานไม่พอ</b> จะแนะนำหรือคัดค้าน saline irrigation ของแผลก่อนปิด (ไม่มีคำแนะนำ) และแนะนำไม่ให้ irrigate ด้วย antibiotic; จะถูกน้อย — WHO มี conditional recommendation ให้ irrigate ด้วย aqueous povidone-iodine ใน clean และ clean-contaminated wound","D":"การทา antiseptic หรือ antimicrobial ลงบน incision ก่อนปิด <b>ไม่แนะนำ</b> (CDC 2017: do not apply antimicrobial agents to the surgical incision) และ iodine เข้มข้นทำลายเนื้อเยื่อ; จะถูกถ้าหมายถึงการเตรียมผิวหนังก่อนลงมีด (ปัจจุบันแนะนำ alcohol-chlorhexidine มากกว่า)","E":"Triclosan-coated suture มี <b>conditional recommendation</b> จาก WHO 2018 ลด SSI ทุก wound class (หลักฐานระดับปานกลาง) — เป็นมาตรการเสริม แต่ในแผล dirty ที่ยังปิดผิวหนังทันที ผลไม่เท่ากับการไม่ปิดผิวหนัง; จะถูกถ้าโจทย์ถามชนิดไหมที่แนะนำเพื่อลด SSI ในทุก wound class"},"trap":"คิดว่า antibiotic นาน ๆ ช่วยลด SSI — ไม่ช่วยและมีโทษ; หลักสำคัญของแผล dirty คือ <b>source control + ไม่ปิดผิวหนังที่ปนเปื้อน</b>; และ superficial SSI สัมพันธ์กับการจัดการผิวหนัง ไม่ใช่ antibiotic ระยะยาว","summary":["Wound class: I clean (SSI ~1–2%), II clean-contaminated (เปิดทางเดินอาหาร หายใจ ปัสสาวะแบบควบคุมได้), III contaminated (มีการรั่วไหลมาก, acute nonpurulent inflammation, traumatic wound สด), IV dirty (หนอง, perforated viscus, traumatic wound เก่า)","แผล dirty: ปิด fascia, เปิดผิวหนังไว้ + wet dressing → <b>delayed primary closure วันที่ 3–5</b> หรือ secondary intention (หรือ negative pressure wound therapy)","หลักฐานใหม่: complicated appendicitis การปิดผิวหนังทันทีมี SSI ไม่ต่างจาก DPC ชัดเจน (Siribumrungwong 2018, WSES 2020) — ตำราและข้อสอบยังถือ DPC เป็นคำตอบคลาสสิก","Antibiotic หลัง source control ของ complicated intra-abdominal infection = <b>4 วัน</b> (STOP-IT); simple appendicitis ไม่ต้องให้ต่อหลังผ่าตัด","WHO 2018: prophylactic antibiotic ภายใน 120 นาทีก่อนลงมีด, alcohol-chlorhexidine skin prep, triclosan-coated suture (conditional), ไม่ทา antimicrobial ลงแผล, ไม่ irrigate ด้วย antibiotic","Laparoscopic appendectomy SSI ระดับแผลต่ำกว่า open แต่ intra-abdominal abscess ใกล้เคียงหรือสูงกว่าเล็กน้อย","ดูข้อ 697, 698 (risk factor และการป้องกัน SSI), ข้อ 682 (wound infection หลังผ่าตัด)"],"notes":"ไฟล์เฉลย บท Surgical infection แถว 1: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับจดครบ 5 ช้อย (A, B ภาษาอังกฤษ; C–E ภาษาไทย): C \"Soak แผลด้วยน้ำเกลืออย่างชุ่มโชคก่อนปิดแผล\" (ชุ่มโชค = ชุ่มโชก), D \"ทา Iodine เยอะๆก่อนปิดแผล\", E \"ใช้ไหมเคลือบ ABX เย็บแผล\" — เราแปลเป็นอังกฤษโดยไม่เปลี่ยนความหมาย","mnemonic":"<b>\"Dirty → ปิด fascia เปิดผิว รอ 3–5 วัน\"</b>; antibiotic หลัง source control = <b>4 วัน</b>","guide":"WHO Global Guidelines for the Prevention of Surgical Site Infection 2nd ed. 2018; WSES Jerusalem guidelines on acute appendicitis 2020","variants":["ผู้ป่วย perforated sigmoid diverticulitis มี fecal peritonitis หลังทำ Hartmann's procedure — การจัดการแผลผิวหนัง → ปิด fascia เปิดผิวหนังไว้ wet dressing แล้ว delayed primary closure","ผู้ป่วย perforated appendicitis หลังผ่าตัด source control ได้ดี — ควรให้ antibiotic นานเท่าไร → 4 วัน","ผู้ป่วย acute non-perforated appendicitis หลังผ่าตัด ต้องให้ antibiotic ต่อหรือไม่ → ไม่ต้อง ให้เฉพาะ prophylaxis ก่อนผ่าตัด"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A ความมั่นใจปานกลางถึงสูง — ต้นฉบับไม่ได้บอกว่าผู้ป่วยอ้วน แต่ในบรรดาช้อยที่ผู้จดให้ obesity เป็นตัวเดียวที่เป็น risk factor ของ SSI (ช้อยอื่นเป็นอาการหรือมาตรการป้องกัน) จึงเติม BMI ให้ข้อมูลครบ","page":5,"page2":3,"orig":"Surgical infection 2","flag":"⚠ เล็กน้อย: เติม BMI 36 ใน stem (ต้นฉบับไม่บอกว่าอ้วน แต่ช้อย A คือ obesity)","stem":"A patient with diabetes and a BMI of 36 underwent elective surgery with appropriate antibiotic prophylaxis. Serous fluid is now draining from the wound. Which of the following is the greatest risk factor for surgical site infection in this patient?","gray":"คนไข้ DM s/p อะไรสักอย่าง มี serous ไหลออกมาจากแผล Risk มากที่สุดที่คนไข้คนนี้จะเกิด SSIs — A. Obesity B. Serous C. Abx prophylaxis D. Elective surgery","opts":["Obesity","Serous wound drainage","Antibiotic prophylaxis","Elective surgery","Short operative time"],"ans":0,"key":"A Obesity (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ถาม <b>risk factor ของ SSI</b> ในผู้ป่วยรายนี้ — ต้องแยกว่าช้อยไหนเพิ่มความเสี่ยง (patient factor) ช้อยไหนเป็นอาการ และช้อยไหนเป็นปัจจัยป้องกัน","why":"<b>Obesity</b> เป็น patient-related risk factor ที่สำคัญของ SSI: ชั้นไขมันหนามีเลือดเลี้ยงน้อย (oxygen tension ต่ำ) เกิด dead space และ seroma ง่าย, ความตึงของแผลสูง, ระดับยา prophylactic ในเนื้อเยื่อต่ำถ้าไม่ปรับขนาด (cefazolin 3 g ถ้าน้ำหนัก ≥120 kg), ผ่าตัดยากและนานขึ้น และมักมี hyperglycemia หรือ DM ร่วม (รายนี้มีทั้ง DM และ BMI 36); ในช้อยที่ให้ obesity จึงเป็น risk factor ที่แท้จริง","wrong":{"B":"Serous drainage เป็น <b>อาการของแผล</b> (seroma, fat necrosis ในคนอ้วน) ไม่ใช่ risk factor ของผู้ป่วย — แม้แผลที่มีน้ำซึมนานจะสัมพันธ์กับ SSI (drainage นาน &gt;5 วันควรประเมินหาการติดเชื้อหรือ seroma) แต่ไม่ใช่ตัวตั้งต้นที่โจทย์ถาม; จะถูกถ้าโจทย์ถามอาการเตือนที่ต้องเปิดแผลตรวจ","C":"Antibiotic prophylaxis ที่ให้ถูกเวลา (ภายใน 60 นาทีก่อนลงมีด) <b>ลด</b> SSI; จะเป็น risk factor เฉพาะเมื่อให้ผิดเวลา ขนาดไม่พอ หรือให้นานเกินไป","D":"Elective surgery มีความเสี่ยงต่ำกว่า <b>emergency surgery</b> (เตรียมผู้ป่วยได้ คุมน้ำตาล หยุดบุหรี่); จะถูกถ้าช้อยเป็น emergency surgery","E":"Operative time สั้น <b>ลด</b> SSI — ผ่าตัดนานกว่า 75th percentile ของหัตถการนั้น (T-time) จึงเป็น risk factor; จะถูกถ้าช้อยเป็น prolonged operative time"},"trap":"เลือก serous discharge เพราะเห็นในโจทย์ — อาการของแผลไม่ใช่ risk factor; ต้องแยก <b>patient factor</b> (DM, obesity, smoking, malnutrition, steroid) กับ <b>procedure factor</b> และมาตรการป้องกัน","summary":["Patient factor ของ SSI: อายุมาก, <b>DM และ hyperglycemia</b> (คุม glucose &lt;200 mg/dL รอบผ่าตัด), <b>obesity</b>, smoking (หยุด 4–6 สัปดาห์ก่อนผ่าตัด), malnutrition (albumin ต่ำ), immunosuppression, steroid, remote infection, S. aureus colonization","Procedure factor: emergency, wound class สูง, ผ่าตัดนาน, hypothermia, เลือดออกมากหรือได้เลือด, hair removal ด้วยมีดโกน, drain, foreign body","Risk index (NNIS): ASA ≥3, wound class III–IV, operative time &gt;T (75th percentile) — ข้อละ 1 คะแนน","Prophylaxis: cefazolin 2 g IV (3 g ถ้า ≥120 kg) ภายใน 60 นาทีก่อนลงมีด, ให้ซ้ำทุก 4 ชม.หรือเสียเลือด &gt;1,500 mL, หยุดเมื่อจบผ่าตัด","Serous drainage นานหลังผ่าตัดในคนอ้วน → seroma หรือ fat necrosis; ถ้ามีแดง หนอง ไข้ → เปิดแผลระบาย","ดูข้อ 696, 698 (การป้องกัน SSI), ข้อ 682 (wound infection หลังผ่าตัด)"],"notes":"ไฟล์เฉลย บท Surgical infection แถว 2: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับจดโจทย์ว่า \"คนไข้ DM s/p อะไรสักอย่าง\" (ผู้จดจำชนิดการผ่าตัดไม่ได้) และไม่ได้บอกว่าผู้ป่วยอ้วน — เราเติม BMI 36, elective surgery และได้ antibiotic prophylaxis ตามช้อย C, D; ช้อย B ต้นฉบับเขียนแค่ \"Serous\" เราเขียนเป็น Serous wound drainage; ช้อย E แต่งเพิ่ม","mnemonic":"","guide":"CDC Guideline for the Prevention of Surgical Site Infection 2017; WHO Global Guidelines for the Prevention of Surgical Site Infection 2nd ed. 2018","variants":["ชายอายุ 55 ปี สูบบุหรี่วันละ 1 ซอง นัดผ่าตัด elective ventral hernia repair — ควรแนะนำอะไรเพื่อลด SSI → หยุดบุหรี่อย่างน้อย 4–6 สัปดาห์ก่อนผ่าตัด","ผู้ป่วยหนัก 130 kg ผ่าตัด bariatric surgery — ขนาด cefazolin prophylaxis → 3 g IV ภายใน 60 นาทีก่อนลงมีด","ผู้ป่วยผ่าตัดนาน 6 ชั่วโมง ได้ cefazolin ก่อนลงมีด — ควรให้ซ้ำเมื่อไร → ทุก 4 ชม.ระหว่างผ่าตัด หรือเมื่อเสียเลือด &gt;1,500 mL"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"ไม่เห็นด้วยกับคีย์ (คีย์ตอบ A saline irrigation) — เราตอบ B ความมั่นใจปานกลาง: WHO 2018 ให้ strong recommendation สำหรับ alcohol-based chlorhexidine skin preparation ขณะที่ saline irrigation ของแผล WHO ระบุว่าหลักฐานไม่พอจะให้คำแนะนำ; ความไม่แน่นอนอยู่ที่ช้อยต้นฉบับ \"Chlorhex เช็ดแผล\" ซึ่งอาจหมายถึงการเช็ดแผลหลังผ่าตัด (ไม่มีหลักฐานว่าลด SSI ชัดเจนทั้งคู่) — ถ้าข้อสอบจริงหมายถึงแบบนั้น คำตอบของผู้ออกข้อสอบอาจเป็น A ตามคีย์; สอดคล้องกับข้อสอบชุด 77D (chlorhexidine สำหรับ surgical hand antisepsis)","page":5,"page2":3,"orig":"Surgical infection 3","flag":"⚠ ตอบต่างจากคีย์ (คีย์ A saline irrigation) — WHO 2018 ให้ strong recommendation สำหรับ alcohol-based chlorhexidine skin preparation ส่วน saline wound irrigation หลักฐานไม่พอ (ไม่มีคำแนะนำ); ช้อย B ต้นฉบับเขียน \"Chlorhex เช็ดแผล\" ตีความเป็นการเตรียมผิวหนังบริเวณแผลผ่าตัด — ถ้าหมายถึงเช็ดแผลหลังผ่าตัด ทั้งสองช้อยไม่มีหลักฐานแข็ง","stem":"Which measure reduces the risk of surgical site infection the most?","gray":"อะไรช่วยลดโอกาส SSIs มากที่สุด — A. Irrigate แผลด้วยน้ำเกลือ B. Chlorhex เช็ดแผล","opts":["Wound irrigation with normal saline","Chlorhexidine-alcohol skin preparation","Razor shaving the night before surgery","Antibiotics continued until drain removal","Plastic adhesive incise drape"],"ans":1,"key":"A Irrigate แผลด้วยน้ำเกลือ (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ถามมาตรการที่ <b>หลักฐานแข็งที่สุด</b> ในการลด SSI — ต้องเทียบกับระดับคำแนะนำของ WHO และ CDC","why":"<b>Alcohol-based chlorhexidine skin preparation</b> ก่อนลงมีดได้ <b>strong recommendation</b> จาก WHO 2018 (หลักฐานระดับ low ถึง moderate) และ CDC 2017 (Category IA สำหรับ alcohol-based agent) — ลด SSI ได้ดีกว่า povidone-iodine แบบ aqueous (RCT Darouiche 2010: chlorhexidine-alcohol ลด SSI ใน clean-contaminated surgery ราว 40%); chlorhexidine จับกับผิวหนังออกฤทธิ์ค้าง (residual activity) และ alcohol ฆ่าเชื้อเร็ว ต้องรอให้แห้งก่อนคลุมผ้า (ระวังไฟไหม้จาก cautery)","wrong":{"A":"Saline wound irrigation ก่อนปิดแผล — WHO 2018 สรุปว่า <b>หลักฐานไม่พอ</b> ที่จะแนะนำหรือคัดค้าน; มีหลักฐานบ้างสำหรับ irrigation ด้วย aqueous povidone-iodine (conditional) ใน clean และ clean-contaminated; นี่คือช้อยที่คีย์เลือก; จะถูกถ้าโจทย์เทียบกับมาตรการที่ไม่มีประโยชน์ทั้งหมด หรือถามการล้างแผลอุบัติเหตุที่ปนเปื้อนก่อนเย็บ","C":"การโกนขนด้วยมีดโกน <b>เพิ่ม</b> SSI (micro-abrasion ให้เชื้อเข้าและเพิ่มจำนวน) — WHO strong recommendation ไม่ให้ใช้มีดโกน; ถ้าจำเป็นใช้ clipper ใกล้เวลาผ่าตัด หรือไม่ต้องกำจัดขนเลย; ไม่มีบริบทที่ถูก","D":"การให้ antibiotic ต่อจนถอด drain <b>ไม่ลด</b> SSI — WHO strong recommendation ไม่ให้ต่อ prophylaxis หลังจบผ่าตัด และ conditional recommendation ไม่ให้ต่อเพราะมี drain; เพิ่ม resistance และ C. difficile; ไม่มีบริบทที่ถูก","E":"Plastic adhesive incise drape (ทั้งแบบธรรมดาและแบบเคลือบ iodine) — WHO conditional recommendation <b>ไม่ใช้</b> เพื่อป้องกัน SSI เพราะไม่ลด SSI; ไม่มีบริบทที่ถูก"},"trap":"เลือก saline irrigation เพราะฟังดูสมเหตุสมผลและคีย์ตอบ — แต่ในแนวทางปัจจุบันมาตรการที่หลักฐานแข็งที่สุดในช้อยคือ <b>alcohol-chlorhexidine skin prep</b>; ส่วนการโกนขนและให้ยาต่อจนถอด drain เพิ่มหรือไม่ลด SSI","summary":["Preoperative: อาบน้ำด้วยสบู่ก่อนผ่าตัด, decolonization ด้วย mupirocin ± chlorhexidine ใน S. aureus carrier ที่ผ่าตัดหัวใจหรือ orthopedic, หยุดบุหรี่, คุมน้ำตาล, ไม่กำจัดขนหรือใช้ clipper","Prophylactic antibiotic: ภายใน <b>120 นาที</b> (WHO) หรือ 60 นาที (แนวทางทั่วไป) ก่อนลงมีด, ให้ซ้ำเมื่อผ่าตัดนาน, <b>หยุดเมื่อจบผ่าตัด</b>","Skin prep: <b>alcohol-based chlorhexidine</b> (strong recommendation) ดีกว่า povidone-iodine; surgical hand antisepsis ด้วยสบู่ antimicrobial หรือ alcohol hand rub","Intraoperative: normothermia, FiO₂ 80% ใน intubated patient (WHO conditional), goal-directed fluid, triclosan-coated suture (conditional), ไม่ใช้ incise drape","ไม่แนะนำ: antibiotic irrigation, ทา antimicrobial บนแผล, ต่อ antibiotic เพราะมี drain","ดูข้อ 696, 697 (SSI ในแผลปนเปื้อนและ risk factor), ข้อ 695 (ไหมกับ infection)"],"notes":"ไฟล์เฉลย บท Surgical infection แถว 3: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับจดช้อย 2 ตัว (A. Irrigate แผลด้วยน้ำเกลือ B. Chlorhex เช็ดแผล) — ช้อย B เราตีความเป็น chlorhexidine-alcohol skin preparation (การเตรียมผิวหนังบริเวณผ่าตัด) และแต่งช้อย C–E (มาตรการที่ไม่ลดหรือเพิ่ม SSI); ต้นฉบับเขียน \"SSIs\"; ในไฟล์โจทย์บทนี้มีแถวข้อ 4, 5 ว่าง (ไม่ใช่ข้อ)","mnemonic":"<b>\"Clip, don't shave; Chlorhex-alcohol, let it dry; Stop antibiotics when you close\"</b>","guide":"WHO Global Guidelines for the Prevention of Surgical Site Infection 2nd ed. 2018; CDC Guideline for the Prevention of Surgical Site Infection 2017","variants":["ก่อนผ่าตัด open hernia repair บริเวณขาหนีบมีขนมาก — การกำจัดขนที่เหมาะสม → ไม่ต้องกำจัด หรือใช้ clipper ใกล้เวลาผ่าตัด ห้ามใช้มีดโกน","หลังผ่าตัด modified radical mastectomy ใส่ drain ไว้ — ควรให้ antibiotic จนถอด drain หรือไม่ → ไม่ควร หยุด prophylaxis เมื่อจบผ่าตัด","สารใดเหมาะที่สุดสำหรับเตรียมผิวหนังก่อนลงมีด และต้องระวังอะไร → alcohol-based chlorhexidine รอให้แห้งก่อนใช้ electrocautery เพื่อป้องกันไฟไหม้"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A ความมั่นใจสูง — สอดคล้องกับข้อสอบชุด 77B (GIST 2 cm ที่ EGJ → resection ไม่ต้องเลาะต่อมน้ำเหลือง) และชุด 76C (วินิจฉัย GIST ด้วย EUS-guided biopsy)","page":5,"page2":4,"orig":"Surgical Oncology 1","stem":"A 2-cm gastrointestinal stromal tumor of the small bowel is found, with no metastasis. What is the most appropriate management?","gray":"GIST 2 cm ที่ small bowel ทำไรต่อดี — A. ทำ Resection B. ให้ Targeted therapy","opts":["Segmental resection","Targeted therapy","Endoscopic surveillance every 6 months","Radiotherapy","Doxorubicin-based chemotherapy"],"ans":0,"key":"A ทำ Resection (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"GIST ขนาดเล็ก (2 cm) ที่ <b>small bowel</b> ไม่มีการแพร่กระจาย — ต้องรู้ว่าตำแหน่งที่ไม่ใช่กระเพาะมี malignant potential สูงกว่าและต้องตัดออกทุกขนาด","why":"NCCN และ ESMO: GIST ที่ <b>non-gastric (small bowel, colon, rectum)</b> มี malignant potential สูงกว่า gastric GIST ขนาดเท่ากัน จึงควร <b>ตัดออกทุกขนาด</b> (ไม่ใช้ surveillance แบบ gastric &lt;2 cm); ทำ <b>segmental resection</b> ให้ได้ margin negative (R0) โดย <b>ไม่ต้องเลาะต่อมน้ำเหลือง</b> (GIST แพร่ทางกระแสเลือดไปตับและเยื่อบุช่องท้อง แทบไม่ไปต่อมน้ำเหลือง) และต้อง <b>ระวังก้อนแตก</b> (rupture = high risk ต้องได้ adjuvant imatinib); หลังผ่าตัดประเมิน risk ตาม site, size, mitotic rate (Miettinen/AFIP) ถ้า high risk ให้ adjuvant imatinib 400 mg/วัน <b>3 ปี</b>","wrong":{"B":"Targeted therapy (imatinib) เป็น <b>adjuvant</b> หลังผ่าตัดในกลุ่ม high risk, <b>neoadjuvant</b> ในก้อนใหญ่หรือตำแหน่งยากเพื่อลดขนาดก่อนผ่าตัด หรือใช้ใน metastatic/unresectable; ก้อน 2 cm ที่ตัดได้ไม่ใช้ยาเป็นการรักษาหลัก; จะถูกถ้าเป็น metastatic GIST หรือก้อนใหญ่ที่ rectum ต้องลดขนาดก่อน","C":"Surveillance ด้วย EUS ทุก 6–12 เดือนใช้กับ <b>gastric GIST &lt;2 cm</b> ที่ไม่มี high-risk EUS features (ขอบไม่เรียบ, cystic space, ulceration, echogenic foci, heterogeneity); small bowel ไม่ใช่กลุ่มนี้และส่องกล้องเข้าถึงยาก; จะถูกถ้าเป็นก้อน 1.5 cm ที่กระเพาะไม่มี high-risk features","D":"Radiotherapy ไม่ได้ผลใน GIST (radioresistant) ใช้เพียงประคับประคองบางกรณีที่ปวดจาก metastasis; จะถูกถ้าโจทย์ถามการบรรเทาอาการปวดจากก้อนที่แพร่กระจายและดื้อยา","E":"Conventional chemotherapy (doxorubicin) <b>ไม่ได้ผล</b> ใน GIST (response &lt;5%) ต่างจาก soft tissue sarcoma อื่น; จะถูกถ้าโจทย์เป็น soft tissue sarcoma ชนิดอื่นที่แพร่กระจาย"},"trap":"เอาเกณฑ์ <b>gastric GIST &lt;2 cm → surveillance</b> มาใช้กับ small bowel — non-gastric ตัดทุกขนาด; และอย่าเลาะต่อมน้ำเหลืองแบบผ่าตัดมะเร็ง adenocarcinoma","summary":["GIST เกิดจาก <b>interstitial cell of Cajal</b>, mutation KIT (~80%) หรือ PDGFRA (~10%), ย้อม <b>CD117 (KIT) และ DOG1</b> positive; ตำแหน่ง: กระเพาะ 60%, small bowel 30%, colon-rectum ~5%","วินิจฉัย: CT ช่องท้อง; ก้อนในกระเพาะใช้ EUS-guided FNA/biopsy; ก้อนที่ตัดได้ชัดเจนอาจผ่าตัดโดยไม่ต้อง biopsy ก่อน","Gastric &lt;2 cm ไม่มี high-risk EUS features → surveillance; มี features หรือโตขึ้น → resect; ≥2 cm → resect; <b>non-gastric → resect ทุกขนาด</b>","ผ่าตัด: wedge หรือ segmental resection margin negative (1–2 cm พอ), <b>ไม่ต้อง lymphadenectomy</b> (ยกเว้น SDH-deficient), หลีกเลี่ยงก้อนแตก, laparoscopic ได้ถ้าก้อนไม่ใหญ่","Risk stratification: site + size + mitotic rate per 5 mm² + rupture → high risk → <b>adjuvant imatinib 3 ปี</b>","Metastatic: imatinib 400 mg (exon 9 KIT 800 mg) → sunitinib → regorafenib → ripretinib; PDGFRA D842V ดื้อ imatinib ใช้ avapritinib; GIST ดื้อ chemotherapy และ radiotherapy","ดูข้อ 700, 701, 702, 703 (oncology principles)"],"notes":"ไฟล์เฉลย บท Surgical Oncology แถว 1: <b>A</b> (ช่องคำอธิบายว่าง) — แถวนี้อยู่หน้า 4 ของไฟล์เฉลย<br>ต้นฉบับจดช้อย 2 ตัว (A. ทำ Resection B. ให้ Targeted therapy) — ช้อย C–E แต่งเพิ่ม; stem เติม \"no metastasis\" เพื่อให้เป็นเคสที่ตัดได้","mnemonic":"<b>\"กระเพาะเล็กรอได้ ที่อื่นตัดหมด\"</b>; GIST ไม่ไปต่อมน้ำเหลือง ไม่กลัว chemo ไม่กลัวแสง กลัวแต่ imatinib","guide":"NCCN Clinical Practice Guidelines in Oncology: Gastrointestinal Stromal Tumors 2025; ESMO–EURACAN–GENTURIS GIST Clinical Practice Guidelines 2022","variants":["ก้อน 1.5 cm ใต้ mucosa ที่ gastric body จาก EUS ขอบเรียบ เนื้อสม่ำเสมอ biopsy เป็น GIST — การจัดการ → surveillance ด้วย EUS เป็นระยะ","หลังตัด GIST ลำไส้เล็กขนาด 8 cm mitotic rate 10 ต่อ 5 mm² — การรักษาต่อ → adjuvant imatinib 3 ปี","GIST ขนาด 12 cm ที่กระเพาะเกาะติดตับอ่อน — ทำอะไรก่อนผ่าตัด → neoadjuvant imatinib เพื่อลดขนาด (ตรวจ mutation ก่อน)"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง — ช้อย B ผิดชัด (hyperplastic และ inflammatory polyp ไม่ใช่ precursor) ข้อที่ติด ⚠ เป็นเพียงการเติมชื่ออวัยวะซึ่งไม่เปลี่ยนคำตอบ","page":6,"page2":4,"orig":"Surgical Oncology 2","stem":"Which best describes the pathway by which colorectal adenocarcinoma develops?","gray":"Adenocarcinoma pathway — A. Cumulative of mutation B. Hyperplastic polyp -&gt; Inflammative polyp -&gt; Cancer C. (ว่าง)","opts":["Accumulation of multiple genetic mutations","Hyperplastic polyp, then inflammatory polyp, then cancer","A single mutation in one oncogene","Direct viral transformation of normal mucosa","Malignant change of every hamartomatous polyp"],"ans":0,"key":"A Cumulative of mutation (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: ต้นฉบับไม่บอกอวัยวะ — เติม colorectal ใน stem","interp":"ถามกลไกการเกิด <b>colorectal adenocarcinoma</b> — ต้องรู้ว่ามะเร็งเกิดจากการ<b>สะสม genetic alteration หลายขั้น</b> ผ่าน precursor lesion (adenoma หรือ serrated lesion) ไม่ใช่ผ่าน polyp ทุกชนิด","why":"Adenoma–carcinoma sequence (Vogelstein): mucosa ปกติ → <b>APC</b> loss (early adenoma, gatekeeper) → <b>KRAS</b> activation (intermediate adenoma) → loss of <b>18q</b> (SMAD4, DCC) (late adenoma) → <b>TP53</b> loss (carcinoma) = chromosomal instability pathway ราว 85% ของ sporadic CRC; ทางอื่นคือ <b>MSI pathway</b> (MMR gene เสีย, Lynch syndrome และ sporadic MLH1 methylation ราว 15%) และ <b>serrated pathway</b> (BRAF, CIMP ผ่าน sessile serrated lesion) — ทุกทางต้อง<b>สะสมหลาย mutation</b> ใช้เวลาราว 10 ปีจาก adenoma ไปเป็นมะเร็ง จึงเป็นเหตุผลของ screening และ polypectomy","wrong":{"B":"ผิด เพราะ hyperplastic polyp ขนาดเล็กที่ distal colon และ rectum เป็น non-neoplastic polyp ที่แทบไม่กลายเป็นมะเร็ง ส่วน inflammatory polyp (pseudopolyp ใน IBD) ก็ไม่ใช่ precursor ของมะเร็งโดยตรง — ใน IBD มะเร็งเกิดผ่าน dysplasia ในเยื่อบุที่อักเสบเรื้อรัง; ลำดับ polyp → polyp → cancer จะถูกถ้าเขียนเป็น sessile serrated lesion → dysplasia → cancer (serrated pathway) หรือ tubular adenoma → villous adenoma → cancer","C":"ผิด เพราะ mutation เดียวไม่พอทำให้เกิดมะเร็ง ต้องมีหลาย hit ทั้ง oncogene activation และ tumor suppressor loss (two-hit hypothesis ของ tumor suppressor); แม้ใน FAP ที่มี germline APC ตั้งแต่เกิดก็ยังต้องสะสม KRAS, TP53 เพิ่มก่อนเป็นมะเร็ง; จะใกล้เคียงถ้าถามว่า mutation แรก (gatekeeper) ของ CIN pathway คืออะไร → APC","D":"ผิด เพราะ CRC ไม่ได้เกิดจากไวรัส; viral carcinogenesis ที่สำคัญคือ HPV (anal และ cervical SCC), HBV และ HCV (HCC), EBV (nasopharyngeal carcinoma, Burkitt lymphoma); จะถูกถ้าถามกลไกของ anal squamous cell carcinoma","E":"ผิด เพราะ hamartomatous polyp ส่วนใหญ่ (juvenile polyp เดี่ยวในเด็ก) ไม่กลายเป็นมะเร็ง ความเสี่ยงเพิ่มขึ้นใน hamartomatous polyposis syndrome แต่ก็ไม่ใช่ทุก polyp และมะเร็งเกิดผ่าน dysplasia ภายใน polyp; จะใกล้เคียงถ้าถามว่า polyposis syndrome กลุ่มนี้ต้อง surveillance หรือไม่ → ต้อง"},"trap":"เห็นคำว่า polyp → cancer แล้วเลือก B — ลำดับ polyp ที่ถูกต้องต้องเป็น <b>neoplastic</b> polyp (adenoma หรือ sessile serrated lesion) ไม่ใช่ hyperplastic หรือ inflammatory polyp","summary":["Colorectal carcinogenesis เป็น multistep: สะสม genetic และ epigenetic alteration หลายตัว ใช้เวลาราว 10 ปีจาก adenoma ไป carcinoma → เปิดช่องให้ screening และตัด polyp","Chromosomal instability pathway (ราว 85%): APC → KRAS → 18q loss (SMAD4, DCC) → TP53; ตัวอย่าง germline คือ FAP (APC)","MSI pathway (ราว 15%): MMR gene (MLH1, MSH2, MSH6, PMS2) เสีย → microsatellite instability; germline = Lynch syndrome, sporadic = MLH1 promoter methylation; มักอยู่ right colon, mucinous, TIL มาก, ตอบสนอง immunotherapy","Serrated pathway: BRAF V600E + CIMP ผ่าน sessile serrated lesion มักอยู่ proximal colon และเป็นต้นเหตุ interval cancer","Polyp ที่เป็น precursor: tubular, tubulovillous, villous adenoma (เสี่ยงขึ้นเมื่อ ≥1 cm, villous component, high-grade dysplasia) และ sessile serrated lesion; hyperplastic polyp เล็กที่ distal และ inflammatory polyp ไม่ใช่ precursor","ดูข้อ 699, 701, 702, 703 (oncology principles) และข้อ 702, 757 (colorectal carcinogenesis และ polyp)"],"notes":"ไฟล์เฉลยบท Surgical Oncology แถว 2: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับโจทย์เขียนแค่ \"Adenocarcinoma pathway\" ไม่ระบุอวัยวะ — เราเติม colorectal ใน stem เพราะช้อย B พูดถึง polyp<br>ปรับช้อย: A ต้นฉบับ \"Cumulative of mutation\" → Accumulation of multiple genetic mutations; B ต้นฉบับ \"Hyperplastic polyp -&gt; Inflammative polyp -&gt; Cancer\" (สะกด Inflammative) → Hyperplastic polyp, then inflammatory polyp, then cancer; ช้อย C ในต้นฉบับเป็นช่องว่าง (ผู้จดไม่ได้จด) — C, D, E แต่งเพิ่ม","mnemonic":"<b>A-K-18-53</b> = APC → KRAS → 18q → p53 (ตามลำดับเวลา จาก adenoma เล็กไปมะเร็ง)","guide":"Sabiston 21st ed.; NCCN Colon Cancer 2025","variants":["ผู้ป่วยอายุ 32 ปีมี adenomatous polyp หลายร้อยตัวทั่วลำไส้ใหญ่ พ่อเป็นมะเร็งลำไส้ใหญ่อายุ 40 ปี gene ที่น่าจะผิดปกติคืออะไร → APC (FAP)","ผู้ป่วยอายุ 45 ปีเป็นมะเร็ง right colon ชนิด mucinous พบ loss of MSH2 ใน IHC และมีญาติเป็นมะเร็งเยื่อบุโพรงมดลูก → Lynch syndrome (MSI pathway)","colonoscopy พบ sessile serrated lesion 12 mm ที่ ascending colon ควรทำอย่างไรและเกี่ยวกับ pathway ใด → ตัดออกให้หมด, serrated pathway (BRAF, CIMP)"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง — สอดคล้องกับข้อสอบชุด 76A และ 77A ที่ตอบ radiotherapy สำหรับ spinal cord compression จากมะเร็ง; ถ้อยคำในช้อย \"to reduce pain and fracture\" ไม่ครบเป้าหมายหลัก (รักษา neurologic function) แต่ในบรรดาช้อยยังเป็นการรักษาเดียวที่จัดการก้อนที่กดทับ","page":6,"page2":4,"orig":"Surgical Oncology 3","stem":"A patient with metastatic cancer develops metastatic spinal cord compression. What is the most appropriate treatment?","gray":"คนไข้เป็น spinal compression from cancer ทำไรต่อ — A. Radiation to reduce pain and fracture B. Opioid to control pain","opts":["Radiotherapy to reduce pain and fracture","Opioid analgesia to control pain","Bisphosphonate infusion alone","Systemic chemotherapy alone","Observation with repeat MRI in 4 weeks"],"ans":0,"key":"A Radiation to reduce pain and fracture (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"<b>Metastatic spinal cord compression (MSCC)</b> เป็น oncologic emergency — ถามการรักษาที่เป็น definitive treatment ไม่ใช่แค่การบรรเทาอาการ","why":"เมื่อสงสัย MSCC: ให้ <b>dexamethasone</b> ทันที (16 mg/วัน) + <b>MRI whole spine</b> ภายใน 24 ชม. → definitive treatment คือ <b>radiotherapy</b> (8 Gy ×1 ในรายพยากรณ์โรคไม่ดี หรือ 20 Gy/5 fractions) เพื่อคุมก้อน ลดปวด รักษา neurologic function และ local control; หรือ <b>decompressive surgery ตามด้วย RT</b> ในรายที่เหมาะ (Patchell 2005: compression ระดับเดียว, คาดชีวิต &gt;3 เดือน, มี spinal instability, tumor ไม่ radiosensitive, ยังไม่ paraplegia นาน &gt;48 ชม.) ซึ่งเดินได้มากกว่า RT อย่างเดียว; ผลลัพธ์ขึ้นกับ<b>ความสามารถเดินตอนเริ่มรักษา</b>","wrong":{"B":"Opioid เป็นการรักษาเสริมเพื่อคุมปวด ให้ร่วมกันได้แต่ไม่แก้การกดทับไขสันหลัง ถ้าให้แค่ยาแก้ปวดจะเสียเวลาจนเกิด paraplegia ถาวร; จะถูกถ้าโจทย์ถามการคุมปวดระหว่างรอ MRI หรือในผู้ป่วยระยะสุดท้ายที่เลือก comfort care","C":"Bisphosphonate (zoledronic acid) หรือ denosumab ใช้<b>ป้องกัน skeletal-related events</b> และ hypercalcemia ในผู้ป่วย bone metastasis ไม่ได้รักษาการกดทับที่เกิดขึ้นแล้ว; จะถูกถ้าถามการป้องกัน pathologic fracture และ SRE ใน bone metastasis ระยะยาว","D":"Chemotherapy อย่างเดียวออกฤทธิ์ช้าเกินไปสำหรับ MSCC ส่วนใหญ่; ใช้เป็นหลักได้เฉพาะ tumor ที่ chemosensitive มาก (lymphoma, germ cell tumor, small cell lung cancer, neuroblastoma) ร่วมกับ steroid และมักให้ RT ด้วย; จะถูกถ้าโจทย์เป็น MSCC จาก lymphoma ในเด็กหรือ germ cell tumor","E":"การรอดู 4 สัปดาห์ผิดเพราะ MSCC ต้องรักษาภายใน 24 ชม. การเสีย motor function ที่เกิดแล้วมักไม่กลับ; ไม่มีสถานการณ์ใดที่ observation เหมาะใน MSCC ยกเว้นผู้ป่วยระยะสุดท้ายที่ปฏิเสธการรักษาและเลือก palliative care"},"trap":"เลือก opioid เพราะผู้ป่วยปวดหลังมาก — ลืมว่าเป้าหมายคือรักษาการกดทับไขสันหลังให้ทันก่อนอ่อนแรงถาวร ส่วนยาแก้ปวดเป็นแค่ส่วนเสริม","summary":["MSCC: พบมากใน lung, breast, prostate cancer, myeloma; ตำแหน่ง thoracic spine มากที่สุด ราว 60–70%","อาการเริ่มคือปวดหลังที่แย่ลง ปวดตอนกลางคืน ปวดแบบ radicular แล้วตามด้วยอ่อนแรง ชา sensory level และ bowel หรือ bladder dysfunction (มักมาช้า)","Work-up: MRI whole spine ภายใน 24 ชม. เพราะ lesion หลายระดับพบบ่อย","ทันที: dexamethasone 16 mg/วัน, คุมปวด, ประเมิน spinal stability (SINS score)","Definitive: radiotherapy (8 Gy ×1 หรือ 20 Gy/5) หรือ decompressive surgery + RT ในรายที่คาดชีวิต &gt;3 เดือน, single level, unstable spine, radioresistant tumor","Chemosensitive tumor (lymphoma, germ cell, SCLC) ใช้ systemic therapy ร่วมได้; bisphosphonate และ denosumab ใช้ป้องกัน SRE ระยะยาว","พยากรณ์โรคด้าน neurologic ขึ้นกับความสามารถเดินก่อนรักษา: เดินได้ก่อนรักษาส่วนใหญ่ยังเดินได้หลังรักษา","ดูข้อ 699, 700, 702, 703 (oncology principles)"],"notes":"ไฟล์เฉลยบท Surgical Oncology แถว 3: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับมีช้อยแค่ 2 ตัว (A Radiation to reduce pain and fracture, B Opioid to control pain) — C, D, E แต่งเพิ่ม; stem ต้นฉบับ \"spinal compression from cancer\" เราเขียนเป็น metastatic spinal cord compression","mnemonic":"MSCC = <b>\"Dex – MRI – Radiate\"</b> ภายใน 24 ชม.","guide":"NICE NG234 spinal metastases and MSCC 2023","variants":["ผู้ป่วยมะเร็งเต้านมมีปวดหลังระดับอก 2 สัปดาห์ ขาอ่อนแรงเล็กน้อย ยังเดินได้ ควรทำอะไรก่อน → dexamethasone + MRI whole spine ด่วน","ผู้ป่วยมะเร็งไตแพร่กระจายมี MSCC ระดับ T10 ระดับเดียว กระดูกสันหลังไม่มั่นคง คาดชีวิต 1 ปี → decompressive surgery + stabilization ตามด้วย RT","ผู้ป่วย prostate cancer มี bone metastasis หลายตำแหน่ง ไม่มีอาการทางระบบประสาท ยาใดลด skeletal-related events → denosumab หรือ zoledronic acid"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ B เมื่อเติมเคสแล้ว — ต้นฉบับที่ถามสั้น ๆ นั้นทั้ง FOBT และ polypectomy เป็น secondary prevention ตามที่คีย์เขียนเองว่า \"น่าจะได้ทั้งคู่\" จึงเติมว่าผู้ป่วยพบ adenoma แล้ว การตรวจ FOBT ไม่มีประโยชน์ต่อผู้ป่วยรายนี้; บางตำราจัด polypectomy เป็น primary prevention ของ \"มะเร็ง\" (เพราะตัด precursor ก่อนกลายเป็นมะเร็ง) แต่ Schwartz จัดการป้องกันมะเร็งในผู้ที่มี premalignant condition เป็น secondary prevention; สอดคล้องกับข้อสอบชุด 77D ที่ตอบว่าการผ่าตัด DCIS ที่พบจาก screening เป็น secondary prevention. ความมั่นใจปานกลางถึงสูง","page":6,"page2":4,"orig":"Surgical Oncology 4","stem":"A 60-year-old man undergoes colonoscopy, which shows a 1.5-cm pedunculated tubular adenoma in the sigmoid colon. Which intervention for this patient is secondary prevention of colorectal cancer?","gray":"Secondary prevention — A. Fecal occult blood test B. Polypectomy","opts":["Fecal occult blood testing","Colonoscopic polypectomy","High-fiber diet and smoking cessation","Adjuvant chemotherapy after resection","CEA surveillance after curative resection"],"ans":1,"key":"B Polypectomy (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ คีย์เขียนเองว่า \"จริงๆก็น่าจะได้ทั้งคู่\" — ต้นฉบับถามสั้น ๆ และ FOBT (screening) ก็เป็น secondary prevention; เติมเคสใน stem ว่าผู้ป่วยตรวจพบ adenoma แล้ว ให้ polypectomy เป็นคำตอบเดียว","interp":"ถามระดับของการป้องกันโรค (primary, secondary, tertiary) — ผู้ป่วยรายนี้<b>ตรวจพบรอยโรค premalignant แล้ว</b> จึงถามว่าการกระทำใดคือการตรวจพบและรักษาระยะเริ่มต้น","why":"<b>Secondary prevention</b> = ตรวจพบและรักษาโรคในระยะ premalignant หรือ early ก่อนมีอาการ เพื่อหยุดไม่ให้โรคดำเนินต่อ (Schwartz: \"prevent cancer in individuals with premalignant conditions\") → ผู้ป่วยมี tubular adenoma 1.5 cm ซึ่งเป็น precursor ของ CRC (adenoma–carcinoma sequence) การ<b>ตัด polyp ออกทาง colonoscopy</b> จึงเป็น secondary prevention ที่ตรงกับผู้ป่วยรายนี้ — National Polyp Study แสดงว่า polypectomy ลดอุบัติการณ์และอัตราตายจาก CRC","wrong":{"A":"FOBT หรือ FIT เป็น secondary prevention (screening) สำหรับ<b>ประชากรทั่วไปที่ไม่มีอาการ</b> อายุ 45–75 ปี แต่ผู้ป่วยรายนี้ตรวจ colonoscopy พบรอยโรคแล้ว การตรวจ FOBT ไม่มีประโยชน์เพิ่ม; ในโจทย์ต้นฉบับที่ถามสั้น ๆ ว่า \"Secondary prevention\" ช้อยนี้ก็ถูก (คีย์จึงเขียนว่าได้ทั้งคู่) — จะเป็นคำตอบถ้าโจทย์เป็นชายอายุ 50 ปีไม่มีอาการมาขอตรวจคัดกรอง","C":"อาหารเส้นใยสูงและเลิกบุหรี่เป็น <b>primary prevention</b> ลดการเกิดโรคในคนที่ยังไม่มีรอยโรค (รวมถึงลดเนื้อแดงและเนื้อแปรรูป, ออกกำลังกาย, คุมน้ำหนัก, aspirin ในบางกลุ่ม); จะถูกถ้าถาม primary prevention","D":"Adjuvant chemotherapy หลังผ่าตัดมะเร็งเป็น <b>tertiary prevention</b> (ลดการกลับเป็นซ้ำหลังเป็นโรคแล้ว) หรือบางตำราถือเป็นส่วนของการรักษา; จะถูกถ้าถามการป้องกันระดับ tertiary ใน stage III colon cancer","E":"CEA surveillance และ colonoscopy ติดตามหลังผ่าตัด curative เป็น <b>tertiary prevention</b> (ตรวจหาการกลับเป็นซ้ำเพื่อลดภาวะแทรกซ้อนและอัตราตาย); จะถูกถ้าถามการติดตามหลังรักษามะเร็งแล้ว"},"trap":"คิดว่า polypectomy คือการ \"ป้องกันไม่ให้เกิดมะเร็ง\" จึงเป็น primary — แต่การกำหนดระดับดูจากว่าผู้ป่วย<b>มีรอยโรค (premalignant) แล้วหรือยัง</b>; มีแล้วแล้วตรวจพบและกำจัด = secondary","summary":["Primary prevention: ป้องกันไม่ให้เกิดโรคในคนที่ยังไม่มีรอยโรค → ปรับอาหาร, เลิกบุหรี่, ออกกำลังกาย, วัคซีน HBV และ HPV, chemoprevention (tamoxifen ใน high-risk breast), prophylactic surgery (colectomy ใน FAP, mastectomy หรือ salpingo-oophorectomy ใน BRCA)","Secondary prevention: ตรวจพบและรักษาระยะ premalignant หรือ early ก่อนมีอาการ → screening (FOBT, FIT, colonoscopy, mammogram, Pap smear), polypectomy, รักษา CIN, ผ่าตัด DCIS ที่พบจาก screening","Tertiary prevention: ลดภาวะแทรกซ้อน การกลับเป็นซ้ำ และความพิการหลังเป็นโรคแล้ว → adjuvant therapy, surveillance หลังรักษา, rehabilitation","CRC screening (USPSTF 2021): อายุ 45–75 ปี เลือก FIT ทุกปี, stool DNA-FIT ทุก 1–3 ปี, colonoscopy ทุก 10 ปี, CT colonography หรือ flexible sigmoidoscopy ทุก 5 ปี; 76–85 ปีพิจารณาเป็นราย","FOBT หรือ FIT ผลบวก ต้องตามด้วย colonoscopy เสมอ","Adenoma ที่เสี่ยงสูง (≥1 cm, villous, high-grade dysplasia, ≥3 ตัว) ต้อง surveillance colonoscopy ถี่ขึ้น","ดูข้อ 699, 700, 701, 703 (oncology principles) และข้อ 700, 757 (colorectal carcinogenesis และ polyp)"],"notes":"ไฟล์เฉลยบท Surgical Oncology แถว 4: <b>B</b> — คำอธิบาย <b>\"จริงๆก็น่าจะได้ทั้งคู่\"</b><br>ต้นฉบับโจทย์มีแค่คำว่า \"Secondary prevention\" กับช้อย 2 ตัว (A Fecal occult blood test, B Polypectomy) — เราเติมเคสใน stem (ชายอายุ 60 ปี colonoscopy พบ pedunculated tubular adenoma 1.5 cm ที่ sigmoid colon) เพื่อให้เหลือคำตอบเดียวตรงกับคีย์ B; ช้อย B เขียนเป็น Colonoscopic polypectomy; C, D, E แต่งเพิ่ม","mnemonic":"<b>ยังไม่มีโรค = primary · มีรอยโรคแต่ยังไม่มีอาการ = secondary · เป็นโรคแล้ว = tertiary</b>","guide":"Schwartz 11th ed.; USPSTF colorectal cancer screening 2021","variants":["หญิงอายุ 50 ปีไม่มีอาการ ได้ mammogram พบ microcalcification ตรวจชิ้นเนื้อเป็น DCIS แล้วผ่าตัดออก การดูแลนี้เป็นการป้องกันระดับใด → secondary prevention","ผู้ป่วย FAP อายุ 20 ปี ทำ prophylactic proctocolectomy เป็นการป้องกันระดับใด → primary prevention ของมะเร็ง (ป้องกันก่อนเกิดมะเร็งในผู้ที่เสี่ยงทางพันธุกรรม) ตามที่ Schwartz จัด","ผู้ป่วย stage III colon cancer หลังผ่าตัดได้ FOLFOX และนัดตรวจ CEA ทุก 3–6 เดือน เป็นการป้องกันระดับใด → tertiary prevention"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง — สอดคล้องกับข้อสอบชุด 77D เรื่อง Li-Fraumeni (germline TP53) ที่มาด้วยมะเร็งตั้งแต่อายุน้อย","page":6,"page2":4,"orig":"Surgical Oncology 5","stem":"An elderly man with lung cancer is found to have a TP53 mutation in his tumor. Which statement is FALSE?","gray":"คนไข้แก่เป็นมะเร็งปอด มี Tp53 mutation ถามว่าข้อใดผิด — A. ได้รับ mutation นี้มาจากพ่อแม่ B. TP53 mutation ทำให้ DNA proliferate แบบบูมๆ และ repair ไม่ได้","opts":["The mutation was inherited from his parents","Cells with this mutation keep proliferating despite unrepaired DNA damage","TP53 is a tumor suppressor gene","Normal p53 induces cell-cycle arrest or apoptosis after DNA damage","Tobacco carcinogens can cause TP53 mutations"],"ans":0,"key":"A ได้รับ mutation นี้มาจากพ่อแม่ (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ถามข้อความที่<b>ผิด</b> — ผู้ป่วย<b>สูงอายุ</b>เป็นมะเร็งปอดแล้วพบ TP53 mutation ใน tumor ต้องแยก <b>somatic</b> (เกิดในเซลล์มะเร็งภายหลัง) กับ <b>germline</b> (ถ่ายทอดทางพันธุกรรม)","why":"TP53 mutation พบบ่อยที่สุดในมะเร็งมนุษย์ (มากกว่าครึ่ง) และในมะเร็งปอดของผู้สูบบุหรี่ส่วนใหญ่เป็น <b>somatic mutation</b> จาก carcinogen (benzo[a]pyrene ทำ G&gt;T transversion ที่ hotspot codon) — <b>ไม่ได้ถ่ายทอดจากพ่อแม่</b>; germline TP53 = <b>Li-Fraumeni syndrome</b> ซึ่งมาด้วยมะเร็งหลายชนิดตั้งแต่อายุน้อย (sarcoma, breast &lt;30 ปี, brain tumor, adrenocortical carcinoma, leukemia) ไม่ใช่มะเร็งปอดครั้งแรกตอนสูงอายุ ข้อความ A จึงผิด","wrong":{"B":"ข้อความนี้<b>ถูก</b> — p53 ที่เสียหน้าที่ทำให้เซลล์ที่ DNA เสียหายไม่ถูกหยุดที่ G1 และไม่ถูกส่งไป apoptosis จึงแบ่งตัวต่อพร้อม mutation ที่สะสมเพิ่ม (genomic instability) ตรงกับต้นฉบับ \"proliferate แบบบูมๆ และ repair ไม่ได้\"; จะเป็นคำตอบถ้าโจทย์ถามข้อความที่ถูก","C":"ข้อความนี้<b>ถูก</b> — TP53 เป็น tumor suppressor gene (chromosome 17p13) ต้องเสียทั้ง 2 allele หรือมี dominant-negative mutation จึงเสียหน้าที่ (two-hit hypothesis); จะเป็นคำตอบถ้าถามว่า gene ใดไม่ใช่ oncogene","D":"ข้อความนี้<b>ถูก</b> — p53 \"guardian of the genome\": เมื่อ DNA เสียหาย p53 เพิ่มขึ้น → กระตุ้น <b>p21</b> (CDK inhibitor) → หยุด cell cycle ที่ G1 ให้ซ่อม DNA; ถ้าซ่อมไม่ได้ → กระตุ้น <b>BAX</b>, PUMA → apoptosis; จะเป็นคำตอบถ้าถามกลไกของ p53 ปกติ","E":"ข้อความนี้<b>ถูก</b> — polycyclic aromatic hydrocarbon ในควันบุหรี่ (benzo[a]pyrene) ทำให้เกิด G&gt;T transversion ใน TP53 ของมะเร็งปอด; aflatoxin B1 ทำ TP53 codon 249 mutation ใน HCC; จะเป็นคำตอบถ้าถามสาเหตุของ somatic TP53 mutation"},"trap":"รู้ว่า TP53 เกี่ยวกับ Li-Fraumeni (hereditary) แล้วคิดว่า TP53 mutation ทุกรายถ่ายทอดทางพันธุกรรม — มะเร็งส่วนใหญ่ที่มี TP53 mutation เป็น somatic โดยเฉพาะผู้สูงอายุที่มีปัจจัยเสี่ยงชัด (บุหรี่)","summary":["Somatic mutation: เกิดภายหลังในเซลล์ใดเซลล์หนึ่ง ไม่ถ่ายทอดสู่ลูก พบในมะเร็งส่วนใหญ่ (sporadic) โดยเฉพาะผู้สูงอายุ; germline mutation: มีในทุกเซลล์ตั้งแต่เกิด ถ่ายทอดได้","TP53 (17p13) = tumor suppressor \"guardian of the genome\": DNA damage → p53 → p21 → G1 arrest เพื่อซ่อม หรือ BAX, PUMA → apoptosis; MDM2 เป็นตัวสลาย p53","TP53 mutation พบในมะเร็งมนุษย์มากกว่าครึ่ง; เป็นขั้นท้ายของ adenoma–carcinoma sequence ใน CRC","Li-Fraumeni syndrome (germline TP53, autosomal dominant): sarcoma, premenopausal breast cancer, brain tumor, adrenocortical carcinoma, leukemia ตั้งแต่อายุน้อยและหลายชนิดในคนเดียว; ใช้ Chompret criteria ส่งตรวจ","ข้อพึงระวังใน Li-Fraumeni: หลีกเลี่ยงรังสีถ้าทำได้ (เสี่ยง second cancer) และ surveillance ด้วย whole-body MRI","Two-hit hypothesis (Knudson): tumor suppressor ต้องเสียทั้ง 2 allele; hereditary syndrome เกิดมะเร็งเร็วเพราะมี hit แรกตั้งแต่เกิด","ดูข้อ 699, 700, 701, 702 (oncology principles)"],"notes":"ไฟล์เฉลยบท Surgical Oncology แถว 5: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับมีช้อยแค่ 2 ตัว: A \"ได้รับ mutation นี้มาจากพ่อแม่\" → The mutation was inherited from his parents; B \"TP53 mutation ทำให้ DNA proliferate แบบบูมๆ และ repair ไม่ได้\" → Cells with this mutation keep proliferating despite unrepaired DNA damage; C, D, E แต่งเพิ่ม (เป็นข้อความจริงทั้งหมด เพื่อให้มีข้อผิดข้อเดียว)<br>ในไฟล์โจทย์ บท Surgical Oncology จบที่ข้อนี้ แล้วมีหัวบท \"Professionalism and Surgical safety\" ต่อ","mnemonic":"<b>\"แก่ + บุหรี่ = somatic · เด็ก + มะเร็งหลายชนิดในครอบครัว = germline (Li-Fraumeni)\"</b>","guide":"Schwartz 11th ed.; NCCN Genetic/Familial High-Risk Assessment 2025","variants":["หญิงอายุ 28 ปีเป็นมะเร็งเต้านม แม่เป็น osteosarcoma ตอนอายุ 15 ปี น้องชายเป็น adrenocortical carcinoma ควรส่งตรวจ gene ใด → germline TP53 (Li-Fraumeni)","ผู้ป่วย HCC ในพื้นที่ที่กินถั่วลิสงขึ้นราบ่อย พบ TP53 codon 249 mutation สาเหตุคืออะไร → aflatoxin B1 (somatic mutation)","ข้อใดคือหน้าที่ของ p21 ที่ถูกกระตุ้นโดย p53 → CDK inhibitor ทำให้หยุด cell cycle ที่ G1"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง — สอดคล้องกับข้อสอบชุด 76C, 77A และ 77D เรื่องหลักจริยธรรม 4 ข้อ","page":6,"page2":4,"orig":"Professionalism 1","stem":"A competent patient who has been fully informed declines the recommended operation. The surgeon respects this decision. Which ethical principle does this reflect?","gray":"คนไข้ไม่อยากผ่า หมอเคารพอะไร — A. Autonomy","opts":["Autonomy","Beneficence","Non-maleficence","Justice","Confidentiality"],"ans":0,"key":"A Autonomy (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ผู้ป่วยที่<b>มี decision-making capacity</b> และได้รับข้อมูลครบ <b>ปฏิเสธการผ่าตัด</b> — แพทย์เคารพการตัดสินใจนั้น ถามว่าตรงกับหลักจริยธรรมข้อใด","why":"<b>Autonomy</b> (respect for autonomy) = เคารพสิทธิของผู้ป่วยที่มีความสามารถในการตัดสินใจเรื่องร่างกายของตนเอง รวมถึงสิทธิ<b>ปฏิเสธการรักษา</b>แม้แพทย์เห็นว่าเป็นประโยชน์ (informed refusal) — เงื่อนไขคือผู้ป่วยมี capacity (เข้าใจ จดจำ ชั่งน้ำหนัก และสื่อสารการตัดสินใจได้), ได้รับข้อมูลครบ (ประโยชน์ ความเสี่ยง ทางเลือก ผลของการไม่รักษา), ตัดสินใจโดยสมัครใจ; แพทย์ต้องบันทึกเวชระเบียน เสนอทางเลือกอื่น และนัดติดตาม ไม่ทอดทิ้งผู้ป่วย","wrong":{"B":"Beneficence = ทำสิ่งที่เป็นประโยชน์ต่อผู้ป่วย ถ้าแพทย์ยึดหลักนี้อย่างเดียวจะพยายามผ่าตัดเพราะเห็นว่าเป็นประโยชน์ ซึ่งขัดกับการเคารพการปฏิเสธ (paternalism); จะถูกถ้าโจทย์ถามหลักที่อยู่เบื้องหลังการแนะนำการผ่าตัดที่ดีที่สุดให้ผู้ป่วย หรือการช่วยชีวิตผู้ป่วยหมดสติในภาวะฉุกเฉิน","C":"Non-maleficence = ไม่ทำอันตรายต่อผู้ป่วย (primum non nocere); จะถูกถ้าโจทย์เป็นแพทย์ไม่ทำหัตถการที่ความเสี่ยงสูงกว่าประโยชน์ หรือหยุดยาที่ทำให้เกิดผลข้างเคียงรุนแรง","D":"Justice = ความเป็นธรรมในการกระจายทรัพยากรและการดูแลอย่างเท่าเทียม; จะถูกถ้าโจทย์ถามเรื่องการจัดสรรเตียง ICU อวัยวะปลูกถ่าย หรือการรักษาผู้ป่วยทุกคนเท่าเทียมโดยไม่เลือกฐานะ","E":"Confidentiality = การรักษาความลับของผู้ป่วย เป็นหน้าที่ทางวิชาชีพที่สัมพันธ์กับ autonomy แต่ไม่ใช่เรื่องการปฏิเสธการรักษา; จะถูกถ้าโจทย์เป็นญาติหรือนายจ้างขอทราบผลตรวจโดยผู้ป่วยไม่ยินยอม"},"trap":"เลือก beneficence เพราะคิดว่าแพทย์ \"ทำสิ่งที่ดีที่สุด\" ให้ผู้ป่วย — แต่สิ่งที่แพทย์ทำในโจทย์คือ<b>เคารพการตัดสินใจ</b>ของผู้ป่วย ซึ่งเป็น autonomy","summary":["4 principles (Beauchamp &amp; Childress): autonomy, beneficence, non-maleficence, justice","Autonomy: ผู้ป่วยมี capacity มีสิทธิยอมรับหรือปฏิเสธการรักษา แม้การปฏิเสธจะทำให้เสียชีวิต","Decision-making capacity: เข้าใจข้อมูล, จดจำได้, ชั่งน้ำหนักเปรียบเทียบได้, สื่อสารการตัดสินใจได้ — ประเมินเป็นรายการตัดสินใจ ไม่ใช่ทั้งคน","Informed refusal ที่ถูกต้อง: อธิบายผลของการไม่รักษา, ตรวจ capacity, เสนอทางเลือก, บันทึกเวชระเบียนและให้ผู้ป่วยลงนามปฏิเสธ, ดูแลต่อและเปิดโอกาสให้เปลี่ยนใจ","ข้อยกเว้นของ autonomy: ผู้ป่วยขาด capacity (ใช้ advance directive หรือผู้แทนโดยชอบธรรมตัดสินใจตาม best interest), ภาวะฉุกเฉินคุกคามชีวิตที่ไม่สามารถขอความยินยอมได้","ดูข้อ 704, 705, 706, 707, 708 (ethics และ safety)"],"notes":"ไฟล์เฉลยบท Professionalism and Surgical safety แถว 1: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับมีช้อยเดียว \"A. Autonomy\" — B, C, D, E แต่งเพิ่ม; stem ต้นฉบับ \"คนไข้ไม่อยากผ่า หมอเคารพอะไร\" เราเขียนเป็นเคสผู้ป่วยที่มี capacity ได้รับข้อมูลครบแล้วปฏิเสธการผ่าตัด","mnemonic":"","guide":"Beauchamp &amp; Childress Principles of Biomedical Ethics 8th ed. 2019","variants":["ผู้ป่วยหญิงอายุ 40 ปีเป็นมะเร็งเต้านม ระยะแรก มี capacity ปฏิเสธการผ่าตัดหลังได้ข้อมูลครบ แพทย์ควรทำอย่างไร → เคารพการตัดสินใจ บันทึก เสนอทางเลือก และนัดติดตาม","ผู้ป่วยหมดสติจาก ruptured spleen ไม่มีญาติ แพทย์ผ่าตัดทันทีโดยไม่มี consent ใช้หลักใด → beneficence (emergency exception)","โรงพยาบาลมี ICU เหลือ 1 เตียงแต่มีผู้ป่วยวิกฤต 2 คน การพิจารณาตามเกณฑ์ที่โปร่งใสคือหลักใด → justice"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง","page":6,"page2":4,"orig":"Professionalism 2","stem":"A woman comes to a male doctor with a breast problem. During the history, she behaves flirtatiously toward him. What should the doctor do?","gray":"a sexy woman with breast problem อ่อยมึง มึงจะทำยังไง — A. ตามพยาบาลมาอยู่ด้วย แล้วซักประวัติต่อ B. ตอบเท่าที่ได้ C. ส่งให้หมอคนอื่นตรวจแทน D. ซักประวัติปกติต่อ แล้วค่อยถามให้ deep ขึ้น 😏","opts":["Call a nurse to stay as a chaperone and continue the history","Answer only as much as possible","Refer her to another doctor for the examination","Continue the history and ask more personal questions","Arrange to meet her privately outside the clinic"],"ans":0,"key":"A ตามพยาบาลมาอยู่ด้วย แล้วซักประวัติต่อ (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ผู้ป่วยแสดงพฤติกรรมเชิงชู้สาวต่อแพทย์ระหว่างการซักประวัติปัญหาเต้านม (ซึ่งต้องตรวจเต้านม = intimate examination) — ถามการรักษา <b>professional boundaries</b> ที่เหมาะสมโดยยังดูแลผู้ป่วยต่อ","why":"แพทย์ต้องรักษา<b>ขอบเขตทางวิชาชีพ</b> และปกป้องทั้งผู้ป่วยและตนเอง → <b>เชิญพยาบาลมาเป็น chaperone</b> อยู่ด้วยตลอดการซักประวัติและการตรวจเต้านม (intimate examination ควรมี chaperone เสมอ โดยเฉพาะแพทย์ชายตรวจผู้ป่วยหญิง) แล้ว<b>ดูแลต่อตามปกติ</b>อย่างสุภาพและเป็นกลาง ไม่ตอบสนองต่อพฤติกรรมนั้น และบันทึกเหตุการณ์ในเวชระเบียน — ผู้ป่วยยังได้รับการดูแลที่ต้องการ ไม่ถูกทอดทิ้ง","wrong":{"B":"การตอบเท่าที่ได้หรือตอบแบบสั้น ๆ ไม่ได้จัดการปัญหาขอบเขตและไม่มีพยานคุ้มครองทั้งสองฝ่าย อีกทั้งอาจทำให้การซักประวัติไม่ครบจนผู้ป่วยเสียประโยชน์; ไม่มีสถานการณ์ที่ช้อยนี้เป็นคำตอบที่ดีที่สุด แต่การวางตัวสุภาพเป็นกลางเป็นส่วนหนึ่งของคำตอบที่ถูก","C":"การส่งต่อให้แพทย์คนอื่นทันทีเป็นการหลีกเลี่ยงหน้าที่และอาจทำให้การดูแลล่าช้า; ควรพิจารณาส่งต่อเฉพาะเมื่อพฤติกรรมยังคงอยู่หลังตั้งขอบเขตแล้ว หรือความสัมพันธ์ทางวิชาชีพเสียไปจนดูแลต่ออย่างเหมาะสมไม่ได้ — จะถูกถ้าโจทย์เป็นผู้ป่วยที่ยังคงตามติดหรือแสดงพฤติกรรมเชิงชู้สาวซ้ำ ๆ แม้แพทย์ตั้งขอบเขตชัดเจนแล้ว","D":"การถามเรื่องส่วนตัวลึกขึ้นที่ไม่เกี่ยวกับปัญหาทางคลินิกเป็นการ<b>ละเมิดขอบเขต</b> (boundary violation) และเป็นจุดเริ่มของ sexual misconduct; ต้นฉบับช้อยนี้มี emoji 😏 ต่อท้าย แสดงว่าผู้จดตั้งใจเป็นช้อยตลก; ไม่มีสถานการณ์ที่ถูก","E":"การนัดพบส่วนตัวนอกคลินิกเป็น sexual boundary violation ที่ร้ายแรง แพทย์ห้ามมีความสัมพันธ์เชิงชู้สาวหรือทางเพศกับผู้ป่วยในความดูแลเด็ดขาด; ไม่มีสถานการณ์ที่ถูก"},"trap":"เลือกส่งต่อแพทย์คนอื่นเพราะคิดว่าเลี่ยงปัญหาได้ — แต่ก่อนส่งต่อ แพทย์ควรจัดการด้วยการมี chaperone และตั้งขอบเขต แล้วดูแลผู้ป่วยต่อ","summary":["Professional boundaries: ความรับผิดชอบในการรักษาขอบเขตเป็นของแพทย์เสมอ ไม่ว่าผู้ป่วยจะเป็นฝ่ายเริ่ม","Chaperone: เสนอให้มีทุกครั้งที่ตรวจ intimate examination (เต้านม, อวัยวะเพศ, ทวารหนัก) ควรเป็นบุคลากรทางการแพทย์ที่ได้รับการอบรม ไม่ใช่ญาติ; บันทึกชื่อ chaperone หรือการที่ผู้ป่วยปฏิเสธ","เมื่อผู้ป่วยแสดงพฤติกรรมเชิงชู้สาว: ตอบสนองอย่างสุภาพ เป็นกลาง ไม่ตอบรับ, มี chaperone, ดูแลทางคลินิกต่อ, บันทึกเหตุการณ์, ปรึกษาหัวหน้าถ้าเกิดซ้ำ","ส่งต่อแพทย์คนอื่นได้เมื่อพฤติกรรมไม่หยุดจนความสัมพันธ์ทางวิชาชีพเสียไป โดยต้องจัดการส่งต่ออย่างเหมาะสม ไม่ทอดทิ้ง","ห้ามความสัมพันธ์ทางเพศหรือเชิงชู้สาวกับผู้ป่วยในความดูแลโดยเด็ดขาด รวมถึงการใช้ข้อมูลผู้ป่วยติดต่อเรื่องส่วนตัว","ดูข้อ 704, 706, 707, 708 (ethics และ safety)"],"notes":"ไฟล์เฉลยบท Professionalism and Surgical safety แถว 2: <b>A</b> (ช่องคำอธิบายว่าง)<br>โจทย์ต้นฉบับเขียนภาษาไม่สุภาพ \"a sexy woman with breast problem อ่อยมึง มึงจะทำยังไง\" — เราเขียน stem เป็นภาษาทางการ<br>ช้อย D ในต้นฉบับมี <b>emoji 😏</b> ต่อท้าย (\"ซักประวัติปกติต่อ แล้วค่อยถามให้ deep ขึ้น 😏\") ซึ่งเป็นรูปฝังในไฟล์ — ไม่ได้ใช้เป็นรูปโจทย์<br>ช้อย A–D แปลจากต้นฉบับ (A \"ตามพยาบาลมาอยู่ด้วย แล้วซักประวัติต่อ\", B \"ตอบเท่าที่ได้\", C \"ส่งให้หมอคนอื่นตรวจแทน\", D \"ซักประวัติปกติต่อ แล้วค่อยถามให้ deep ขึ้น\"); E แต่งเพิ่ม","mnemonic":"","guide":"GMC Intimate examinations and chaperones 2024","variants":["แพทย์ชายต้องตรวจทวารหนักผู้ป่วยหญิงอายุ 25 ปีที่มีเลือดออกทางทวาร ผู้ป่วยปฏิเสธ chaperone ควรทำอย่างไร → อธิบายเหตุผล ถ้ายังปฏิเสธพิจารณาเลื่อนการตรวจหรือให้แพทย์หญิงตรวจ และบันทึก","ผู้ป่วยส่งข้อความเชิงชู้สาวถึงแพทย์ทาง social media หลายครั้ง แม้แพทย์เคยบอกแล้วว่าไม่เหมาะสม → ไม่ตอบรับ บันทึก ปรึกษาหัวหน้า และพิจารณาส่งต่อการดูแลอย่างเหมาะสม","แพทย์ประจำบ้านต้องการคบหาผู้ป่วยที่ยังรักษาอยู่ในหอผู้ป่วย ผิดหลักใด → professional boundary (ห้ามความสัมพันธ์กับผู้ป่วยในความดูแล)"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง — ข้อเดียวกับข้อสอบชุด 77B และสอดคล้องกับชุด 77A (time out ลด surgical error)","page":7,"page2":4,"orig":"Professionalism 3","stem":"In the WHO Surgical Safety Checklist, what is the purpose of the time out?","gray":"Time out ทำเพื่ออะไร — A. To confirm patient name, procedure, and where the incision will be made B. To check the anaesthesia machine and medication C. To count the instrument, sponge and needle used","opts":["To confirm the patient, procedure and incision site","To check the anesthesia machine and medication","To count the instruments, sponges and needles used","To confirm fasting status before induction","To review recovery concerns before leaving the room"],"ans":0,"key":"A To confirm patient name, procedure, and where the incision will be made (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ถามว่า <b>Time Out</b> ใน WHO Surgical Safety Checklist ทำเพื่ออะไร — ต้องแยก 3 ช่วงของ checklist ว่ารายการไหนอยู่ช่วงใด","why":"<b>Time Out</b> ทำ<b>ก่อนลงมีด (before skin incision)</b> ทั้งทีมหยุดพร้อมกัน: สมาชิกแนะนำชื่อและบทบาท, <b>ยืนยันชื่อผู้ป่วย หัตถการ และตำแหน่งที่จะผ่า</b> (ป้องกัน wrong patient, wrong procedure, wrong site), ยืนยันว่าได้ prophylactic antibiotic ภายใน 60 นาที, คาดการณ์ critical events (ศัลยแพทย์: ขั้นตอนวิกฤต เวลา blood loss; วิสัญญี: ข้อกังวลเฉพาะผู้ป่วย; พยาบาล: sterility และเครื่องมือ) และ essential imaging แสดงอยู่หรือไม่","wrong":{"B":"การตรวจ anesthesia machine และยาอยู่ในช่วง <b>Sign In</b> (ก่อน induction) ร่วมกับการยืนยันตัวผู้ป่วย site marking consent, pulse oximeter, allergy, difficult airway, ความเสี่ยงเสียเลือด &gt;500 mL (เด็ก 7 mL/kg); จะถูกถ้าโจทย์ถามสิ่งที่ทำก่อน induction","C":"การนับเครื่องมือ ผ้าซับ และเข็ม อยู่ในช่วง <b>Sign Out</b> (ก่อนผู้ป่วยออกจากห้องผ่าตัด) ป้องกัน retained surgical item; จะถูกถ้าถามสิ่งที่ทำก่อนปิดแผลหรือก่อนออกจากห้อง","D":"การยืนยัน NPO status เป็นส่วนของการประเมินก่อนระงับความรู้สึกและ Sign In ไม่ใช่วัตถุประสงค์ของ Time Out; จะใกล้เคียงถ้าถามการเตรียมผู้ป่วยก่อน induction (aspiration risk)","E":"การทบทวนข้อกังวลสำหรับ recovery และการจัดการหลังผ่าตัดอยู่ในช่วง <b>Sign Out</b> ร่วมกับยืนยันชื่อหัตถการ, นับเครื่องมือ, ติดป้าย specimen และปัญหาเครื่องมือ; จะถูกถ้าถามสิ่งที่ทำตอนจบผ่าตัด"},"trap":"สับสนว่าการยืนยันตัวผู้ป่วยมีทั้งใน Sign In และ Time Out — Time Out คือการยืนยัน<b>ครั้งสุดท้ายพร้อมทั้งทีมก่อนลงมีด</b> ส่วนการตรวจเครื่องดมยาอยู่ Sign In และการนับเครื่องมืออยู่ Sign Out","summary":["WHO Surgical Safety Checklist (2009) มี 3 ช่วง: Sign In → Time Out → Sign Out; ลด complication และ mortality อย่างมีนัยสำคัญในการศึกษาหลายประเทศ","Sign In (ก่อน induction): ยืนยัน identity, site, procedure, consent; site marking; anesthesia machine และยา; pulse oximeter; allergy; difficult airway หรือ aspiration risk; blood loss risk &gt;500 mL (เด็ก 7 mL/kg)","Time Out (ก่อนลงมีด): ทีมแนะนำตัว; ยืนยันผู้ป่วย หัตถการ ตำแหน่งผ่า; antibiotic prophylaxis ภายใน 60 นาที; anticipated critical events ของศัลยแพทย์ วิสัญญี พยาบาล; essential imaging","Sign Out (ก่อนออกจากห้อง): ชื่อหัตถการที่ทำจริง; นับเครื่องมือ ผ้าซับ เข็มครบ; specimen labeling; ปัญหาเครื่องมือ; key concerns สำหรับ recovery","Universal Protocol (Joint Commission): pre-procedure verification + site marking + time out ป้องกัน wrong site, wrong procedure, wrong person surgery","ดูข้อ 704, 705, 707, 708 (ethics และ safety)"],"notes":"ไฟล์เฉลยบท Professionalism and Surgical safety แถว 3: <b>A</b> (ช่องคำอธิบายว่าง)<br>ช้อย A–C แปลจากต้นฉบับ (A \"To confirm patient name, procedure, and where the incision will be made\" → To confirm the patient, procedure and incision site; B \"To check the anaesthesia machine and medication\"; C \"To count the instrument, sponge and needle used\"); D, E แต่งเพิ่ม","mnemonic":"<b>In = ก่อนหลับ · Out = ก่อนออก · Time Out = ก่อนกรีด</b>","guide":"WHO Surgical Safety Checklist 2009","variants":["ก่อนให้ยานำสลบ ทีมยืนยันว่ามี pulse oximeter ทำงานและผู้ป่วยไม่มีประวัติแพ้ยา อยู่ในช่วงใดของ checklist → Sign In","ศัลยแพทย์กำลังจะผ่าตัดไตซ้าย ทีมหยุดยืนยันตำแหน่งและพบว่า site marking อยู่ด้านขวา ควรทำอย่างไร → หยุด ยืนยันกับเวชระเบียน ภาพถ่ายรังสี และผู้ป่วย ก่อนลงมีด (Time Out)","หลังปิดแผลผ่าตัดช่องท้อง พยาบาลนับผ้าซับขาด 1 ผืน ควรทำอย่างไร → นับซ้ำ ค้นหาในแผลและห้อง และทำ x-ray ก่อนผู้ป่วยออกจากห้อง"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง — สอดคล้องกับข้อสอบชุด 77D เรื่อง hernia ร่วมปัสสาวะไม่ออก (ไม่ควรข้ามการปรึกษา urology)","page":7,"page2":4,"orig":"Professionalism 4","stem":"A man is scheduled for inguinal hernia repair. Which statement about his preoperative care and consent is correct?","gray":"คนไข้ผ่า hernia ถามว่าข้อใดถูก — A. บอกคนไข้ว่าผ่าอะไร ใช้ mesh อะไร B. ไม่บอกเรื่อง mesh C. ถ้าคนไข้มีปัญหาเรื่องฉี่ไม่จำเป็นต้องปรึกษา URO","opts":["Explain the operation and the mesh to be used","Do not mention the mesh","No urology consultation is needed for voiding problems","Let a relative sign consent instead of the competent patient","Avoid discussing complications to reduce anxiety"],"ans":0,"key":"A บอกคนไข้ว่าผ่าอะไร ใช้ mesh อะไร (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ถามหลัก <b>informed consent</b> และการเตรียมผู้ป่วยก่อนผ่าตัด inguinal hernia — ข้อมูลอะไรที่ผู้ป่วยต้องได้รับ และปัญหาร่วมอะไรที่ต้องจัดการก่อนผ่า","why":"Informed consent ที่ถูกต้องต้องอธิบาย<b>ชนิดการผ่าตัด</b> (open Lichtenstein หรือ laparoscopic TEP, TAPP) และ<b>วัสดุ mesh</b> ที่จะใส่ (polypropylene เป็น permanent implant) พร้อมความเสี่ยงที่สำคัญ (recurrence, chronic groin pain, hematoma, seroma, infection, urinary retention, testicular atrophy) ทางเลือก (watchful waiting ในชายที่ไม่มีอาการหรืออาการน้อย, tissue repair) และผลของการไม่ผ่าตัด — mesh เป็น implant ถาวรที่ผู้ป่วยมีสิทธิทราบ (กรณีฟ้องร้องเรื่อง mesh ทำให้การ disclose ชนิดวัสดุสำคัญมาก)","wrong":{"B":"การไม่บอกเรื่อง mesh ขัดหลัก autonomy และ informed consent เพราะ mesh เป็นวัสดุถาวรที่มีความเสี่ยงเฉพาะ (mesh infection, chronic pain, migration) ผู้ป่วยบางรายอาจไม่ต้องการ implant และเลือก tissue repair (Shouldice) ได้; ไม่มีสถานการณ์ที่ถูก","C":"ผิด — ผู้ป่วยที่มีปัญหาปัสสาวะ (LUTS, BPH) ต้องประเมินหรือปรึกษา urology ก่อนผ่าตัด เพราะเสี่ยง postoperative urinary retention และการเบ่งปัสสาวะเรื้อรังเพิ่ม intra-abdominal pressure ทำให้ recurrence; BPH ที่มีอาการมากอาจต้องรักษาก่อน; จะใกล้เคียงถ้าโจทย์บอกว่าผู้ป่วยไม่มีอาการทางเดินปัสสาวะเลย","D":"ผู้ใหญ่ที่มี capacity ต้องลงนามยินยอมด้วยตนเอง ญาติลงนามแทนไม่ได้ (ญาติลงนามได้เป็นพยาน); จะถูกถ้าผู้ป่วยขาด capacity (dementia รุนแรง) ซึ่งให้ผู้แทนโดยชอบธรรมตัดสินใจตาม best interest","E":"การไม่บอกภาวะแทรกซ้อนเพื่อลดความกังวล (therapeutic privilege) ใช้ไม่ได้ในบริบทนี้ ผู้ป่วยต้องได้รับข้อมูลความเสี่ยงที่มีนัยสำคัญต่อการตัดสินใจ (material risk); ใช้ได้น้อยมากเฉพาะเมื่อข้อมูลจะก่ออันตรายร้ายแรงต่อผู้ป่วย และต้องบันทึกเหตุผล"},"trap":"คิดว่าปัญหาปัสสาวะเป็นเรื่องแยกจากการผ่าตัด hernia — แต่ BPH เป็นทั้งปัจจัยเสี่ยงของ hernia (เบ่ง) และ postoperative urinary retention จึงต้องประเมินก่อนผ่า","summary":["Informed consent: capacity, ข้อมูลครบ (การวินิจฉัย ชนิดผ่าตัด วัสดุที่ใส่ ประโยชน์ ความเสี่ยงสำคัญ ทางเลือก ผลของการไม่รักษา), สมัครใจ, ลงนามโดยผู้ป่วยเอง, บันทึก","Material risk (Montgomery 2015): ต้องบอกความเสี่ยงที่ผู้ป่วยทั่วไปหรือผู้ป่วยรายนั้นจะถือว่าสำคัญ ไม่ใช่แค่ที่แพทย์คิดว่าสำคัญ","Inguinal hernia repair ผู้ใหญ่: mesh repair เป็นมาตรฐาน (Lichtenstein หรือ TEP, TAPP); ความเสี่ยง recurrence, chronic pain ราว 10–12%, urinary retention, hematoma, seroma, ischemic orchitis, testicular atrophy","ก่อนผ่าตัดประเมินปัจจัยที่เพิ่ม intra-abdominal pressure: BPH (LUTS), chronic cough, constipation, ascites — แก้หรือปรึกษาแผนกที่เกี่ยวข้อง","ผู้ป่วยที่มี BPH หรือ LUTS เสี่ยง postoperative urinary retention: ให้ปัสสาวะก่อนเข้าห้องผ่าตัด, จำกัดสารน้ำ, พิจารณา local anesthesia, เตรียม catheterization","ดูข้อ 704, 705, 706, 708 (ethics และ safety) และข้อ 707, 716 (hernia กับปัญหาปัสสาวะ)"],"notes":"ไฟล์เฉลยบท Professionalism and Surgical safety แถว 4: <b>A</b> (ช่องคำอธิบายว่าง)<br>ช้อย A–C แปลจากต้นฉบับ (A \"บอกคนไข้ว่าผ่าอะไร ใช้ mesh อะไร\", B \"ไม่บอกเรื่อง mesh\", C \"ถ้าคนไข้มีปัญหาเรื่องฉี่ไม่จำเป็นต้องปรึกษา URO\"); D, E แต่งเพิ่ม; stem ต้นฉบับ \"คนไข้ผ่า hernia\" เราเขียนเป็น inguinal hernia repair","mnemonic":"","guide":"HerniaSurge 2018; GMC Decision making and consent 2020","variants":["ชายอายุ 70 ปีมี right inguinal hernia และปัสสาวะไม่พุ่ง ตื่นปัสสาวะกลางคืน 4 ครั้ง ก่อนนัดผ่าตัดควรทำอะไร → ประเมิน BPH หรือปรึกษา urology ก่อน","ผู้ป่วยถามว่า mesh ที่จะใส่จะอยู่ในตัวตลอดไปหรือไม่ และไม่อยากใส่วัสดุแปลกปลอม ทางเลือกคืออะไร → tissue repair (Shouldice) โดยบอกว่า recurrence สูงกว่า mesh","ผู้ป่วย dementia รุนแรงมี incarcerated hernia ต้องผ่าตัดฉุกเฉิน ใครเป็นผู้ให้ความยินยอม → ผู้แทนโดยชอบธรรมตัดสินใจตาม best interest หรือทำตามภาวะฉุกเฉิน"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ B มั่นใจสูง","page":7,"page2":4,"orig":"Professionalism 5","stem":"A doctor is about to insert a nasogastric tube in a patient with massive upper gastrointestinal bleeding. Which set of personal protective equipment is most appropriate?","gray":"PPE for ng with massive UGIB in pt — 1 face shield , 2 plastic apron , 3 sterile gloves , 4 disposable gloves , 5 n95 , 6 surgical mask , 7 something respirator? — 1. 1 2 3 6 2. 1 2 4 6","opts":["Face shield, plastic apron, sterile gloves, surgical mask","Face shield, plastic apron, disposable gloves, surgical mask","N95 respirator, plastic apron, sterile gloves","Surgical mask and disposable gloves only","Powered air-purifying respirator and sterile gown"],"ans":1,"key":"B 1 2 4 6 (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"การใส่ NG tube ในผู้ป่วย massive UGIB เสี่ยง<b>เลือดและสารคัดหลั่งกระเด็น</b> (ผู้ป่วยไอ ขย้อน อาเจียนเลือด) — ถามชุด PPE ตาม standard precautions ที่เหมาะกับหัตถการ (clean ไม่ใช่ sterile) และชนิดการแพร่เชื้อ","why":"ตาม <b>standard precautions</b>: หัตถการที่อาจมีเลือดหรือสารคัดหลั่งกระเด็น → ป้องกันตา หน้า จมูก ปาก ด้วย <b>face shield + surgical mask</b>, ป้องกันเสื้อผ้าด้วย <b>plastic apron</b> (หรือ gown กันน้ำ) และ<b>ถุงมือ</b> — การใส่ NG เป็นหัตถการ <b>clean ไม่ใช่ sterile</b> จึงใช้ <b>disposable (non-sterile) gloves</b> = ชุด 1 2 4 6","wrong":{"A":"ชุดนี้ป้องกันการกระเด็นได้ แต่ <b>sterile gloves ไม่จำเป็น</b> เพราะทางเดินอาหารไม่ใช่ sterile site การใส่ NG เป็น clean procedure (สิ้นเปลือง); จะถูกถ้าหัตถการเป็น sterile procedure ที่มีการกระเด็น เช่นการใส่ central venous catheter, chest drain หรือ urinary catheter ใช้ sterile gloves","C":"N95 ใช้สำหรับ <b>airborne precautions</b> (TB, measles, varicella) หรือ aerosol-generating procedure ในผู้ป่วยโรคติดต่อทางอากาศ ชุดนี้ไม่มี face shield ป้องกันตาจากเลือดกระเด็น และ sterile gloves ไม่จำเป็น; จะถูกถ้าผู้ป่วยมี pulmonary TB ที่ยังไม่ได้รักษาแล้วทำ bronchoscopy","D":"Surgical mask กับถุงมืออย่างเดียวไม่ป้องกันตาและเสื้อผ้าจากเลือดที่กระเด็นจำนวนมาก; จะถูกถ้าเป็นหัตถการที่เสี่ยงสัมผัสเลือดน้อยในผู้ป่วยที่มี droplet precautions เช่นการเจาะเลือดผู้ป่วย influenza","E":"PAPR และ sterile gown เกินความจำเป็นมาก ใช้ใน airborne pathogen ร่วม aerosol-generating procedure ที่เสี่ยงสูง หรือผู้ที่ fit-test N95 ไม่ผ่าน (Ebola หรือ COVID-19 ในบางบริบท); จะถูกถ้าผู้ป่วยติดเชื้อทางอากาศอันตรายสูงและทำ intubation"},"trap":"เลือก sterile gloves เพราะคิดว่าเลือดออกมากต้องป้องกันมากที่สุด — ระดับการป้องกันเลือดกระเด็นมาจาก face shield, mask และ apron ส่วนถุงมือเลือกตามว่าหัตถการ sterile หรือไม่","summary":["Standard precautions ใช้กับผู้ป่วยทุกราย: hand hygiene, PPE ตามความเสี่ยงสัมผัส, respiratory hygiene, safe injection, การจัดการของมีคม","PPE ตามความเสี่ยง: สัมผัสเลือด → ถุงมือ; อาจกระเด็นถูกเสื้อผ้า → apron หรือ gown กันน้ำ; อาจกระเด็นเข้าตา จมูก ปาก → face shield หรือ goggles + surgical mask","Clean procedure (NG, ดูดเสมหะ, ทำแผลทั่วไป) ใช้ disposable gloves; sterile procedure (central line, urinary catheter, chest drain, lumbar puncture) ใช้ sterile gloves","Transmission-based precautions: contact (MRSA, C. difficile) → gown + gloves; droplet (influenza, meningococcus) → surgical mask; airborne (TB, measles, varicella) → N95 + airborne infection isolation room","Aerosol-generating procedures (intubation, bronchoscopy, NIV, CPR) ในโรคติดต่อทางอากาศ → N95 หรือ PAPR + eye protection + gown + gloves","ลำดับถอด PPE: ถุงมือ → face shield หรือ goggles → gown หรือ apron → mask หรือ respirator แล้ว hand hygiene","ดูข้อ 704, 705, 706, 707 (ethics และ safety)"],"notes":"ไฟล์เฉลยบท Professionalism and Surgical safety แถว 5: <b>B</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับให้รายการอุปกรณ์เป็นเลข \"1 face shield , 2 plastic apron , 3 sterile gloves , 4 disposable gloves , 5 n95 , 6 surgical mask , 7 something respirator?\" (อุปกรณ์หมายเลข 7 ผู้จดจำชื่อไม่ได้ จึงเขียน \"something respirator?\") แล้วช้อยเป็นเลข <b>1. 1 2 3 6</b> และ <b>2. 1 2 4 6</b> — คีย์ B = ช้อยที่ 2 (1 2 4 6); ช้อยของเราเขียนเป็นชื่ออุปกรณ์: A = 1 2 3 6, B = 1 2 4 6; C, D, E แต่งเพิ่ม","mnemonic":"<b>กระเด็น = หน้า + ตัว + มือ (shield, mask, apron, gloves) · sterile เฉพาะหัตถการ sterile</b>","guide":"CDC Isolation Precautions 2007","variants":["พยาบาลจะดูดเสมหะผู้ป่วย pulmonary TB ที่เพิ่งเริ่มยา ควรใช้ PPE ใด → N95 + eye protection + gown + gloves ในห้อง airborne isolation","แพทย์จะใส่ central venous catheter ทาง internal jugular vein ต้องใช้อะไร → maximal sterile barrier: cap, mask, sterile gown, sterile gloves, full-body drape","ผู้ป่วยมี C. difficile diarrhea แพทย์จะตรวจท้อง ควรใช้ PPE ใดและล้างมือด้วยอะไร → gown + gloves, ล้างมือด้วยสบู่และน้ำ (alcohol ไม่ฆ่า spore)"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง — สอดคล้องกับข้อสอบชุด 76C, 77B, 77C เรื่อง metabolic response to injury","page":7,"page2":4,"orig":"Metabolic response 1","stem":"A patient involved in a car accident is now in hospital. Which statement correctly describes his metabolic state?","gray":"Patient had car accident? Now at hospital. Which is correct about his metabolic state — A. Hypermetabolism, Hyperglycemia, Net nitrogen loss B. Hypometabolism, Hyperglycemia, Net nitrogen loss C. Hypermetabolism, Hyperglycemia, Net nitrogen gain D. Hypermetabolism, Hypoglycemia, Net nitrogen gain E. Hypermetabolism, Hypoglycemia, Net nitrogen loss","opts":["Hypermetabolism, hyperglycemia, net nitrogen loss","Hypometabolism, hyperglycemia, net nitrogen loss","Hypermetabolism, hyperglycemia, net nitrogen gain","Hypermetabolism, hypoglycemia, net nitrogen gain","Hypermetabolism, hypoglycemia, net nitrogen loss"],"ans":0,"key":"A Hypermetabolism, Hyperglycemia, Net nitrogen loss (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ผู้ป่วยบาดเจ็บ (trauma) ที่มาถึงโรงพยาบาลแล้ว — ถาม <b>metabolic response to injury</b> ใน flow phase ทั้ง 3 มิติ: อัตราเมแทบอลิซึม, ระดับน้ำตาล, nitrogen balance","why":"หลังบาดเจ็บ ร่างกายเข้าสู่ <b>flow phase (catabolic)</b> จาก stress hormone (catecholamine, cortisol, glucagon) และ cytokine (IL-1, IL-6, TNF-α): <b>hypermetabolism</b> (REE และ O₂ consumption เพิ่ม, ไข้, tachycardia), <b>hyperglycemia</b> (gluconeogenesis + glycogenolysis เพิ่ม และ insulin resistance ที่กล้ามเนื้อ), <b>net nitrogen loss</b> (proteolysis ของกล้ามเนื้อปล่อย alanine และ glutamine ไปทำ gluconeogenesis และ acute phase protein → negative nitrogen balance, urinary urea nitrogen เพิ่ม) ร่วมกับ lipolysis","wrong":{"B":"Hypometabolism เป็นลักษณะของ <b>ebb phase</b> (24–48 ชม.แรกหลังบาดเจ็บ: hypovolemia, O₂ consumption และ cardiac output ลด, อุณหภูมิลด) หรือ simple starvation; จะถูกถ้าโจทย์ถามสภาวะในชั่วโมงแรกหลังบาดเจ็บขณะยังช็อก","C":"Net nitrogen gain เกิดในช่วง <b>anabolic phase</b> (ระยะฟื้นตัว สร้างกล้ามเนื้อกลับ) ไม่ใช่ในระยะ catabolic หลังบาดเจ็บ; จะถูกถ้าถามระยะฟื้นตัวหลายสัปดาห์หลังบาดเจ็บที่ผู้ป่วยกินได้ดีแล้ว","D":"Hypoglycemia และ nitrogen gain ไม่เข้ากับ stress response — stress ทำให้ hyperglycemia; hypoglycemia จะพบใน adrenal insufficiency, sepsis ระยะท้ายที่ตับล้มเหลว หรือได้ insulin เกิน; ไม่มีสถานการณ์ที่ทั้งชุดนี้ถูกหลังบาดเจ็บ","E":"Nitrogen loss ถูก แต่ hypoglycemia ผิด เพราะ counter-regulatory hormone และ insulin resistance ทำให้น้ำตาลสูง; จะใกล้เคียงถ้าโจทย์เป็นภาวะช็อกระยะท้ายที่ glycogen หมดและตับล้มเหลว"},"trap":"สับสนกับ simple starvation ที่เป็น hypometabolism, ketosis และ protein sparing — หลังบาดเจ็บร่างกายใช้โปรตีนเป็นแหล่งพลังงานต่อเนื่อง ไม่ได้ประหยัดโปรตีน; หรือเลือก B เพราะนึกถึง ebb phase","summary":["Ebb phase (24–48 ชม.แรก): hypometabolism, hypovolemia, O₂ consumption และ cardiac output ลด, อุณหภูมิลด — เป้าหมายรักษาคือ resuscitation","Flow phase (catabolic, ราว 3–10 วัน ขึ้นกับความรุนแรง): hypermetabolism, ↑catecholamine, cortisol, glucagon, insulin resistance → hyperglycemia, proteolysis → negative nitrogen balance, lipolysis","Flow phase anabolic (ระยะฟื้นตัว หลายสัปดาห์ถึงเดือน): สร้างโปรตีนกลับ nitrogen balance เป็นบวก","Hormone: ACTH, cortisol, catecholamine, glucagon, GH, ADH, aldosterone เพิ่ม (กักเก็บ Na และน้ำ → oliguria หลังผ่าตัด); insulin สัมพัทธ์ลดและดื้อ","Simple starvation ต่างกัน: hypometabolism, insulin ลด, ketosis หลังราว 3 วัน สมองใช้ ketone → protein sparing","การประเมิน nitrogen balance = nitrogen intake (protein ÷ 6.25) − (urinary urea nitrogen + 4 g)","ดูข้อ 710, 711, 712, 713 (metabolism และ nutrition)"],"notes":"ไฟล์เฉลยบท Metabolic response แถว 1: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับเขียน \"Patient had car accident<b>?</b>\" (มีเครื่องหมาย ? หลัง car accident — ผู้จดไม่แน่ใจรายละเอียดของเคส); ช้อยครบ 5 ตัวตามต้นฉบับ","mnemonic":"<b>Ebb = ต่ำ (ช็อก) · Flow = สูง เผาผลาญ (hyper-, hyperglycemia, N loss) · Anabolic = สร้างคืน (N gain)</b>","guide":"Sabiston 21st ed.; ESPEN clinical nutrition in surgery 2021","variants":["ผู้ป่วยไฟไหม้ 40% TBSA วันที่ 5 มีไข้ HR 120 น้ำตาล 220 mg/dL urinary urea nitrogen สูง อยู่ในระยะใด → flow phase (hypermetabolic catabolic)","ผู้ป่วยอดอาหาร 2 สัปดาห์โดยไม่มีการบาดเจ็บ ระดับ metabolic rate และการใช้โปรตีนเป็นอย่างไร → hypometabolism, ketosis, protein sparing","ผู้ป่วยหลังผ่าตัดใหญ่ 3 สัปดาห์ กินได้ดี น้ำหนักเริ่มขึ้น nitrogen balance เป็นอย่างไร → positive (anabolic phase)"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง","page":8,"page2":4,"orig":"Metabolic response 2","stem":"Which pathway allows lactate produced by glycolysis in skeletal muscle to be converted back into glucose?","gray":"กระบวนการใด ทำให้กล้ามเนื้อสามารถเปลี่ยน lactate from glycolysis กลับไปเป็น glucose — A. Cori cycle B. Cahill (glucose-alanine) cycle C. (ว่าง)","opts":["Cori cycle","Cahill cycle","Krebs cycle","Urea cycle","Glycogenolysis"],"ans":0,"key":"A Cori cycle (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ถามวงจรที่นำ <b>lactate</b> จาก anaerobic glycolysis ในกล้ามเนื้อกลับมาเป็น glucose — ต้องแยกจากวงจรที่ใช้ alanine","why":"<b>Cori cycle</b> (lactic acid cycle): กล้ามเนื้อ (และ RBC, แผล) ทำ anaerobic glycolysis ได้ <b>lactate</b> → ส่งทางเลือดไป<b>ตับ</b> → gluconeogenesis เปลี่ยนเป็น glucose (ใช้ 6 ATP) → glucose กลับไปกล้ามเนื้อ (ได้ 2 ATP จาก glycolysis) — การเปลี่ยน lactate เป็น glucose เกิด<b>ที่ตับ</b> ไม่ใช่ที่กล้ามเนื้อ เพราะกล้ามเนื้อขาด enzyme ของ gluconeogenesis; ในภาวะ stress และ injury วงจรนี้ทำงานเพิ่มขึ้นเพื่อส่ง glucose ให้แผลและเซลล์ที่ใช้ glucose เป็นหลัก","wrong":{"B":"<b>Cahill cycle</b> (ต้นฉบับเขียน \"Cahill (glucose-alanine) cycle\") = glucose–alanine cycle: กล้ามเนื้อเปลี่ยน pyruvate เป็น <b>alanine</b> โดยรับ amino group จากการสลายโปรตีน → ตับ → glucose + urea; ทำหน้าที่ขนส่ง nitrogen จากกล้ามเนื้อไปตับใน stress และ starvation; จะถูกถ้าโจทย์ถามวงจรที่ใช้ alanine จากการสลายกล้ามเนื้อ","C":"Krebs cycle (TCA cycle) ใน mitochondria ออกซิไดซ์ acetyl-CoA ให้ NADH, FADH₂ ไปทำ ATP ไม่ได้เปลี่ยน lactate เป็น glucose; จะถูกถ้าถามวิถีที่ให้ electron แก่ oxidative phosphorylation ในภาวะ aerobic","D":"Urea cycle ที่ตับเปลี่ยน ammonia เป็น urea เพื่อขับทางไต; จะถูกถ้าถามการกำจัด nitrogen จาก amino acid catabolism (ทำงานร่วมกับ Cahill cycle)","E":"Glycogenolysis คือการสลาย glycogen; ในกล้ามเนื้อได้ glucose-6-phosphate ใช้เองแต่<b>ปล่อย glucose ออกสู่เลือดไม่ได้</b>เพราะขาด glucose-6-phosphatase ส่วนที่ตับปล่อย glucose ได้แต่ไม่ได้มาจาก lactate; จะถูกถ้าถามแหล่ง glucose แรกในช่วง 24 ชม.แรกของการอดอาหาร (liver glycogen)"},"trap":"สับสน Cori (lactate) กับ Cahill (alanine) เพราะทั้งคู่เป็นวงจรกล้ามเนื้อ–ตับ ที่ได้ glucose กลับไปกล้ามเนื้อ — ดูที่สารตั้งต้น: lactate = Cori, alanine = Cahill","summary":["Cori cycle: lactate จากกล้ามเนื้อ, RBC, แผล → ตับ gluconeogenesis → glucose; ใช้ 6 ATP ได้ 2 ATP (สิ้นเปลืองพลังงาน) เพิ่มขึ้นใน stress, sepsis, injury","Cahill (glucose–alanine) cycle: pyruvate + NH₂ จาก proteolysis → alanine → ตับ → glucose + urea; ขนส่ง nitrogen และสะท้อนการสลายกล้ามเนื้อใน catabolic state","Gluconeogenesis substrate: lactate, alanine และ glutamine (จากกล้ามเนื้อ), glycerol (จาก lipolysis) — fatty acid เปลี่ยนเป็น glucose ไม่ได้","Liver glycogen หมดในราว 24–36 ชม. ของการอดอาหาร → พึ่ง gluconeogenesis; muscle glycogen ใช้ได้เฉพาะในกล้ามเนื้อเอง","ไตก็ทำ gluconeogenesis ได้ (โดยเฉพาะ starvation ระยะยาวจาก glutamine)","Hyperlactatemia ใน shock มาจาก anaerobic glycolysis เพิ่ม + ตับกำจัด lactate ลด","ดูข้อ 709, 711, 712, 713 (metabolism และ nutrition)"],"notes":"ไฟล์เฉลยบท Metabolic response แถว 2: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับถามว่า \"กระบวนการใด ทำให้<b>กล้ามเนื้อ</b>สามารถเปลี่ยน lactate from glycolysis กลับไปเป็น glucose\" — ตามจริงการเปลี่ยนเกิดที่<b>ตับ</b> (กล้ามเนื้อขาด enzyme gluconeogenesis) stem ของเราจึงเขียนว่า lactate ที่ผลิตในกล้ามเนื้อถูกเปลี่ยนกลับเป็น glucose โดยไม่ระบุว่ากล้ามเนื้อเปลี่ยนเอง<br>ช้อย B ต้นฉบับ \"Cahill (glucose-alanine) cycle\" → เขียน \"Cahill cycle\" (ตัดวงเล็บตามกติกาช้อย) และอธิบายใน wrong ว่าคือ glucose–alanine cycle; ช้อย C ในต้นฉบับเป็นช่องว่าง — C, D, E แต่งเพิ่ม<br>ในไฟล์โจทย์บท Metabolic response มีแถว 3, 4, 5 ว่าง (ไม่ใช่ข้อ)","mnemonic":"<b>Cori = Lactate (C-L ติดกัน) · Cahill = Alanine (ทั้งคู่มี A)</b>","guide":"Sabiston 21st ed.","variants":["ผู้ป่วย septic shock มี lactate 6 mmol/L และ hypoglycemia ร่วมกับ liver failure เพราะเหตุใด lactate ถึงสูงต่อเนื่อง → ตับเปลี่ยน lactate เป็น glucose (Cori cycle) ไม่ได้","ผู้ป่วยหลังบาดเจ็บรุนแรงมีการสลายกล้ามเนื้อมาก amino acid ที่กล้ามเนื้อส่งไปตับเพื่อทำ gluconeogenesis มากที่สุดคือ → alanine และ glutamine","ทำไม muscle glycogen ไม่ช่วยรักษาระดับน้ำตาลในเลือดขณะอดอาหาร → กล้ามเนื้อขาด glucose-6-phosphatase"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A — ตามแนวทาง ERAS ผู้ป่วยหลัง gastrectomy ที่ตื่นดีและผายลมแล้วเริ่มกินทางปาก (น้ำแล้วอาหารอ่อน) ได้เลยในหลายราย แต่เมื่อช้อยมีแต่ NJ, TPN, PPN ช้อยที่เป็น enteral คือ NJ จึงถูกที่สุด; สอดคล้องกับข้อสอบชุด 76C, 77A เรื่อง enteral ดีกว่า parenteral. ความมั่นใจสูง","page":8,"page2":4,"orig":"Surgical Nutrition 1","stem":"After gastrectomy, a patient is fully alert and has passed flatus. What is the most appropriate nutrition plan?","gray":"S/P Gastrectomy คนไข้ response ตื้นดี มีตด nutritional plan คือไร — A. NJ feed B. TPN C. PPN","opts":["Nasojejunal tube feeding","Total parenteral nutrition","Peripheral parenteral nutrition","Gastrostomy feeding","Nil by mouth with 5% dextrose only"],"ans":0,"key":"A NJ feed (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ผู้ป่วยหลัง gastrectomy ที่<b>รู้สึกตัวดีและผายลมแล้ว</b> (ลำไส้ทำงาน) — ถามแผนโภชนาการที่เหมาะ ต้องเลือกระหว่าง enteral กับ parenteral และเส้นทางที่ใช้ได้หลังตัดกระเพาะ","why":"เมื่อลำไส้ทำงาน ให้ <b>enteral nutrition ก่อนเสมอ</b> (\"if the gut works, use it\") — รักษา gut mucosal integrity, ลด bacterial translocation, ติดเชื้อน้อยกว่า และถูกกว่า PN; หลัง gastrectomy การให้อาหารต้องผ่าน<b>ปลายเลย anastomosis</b> → <b>nasojejunal tube</b> (หรือ feeding jejunostomy ที่ใส่ระหว่างผ่าตัด) เริ่มได้ภายใน 24–48 ชม. ตาม ERAS; ผู้ป่วยรายนี้ตื่นดีและผายลมแล้วจึงเริ่ม enteral feeding ได้ทันที","wrong":{"B":"TPN ใช้เมื่อ enteral nutrition ห้ามหรือให้ได้ไม่พอ (ileus, obstruction, high-output fistula, short bowel, anastomotic leak รุนแรง) นานเกิน 7 วัน; ผู้ป่วยรายนี้ลำไส้ทำงานแล้ว TPN เพิ่มความเสี่ยง line sepsis, hyperglycemia, cholestasis, gut atrophy โดยไม่จำเป็น; จะถูกถ้าโจทย์บอกว่ามี anastomotic leak และ prolonged ileus กินหรือ feed ไม่ได้มากกว่า 7 วัน","C":"PPN ใช้ระยะสั้นเมื่อ enteral ให้ไม่ได้ชั่วคราว ให้พลังงานได้จำกัด (osmolarity ≤850–900 mOsm/L) และเสี่ยง thrombophlebitis; ไม่จำเป็นเมื่อลำไส้ทำงาน; จะถูกถ้าผู้ป่วยมี ileus ระยะสั้นที่คาดว่าจะหายใน 1 สัปดาห์และไม่มี central line (ดูข้อ 713)","D":"Gastrostomy ต้องใช้กระเพาะ หลัง total gastrectomy ไม่มีกระเพาะ และหลัง subtotal gastrectomy ก็ไม่ควรใส่อาหารเข้ากระเพาะที่เหลือผ่าน anastomosis ใหม่; จะถูกถ้าผู้ป่วยกลืนไม่ได้ระยะยาวแต่กระเพาะปกติ (stroke, head and neck cancer) → PEG","E":"งดอาหารและให้ 5% dextrose อย่างเดียวให้พลังงานแค่ราว 170 kcal/L ไม่มีโปรตีน ไม่พอสำหรับผู้ป่วยหลังผ่าตัดใหญ่ และขัดกับ ERAS ที่ให้เริ่มอาหารเร็ว; จะถูกถ้าเป็นช่วงสั้นมากหลังผ่าตัดที่ยังไม่ปลอดภัยต่อการ feed"},"trap":"ยังเชื่อแนวคิดเก่าว่าต้องรอให้ลำไส้ทำงานเต็มที่หรือให้ TPN หลังผ่าตัดกระเพาะ — แนวทางปัจจุบันให้ enteral เร็วที่สุดผ่านทางที่ข้าม anastomosis","summary":["หลัก: enteral nutrition ก่อนเสมอถ้าลำไส้ใช้ได้ — ลด infection, รักษา gut barrier, ถูกกว่า","ERAS: หลีกเลี่ยงการงดอาหารนาน, เริ่ม oral หรือ enteral ภายใน 24 ชม. หลังผ่าตัดในผู้ป่วยส่วนใหญ่ รวมถึงหลัง gastrectomy ที่กินทางปากได้เร็ว","ถ้ากินทางปากได้ไม่พอ หลังผ่าตัดทางเดินอาหารส่วนบน: tube ปลายเลย anastomosis = nasojejunal tube หรือ needle catheter jejunostomy (แนะนำใส่ระหว่างผ่าตัดในผู้ป่วยขาดอาหารรุนแรงที่ผ่าตัดมะเร็งส่วนบน)","PN: เมื่อ EN ห้ามหรือให้ได้ &lt;50% ของความต้องการนาน &gt;7 วัน (ขาดอาหารรุนแรงเริ่มเร็วกว่า); PPN ระยะสั้น, TPN ทาง central ระยะยาว","ความต้องการโดยประมาณ: พลังงาน 25–30 kcal/kg/วัน, โปรตีน 1.5 g/kg/วัน","ระวัง refeeding syndrome ในผู้ป่วยขาดอาหาร (hypophosphatemia, hypokalemia, hypomagnesemia) → เริ่มช้าและให้ thiamine","ดูข้อ 709, 710, 712, 713 (metabolism และ nutrition)"],"notes":"ไฟล์เฉลยบท Surgical Nutrition แถว 1: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับเขียน \"คนไข้ response <b>ตื้นดี</b> มีตด\" (= ตื่นดี มีผายลม) — เราเขียน stem เป็น fully alert and has passed flatus<br>ช้อย A–C แปลจากต้นฉบับ (A \"NJ feed\" → Nasojejunal tube feeding, B \"TPN\", C \"PPN\"); D, E แต่งเพิ่ม","mnemonic":"<b>\"If the gut works, use it\"</b> — แต่ใส่ปลายเลย anastomosis","guide":"ESPEN clinical nutrition in surgery 2021; ERAS Society gastrectomy 2014","variants":["ผู้ป่วยหลัง Whipple วันที่ 3 ลำไส้ทำงาน กินทางปากได้น้อยกว่า 50% ของความต้องการ มี feeding jejunostomy ใส่ไว้ระหว่างผ่าตัด ควรทำอย่างไร → เริ่ม feed ผ่าน jejunostomy","ผู้ป่วยหลัง total gastrectomy วันที่ 6 มี anastomotic leak ต้อง NPO คาดว่านาน 2–3 สัปดาห์ และไม่มี enteral access ปลายเลย leak → TPN ทาง central line","ผู้ป่วย stroke กลืนไม่ได้ระยะยาว กระเพาะปกติ ควรให้อาหารทางใด → PEG"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A — ต้นฉบับที่ไม่มีประวัติผ่าตัดนั้น B12 และ folate deficiency (ช้อย C) ตอบได้ทั้งคู่ เมื่อเติม total gastrectomy 4 ปีก่อนแล้ว B12 เป็นคำตอบเดียว; ถ้าโจทย์ให้ผู้ป่วยติดสุราเรื้อรังกินอาหารน้อยโดยไม่เคยผ่าตัด จะตอบ folate. สอดคล้องกับข้อสอบชุด 77B และ 77C (total gastrectomy → B12 deficiency). ความมั่นใจสูง","page":8,"page2":4,"orig":"Surgical Nutrition 2","stem":"A patient who underwent total gastrectomy 4 years ago without vitamin supplementation has glossitis. Blood tests show macrocytic anemia. Which deficiency is most likely?","gray":"คนไข้มีอาการ Glossitis ตรวจเลือดได้ Macrocytic anemia ถามว่าอะไร def — A. B12 def B. C def C. B9 def","opts":["Vitamin B12 deficiency","Vitamin C deficiency","Folate deficiency","Iron deficiency","Thiamine deficiency"],"ans":0,"key":"A B12 def (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: folate deficiency (ช้อย C) ก็ทำ glossitis + macrocytic anemia — เติมใน stem ว่าเคยผ่าตัด total gastrectomy 4 ปีก่อนและไม่ได้รับวิตามินเสริม (อยู่ในบท Surgical Nutrition)","interp":"Glossitis + <b>macrocytic anemia</b> = megaloblastic anemia (B12 หรือ folate) — ประวัติ <b>total gastrectomy 4 ปีก่อน</b>โดยไม่ได้วิตามินเสริม เป็นตัวแยกว่าเป็น B12","why":"หลัง total gastrectomy ไม่มี <b>parietal cell</b> → ไม่มี <b>intrinsic factor</b> (และกรดที่ช่วยแยก B12 ออกจากโปรตีนในอาหาร) → ดูดซึม B12 ที่ <b>terminal ileum</b> ไม่ได้; ตับเก็บ B12 ไว้ได้ราว <b>3–5 ปี</b> อาการจึงมาหลังผ่าตัดหลายปีพอดีกับผู้ป่วยรายนี้ → megaloblastic anemia, glossitis และอาจมี neurologic deficit (subacute combined degeneration); ต้องให้ <b>B12 ฉีด (IM) ตลอดชีวิต</b>หลัง total gastrectomy","wrong":{"B":"Vitamin C deficiency (scurvy) ทำเลือดออกตามไรฟัน เหงือกบวม perifollicular hemorrhage, corkscrew hair, แผลหายช้า (collagen hydroxylation ผิดปกติ) ส่วนภาวะซีดมักเป็น normocytic หรือจากขาดเหล็กร่วม ไม่ใช่ macrocytic; จะถูกถ้าโจทย์เป็นผู้สูงอายุกินผักผลไม้น้อยมีเลือดออกตามไรฟันและแผลผ่าตัดแยก","C":"Folate deficiency ทำ macrocytic anemia + glossitis ได้เช่นกันและแยกด้วยอาการอย่างเดียวไม่ได้ แต่ <b>ไม่มีอาการทางระบบประสาท</b> MMA ปกติ (homocysteine สูงทั้งคู่), ร่างกายเก็บ folate ได้แค่ 3–4 เดือน และ total gastrectomy ไม่ได้ทำลายการดูดซึม folate (ดูดซึมที่ jejunum); จะถูกถ้าโจทย์เป็นผู้ติดสุรา ขาดอาหาร ตั้งครรภ์ หรือได้ methotrexate, phenytoin","D":"Iron deficiency ก็ทำ glossitis และ angular cheilitis ได้ และพบบ่อยหลัง gastrectomy (ขาดกรดช่วยเปลี่ยน Fe³⁺ เป็น Fe²⁺ และอาหารข้าม duodenum ใน Billroth II หรือ Roux-en-Y) แต่เป็น <b>microcytic</b> anemia; จะถูกถ้า MCV ต่ำ ferritin ต่ำ","E":"Thiamine (B1) deficiency ทำ Wernicke encephalopathy (confusion, ataxia, ophthalmoplegia) และ beriberi (heart failure, neuropathy) ไม่ทำ anemia; จะถูกถ้าโจทย์เป็นผู้ป่วยหลัง bariatric surgery ที่อาเจียนบ่อยแล้วมีอาการทางระบบประสาท"},"trap":"ตอบ folate เพราะ macrocytic anemia + glossitis เข้าได้ทั้งคู่ — ตัวแยกคือ<b>ประวัติผ่าตัด</b> (gastrectomy → ไม่มี intrinsic factor; ileal resection → ดูดซึม B12 ไม่ได้) และอาการทางประสาท","summary":["B12 ดูดซึม: กรดและ pepsin แยก B12 จากโปรตีนอาหาร → จับ R-protein → ใน duodenum ปล่อยจับ intrinsic factor (จาก parietal cell) → ดูดซึมที่ terminal ileum","สาเหตุ B12 deficiency ทางศัลยกรรม: total gastrectomy, bariatric surgery (RYGB), terminal ileal resection มากกว่า 60–100 cm, Crohn ที่ terminal ileum, blind loop syndrome (bacterial overgrowth)","อาการ: megaloblastic anemia, glossitis, subacute combined degeneration (dorsal column + lateral corticospinal: เสีย proprioception, vibration, ataxia), neuropathy, ความจำเสื่อม","Lab: MCV สูง, hypersegmented neutrophil, B12 ต่ำ, MMA และ homocysteine สูง (folate deficiency: homocysteine สูงแต่ MMA ปกติ)","รักษา: B12 ฉีด IM (hydroxocobalamin หรือ cyanocobalamin) ตลอดชีวิตหลัง total gastrectomy; ห้ามให้ folate อย่างเดียวในผู้ป่วยขาด B12 เพราะซีดดีขึ้นแต่อาการทางประสาทแย่ลง","ผลระยะยาวอื่นหลัง gastrectomy: iron deficiency (microcytic), calcium และ vitamin D ต่ำ (osteoporosis), dumping syndrome, น้ำหนักลด","ดูข้อ 709, 710, 711, 713 (metabolism และ nutrition)"],"notes":"ไฟล์เฉลยบท Surgical Nutrition แถว 2: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับมีแค่ \"คนไข้มีอาการ Glossitis ตรวจเลือดได้ Macrocytic anemia ถามว่าอะไร def\" — ไม่มีประวัติผ่าตัด เราเติมใน stem ว่าเคยทำ total gastrectomy 4 ปีก่อนและไม่ได้รับวิตามินเสริม เพราะ folate deficiency (ช้อย C ต้นฉบับ \"B9 def\") ก็ทำ glossitis + macrocytic anemia ได้<br>ช้อย A–C แปลจากต้นฉบับ (A \"B12 def\", B \"C def\", C \"B9 def\" → Folate deficiency); D, E แต่งเพิ่ม","mnemonic":"<b>B12 = \"Brain + Blood\"</b> (มีอาการทางประสาท) · <b>Folate = Blood only</b>","guide":"BSH cobalamin and folate 2014","variants":["ผู้ป่วย Crohn disease เคยตัด terminal ileum 100 cm เมื่อ 4 ปีก่อน มี paresthesia ปลายเท้า MCV 112 → B12 deficiency","ผู้ป่วยติดสุราเรื้อรังกินอาหารน้อย มี glossitis MCV 110 ไม่มีอาการทางประสาท MMA ปกติ → folate deficiency","ผู้ป่วยหลัง Roux-en-Y gastric bypass 2 ปี ซีด MCV 72 ferritin ต่ำ → iron deficiency"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ B เมื่อเติมข้อมูลแล้ว ความมั่นใจปานกลาง — ต้นฉบับให้ข้อมูลแค่ ileus วันที่ 5 ซึ่งตอบได้หลายแบบตามบริบท: ถ้าผู้ป่วยขาดอาหารเดิมหรือคาดว่าต้องงดอาหารทางเดินอาหารนานกว่า 2 สัปดาห์ ควรให้ TPN ทาง central (ช้อย A); ถ้าลำไส้เริ่มทำงานจะเริ่ม enteral (ช้อย C); เราเติมข้อมูลให้ตรงคีย์ PPN ซึ่งเหมาะกับการให้ระยะสั้นในผู้ป่วยโภชนาการดี; สอดคล้องกับข้อสอบชุด 76D (short bowel → TPN และ PPN ทาง peripheral เสี่ยง thrombophlebitis)","page":8,"page2":4,"orig":"Surgical Nutrition 3","stem":"A previously well-nourished patient still has postoperative ileus on day 5 and cannot tolerate oral or enteral intake. The ileus is expected to resolve within about 1 week. Which nutrition support is most appropriate?","gray":"Post-op day 5 ileus ให้อะไรดี — A. TPN Central vein B. PPN C. Enteral","opts":["TPN via central vein","Peripheral parenteral nutrition","Enteral feeding","5% dextrose in water only","No nutrition until bowel function returns"],"ans":1,"key":"B PPN (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ ต้นฉบับให้ข้อมูลน้อย — เติมใน stem ว่าเดิมภาวะโภชนาการดีและคาดว่า ileus จะหายในราว 1 สัปดาห์ (PPN เหมาะกับระยะสั้น); ถ้าขาดอาหารเดิมหรือคาดว่าต้องงดอาหารทางเดินอาหาร &gt;2 สัปดาห์ ตอบ TPN ทาง central","interp":"ผู้ป่วย<b>ภาวะโภชนาการเดิมดี</b> มี postoperative ileus ถึงวันที่ 5 กินและ feed ไม่ได้ คาดว่าจะหายในราว 1 สัปดาห์ (รวมงดอาหารราว 12 วัน) — ถาม nutrition support ที่เหมาะกับ<b>ระยะเวลาสั้น</b>เมื่อใช้ทางเดินอาหารไม่ได้","why":"Ileus ทำให้ enteral ใช้ไม่ได้ และผู้ป่วยจะงดอาหารรวมเกิน 7 วัน → ต้องให้ <b>parenteral nutrition</b> (ESPEN: เริ่ม PN เมื่อกินหรือ feed ไม่ได้ หรือได้ &lt;50% ของความต้องการนาน &gt;7 วัน); เมื่อคาดว่าใช้เพียง<b>ระยะสั้น</b> (≤10–14 วัน) ในผู้ป่วยที่โภชนาการเดิมดี <b>PPN</b> ทาง peripheral vein เพียงพอ ไม่ต้องเสี่ยงภาวะแทรกซ้อนจาก central line (pneumothorax, CLABSI, thrombosis); ข้อจำกัดคือ osmolarity ≤850–900 mOsm/L จึงต้องใช้ปริมาตรมากและให้พลังงานได้จำกัด และเสี่ยง thrombophlebitis","wrong":{"A":"TPN ทาง central vein เหมาะเมื่อคาดว่าต้องใช้ PN <b>ระยะยาว</b> (&gt;2 สัปดาห์), ความต้องการพลังงานสูง, ต้องจำกัดน้ำ (heart failure, renal failure) หรือขาดอาหารรุนแรงเดิม; จะถูกถ้าโจทย์บอกว่าผู้ป่วยขาดอาหารก่อนผ่าตัด หรือมี short bowel, high-output fistula, prolonged ileus ที่คาดว่านานหลายสัปดาห์","C":"Enteral feeding ห้ามใน ileus ที่ทนอาหารทางเดินอาหารไม่ได้ (ท้องอืด อาเจียน NG output มาก) อาจทำให้อาเจียนและ aspiration; จะถูกถ้าลำไส้เริ่มทำงาน (ผายลม NG output ลด) หรือเป็น ileus เล็กน้อยที่ยังทน trophic feeding ทาง NJ ได้","D":"5% dextrose อย่างเดียวให้พลังงานแค่ราว 170 kcal/L ไม่มีโปรตีน ไม่ใช่ nutrition support ทำให้เสีย lean body mass ต่อเนื่อง; ใช้ได้เป็น maintenance fluid ช่วงสั้น 1–3 วันแรกหลังผ่าตัดเท่านั้น","E":"การรอโดยไม่ให้สารอาหารถูกได้ในผู้ป่วยโภชนาการดีที่คาดว่างดอาหารรวม<b>ไม่เกิน 7 วัน</b> แต่ผู้ป่วยรายนี้งดมาแล้ว 5 วันและต้องงดต่ออีกราว 1 สัปดาห์ จึงต้องเริ่ม PN; จะถูกถ้าโจทย์เป็น ileus วันที่ 2 ที่คาดว่าจะหายใน 1–2 วัน"},"trap":"เลือก TPN ทาง central เพราะคิดว่า PN ต้องให้ทาง central เสมอ — สำหรับระยะสั้นในผู้ป่วยโภชนาการดี PPN เพียงพอและหลีกเลี่ยงความเสี่ยงของ central line; หรือเลือก enteral เพราะจำว่า enteral ดีกว่าเสมอ แต่ ileus เป็นข้อห้าม","summary":["ESPEN surgery: ผู้ป่วยที่คาดว่ากินไม่ได้ &gt;5 วัน หรือกินได้ &lt;50% นาน &gt;7 วัน ควรได้ nutrition support; เลือก oral หรือ enteral ก่อน","PN เมื่อ EN ห้ามหรือไม่พอ: ileus, obstruction, high-output fistula, short bowel, severe malabsorption, ischemic bowel","PPN: osmolarity ≤850–900 mOsm/L, ใช้ระยะสั้น ≤10–14 วัน, ให้พลังงานได้จำกัด ต้องใช้ปริมาตรมาก, เสี่ยง thrombophlebitis (เปลี่ยนตำแหน่งเข็มบ่อย)","TPN ทาง central (CVC หรือ PICC): ระยะยาว ความต้องการสูง หรือจำกัดน้ำ; ภาวะแทรกซ้อน CLABSI, thrombosis, pneumothorax ตอนใส่, hyperglycemia, refeeding, PN-associated liver disease","ผู้ป่วยขาดอาหารรุนแรงเดิม (น้ำหนักลด &gt;10–15% ใน 6 เดือน, BMI &lt;18.5, albumin &lt;3 g/dL) เริ่ม nutrition support เร็วขึ้นและอาจให้ก่อนผ่าตัด 7–14 วัน","ติดตาม PN: น้ำตาล, electrolyte (PO₄, K, Mg), liver function, triglyceride; เปลี่ยนกลับเป็น enteral ทันทีที่ลำไส้ทำงาน","ดูข้อ 709, 710, 711, 712 (metabolism และ nutrition)"],"notes":"ไฟล์เฉลยบท Surgical Nutrition แถว 3: <b>B</b> (ช่องคำอธิบายว่าง) — ในไฟล์เฉลย<b>เลขข้อของแถวนี้พิมพ์เพี้ยน</b> เป็น \".\" อยู่บรรทัดเดียวกับคำตอบ B แล้วเลข \"3\" ตกไปอยู่บรรทัดถัดไป<br>ต้นฉบับมีแค่ \"Post-op day 5 ileus ให้อะไรดี\" — เราเติมใน stem ว่าเดิมโภชนาการดี กินหรือ feed ไม่ได้ และคาดว่า ileus จะหายในราว 1 สัปดาห์ เพื่อให้ PPN (ระยะสั้น) เป็นคำตอบเดียว<br>ช้อย A–C แปลจากต้นฉบับ (A \"TPN Central vein\", B \"PPN\", C \"Enteral\"); D, E แต่งเพิ่ม<br>ในไฟล์โจทย์บท Surgical Nutrition มีแถว 4, 5 ว่าง (ไม่ใช่ข้อ)","mnemonic":"<b>สั้น + โภชนาการดี = Peripheral · ยาว + ขาดอาหาร + จำกัดน้ำ = Central</b>","guide":"ESPEN clinical nutrition in surgery 2021","variants":["ผู้ป่วยหลังผ่าตัด small bowel resection เหลือลำไส้เล็ก 80 cm คาดว่าต้องพึ่ง PN ระยะยาว → TPN ทาง central line","ผู้ป่วยได้ PPN ทาง peripheral วันที่ 4 แล้วมีแขนบวมแดงปวดตามแนวเส้นเลือด เกิดจากอะไร → infusion thrombophlebitis จาก osmolarity สูง","ผู้ป่วยมะเร็งกระเพาะน้ำหนักลด 15% ใน 3 เดือน หลังผ่าตัดมี ileus นาน คาดว่าเกิน 2 สัปดาห์ → TPN ทาง central"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง — สอดคล้องกับข้อสอบชุด 77A และ 77B เรื่องเส้นประสาทใน groin","page":9,"page2":4,"orig":"Hernia 1","stem":"After open inguinal hernia repair, a man has numbness of the skin of the upper medial thigh. Which nerve was most likely injured?","gray":"S/P ผ่า hernia มีอาการชาที่ต้นขาด้านใน โดน nerve อะไร — A. Ilioinguinal nerve B. Genitofemoral nerve C. (ว่าง)","opts":["Ilioinguinal nerve","Genitofemoral nerve","Iliohypogastric nerve","Lateral femoral cutaneous nerve","Femoral nerve"],"ans":0,"key":"A Ilioinguinal nerve (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ชาที่<b>ผิวหนังต้นขาด้านในส่วนบน</b>หลังผ่าตัด open inguinal hernia — ถามเส้นประสาทที่บาดเจ็บ ต้องรู้ sensory distribution ของเส้นประสาทแถบ groin","why":"<b>Ilioinguinal nerve</b> (L1) วิ่งใน inguinal canal บน spermatic cord ใต้ external oblique aponeurosis จึงบาดเจ็บง่ายที่สุดใน open repair (ถูกตัด เย็บติด หรือ mesh กด) — เลี้ยงผิวหนัง<b>ต้นขาด้านในส่วนบน (upper medial thigh)</b>, root of penis, mons pubis, anterior scrotum หรือ labium majus → บาดเจ็บทำให้ชาหรือปวดแบบ neuropathic บริเวณนี้","wrong":{"B":"Genitofemoral nerve (L1–L2): genital branch เข้า inguinal canal เลี้ยง cremaster และผิวหนัง scrotum ด้านข้าง, femoral branch เลี้ยงผิวหนัง<b>หน้าต้นขาบริเวณ femoral triangle</b> (ไม่ใช่ด้านใน); บาดเจ็บได้ทั้ง open และ laparoscopic; จะถูกถ้าโจทย์ให้ชาที่ scrotum ด้านข้างหรือเสีย cremasteric reflex หรือชาที่ต้นขาด้านหน้าส่วนบน","C":"Iliohypogastric nerve (T12–L1) วิ่งระหว่าง internal oblique กับ external oblique เหนือ inguinal canal เลี้ยงผิวหนัง<b>เหนือหัวหน่าว (suprapubic)</b>; จะถูกถ้าโจทย์ให้ชาที่ผิวหนังเหนือหัวหน่าวหลังผ่าตัด","D":"Lateral femoral cutaneous nerve (L2–L3) เลี้ยงผิวหนัง<b>ต้นขาด้านข้าง</b> (meralgia paresthetica) บาดเจ็บใน laparoscopic repair เมื่อยิง tack หรือ dissection ใน \"triangle of pain\" (lateral ต่อ gonadal vessels ใต้ iliopubic tract) ไม่ค่อยเกี่ยวกับ open repair; จะถูกถ้าโจทย์เป็นชาต้นขาด้านข้างหลัง TEP หรือ TAPP","E":"Femoral nerve เป็น<b>motor</b>ของ quadriceps + sensory หน้าต้นขาและด้านในขา (saphenous) บาดเจ็บน้อยมากในการผ่าตัด hernia (อาจจากเย็บลึกใน femoral repair หรือ tack ใน triangle of pain) อาการคือเหยียดเข่าไม่ได้; จะถูกถ้าโจทย์ให้ quadriceps weakness และ knee reflex หาย"},"trap":"เลือก genitofemoral เพราะชื่อมีคำว่า femoral (ต้นขา) — femoral branch เลี้ยงต้นขาด้านหน้า ส่วนต้นขาด้านในส่วนบนเป็นของ ilioinguinal ซึ่งเป็นเส้นที่บาดเจ็บบ่อยที่สุดใน open repair","summary":["เส้นประสาทใน open repair: ilioinguinal (บน cord, ต้นขาด้านในบน + root of penis + anterior scrotum), iliohypogastric (เหนือ canal, suprapubic), genital branch of genitofemoral (ใน cord, cremaster + scrotum)","เส้นประสาทใน laparoscopic repair: \"triangle of pain\" (lateral ต่อ gonadal vessels ใต้ iliopubic tract) มี LFCN, femoral branch of genitofemoral, femoral nerve → ห้ามยิง tack ใต้ iliopubic tract","\"Triangle of doom\" (ระหว่าง vas deferens ด้านในกับ gonadal vessels ด้านนอก) มี external iliac artery และ vein","Chronic postherniorrhaphy inguinal pain = ปวดเกิน 3 เดือนหลังผ่าตัด พบราว 10–12% ระดับที่รบกวนชีวิตราว 1–3%","HerniaSurge: ระบุเส้นประสาททั้ง 3 เส้นใน open repair และเก็บไว้; ถ้าเส้นประสาทถูกรบกวนจากการวาง mesh พิจารณา pragmatic neurectomy","รักษา chronic pain: ยาแก้ปวด, nerve block; ถ้าไม่ดีขึ้นหลัง 6–12 เดือน → triple neurectomy ± mesh removal โดยผู้เชี่ยวชาญ","ดูข้อ 715, 716, 717, 718, 707 (hernia)"],"notes":"ไฟล์เฉลยบท \"+=Hernia\" แถว 1: <b>A</b> (ช่องคำอธิบายว่าง) — ชื่อบทในไฟล์เฉลยพิมพ์ว่า \"+=Hernia\"<br>ต้นฉบับ \"มีอาการชาที่ต้นขาด้านใน\" → upper medial thigh; ไม่ได้ระบุ open หรือ laparoscopic เราเขียนเป็น open inguinal hernia repair (บริบทเส้นประสาทในช้อยต้นฉบับ)<br>ช้อย A, B ตามต้นฉบับ; ช้อย C ในต้นฉบับเป็นช่องว่าง — C, D, E แต่งเพิ่ม","mnemonic":"<b>Ilio-INguinal = INner thigh · Ilio-HYPOgastric = ใต้สะดือเหนือหัวหน่าว · LFCN = Lateral</b>","guide":"HerniaSurge 2018","variants":["หลัง TEP ผู้ป่วยชาและแสบร้อนที่ต้นขาด้านข้าง เส้นประสาทใดบาดเจ็บ → lateral femoral cutaneous nerve","หลัง Lichtenstein repair ผู้ป่วยชาที่ผิวหนังเหนือหัวหน่าว → iliohypogastric nerve","ผู้ป่วยปวดแสบร้อนที่ groin ร้าวลง scrotum นาน 8 เดือนหลังผ่าตัด hernia ไม่ดีขึ้นด้วยยาและ nerve block → พิจารณา triple neurectomy"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง — ข้อคล้ายข้อสอบชุด 77D และ 76C (femoral hernia อยู่ใต้และ lateral ต่อ pubic tubercle); การตีความตำแหน่งในต้นฉบับเป็นจุดเดียวที่ปรับ ไม่เปลี่ยนคำตอบ","page":9,"page2":4,"orig":"Hernia 2","stem":"A patient has symptoms of bowel obstruction and a tender, irreducible groin mass below the inguinal ligament and lateral to the pubic tubercle. What is the most likely diagnosis?","gray":"คนไข้มีอาการ Gut obstruction มีก้อนที่ lateral ต่อ inguinal ligament และใต้ต่อ inguinal ligament ถามว่าเป็นไร — A. Incarcerated femoral hernia B. Strangulated inguinal hernia C. Adhesive small bowel obstruction with lymphadenopathy","opts":["Incarcerated femoral hernia","Strangulated inguinal hernia","Adhesive small bowel obstruction with lymphadenopathy","Obturator hernia","Spigelian hernia"],"ans":0,"key":"A Incarcerated femoral hernia (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: ต้นฉบับเขียน \"lateral ต่อ inguinal ligament และใต้ต่อ inguinal ligament\" — ตีความเป็นใต้ inguinal ligament และ lateral ต่อ pubic tubercle (ตำแหน่ง femoral canal) แบบชุด 77D","interp":"ผู้ป่วยมี <b>bowel obstruction</b> + ก้อนที่ groin กดเจ็บ ดันกลับไม่ได้ ตำแหน่ง<b>ใต้ inguinal ligament และ lateral ต่อ pubic tubercle</b> — ใช้ landmark แยก femoral กับ inguinal hernia","why":"Femoral hernia ออกทาง <b>femoral canal</b> ซึ่งอยู่<b>ใต้ inguinal ligament</b> คอ hernia อยู่ <b>inferior และ lateral ต่อ pubic tubercle</b> (inguinal hernia อยู่ superior และ medial ต่อ pubic tubercle); ขอบของ femoral ring: anterior = inguinal ligament, posterior = pectineal (Cooper) ligament, medial = lacunar ligament, lateral = femoral vein — ขอบแข็งและแคบจึง <b>incarcerate และ strangulate ได้บ่อยที่สุด</b>ใน groin hernia มักมาด้วย bowel obstruction; ต้องผ่าตัดฉุกเฉิน (ถ้ามี strangulation หรือ peritonitis ต้องประเมินลำไส้)","wrong":{"B":"Inguinal hernia ออกเหนือ inguinal ligament คออยู่ superior และ medial ต่อ pubic tubercle (indirect ผ่าน deep ring lateral ต่อ inferior epigastric vessels; direct ผ่าน Hesselbach triangle) และลงถุงอัณฑะได้; จะถูกถ้าโจทย์ให้ก้อนเหนือ inguinal ligament ลงถุงอัณฑะ ดันกลับไม่ได้ มีผิวแดง ไข้ และ bowel obstruction","C":"Adhesive SBO ต้องมีประวัติผ่าตัดช่องท้อง และ lymphadenopathy ที่ขาหนีบจะคลำได้เป็นก้อนแข็งหลายก้อน ไม่ใช่ก้อนเดี่ยวที่สัมพันธ์กับ obstruction; ก้อนที่ groin ร่วมกับ bowel obstruction ต้องคิดถึง incarcerated hernia ก่อนเสมอ; จะถูกถ้าโจทย์เป็นผู้ป่วยเคยผ่าตัดช่องท้องมี obstruction และตรวจ groin ปกติ","D":"Obturator hernia ออกทาง obturator canal พบในหญิงสูงอายุผอม มาด้วย SBO และปวดร้าวต้นขาด้านในเมื่อหมุนสะโพกเข้า (Howship-Romberg sign) มัก<b>คลำก้อนไม่ได้</b>ที่ groin วินิจฉัยด้วย CT; จะถูกถ้าโจทย์เป็นหญิงอายุ 85 ปีผอมมาก มี SBO ปวดต้นขาด้านในโดยไม่มีก้อน","E":"Spigelian hernia ออกที่ Spigelian fascia ตามแนว linea semilunaris (ขอบนอก rectus) ใต้ arcuate line อยู่<b>เหนือ</b> groin บริเวณท้องน้อยด้านข้าง มักอยู่ใต้ external oblique จึงคลำยาก; จะถูกถ้าโจทย์ให้ก้อนที่ขอบนอกของ rectus abdominis ระดับใต้สะดือ"},"trap":"เห็นก้อนที่ groin ร่วมกับ obstruction แล้วตอบ inguinal hernia ทันที — ต้องดูตำแหน่งเทียบ inguinal ligament และ pubic tubercle; femoral hernia มักถูกเข้าใจผิดเป็น inguinal hernia หรือ lymph node โดยเฉพาะในหญิงอ้วน","summary":["Femoral hernia: ใต้ inguinal ligament, inferolateral ต่อ pubic tubercle, medial ต่อ femoral vein; พบในหญิงมากกว่าชาย แต่ inguinal hernia ยังพบบ่อยที่สุดในหญิง","Femoral ring: anterior inguinal ligament, posterior Cooper ligament, medial lacunar ligament, lateral femoral vein → แคบและแข็ง → incarceration และ strangulation สูงสุดใน groin hernia","Femoral hernia ทุกรายควรผ่าตัด (ไม่ใช้ watchful waiting); elective ควรผ่าเร็ว, incarcerated หรือ strangulated ผ่าฉุกเฉิน","HerniaSurge: femoral hernia แนะนำ laparoscopic repair ด้วย mesh (ซ่อมได้ทั้ง inguinal และ femoral) ในภาวะ elective; ฉุกเฉินใช้ open approach (low, high หรือ preperitoneal) ได้","Richter hernia: เฉพาะ antimesenteric wall ของลำไส้ติดอยู่ อาจ strangulate โดยไม่มี obstruction ชัด พบบ่อยใน femoral hernia","Strangulation sign: ปวดมาก กดเจ็บ ผิวแดง ไข้ WBC สูง lactate สูง peritonitis → ต้องประเมินความมีชีวิตของลำไส้และตัดถ้าตาย","ดูข้อ 714, 716, 717, 718, 707 (hernia)"],"notes":"ไฟล์เฉลยบท \"+=Hernia\" แถว 2: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับเขียนตำแหน่งก้อนว่า \"<b>lateral ต่อ inguinal ligament และใต้ต่อ inguinal ligament</b>\" (คำว่า lateral ต่อ inguinal ligament ไม่ใช่ landmark ที่ใช้จริง) — เราตีความเป็นใต้ inguinal ligament และ lateral ต่อ pubic tubercle (ตำแหน่ง femoral canal) และเติมว่าก้อนกดเจ็บ ดันกลับไม่ได้; ต้นฉบับ \"Gut obstruction\" → symptoms of bowel obstruction<br>ช้อย A–C ตามต้นฉบับ; D, E แต่งเพิ่ม","mnemonic":"<b>Femoral = ใต้ + นอก ต่อ pubic tubercle · Inguinal = เหนือ + ใน</b>; ขอบ femoral ring จากหน้าไปหลังวนเข็ม: <b>Inguinal – Lacunar – Cooper – Vein</b>","guide":"HerniaSurge 2018; WSES emergency hernia 2017","variants":["หญิงอายุ 70 ปีอาเจียน ท้องอืด 2 วัน มีก้อนเล็ก 2 cm กดเจ็บที่ต้นขาด้านบนใต้ inguinal ligament → incarcerated femoral hernia ผ่าตัดฉุกเฉิน","หญิงอายุ 88 ปีผอมมาก มี SBO และปวดร้าวต้นขาด้านในเมื่อหมุนสะโพก คลำ groin ไม่พบก้อน → obturator hernia ยืนยันด้วย CT","ชายอายุ 60 ปีมีก้อนเหนือ inguinal ligament ลงถุงอัณฑะ ปวดมาก ผิวแดง ดันกลับไม่ได้ ไข้ → strangulated inguinal hernia"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง — สอดคล้องกับข้อสอบชุด 77A (หลัง hernioplasty ปัสสาวะไม่ออก bladder 600 mL → analgesics)","page":9,"page2":4,"orig":"Hernia 3","stem":"After bilateral inguinal hernia repair, a man has a 15-cm cystic-appearing mass in the suprapubic region. Which measure could have helped prevent this?","gray":"คนไข้ bilateral inguinal hernia ผ่าแก้ไปแล้ว มีก้อน cystic-liked lesion ขนาด 15 cm ที่บริเวณ suprapubic ถามว่าอะไรป้องกันสิ่งนี้ได้ — A. Analgesic B. Kegel Exercise C. Prophylaxis antibiotic","opts":["Analgesics","Kegel exercise","Prophylactic antibiotics","Liberal intravenous fluid","Anticholinergic drug"],"ans":0,"key":"A Analgesic (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"หลังผ่าตัด hernia ทั้งสองข้าง มีก้อน cystic ขนาด 15 cm ตรงกลาง<b>เหนือหัวหน่าว</b> — ต้องตีความว่าก้อนคืออะไร (ภาวะแทรกซ้อนหลังผ่าตัด hernia ที่พบบ่อยและมาด้วยก้อนกลางท้องน้อย) แล้วเลือกวิธีป้องกัน","why":"ก้อน cystic ขนาดใหญ่กลางท้องน้อยหลังผ่าตัด hernia คือ<b>กระเพาะปัสสาวะที่โป่งจาก postoperative urinary retention (POUR)</b> (พบราว 1–22% หลังผ่าตัด hernia, สูงใน bilateral และ laparoscopic) — ความ<b>ปวดแผล</b>กระตุ้น sympathetic ทำให้ internal sphincter หดและ detrusor ถูกยับยั้ง จึงปัสสาวะไม่ออก การให้<b>ยาแก้ปวดเพียงพอ</b> (local infiltration, ilioinguinal nerve block, NSAIDs, paracetamol เพื่อลด opioid ที่ยับยั้ง detrusor) จึงช่วยป้องกัน ร่วมกับการใช้ local anesthesia, จำกัดสารน้ำ, ให้ปัสสาวะก่อนเข้าห้องผ่าตัด และลุกเดินเร็ว","wrong":{"B":"Kegel exercise (pelvic floor muscle training) เพิ่มความแข็งแรงของ external sphincter และ pelvic floor ใช้รักษา<b>stress urinary incontinence</b> ไม่ได้ช่วยให้ปัสสาวะออก และไม่ป้องกัน retention; จะถูกถ้าโจทย์เป็นปัสสาวะเล็ดเวลาไอจามหลังคลอดหรือหลัง prostatectomy","C":"Prophylactic antibiotic ป้องกัน surgical site infection (ใช้ใน mesh repair ที่ความเสี่ยงสูง) ไม่เกี่ยวกับ retention; ก้อนในโจทย์ไม่ใช่ abscess (ไม่มีไข้ ไม่อยู่ที่แผล); จะถูกถ้าโจทย์เป็นแผลบวมแดงมีหนองหลังผ่าตัด hernia ในผู้ป่วยความเสี่ยงสูง","D":"การให้สารน้ำทางหลอดเลือดมาก (&gt;500 mL ระหว่างผ่าตัด) ทำให้กระเพาะปัสสาวะเต็มเร็วระหว่างที่ detrusor ถูกยับยั้งจากยาระงับความรู้สึก เป็น<b>ปัจจัยเสี่ยง</b>ของ retention; ควรจำกัดสารน้ำ; จะถูกถ้าโจทย์เป็นผู้ป่วย dehydration หรือ AKI ก่อนไต","E":"Anticholinergic (atropine, glycopyrrolate, oxybutynin) ยับยั้ง detrusor contraction ทำให้ retention <b>แย่ลง</b>; ยาที่มีการศึกษาว่าอาจลด POUR คือ alpha-blocker (tamsulosin) ก่อนผ่าตัดในชาย แต่ผลยังไม่สม่ำเสมอ; anticholinergic จะถูกถ้าโจทย์เป็น overactive bladder หรือ urge incontinence"},"trap":"ตีความก้อน cystic เหนือหัวหน่าวว่าเป็น seroma หรือ abscess แล้วเลือก antibiotic — ก้อนกลางท้องน้อย 15 cm หลังผ่าตัด groin คือกระเพาะปัสสาวะเต็ม (ตรวจด้วย bladder scan หรือสวนปัสสาวะ); seroma อยู่ที่ groin หรือ scrotum ตามแผล","summary":["Postoperative urinary retention หลังผ่าตัด hernia พบ 1–22% เป็นภาวะแทรกซ้อนระยะแรกที่พบบ่อยที่สุดอย่างหนึ่ง","ปัจจัยเสี่ยง: อายุมาก, ชาย, BPH หรือ LUTS เดิม, bilateral repair, laparoscopic, general หรือ spinal anesthesia, IV fluid มาก, opioid, anticholinergic, ปวดแผลมาก, ผ่าตัดนาน","ป้องกัน: ปัสสาวะก่อนเข้าห้องผ่าตัด, ใช้ local anesthesia ใน open repair เมื่อทำได้, จำกัดสารน้ำ, analgesia แบบ multimodal ลด opioid, ลุกเดินเร็ว","วินิจฉัย: ปัสสาวะไม่ออกหรือออกน้อย ปวดหน่วง คลำได้กระเพาะปัสสาวะเหนือหัวหน่าว → bladder scan (&gt;400–600 mL)","รักษา: in-and-out catheterization หรือคาสายชั่วคราว; ถ้า retention ซ้ำให้ทดลองถอดสายพร้อม alpha-blocker และปรึกษา urology","Kegel = stress incontinence; anticholinergic = urge incontinence (แต่ทำ retention แย่ลง)","ดูข้อ 714, 715, 717, 718 (hernia) และข้อ 707, 716 (hernia กับปัญหาปัสสาวะ)"],"notes":"ไฟล์เฉลยบท \"+=Hernia\" แถว 3: <b>A</b> — คำอธิบาย <b>\"bladder\"</b> (คีย์บอกว่าก้อน cystic เหนือหัวหน่าวคือกระเพาะปัสสาวะ)<br>ต้นฉบับเขียน \"cystic-<b>liked</b> lesion\" (สะกดตามผู้จด) — stem ของเราไม่บอกว่าก้อนคือกระเพาะปัสสาวะ ให้ผู้สอบตีความเอง<br>ช้อย A–C แปลจากต้นฉบับ (A \"Analgesic\", B \"Kegel Exercise\", C \"Prophylaxis antibiotic\"); D, E แต่งเพิ่ม","mnemonic":"<b>ปวด → sympathetic → sphincter หด → ฉี่ไม่ออก</b> = แก้ปวดช่วยให้ฉี่ออก","guide":"HerniaSurge 2018","variants":["ชายอายุ 72 ปีหลัง TEP ทั้งสองข้าง 6 ชม. ยังไม่ปัสสาวะ ปวดหน่วงท้องน้อย bladder scan 750 mL → in-and-out catheterization","ปัจจัยใดระหว่างผ่าตัดเพิ่มความเสี่ยงปัสสาวะไม่ออกหลังผ่าตัด hernia มากที่สุด → IV fluid ปริมาณมากและ general หรือ spinal anesthesia","หลัง Lichtenstein repair 1 สัปดาห์ มีก้อนนุ่ม fluctuant ที่แผล groin ไม่แดง ไม่มีไข้ → seroma ให้สังเกตอาการ"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A — ต้นฉบับ \"groin mass\" ไม่บอกอายุ ถ้าเป็นเด็ก herniotomy (ช้อย B) จะถูก จึงเติมว่าเป็นผู้ใหญ่ชายที่มี symptomatic reducible inguinal hernia; สอดคล้องกับข้อสอบชุด 76A และ 77D (Lichtenstein mesh repair). ความมั่นใจสูง","page":9,"page2":4,"orig":"Hernia 4","stem":"An adult man has a symptomatic, reducible inguinal hernia and is scheduled for elective repair. Which operation is most appropriate?","gray":"คนไข้เป็น groin mass รักษาไง — A. Lichtenstein’s repair B. Herniotomy C. (ว่าง)","opts":["Lichtenstein repair","Herniotomy alone","Bassini tissue repair","Truss","Observation without follow-up"],"ans":0,"key":"A Lichtenstein’s repair (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: ต้นฉบับเขียนแค่ \"groin mass\" — เติมว่าเป็นผู้ใหญ่ชายที่มี symptomatic reducible inguinal hernia (herniotomy ใช้ในเด็ก)","interp":"ผู้ใหญ่ชายที่มี<b>inguinal hernia ที่มีอาการและดันกลับได้</b> นัดผ่าตัด elective — ถามวิธีผ่าตัดมาตรฐานในผู้ใหญ่ ต้องแยกจากการผ่าตัดในเด็ก","why":"ผู้ใหญ่ที่มี symptomatic inguinal hernia ควรได้ <b>mesh repair</b> ซึ่ง recurrence ต่ำกว่า tissue repair — HerniaSurge 2018 แนะนำ <b>Lichtenstein</b> (open, tension-free mesh วางบน posterior wall ใต้ external oblique) หรือ laparoscopic (TEP, TAPP) ตามความชำนาญ; laparoscopic เหมาะกว่าใน bilateral, recurrent หลัง open repair และผู้หญิง; Lichtenstein เหมาะกับ primary unilateral และทำใต้ local anesthesia ได้","wrong":{"B":"Herniotomy (ผูกและตัด hernia sac อย่างเดียว ไม่ซ่อม posterior wall) เป็นการผ่าตัดใน<b>เด็ก</b>เพราะสาเหตุคือ patent processus vaginalis ส่วน posterior wall ปกติ; ในผู้ใหญ่ herniotomy อย่างเดียว recurrence สูง; จะถูกถ้าโจทย์เป็นเด็กอายุ 2 ปีมี indirect inguinal hernia","C":"Bassini repair (เย็บ conjoint tendon กับ inguinal ligament) เป็น tissue repair ที่มี tension และ recurrence สูงกว่า mesh; ถ้าต้องทำ tissue repair HerniaSurge แนะนำ Shouldice; จะใกล้เคียงถ้าโจทย์เป็นผู้ป่วยที่ไม่ต้องการ mesh หรือแผลปนเปื้อนมาก (strangulated hernia ที่ต้องตัดลำไส้)","D":"Truss (กางเกงพยุง) ไม่แนะนำเป็นการรักษา ไม่ป้องกัน incarceration อาจทำให้ปวดและผิวหนังอักเสบ; ใช้ได้ชั่วคราวในผู้ป่วยที่ผ่าตัดไม่ได้จริงและปฏิเสธการผ่าตัด","E":"Watchful waiting ใช้ได้ในชายที่<b>ไม่มีอาการหรืออาการน้อย</b> โดยต้องติดตามและอธิบายอาการเตือนของ incarceration (ส่วนใหญ่จะมีอาการและต้องผ่าตัดในภายหลัง) ไม่ใช่สังเกตโดยไม่ติดตาม; ผู้ป่วยรายนี้มีอาการจึงควรผ่าตัด; จะใกล้เคียงถ้าโจทย์เป็นชายสูงอายุไม่มีอาการและมีโรคร่วมมาก"},"trap":"เห็นคำว่า herniotomy แล้วคิดว่าเป็นการผ่าตัด hernia ทั่วไป — herniotomy ใช้ในเด็ก; ผู้ใหญ่ต้องซ่อม posterior wall ด้วย mesh (herniorrhaphy หรือ hernioplasty)","summary":["คำศัพท์: herniotomy = ตัด sac; herniorrhaphy = ตัด sac + เย็บซ่อม tissue (Bassini, Shouldice, McVay); hernioplasty = ซ่อมด้วย mesh (Lichtenstein, TEP, TAPP)","HerniaSurge 2018: ผู้ใหญ่ symptomatic inguinal hernia → mesh repair; Lichtenstein หรือ laparoscopic ตามความชำนาญ","เลือก laparoscopic (TEP, TAPP) เมื่อ bilateral, recurrent หลัง open repair, ผู้หญิง (หา femoral hernia ร่วม), ต้องการกลับไปทำงานเร็ว; เลือก open เมื่อ recurrent หลัง laparoscopic, เคยผ่าตัด lower abdomen มาก, ต้องการ local anesthesia","Tissue repair ที่ดีที่สุดเมื่อไม่ใช้ mesh = Shouldice","Watchful waiting: ชายที่ไม่มีอาการหรืออาการน้อย ปลอดภัย แต่ราว 70% จะมีอาการจนต้องผ่าตัดภายใน 5–10 ปี; femoral hernia และผู้หญิงไม่ควรรอ","เด็ก: herniotomy เสมอ ผ่าตัดเร็วหลังวินิจฉัย (ทารกคลอดก่อนกำหนดเสี่ยง incarceration สูง)","ดูข้อ 714, 715, 716, 718, 707 (hernia)"],"notes":"ไฟล์เฉลยบท \"+=Hernia\" แถว 4: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับเขียนแค่ \"คนไข้เป็น groin mass รักษาไง\" — เราเติมใน stem ว่าเป็นผู้ใหญ่ชายที่มี symptomatic reducible inguinal hernia นัดผ่าตัด elective เพราะถ้าเป็นเด็ก herniotomy (ช้อย B) จะเป็นคำตอบ<br>ช้อย A ต้นฉบับ \"Lichtenstein’s repair\" → Lichtenstein repair; B \"Herniotomy\" → Herniotomy alone; ช้อย C ในต้นฉบับเป็นช่องว่าง — C, D, E แต่งเพิ่ม","mnemonic":"<b>เด็ก = -otomy (ตัด sac) · ผู้ใหญ่ = -plasty (mesh)</b>","guide":"HerniaSurge 2018","variants":["เด็กชายอายุ 3 ปีมีก้อนที่ขาหนีบขวาโป่งเวลาร้องไห้ ดันกลับได้ → herniotomy","ชายอายุ 55 ปีมี bilateral inguinal hernia ที่มีอาการ → laparoscopic TEP หรือ TAPP ด้วย mesh","ชายอายุ 65 ปีเคยทำ Lichtenstein repair ข้างขวา แล้ว recurrence ข้างเดิม → laparoscopic repair (posterior approach)"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"<b>ไม่เห็นด้วยกับคีย์ D</b> — colonic obstruction ทำให้เบ่ง เพิ่ม intra-abdominal pressure และตำราสอนให้มองหา colon cancer ในผู้สูงอายุที่เพิ่งเป็น hernia จึงเป็น risk factor; ช้อย A–C ก็เป็น risk factor ทั้งหมด (แผล open appendectomy เพิ่มความเสี่ยง right inguinal hernia, ascites, smoking) ข้อสอบต้นฉบับจึงไม่มีช้อยที่ \"ไม่ใช่ risk factor\" ที่ชัดเจน เราจึงแต่งช้อย E และตอบ E. ความมั่นใจปานกลาง — ถ้าข้อสอบจริงมีแค่ A–D ผู้ออกอาจตั้งใจให้ A (มองว่าแผล appendectomy ทำให้ incisional hernia มากกว่า inguinal hernia) หรือ D ตามคีย์ (มองว่า colon cancer ไม่ได้เกี่ยวกับ hernia โดยตรง); เราเลือกตามหลักฐานว่าทั้งสองเป็น risk factor","page":9,"page2":4,"orig":"Hernia 5","stem":"A man presents with an inguinal mass that enlarges on standing. Which of the following is NOT a risk factor for his condition?","gray":"Male Patient present with mass in inguinal area that increase size when standing. What is not a risk of his condition — A. long wound from appendectomy B. Ascites from cirrhosis C. Smoking &gt; 5 pack year D. Partial obstruction from ca colon","opts":["Long wound from appendectomy","Ascites from cirrhosis","Smoking more than 5 pack-years","Partial obstruction from colon cancer","Well-controlled hypertension"],"ans":4,"key":"D Partial obstruction from ca colon (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ ตอบต่างจากคีย์: ช้อย A–D ในต้นฉบับเป็น risk factor ของ inguinal hernia ทั้งหมด — colonic obstruction ทำให้เบ่ง ↑intra-abdominal pressure (ตำราให้หา colon cancer ในผู้สูงอายุที่เพิ่งเป็น hernia) จึงไม่ใช่คำตอบ; แต่งช้อย E (well-controlled hypertension) เป็นสิ่งที่ไม่ใช่ risk factor","interp":"ชายมีก้อนที่ขาหนีบโตขึ้นเวลายืน = <b>inguinal hernia</b> — ถามสิ่งที่<b>ไม่ใช่</b> risk factor ต้องรู้ว่า risk factor มาจาก 2 กลไก: intra-abdominal pressure เพิ่ม และผนังหน้าท้องอ่อนแอ","why":"<b>Well-controlled hypertension</b> ไม่เพิ่ม intra-abdominal pressure และไม่ทำให้ผนังหน้าท้องอ่อนแอ จึง<b>ไม่ใช่</b> risk factor ของ inguinal hernia — ส่วนช้อย A–D เป็น risk factor ทั้งหมด: แผล appendectomy (ทำลาย ilioinguinal และ iliohypogastric nerve → กล้ามเนื้อ internal oblique และ transversus อ่อนแรง เสีย shutter mechanism → right inguinal hernia), ascites (↑IAP), smoking (ความผิดปกติของ collagen: สัดส่วน collagen type I ต่อ III ลด และ MMP เพิ่ม), colonic obstruction (เบ่งถ่าย → ↑IAP)","wrong":{"A":"แผล appendectomy เป็น risk factor ของ <b>right inguinal hernia</b> (โดยเฉพาะ open appendectomy แผลยาวหรือแผลติดเชื้อ ที่ทำลาย ilioinguinal หรือ iliohypogastric nerve และกล้ามเนื้อ) และยังเป็นปัจจัยของ incisional hernia ที่แผลเอง; จะเป็นคำตอบถ้าผู้ออกข้อสอบตั้งใจว่าแผลผ่าตัดทำให้เกิดแค่ incisional hernia ไม่ใช่ inguinal hernia (ดู opinion)","B":"Ascites จาก cirrhosis เพิ่ม intra-abdominal pressure ต่อเนื่อง ทำให้เกิดทั้ง umbilical และ inguinal hernia ได้บ่อย (เช่นเดียวกับ peritoneal dialysis); จะไม่ใช่ risk factor ถ้า ascites ถูกควบคุมจนหมดแล้วนาน — แต่ในรูปช้อยนี้เป็น risk factor","C":"การสูบบุหรี่ทำให้ collagen metabolism ผิดปกติ (collagen type III เพิ่มเทียบ type I, protease เพิ่ม) ผนังหน้าท้องและ transversalis fascia อ่อนแอ เป็น risk factor ของ direct inguinal hernia และ recurrence หลังผ่าตัด อีกทั้งไอเรื้อรัง; ไม่ใช่คำตอบ","D":"<b>คีย์เลือกช้อยนี้</b> แต่ colonic obstruction บางส่วนทำให้ท้องผูกต้องเบ่ง ↑intra-abdominal pressure จึงเป็น risk factor; ตำราสอนให้หา colon cancer ในผู้สูงอายุที่<b>เพิ่งเป็น</b> inguinal hernia โดยไม่มีสาเหตุอื่น; จะเป็นคำตอบถ้าผู้ออกข้อสอบตั้งใจว่า colon cancer ไม่ได้เกี่ยวกับ hernia โดยตรง"},"trap":"มองว่า colon cancer เป็นโรคคนละระบบกับ hernia — แต่ก้อนที่อุดลำไส้ทำให้เบ่งถ่ายเรื้อรัง เพิ่ม intra-abdominal pressure เหมือน chronic cough และ BPH","summary":["Risk factor จาก intra-abdominal pressure เพิ่ม: chronic cough (COPD), ท้องผูกเรื้อรังหรือเบ่งถ่าย (รวม colonic obstruction), BPH หรือเบ่งปัสสาวะ, ascites, peritoneal dialysis, ยกของหนัก, ตั้งครรภ์","Risk factor จากผนังหน้าท้องอ่อนแอ: อายุมาก, collagen disorder (Ehlers-Danlos, Marfan), smoking, family history, แผลผ่าตัด RLQ (open appendectomy) ที่ทำลายเส้นประสาท, abdominal aortic aneurysm (collagen ผิดปกติร่วม)","ปัจจัยอื่น: เพศชาย (เสี่ยงตลอดชีวิตราว 27% ในชาย ราว 3% ในหญิง), patent processus vaginalis, ทารกคลอดก่อนกำหนด, BMI ต่ำ (คนอ้วนกลับพบ inguinal hernia น้อยกว่า)","ผู้สูงอายุที่เพิ่งเกิด inguinal hernia ให้ซักประวัติการขับถ่าย น้ำหนักลด ถ่ายเป็นเลือด และพิจารณาหา colorectal cancer, BPH, ไอเรื้อรัง","ก่อนผ่าตัดควรแก้ปัจจัยที่แก้ได้: หยุดบุหรี่, รักษาไอ, รักษา BPH หรือท้องผูก, คุม ascites — ลด recurrence","ดูข้อ 714, 715, 716, 717, 707 (hernia)"],"notes":"ไฟล์เฉลยบท \"+=Hernia\" แถว 5: <b>D</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับมีช้อย 4 ตัว A \"long wound from appendectomy\", B \"Ascites from cirrhosis\", C \"Smoking &gt; 5 pack year\" → Smoking more than 5 pack-years, D \"Partial obstruction from ca colon\" → Partial obstruction from colon cancer — <b>ทั้ง 4 ช้อยเป็น risk factor ของ inguinal hernia</b> จึงแต่งช้อย E (Well-controlled hypertension) เป็นสิ่งที่ไม่ใช่ risk factor และตอบ E ต่างจากคีย์ D","mnemonic":"<b>ดัน (pressure) + อ่อน (weak wall)</b>: ไอ เบ่ง ท้องมาน ยกหนัก / แก่ สูบบุหรี่ collagen แผล RLQ","guide":"HerniaSurge 2018; Bailey &amp; Love 28th ed.","variants":["ชายอายุ 72 ปีเพิ่งมี left inguinal hernia 2 เดือน ร่วมกับถ่ายอุจจาระลำเล็กลง น้ำหนักลด 5 kg ควรทำอะไรก่อนผ่าตัด hernia → colonoscopy หามะเร็งลำไส้ใหญ่","ชายอายุ 68 ปีมี inguinal hernia และปัสสาวะไม่พุ่ง ต้องเบ่ง ควรทำอะไรก่อนผ่าตัด → ประเมินและรักษา BPH","ผู้ป่วย cirrhosis มี tense ascites และ inguinal hernia ที่มีอาการ ควรทำอะไรก่อนผ่าตัด → คุม ascites (diuretic, paracentesis) และปรับสภาพตับ"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":10,"page2":4,"orig":"Small bowel 1","stem":"Which radiologic finding is most specific for strangulated small bowel obstruction?","gray":"ข้อใดเป็น specific sign ของ Strangulated small bowel obstruction — A. Pneumatosis intestinalis B. String of bead C. Small bowel dilatation D. Step ladder","opts":["Pneumatosis intestinalis","String-of-beads sign","Small bowel dilatation","Step-ladder pattern","Multiple air-fluid levels"],"ans":0,"key":"A Pneumatosis intestinalis (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ถามหา sign ที่ <b>เจาะจงต่อ strangulation</b> (ลำไส้ขาดเลือด) ไม่ใช่ sign ที่บอกแค่ว่ามี small bowel obstruction — ต้องแยกให้ออกว่าช้อยไหนบอก “อุดตัน” และช้อยไหนบอก “ลำไส้เริ่มตาย”","why":"<b>Pneumatosis intestinalis</b> คือแก๊สในผนังลำไส้ เกิดเมื่อ mucosa ขาดเลือดจน barrier เสีย แก๊สจาก lumen หรือแบคทีเรียแทรกเข้าผนัง = <b>transmural ischemia</b>; เมื่อแก๊สเดินทางต่อไปตาม mesenteric vein จะเห็น <b>portal venous gas</b> — สองอย่างนี้ specific ต่อ strangulation/ischemia มาก แต่เป็น sign ที่มาช้า (ลำไส้ตายแล้ว) จึงไม่ไว (sensitivity ต่ำ); เห็นเมื่อไรต้องผ่าตัดฉุกเฉิน","wrong":{"B":"String-of-beads sign คือฟองแก๊สเล็ก ๆ เรียงเป็นแถวติดอยู่ใต้ valvulae conniventes ใน loop ที่เต็มไปด้วยน้ำ บอกว่าเป็น <b>mechanical SBO ระดับ high-grade</b> แต่ไม่ได้บอกว่าลำไส้ขาดเลือด; จะถูกถ้าโจทย์ถาม sign บน plain film ที่ค่อนข้างจำเพาะต่อ SBO","C":"Small bowel dilatation (&gt;3 cm) เป็นลักษณะพื้นฐานของ SBO ทุกชนิด รวมทั้ง ileus — ไม่จำเพาะต่อ strangulation เลย; จะถูกถ้าถาม finding แรกที่ใช้วินิจฉัยว่ามีลำไส้เล็กอุดตันหรือขยาย","D":"Step-ladder pattern คือ loop ลำไส้เล็กขยายเรียงซ้อนกันเป็นขั้นบันไดพร้อม air-fluid levels คนละระดับ บอกว่ามี <b>mechanical SBO</b> (มักเป็น adhesive SBO) ไม่บอก ischemia; จะถูกถ้าถาม plain film ของ distal SBO","E":"Multiple air-fluid levels พบได้ทั้ง SBO, ileus และ gastroenteritis — ไม่จำเพาะต่อ strangulation; จะถูกถ้าถาม finding ใน upright film ที่เข้าได้กับลำไส้อุดตัน"},"trap":"เลือก step-ladder หรือ string of beads เพราะจำได้ว่าเป็น “sign ของ SBO” — แต่โจทย์ถามความจำเพาะต่อ <b>strangulation</b> ซึ่งต้องเป็น sign ของลำไส้ขาดเลือด (pneumatosis, portal venous gas, ผนังไม่ enhance) ไม่ใช่ sign ของการอุดตัน","summary":["SBO บน plain film: ลำไส้เล็กขยาย &gt;3 cm, step-ladder, multiple air-fluid levels, string of beads (high-grade), แก๊สในลำไส้ใหญ่น้อยหรือไม่มี","CT เป็น investigation หลักของ SBO: หา transition point, สาเหตุ (adhesion, hernia, tumor), closed loop และ sign ของ ischemia","CT sign ของ strangulation: wall enhancement ลดหรือหาย, wall thickening, mesenteric edema หรือ haziness, ascites, closed loop รูป U หรือ C, whirl sign","Sign ที่ specific ที่สุดแต่มาช้า: <b>pneumatosis intestinalis และ portal venous gas</b> = transmural ischemia","Clinical ที่บอก strangulation: ไข้ ชีพจรเร็ว ปวดตลอดไม่เป็นพัก peritonitis WBC และ lactate สูง — ไม่มีตัวใดตัวหนึ่งไวพอ จึงต้องใช้ร่วมกับ CT","รักษา: ASBO ที่ไม่มี strangulation → NPO, NG decompression, IV fluid ± water-soluble contrast challenge; มี strangulation หรือ peritonitis → ผ่าตัดฉุกเฉิน","ดูข้อ 720, 721, 733, 734 (small bowel, obstruction และ mesenteric ischemia)"],"notes":"ไฟล์เฉลย (หน้า 4 บท Small bowel and Small bowel obstruction แถว 1): <b>A</b> (ช่องคำอธิบายในไฟล์เฉลยว่าง) · <b>โน้ตผู้จดในไฟล์โจทย์:</b> ไม่มี; ต้นฉบับมีช้อย A–D (“String of bead”, “Step ladder”) → เราเกลาเป็น String-of-beads sign และ Step-ladder pattern และแต่งช้อย E Multiple air-fluid levels","mnemonic":"<b>อุดตัน = ขั้นบันได ลูกปัด; ลำไส้ตาย = แก๊สในผนัง แก๊สใน portal vein</b>","guide":"Bologna ASBO guidelines (WSES) 2017","variants":["ผู้ป่วยเคยผ่าตัดช่องท้อง มาด้วยปวดท้อง อาเจียน ไม่ผายลม CT พบ closed-loop ลำไส้เล็กผนังไม่ enhance และมีน้ำในช่องท้อง → strangulated SBO ผ่าตัดฉุกเฉิน","ผู้ป่วย adhesive SBO ไม่มีไข้ ชีพจรปกติ CT ไม่มี sign ของ ischemia → NPO, NG decompression, IV fluid และ water-soluble contrast challenge","CT ของผู้ป่วยปวดท้องรุนแรงพบแก๊สในผนังลำไส้เล็กและแก๊สในแขนงของ portal vein → transmural bowel ischemia ต้องผ่าตัดสำรวจ"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":10,"page2":5,"orig":"Small bowel 2","stem":"On postoperative day 5, a bedridden patient who recently had a stroke still has marked abdominal distension and has not passed flatus despite 48 hours of conservative treatment with correction of electrolytes. Imaging shows diffuse colonic dilatation with a cecal diameter of 11 cm and no mechanical obstruction. Which drug is most appropriate?","gray":"POD 5 S/P คนไข้ stroke แต่ยังมี ileus ถามว่าให้ยาอะไรดี — A. Neostigmine B. Atropine C. Epinephrine D. PEG E. Loperamide","opts":["Neostigmine","Atropine","Epinephrine","Polyethylene glycol","Loperamide"],"ans":0,"key":"A Neostigmine (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: neostigmine มีหลักฐานใน acute colonic pseudo-obstruction ไม่ใช่ postoperative ileus ทั่วไป — เติมใน stem ว่ารักษาแบบประคับประคอง 48 ชม.แล้วไม่ดีขึ้น แก้ electrolyte แล้ว ภาพแสดงลำไส้ใหญ่ขยายทั่วไป cecum 11 cm ไม่มีการอุดตันทางกล","interp":"ผู้ป่วยติดเตียงหลัง stroke หลังผ่าตัด ลำไส้ใหญ่ขยายทั่วไปโดยไม่มีจุดอุดตัน รักษาประคับประคองแล้วไม่ดีขึ้น และ cecum ขยายถึง 11 cm → ถามยาที่ <b>กระตุ้นการบีบตัวของลำไส้ใหญ่</b> เพื่อ decompress ก่อนถึงขั้นทำ colonoscopy","why":"<b>Neostigmine</b> เป็น acetylcholinesterase inhibitor → acetylcholine ที่ muscarinic receptor เพิ่ม → <b>parasympathetic tone ของลำไส้ใหญ่เพิ่ม</b> แก้ภาวะที่ sympathetic เด่นเกินจนลำไส้ใหญ่ไม่บีบตัว; ขนาด 2 mg IV ฉีดช้า ๆ 3–5 นาที ตอบสนองราว 80–90% (มักผายลม/ถ่ายภายใน 30 นาที); ให้เมื่อ conservative 24–48 ชม.ไม่ได้ผลหรือ cecum &gt;10–12 cm โดยต้อง monitor ECG และเตรียม atropine ไว้แก้ bradycardia; ข้อห้าม: mechanical obstruction, perforation, bradycardia, bronchospasm","wrong":{"B":"Atropine เป็น anticholinergic → <b>ลด</b> motility ของลำไส้ ทำให้ลำไส้ขยายมากขึ้น; ใช้เป็นยาแก้พิษเมื่อเกิด symptomatic bradycardia จาก neostigmine — จะถูกถ้าโจทย์ถามว่าต้องเตรียมยาอะไรไว้ข้างเตียงระหว่างฉีด neostigmine","C":"Epinephrine กระตุ้น sympathetic (α, β) → ลำไส้คลายตัวและหลอดเลือด splanchnic หดตัว ซ้ำเติมภาวะลำไส้ใหญ่ไม่บีบตัว; ไม่มีบทบาทในเคสนี้ — จะถูกในบริบทอื่น อย่าง anaphylaxis หรือ cardiac arrest","D":"Polyethylene glycol ปริมาณมากทางปากเป็น osmotic laxative ใช้ bowel prep — <b>ห้ามให้ขณะลำไส้ใหญ่ยังขยายมาก</b> เพราะเพิ่มปริมาตรในลำไส้และเสี่ยงแตก; PEG ขนาดต่ำต่อเนื่อง <b>หลัง</b> decompression สำเร็จช่วยลดการกลับเป็นซ้ำ — จะถูกถ้าโจทย์ถามการป้องกัน recurrence หลังลำไส้ยุบแล้ว","E":"Loperamide เป็น opioid receptor agonist ที่ลำไส้ → ลด motility ทำให้ ileus แย่ลง; ใช้รักษา diarrhea หรือ high-output stoma — จะถูกถ้าโจทย์ถามยาลดปริมาณ ileostomy output"},"trap":"ต้นฉบับเขียนแค่ “ยังมี ileus” — postoperative ileus ของลำไส้เล็กทั่วไปไม่มียาที่ได้ผลชัด (รักษาด้วย NG, แก้ electrolyte, ลด opioid, ERAS); neostigmine ใช้กับ <b>ลำไส้ใหญ่ขยายแบบ functional</b> ที่รักษาประคับประคองไม่ได้ผล และต้องแยก mechanical obstruction ก่อนเสมอ","summary":["Acute colonic pseudo-obstruction: ลำไส้ใหญ่ขยายโดยไม่มีสิ่งอุดตัน พบในผู้ป่วยหลังผ่าตัด ติดเตียง โรคระบบประสาท ICU electrolyte ผิดปกติ opioid","ต้องแยก mechanical obstruction ด้วย CT หรือ water-soluble contrast enema ก่อน","Conservative 24–48 ชม.: NPO, NG tube, rectal tube, แก้ K และ Mg, หยุด opioid และ anticholinergic, ลุกเดินหรือพลิกตัว","Neostigmine 2 mg IV ช้า ๆ 3–5 นาที ตอบสนอง 80–90%; monitor ECG, เตรียม atropine; ห้ามใน obstruction, perforation, bradycardia, bronchospasm","ไม่ได้ผลหรือห้ามใช้ยา → colonoscopic decompression ± ใส่ decompression tube; perforation หรือ ischemia → ผ่าตัด","เสี่ยงแตกเมื่อ cecum &gt;12 cm หรือขยายนาน &gt;6 วัน; หลัง decompression ให้ PEG ขนาดต่ำลดการกลับเป็นซ้ำ","Postoperative ileus ล้วน ๆ: NG decompression, แก้ electrolyte, ลด opioid, ERAS, early feeding; alvimopan ใช้ป้องกันหลัง bowel resection บางกรณี","ดูข้อ 734 (ภาพลำไส้ใหญ่ขยายในผู้ป่วย ICU) และข้อ 719, 733"],"notes":"ไฟล์เฉลย (หน้า 5 บท Small bowel and Small bowel obstruction แถว 2): <b>A</b> (ช่องคำอธิบายในไฟล์เฉลยว่าง) · <b>โน้ตผู้จดในไฟล์โจทย์:</b> ไม่มี; ต้นฉบับเขียนสั้น ๆ ว่า “POD 5 S/P คนไข้ stroke แต่ยังมี ileus” → เราเติมใน stem ว่าติดเตียง รักษาประคับประคอง 48 ชม.แล้วไม่ดีขึ้น แก้ electrolyte แล้ว ภาพพบลำไส้ใหญ่ขยายทั่วไป cecum 11 cm ไม่มีการอุดตันทางกล; ช้อย D ต้นฉบับ “PEG” → เขียนเต็มเป็น Polyethylene glycol; ช้อยครบ 5 ช้อยตามต้นฉบับ","mnemonic":"<b>Neo-STIG-mine = STIMulate ลำไส้; atropine เตรียมไว้แก้</b>","guide":"ASGE acute colonic pseudo-obstruction and colonic volvulus 2020; ASCRS colonic volvulus and ACPO 2021","variants":["ผู้ป่วยหลังผ่าตัดเปลี่ยนข้อสะโพกวันที่ 4 ท้องอืดมาก CT พบลำไส้ใหญ่ขยายทั่วไป cecum 13 cm ไม่มี transition point แก้ electrolyte แล้วไม่ดีขึ้น → neostigmine 2 mg IV ภายใต้ ECG monitoring","ระหว่างฉีด neostigmine ผู้ป่วยชีพจรลดลงเหลือ 38 ครั้ง/นาที ความดันต่ำ → atropine IV","ผู้ป่วย pseudo-obstruction ได้ neostigmine แล้วไม่ตอบสนอง cecum 12 cm ไม่มี peritonitis → colonoscopic decompression"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":10,"page2":5,"orig":"Small bowel 3","stem":"A 70-year-old man with atrial fibrillation presents with acute colicky abdominal pain. What is the most appropriate investigation?","gray":"Colicky pain without disproportion คนไข้มี U/D เป็น AF ถามว่าทำไรดี — A. CTA B. X-ray C. CT","opts":["CT angiography","Plain abdominal radiograph","Non-contrast CT","Abdominal ultrasound","Colonoscopy"],"ans":0,"key":"A CTA (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: ต้นฉบับเขียน \"without disproportion\" (อาจจดสลับกับ pain out of proportion) — ไม่ว่าแบบไหน AF + ปวดท้องเฉียบพลันต้องคิดถึง acute mesenteric ischemia และส่ง CTA","interp":"ผู้สูงอายุที่มี <b>atrial fibrillation</b> มาด้วยปวดท้องเฉียบพลัน → ต้องคิดถึงลิ่มเลือดหลุดไปอุด superior mesenteric artery ก่อน แล้วถาม investigation ที่ยืนยันได้เร็วและแม่นที่สุด","why":"Acute mesenteric ischemia จาก <b>SMA embolus</b> (~50% ของ AMI, แหล่งลิ่มเลือดคือ AF หรือ valvular disease) มักปวดรุนแรงไม่สัมพันธ์กับตรวจร่างกายในระยะแรก ห้องแลป (lactate, D-dimer) ไวไม่พอจึงห้ามรอผล; <b>biphasic CT angiography</b> (arterial + portal venous phase) เป็น investigation of choice — sensitivity ราว 93–95% specificity ราว 95% เห็นทั้งตำแหน่งที่อุด สภาพผนังลำไส้ pneumatosis และ portal venous gas; ทำทันทีแม้ creatinine สูง เพราะการวินิจฉัยช้าทำให้ลำไส้ตายและ mortality สูงมาก","wrong":{"B":"Plain abdominal radiograph ระยะแรกของ AMI มักปกติ (gasless หรือ ileus ไม่จำเพาะ) เห็นผิดปกติชัดเมื่อลำไส้ตายแล้ว (pneumatosis, free air) — ปกติก็ตัดโรคไม่ได้ ทำให้เสียเวลา; จะถูกถ้าต้องการดู free air ด่วนในผู้ป่วยที่สงสัย perforation และไปทำ CT ไม่ได้","C":"Non-contrast CT ไม่เห็นการอุดตันของหลอดเลือดและการ enhance ของผนังลำไส้ จึงวินิจฉัย AMI ไม่ได้; จะถูกถ้าสงสัยนิ่วในไต (CT KUB) หรือมีข้อห้ามสารทึบรังสีจริงอย่างแพ้รุนแรง","D":"Abdominal ultrasound + Doppler ดู origin ของ SMA และ celiac ได้บ้าง แต่ถูกบังด้วยแก๊สในลำไส้ที่ขยาย ขึ้นกับผู้ตรวจ และไม่เห็น embolus ส่วนปลายหรือสภาพลำไส้ — ไม่เหมาะในภาวะฉุกเฉิน; จะถูกถ้าคัดกรอง chronic mesenteric ischemia หรือสงสัยโรคถุงน้ำดี","E":"Colonoscopy เห็นได้แค่ mucosa ของลำไส้ใหญ่ ใช้ใน ischemic colitis (มักเป็น nonocclusive ที่ watershed area) แต่ไม่เห็น SMA occlusion หรือลำไส้เล็ก และการเป่าลมอาจทำให้ลำไส้ขาดเลือดแย่ลง; จะถูกถ้าผู้ป่วย stable มีถ่ายเป็นเลือดและสงสัย ischemic colitis"},"trap":"ต้นฉบับจดว่า “without disproportion” และใช้คำว่า colicky ซึ่งอาจทำให้ลังเลไปทาง plain film หรือ CT ธรรมดา — แต่ <b>AF + ปวดท้องเฉียบพลันในผู้สูงอายุ = ต้องตัด AMI ด้วย CTA</b> เสมอ ห้ามรอให้มี peritonitis หรือ lactate สูง","summary":["สาเหตุ AMI: SMA embolus ~50% (AF, valvular disease, MI), SMA thrombosis ~25% (atherosclerosis เดิม มี postprandial pain น้ำหนักลด), NOMI (low flow, vasopressor), mesenteric venous thrombosis (hypercoagulable)","อาการ: pain out of proportion ระยะแรก → ต่อมามี peritonitis, ถ่ายเป็นเลือด, shock; lactate และ D-dimer ไวไม่พอ ห้ามใช้ตัดโรค","Investigation of choice: <b>biphasic CTA</b> ทำทันทีแม้ creatinine สูง","รักษา: resuscitation, systemic heparin ทันที, broad-spectrum antibiotics","Revascularization: embolectomy แบบเปิด หรือ endovascular (aspiration, thrombolysis, stent) ขึ้นกับสาเหตุและทรัพยากร","Laparotomy ตัดลำไส้ที่ตาย ± second-look ภายใน 24–48 ชม.; NOMI → แก้สาเหตุ ± intra-arterial papaverine; MVT → anticoagulation","ดูข้อ 760 (embolus จาก AF) และข้อ 719, 720, 733, 734"],"notes":"ไฟล์เฉลย (หน้า 5 บท Small bowel and Small bowel obstruction แถว 3): <b>A</b> (ช่องคำอธิบายในไฟล์เฉลยว่าง) · <b>โน้ตผู้จดในไฟล์โจทย์:</b> ไม่มี; ต้นฉบับเขียน “Colicky pain without disproportion คนไข้มี U/D เป็น AF” (U/D = underlying disease) — คำว่า “without disproportion” อาจเป็นการจดสลับกับ pain out of proportion; ต้นฉบับมีช้อย A–C (“CTA”, “X-ray”, “CT”) → แปลเป็น CT angiography, Plain abdominal radiograph, Non-contrast CT และแต่งช้อย D, E · ในไฟล์โจทย์บทนี้มีแถว 4 (มีแค่ “A.” ว่าง) และแถว 5 ว่าง ไม่ใช่ข้อ; ไฟล์เฉลยบทนี้มีแค่แถว 1–3","mnemonic":"<b>AF + ปวดท้อง = CTA ก่อนคิดอย่างอื่น</b>","guide":"ESVS mesenteric arteries and veins 2017; WSES acute mesenteric ischemia 2022","variants":["หญิงอายุ 75 ปี mitral stenosis ไม่ได้กินยาต้านการแข็งตัวของเลือด ปวดท้องรุนแรงทันที ตรวจท้องนุ่ม → biphasic CTA","ผู้ป่วย CTA พบ SMA อุดตันห่างจาก origin 5 cm ลำไส้ยังไม่มี sign ของการตาย → heparin และ embolectomy หรือ endovascular revascularization","ผู้ป่วย septic shock ใช้ norepinephrine ขนาดสูง ปวดท้องและ lactate สูง CTA พบ SMA เปิดแต่แขนงตีบเป็นช่วง ๆ → nonocclusive mesenteric ischemia"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":10,"page2":5,"orig":"Liver + Jaundice 1","stem":"A 40-year-old woman has persistent epigastric fullness and early satiety. Upper endoscopy is normal. MRI shows a 15 × 20 cm liver mass that is markedly hyperintense on T2-weighted images, and contrast-enhanced CT shows peripheral nodular enhancement in the arterial phase with centripetal fill-in. The mass compresses the stomach. What is the most appropriate management?","gray":"Female present with dyspepsia. Imaging show 15 x 20 cm hyper-intensity mass on MRI T2W1. CT with contrast show peripheral nodular enhancement in arterial phase and central fill-in. What is the management? — A. follow up B. Liver Resection C. Ablation D. Portal vein embolization E. TACE","opts":["Follow-up","Liver resection","Ablation","Portal vein embolization","TACE"],"ans":1,"key":"B Liver Resection (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ ส่วนใหญ่ของก้อนชนิดนี้ (แม้ใหญ่) ดูแลแบบ follow-up (ชุด 77A) — เติมใน stem ว่าอาการชัดและสัมพันธ์กับก้อน (อิ่มเร็ว แน่นท้องต่อเนื่อง ส่องกล้องปกติ ก้อนกดกระเพาะ) อายุ 40 ปี ให้ resection เป็นคำตอบเดียว; ถ้าไม่มีอาการหรืออาการไม่สัมพันธ์ ตอบ follow-up","interp":"ภาพ MRI T2 สว่างมาก (light bulb) + CT มี peripheral nodular enhancement แล้ว fill-in เข้ากลาง = วินิจฉัยก้อนตับชนิด benign ที่พบบ่อยที่สุดได้จากภาพ; ประเด็นคือ <b>ก้อนใหญ่มากและมีอาการที่สัมพันธ์กับก้อน</b> (กดกระเพาะ หลังแยกสาเหตุอื่นด้วยการส่องกล้องแล้ว) → ถามว่าเมื่อไรต้องรักษา และรักษาด้วยวิธีใด","why":"Liver hemangioma ส่วนใหญ่ <b>observe ไม่ว่าขนาดเท่าไร</b> (EASL 2016) แต่ข้อบ่งชี้ในการรักษาคือ <b>อาการที่พิสูจน์ได้ว่าเกิดจากก้อน</b> (หลังแยกสาเหตุอื่นแล้ว), Kasabach–Merritt syndrome, rupture, โตเร็ว หรือวินิจฉัยไม่ชัด; ผู้ป่วยรายนี้อายุน้อย ก้อน 15 × 20 cm กดกระเพาะจนอิ่มเร็วแน่นท้องต่อเนื่อง และส่องกล้องปกติ → <b>surgical resection</b> (enucleation ซึ่งเสียเลือดและเสียเนื้อตับน้อยกว่า หรือ anatomical resection) เป็นการรักษาหลักที่หายขาด","wrong":{"A":"Follow-up เป็นคำตอบของก้อนชนิดนี้ส่วนใหญ่ — ไม่มีอาการ หรืออาการคลุมเครือที่ไม่สัมพันธ์กับก้อน ไม่ต้องตามภาพซ้ำถ้าวินิจฉัยชัด; ในข้อนี้อาการชัดและสัมพันธ์กับก้อนจึงไม่พอ — จะถูกถ้าผู้ป่วยไม่มีอาการ หรืออาการ dyspepsia ไม่สัมพันธ์กับก้อนแบบในข้อสอบชุด 77A เรื่องเดียวกัน","C":"Ablation (RFA, MWA) ใช้ได้ในก้อนเล็กไม่เกินราว 5–10 cm ในศูนย์ที่ชำนาญ ก้อน 15 × 20 cm ใหญ่เกินกว่าจะ ablate ได้ครบและเสี่ยง hemolysis, AKI; จะถูกถ้าก้อนมีอาการขนาดไม่ใหญ่และผู้ป่วยเสี่ยงผ่าตัดสูง","D":"Portal vein embolization ใช้เพิ่ม future liver remnant ก่อน major hepatectomy ในผู้ป่วยมะเร็งที่ FLR ไม่พอ ไม่ได้รักษาก้อนโดยตรง; จะถูกถ้าโจทย์ถามการเตรียมตัวก่อน extended hepatectomy ที่ FLR น้อยกว่า 20–30%","E":"TACE เป็นการรักษา HCC ระยะ intermediate; ในก้อนชนิดนี้ใช้ <b>TAE</b> (ไม่ใส่ยาเคมี) เพื่อลดขนาดหรือลดเลือดออกก่อนผ่าตัด หรือในผู้ที่ผ่าตัดไม่ได้หรือก้อนแตก — ไม่ใช่การรักษาหลักในผู้ป่วยอายุน้อยที่ผ่าตัดได้; จะถูกถ้าเป็น HCC BCLC B"},"trap":"เห็นก้อนใหญ่ 15 × 20 cm แล้วรีบผ่าตัดเพราะขนาดอย่างเดียว — ขนาดไม่ใช่ข้อบ่งชี้ในตัวเอง; ต้องมีอาการที่สัมพันธ์กับก้อนหลังแยกสาเหตุอื่น หรือมีภาวะแทรกซ้อน; อีกกับดักคือคิดจะ biopsy ก้อนนี้ ซึ่งห้ามทำเพราะเลือดออกมาก","summary":["Hemangioma = benign liver tumor ที่พบบ่อยที่สุด ผู้หญิงมากกว่า ส่วนใหญ่ไม่มีอาการ พบโดยบังเอิญ","ภาพ: US hyperechoic ขอบชัด; MRI T2 สว่างมาก (light bulb); CT หรือ MRI มี <b>peripheral nodular discontinuous enhancement แล้ว centripetal fill-in</b> ใน delayed phase","ห้าม biopsy; วินิจฉัยชัดจากภาพแล้วไม่ต้องตามภาพซ้ำ และไม่ต้องห้ามตั้งครรภ์หรือยาคุม","ข้อบ่งชี้รักษา: อาการที่พิสูจน์ว่าเกิดจากก้อน, Kasabach–Merritt (thrombocytopenia, consumptive coagulopathy), rupture, โตเร็ว, วินิจฉัยไม่ชัด","วิธีรักษา: enucleation หรือ anatomical resection; TAE ก่อนผ่าตัดหรือในผู้ที่ผ่าตัดไม่ได้หรือก้อนแตก; ablation ในก้อนไม่ใหญ่; liver transplant ในรายที่ใหญ่มากผ่าตัดไม่ได้","PVE ใช้เพิ่ม FLR ก่อน major hepatectomy ไม่ใช่การรักษา hemangioma; TACE ใช้กับ HCC","ดูข้อ 725, 726, 729 (ก้อนและโรคตับอื่นในชุดนี้)"],"notes":"ไฟล์เฉลย (หน้า 5 บท Liver + Jaundice แถว 1): <b>B</b> (ช่องคำอธิบายในไฟล์เฉลยว่าง) · <b>โน้ตผู้จดในไฟล์โจทย์:</b> ไม่มี; หัวบท “Liver + Jaundice” ในไฟล์โจทย์มี “A.” ว่างอยู่ในช่อง Choice ข้างหัวบท (ไม่ใช่ข้อ) · สิ่งที่เราปรับ: ต้นฉบับบอกแค่ “Female present with dyspepsia” → เติมอายุ 40 ปี อาการแน่นลิ้นปี่และอิ่มเร็วต่อเนื่อง ส่องกล้องปกติ และก้อนกดกระเพาะ เพื่อให้อาการสัมพันธ์กับก้อนชัด; “MRI T2W1” ในต้นฉบับ = T2-weighted image; “central fill-in” เขียนเป็น centripetal fill-in; ช้อยครบ 5 ช้อยตามต้นฉบับ","mnemonic":"","guide":"EASL benign liver tumours 2016; ACG focal liver lesions 2024","variants":["หญิงอายุ 35 ปี ตรวจสุขภาพพบก้อนตับ 6 cm MRI T2 สว่างมาก มี peripheral nodular enhancement แล้ว fill-in ไม่มีอาการ → observe ไม่ต้องตามภาพซ้ำ","ผู้ป่วยก้อนตับขนาด 18 cm ลักษณะภาพเหมือนกัน เกล็ดเลือด 30,000 fibrinogen ต่ำ → Kasabach–Merritt syndrome ข้อบ่งชี้ผ่าตัดหรือ TAE","ผู้ป่วยก้อนตับลักษณะนี้มาด้วยปวดท้องทันทีและความดันต่ำ CT พบเลือดในช่องท้อง → resuscitation, TAE แล้วผ่าตัดภายหลัง"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":11,"page2":5,"orig":"Liver + Jaundice 2","stem":"A man from Roi Et province presents with painless progressive jaundice and weight loss. What is the most likely diagnosis?","gray":"คนไข้อยู่จังหวัดร้อยเอ็ด มีอาการเหลือง ถามว่าเป็นอะไร — A. CCA B. HCC","opts":["Cholangiocarcinoma","Hepatocellular carcinoma","Choledocholithiasis","Acute hepatitis A","Primary biliary cholangitis"],"ans":0,"key":"A CCA (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: เติม painless progressive jaundice และน้ำหนักลดใน stem (แบบชุด 77D)","interp":"จุดสำคัญคือ <b>ภูมิลำเนาร้อยเอ็ด (ภาคอีสาน)</b> + เหลืองแบบค่อยเป็นค่อยไปไม่ปวด + น้ำหนักลด → มะเร็งที่สัมพันธ์กับพยาธิใบไม้ตับ","why":"ภาคอีสานมีการระบาดของ <b>Opisthorchis viverrini</b> จากการกินปลาน้ำจืดดิบหรือสุก ๆ ดิบ ๆ (ก้อยปลา ปลาร้า ปลาส้ม) พยาธิอยู่ในท่อน้ำดีทำให้อักเสบเรื้อรัง ร่วมกับ nitrosamine ในอาหารหมัก → อุบัติการณ์ <b>cholangiocarcinoma สูงที่สุดในโลก</b> (ขอนแก่น ร้อยเอ็ด และจังหวัดใกล้เคียง); ชนิด perihilar (Klatskin) พบมากสุด อาการเด่นคือ painless progressive jaundice คันน้ำหนักลด; ตรวจ CA19-9 และ US, CT หรือ MRCP","wrong":{"B":"Hepatocellular carcinoma ก็พบบ่อยในไทย (HBV, HCV, alcohol, aflatoxin) แต่อาการเด่นคือปวดชายโครงขวา ก้อนที่ตับ น้ำหนักลด ส่วนเหลืองมักเป็นระยะท้ายจาก liver decompensation หรือ tumor invasion; จะถูกถ้าโจทย์เป็นผู้ป่วย HBV cirrhosis มีก้อนตับและ AFP สูง","C":"Choledocholithiasis ทำให้เหลืองได้แต่มักมี biliary colic เหลืองขึ้นลง ± ไข้ (cholangitis) และไม่ค่อยน้ำหนักลดต่อเนื่อง; จะถูกถ้าโจทย์มีปวด RUQ เป็นพัก ๆ ร่วมกับเหลืองและพบนิ่วในถุงน้ำดี","D":"Acute hepatitis A มีไข้ อ่อนเพลีย คลื่นไส้นำมาก่อนเหลือง เป็นเฉียบพลันและหายเองใน 1–2 เดือน transaminase สูงมาก ไม่ใช่เหลืองแบบค่อยเป็นค่อยไปร่วมกับน้ำหนักลด; จะถูกถ้าเป็นวัยรุ่นไข้นำมาก่อนเหลืองหลังกินอาหารทะเลดิบ","E":"Primary biliary cholangitis พบในหญิงวัยกลางคน คันนำมาก่อนเหลืองนานหลายปี ALP สูง AMA บวก; ไม่สัมพันธ์กับภูมิลำเนาอีสาน; จะถูกถ้าเป็นหญิงอายุ 50 ปีคันเรื้อรัง ALP สูงและ AMA บวก"},"trap":"เลือก HCC เพราะคิดว่าเป็นมะเร็งตับที่พบบ่อยที่สุดในไทยโดยรวม — แต่โจทย์ให้ <b>ภูมิลำเนาอีสาน + เหลือง</b> ซึ่งชี้ไปที่มะเร็งท่อน้ำดีจากพยาธิใบไม้ตับ","summary":["Risk factor ของ CCA: Opisthorchis viverrini (อีสาน), Clonorchis sinensis (เอเชียตะวันออก), PSC, choledochal cyst, hepatolithiasis, HBV และ HCV, nitrosamine","แบ่งตามตำแหน่ง: intrahepatic, perihilar (Klatskin พบมากสุด ~50–60%), distal","อาการ: painless progressive jaundice, คัน, ปัสสาวะสีเข้ม อุจจาระซีด, น้ำหนักลด; ก้อนเหนือ hilum ไม่ทำให้คลำถุงน้ำดีได้","ตรวจ: US เห็นท่อน้ำดีในตับขยายแต่ CBD ปกติ (hilar), CT หรือ MRI + MRCP ประเมินขอบเขต, CA19-9 (สูงลวงได้ใน cholestasis)","Bismuth–Corlette classification ใช้วางแผนผ่าตัดและ biliary drainage","รักษา: resection ที่ได้ R0 เป็นทางเดียวที่หายขาด; adjuvant capecitabine; unresectable → gemcitabine + cisplatin + durvalumab หรือ pembrolizumab และ biliary drainage","ป้องกัน: งดปลาดิบ ตรวจและรักษาพยาธิด้วย praziquantel; แผนคัดกรองด้วย US ในพื้นที่เสี่ยง","ดูข้อ 724 (palliative ใน perihilar CCA) และข้อ 727, 728, 730"],"notes":"ไฟล์เฉลย (หน้า 5 บท Liver + Jaundice แถว 2): <b>A</b> (ช่องคำอธิบายในไฟล์เฉลยว่าง) · <b>โน้ตผู้จดในไฟล์โจทย์:</b> ไม่มี; ต้นฉบับเขียนแค่ “มีอาการเหลือง” → เราเติม painless progressive jaundice และน้ำหนักลดใน stem; ต้นฉบับมีช้อย A “CCA”, B “HCC” → เขียนเต็มเป็น Cholangiocarcinoma, Hepatocellular carcinoma และแต่งช้อย C–E","mnemonic":"<b>ก้อยปลา → พยาธิใบไม้ตับ → มะเร็งท่อน้ำดี</b>","guide":"NCCN Biliary Tract Cancers 2025; EASL-ILCA intrahepatic cholangiocarcinoma 2023","variants":["ชายอายุ 60 ปีจากขอนแก่น ชอบกินก้อยปลา เหลืองมากขึ้นเรื่อย ๆ 2 เดือน US พบท่อน้ำดีในตับทั้งสองข้างขยายแต่ CBD ขนาดปกติ → perihilar cholangiocarcinoma","ผู้ป่วยจากอุดรธานีตรวจอุจจาระพบไข่พยาธิใบไม้ตับ ไม่มีอาการ → praziquantel และแนะนำงดกินปลาดิบ","ผู้ป่วย HBV cirrhosis มีก้อนตับ 4 cm ที่ arterial enhancement และ washout → hepatocellular carcinoma"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":11,"page2":5,"orig":"Liver + Jaundice 3","stem":"A patient with unresectable perihilar cholangiocarcinoma has jaundice and severe pruritus. He declines chemotherapy and radiotherapy and wants comfort-focused care. What is the most appropriate management?","gray":"คนไข้เป็น perihilar CCA ไม่อยากรักษาด้วย chemo หรือรังสี แล้วอยากจะสบาย ๆ ทำไรดี — A. Liver transplant B. PTBD C. ยัด Chemo เข้าไปอีก","opts":["Liver transplantation","Percutaneous transhepatic biliary drainage","More intensive chemotherapy","External beam radiotherapy","Surgical hepaticojejunostomy bypass"],"ans":1,"key":"B PTBD (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: เติม unresectable + jaundice with pruritus ใน stem; ห้ามใส่ ERCP stent เป็นช้อย (เป็นทางเลือกที่ถูกเท่ากันในบาง Bismuth type — ชุด 76A ตอบ ERCP stent)","interp":"ผู้ป่วย perihilar CCA ที่ผ่าตัดไม่ได้ ปฏิเสธการรักษามะเร็ง ต้องการ <b>palliative care</b> และมีอาการจาก obstructive jaundice (คันรุนแรง) → ถามวิธีลดอาการที่ invasive น้อยที่สุดและได้ผล","why":"เป้าหมายคือคุณภาพชีวิต อาการรบกวนหลักคือเหลืองและคันจากท่อน้ำดีอุดตัน → <b>palliative biliary drainage</b>; ใน perihilar tumor โดยเฉพาะ Bismuth III–IV หรือเมื่อ ERCP ทำไม่สำเร็จ <b>PTBD</b> เลือกระบายข้างที่มีเนื้อตับทำงานพอ (drain ≥30–50% ของ liver volume) ได้ผลดีและเสี่ยง cholangitis น้อยกว่าการพยายาม ERCP หลายท่อ; ทำภายใต้ local anesthesia ไม่ต้องดมยาสลบ และเปลี่ยนเป็น internal metal stent ได้ถ้าคาดว่าชีวิตยาวกว่า 3 เดือน","wrong":{"A":"Liver transplantation ใน perihilar CCA ทำได้เฉพาะ Mayo protocol (ก้อน ≤3 cm ไม่มี metastasis และผ่าน neoadjuvant chemoradiation) — ผู้ป่วยรายนี้ unresectable และ <b>ปฏิเสธ chemo และรังสี</b> จึงเข้าเกณฑ์ไม่ได้ และขัดกับเป้าหมายที่ต้องการสบาย; จะถูกถ้าเป็น hilar CCA ขนาดเล็กที่ผ่านโปรโตคอลครบในศูนย์ปลูกถ่ายตับ","C":"More intensive chemotherapy ขัดกับความต้องการของผู้ป่วยที่ปฏิเสธเคมีบำบัดโดยตรง (หลัก autonomy); และให้เคมีบำบัดขณะยังเหลืองสูงไม่ได้ต้อง drain ก่อน — จะถูกถ้าผู้ป่วยต้องการรักษามะเร็ง: gemcitabine + cisplatin + durvalumab หลัง biliary drainage","D":"External beam radiotherapy ผู้ป่วยปฏิเสธแล้ว และไม่ได้แก้การอุดตันของท่อน้ำดีได้ทันที; จะถูกถ้าใช้ในบริบท chemoradiation ของ Mayo protocol หรือ adjuvant หลัง R1 resection","E":"Surgical hepaticojejunostomy bypass ใน hilar tumor ทำยาก ต้องดมยาสลบผ่าตัดใหญ่ morbidity และ mortality สูง ไม่เหมาะกับผู้ป่วยที่ต้องการ comfort care; จะถูกถ้าพบว่าผ่าตัดไม่ได้ระหว่าง laparotomy และวางแผน bypass ไว้แล้ว"},"trap":"เห็นคำว่า “อยากสบาย” แล้วคิดว่าไม่ต้องทำหัตถการอะไรเลย — แต่การระบายน้ำดีเป็น <b>palliative intervention</b> ที่ลดคัน ลด cholangitis และเพิ่มคุณภาพชีวิตได้จริง; อีกกับดักคือ perihilar tumor ระบายด้วย ERCP ได้ยากกว่า distal obstruction","summary":["Unresectable perihilar CCA: palliative biliary drainage เพื่อลดเหลือง คัน และ cholangitis; เตรียมให้เคมีบำบัดได้ถ้าผู้ป่วยต้องการ","Bismuth I–II → ERCP stent ได้ผลดี; Bismuth III–IV หรือ ERCP ล้มเหลว → PTBD","หลักเลือกข้าง: drain ตับที่ไม่ atrophy และไม่มี portal vein invasion ให้ได้อย่างน้อย 30–50% ของ liver volume; ห้ามฉีด contrast เข้าส่วนที่ไม่ drain เพราะเกิด cholangitis","Metal stent เมื่อคาดชีวิตยาวกว่า 3 เดือน (เปิดนานกว่า), plastic stent ถ้าสั้นหรือยังไม่แน่ใจวินิจฉัย","Liver transplant เฉพาะ Mayo protocol: hilar CCA ≤3 cm, ไม่มี nodal หรือ distant metastasis, ผ่าน neoadjuvant chemoradiation","Systemic therapy มาตรฐาน: gemcitabine + cisplatin + durvalumab หรือ pembrolizumab; ทางเลือกเสริม photodynamic therapy หรือ RFA ในท่อน้ำดี","ดูข้อ 723 (cholangiocarcinoma ในอีสาน) และข้อ 727, 728"],"notes":"ไฟล์เฉลย (หน้า 5 บท Liver + Jaundice แถว 3): <b>B</b> (ช่องคำอธิบายในไฟล์เฉลยว่าง) · <b>โน้ตผู้จดในไฟล์โจทย์:</b> ช้อย C ต้นฉบับเขียนภาษาพูดว่า “ยัด Chemo เข้าไปอีก” → แปลเป็น More intensive chemotherapy; ต้นฉบับไม่บอกว่า unresectable และไม่บอกอาการ → เราเติม unresectable, jaundice และ severe pruritus ใน stem; แต่งช้อย D, E โดยไม่ใส่ ERCP with stent เพราะถูกเท่ากันในบาง Bismuth type","mnemonic":"","guide":"NCCN Biliary Tract Cancers 2025; ESGE biliary stenting 2017","variants":["ผู้ป่วย distal CBD cancer ผ่าตัดไม่ได้ เหลืองและคัน คาดชีวิต 6 เดือน → ERCP with self-expandable metal stent","ผู้ป่วย perihilar CCA Bismuth IV ผ่าตัดไม่ได้ ทำ ERCP แล้วใส่ guidewire ผ่านไม่ได้ → PTBD","ผู้ป่วย hilar CCA ก้อน 2.5 cm ไม่มี metastasis ผ่าตัดไม่ได้เพราะ PSC → พิจารณา neoadjuvant chemoradiation ตามด้วย liver transplantation ตาม Mayo protocol"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":11,"page2":5,"orig":"Liver + Jaundice 4","stem":"A 35-year-old man had diarrhea 1 week ago. He now has fever and right upper quadrant pain. CT shows a 5-cm lesion with an enhancing wall in the right lobe of the liver. He is hemodynamically stable. Which of the following is NOT appropriate initial management?","gray":"คนไข้เมื่อ 1 อาทิตย์ที่แล้ว มีอาการท้องเสีย ปัจจุบันมีก้อนที่ liver capsule enhancted ถามว่าข้อใดผิด — A. ให้ยา Ceftri + Metro B. ให้ drain C. (ว่าง)","opts":["Give ceftriaxone plus metronidazole","Routine percutaneous drainage","Send serology for Entamoeba histolytica","Give a luminal agent after metronidazole","Supportive care with analgesics and antipyretics"],"ans":1,"key":"B ให้ drain (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: เติมใน stem ว่า abscess 5 cm ที่ right lobe, hemodynamics ปกติ ไม่มีท่าว่าจะแตก — ถ้าก้อนใหญ่มาก อยู่ left lobe ใกล้ pericardium ใกล้แตก หรือไม่ตอบสนองยา 5–7 วัน การ drain จึงเหมาะ","interp":"ชายวัยทำงาน + <b>ท้องเสียนำมาก่อน 1 สัปดาห์</b> + ไข้ ปวด RUQ + ก้อนเดี่ยวใน right lobe ที่ผนัง enhance → ฝีในตับจากเชื้อโปรโตซัวที่มาจากลำไส้ใหญ่; ถามข้อที่ <b>ไม่ควรทำ</b> เป็นการรักษาเริ่มต้น","why":"Amoebic liver abscess ตอบสนองต่อ <b>metronidazole</b> ดีมาก (ไข้และปวดลดภายใน 3–5 วันในกว่า 90%) จึงไม่ต้อง drain เป็น routine; การเจาะระบายสงวนไว้เมื่อ (1) ไม่ตอบสนองต่อยา 5–7 วัน (2) ก้อนใหญ่มากหรือใกล้แตก (3) อยู่ <b>left lobe</b> เสี่ยงแตกเข้า pericardium (4) วินิจฉัยไม่ชัดหรือสงสัย pyogenic หรือ secondary bacterial infection — ผู้ป่วยรายนี้ก้อน 5 cm ที่ right lobe stable จึง routine drain = ไม่เหมาะ","wrong":{"A":"Ceftriaxone + metronidazole เป็น empirical therapy ที่ถูกต้องระหว่างรอแยก amoebic กับ pyogenic liver abscess เพราะครอบคลุมทั้งแบคทีเรีย (gram-negative, anaerobe) และ E. histolytica; ปรับเหลือ metronidazole เมื่อ serology ยืนยัน — จะเป็นคำตอบ “ไม่เหมาะ” ถ้าให้ ceftriaxone อย่างเดียวโดยไม่มี metronidazole","C":"Serology for E. histolytica (antibody) บวกกว่า 90% ในฝีตับจากอะมีบา ช่วยยืนยันวินิจฉัย ควรส่งเสมอ (แต่บวกนานในพื้นที่ระบาด แปลผลร่วมกับ clinical); ตรวจอุจจาระมักไม่พบเชื้อแล้ว — จะเป็นคำตอบ “ไม่เหมาะ” ถ้าโจทย์ให้รอผล serology ก่อนเริ่มยา","D":"Luminal agent (paromomycin หรือ diloxanide furoate) ต้องให้ต่อหลัง metronidazole ครบ 7–10 วันเพื่อกำจัด cyst ในลำไส้ ป้องกันการกลับเป็นซ้ำและแพร่เชื้อ — เป็นส่วนหนึ่งของการรักษามาตรฐาน; จะเป็นคำตอบ “ไม่เหมาะ” ถ้าให้ luminal agent เดี่ยว ๆ แทน metronidazole ในฝีตับ","E":"Supportive care ด้วยยาแก้ปวดลดไข้ IV fluid เป็นส่วนหนึ่งของการดูแลทุกราย ไม่ผิด — จะเป็นคำตอบ “ไม่เหมาะ” ถ้าให้ supportive care อย่างเดียวโดยไม่ให้ยาฆ่าเชื้อ"},"trap":"ติดภาพจำว่า “abscess ต้อง drain” — จริงสำหรับ pyogenic liver abscess ขนาดใหญ่กว่าราว 5 cm แต่ <b>amoebic liver abscess รักษาด้วยยาเป็นหลัก</b> drain เฉพาะมีข้อบ่งชี้; ข้อนี้ถาม NOT ต้องอ่านโจทย์ให้ดี","summary":["Amoebic liver abscess: ชายวัยทำงาน, ประวัติท้องเสียหรือ dysentery (มักไม่มีแล้วตอนมา), ไข้ ปวด RUQ, ก้อนเดี่ยวใน right lobe","ตรวจ: US หรือ CT ก้อนเดี่ยวผนัง enhance, serology E. histolytica บวก; หนองถ้าเจาะ = anchovy paste ไม่มีกลิ่น","รักษา: metronidazole 750 mg วันละ 3 ครั้ง 7–10 วัน ตามด้วย luminal agent (paromomycin 7 วัน หรือ diloxanide furoate 10 วัน)","Drain เมื่อ: ไม่ตอบสนอง 5–7 วัน, ก้อนใหญ่มากหรือใกล้แตก, left lobe, วินิจฉัยไม่ชัด, secondary bacterial infection","ภาวะแทรกซ้อน: แตกเข้าช่องท้อง เยื่อหุ้มปอดหรือปอด (empyema, hepatobronchial fistula), แตกเข้า pericardium (left lobe) อันตรายที่สุด","Pyogenic liver abscess: ผู้สูงอายุ DM, biliary disease, K. pneumoniae; ก้อนหลายก้อนได้; antibiotics 4–6 สัปดาห์ + percutaneous drainage เมื่อ &gt;3–5 cm","Empirical ระหว่างแยก: ceftriaxone + metronidazole ครอบคลุมทั้งสองกลุ่ม","ดูข้อ 722, 726, 729 (โรคตับอื่นในชุดนี้)"],"notes":"ไฟล์เฉลย (หน้า 5 บท Liver + Jaundice แถว 4): <b>B</b> (ช่องคำอธิบายในไฟล์เฉลยว่าง) · <b>โน้ตผู้จดในไฟล์โจทย์:</b> ไม่มี; ต้นฉบับเขียน “ก้อนที่ liver capsule enhancted” (สะกดตามต้นฉบับ) → เราเขียนเป็น lesion with an enhancing wall; ช้อย C ในต้นฉบับมีแค่ “C.” ว่าง; เติมใน stem ว่าอายุ 35 ปี ไข้ ปวด RUQ ก้อน 5 cm ที่ right lobe และ hemodynamically stable; ช้อย A “ให้ยา Ceftri + Metro”, B “ให้ drain” → แปลเป็นอังกฤษ และแต่งช้อย C–E","mnemonic":"<b>อะมีบา = ยาก่อน (metro แล้วตาม luminal); หนองแบคทีเรีย = ยา + drain</b>","guide":"Sabiston Textbook of Surgery 21st ed.; Mandell, Douglas, and Bennett's Principles and Practice of Infectious Diseases 9th ed.","variants":["ชายอายุ 30 ปี ไข้ ปวด RUQ US พบก้อนเดี่ยว 6 cm ใน right lobe serology E. histolytica บวก → metronidazole แล้วตามด้วย paromomycin","ผู้ป่วยฝีตับจากอะมีบาขนาด 8 cm ใน left lobe ติดกับ pericardium → percutaneous aspiration ร่วมกับ metronidazole","หญิงอายุ 65 ปี DM ไข้สูง CT พบก้อนหลาย loculation 7 cm เพาะเชื้อได้ K. pneumoniae → IV antibiotics และ percutaneous drainage"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":11,"page2":5,"orig":"Liver + Jaundice 5","stem":"A patient with chronic hepatitis C has portal hypertension. Which pair of findings is expected?","gray":"คนไข้เป็น Hepatitis C และ Portal Hytension ถามว่าคนไข้จะมีอาการอะไร — A. Palmar erythema + Thrombocytosis B. Ascites + Thrombocytopenia","opts":["Palmar erythema and thrombocytosis","Ascites and thrombocytopenia","Splenomegaly and leukocytosis","Caput medusae and polycythemia","Esophageal varices and thrombocytosis"],"ans":1,"key":"B Ascites + Thrombocytopenia (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ถาม finding ที่เป็นผลโดยตรงจาก <b>portal hypertension</b> — ช้อยเป็นคู่ ต้องถูกทั้งสองตัว; ตัวลวงจับคู่ finding ที่ถูกหนึ่งตัวกับค่าเลือดที่กลับทิศ","why":"Portal hypertension (HVPG &gt;5 mmHg, clinically significant ≥10 mmHg) ทำให้ (1) <b>splenomegaly → hypersplenism</b> เก็บกักและทำลายเกล็ดเลือด → <b>thrombocytopenia</b> (ร่วมกับ thrombopoietin จากตับลดลง) และอาจมี leukopenia, anemia; (2) <b>ascites</b> จาก sinusoidal hypertension + splanchnic vasodilation กระตุ้น RAAS กักเกลือและน้ำ + albumin ต่ำ; จึงเป็นคู่ที่ถูกทั้งสองตัว","wrong":{"A":"Palmar erythema พบใน cirrhosis จริงแต่เกิดจาก <b>hyperestrogenism จากตับทำงานลดลง</b> ไม่ใช่จาก portal hypertension โดยตรง และ thrombocytosis กลับทิศ (PH ทำให้เกล็ดเลือดต่ำ); จะถูกถ้าถาม stigmata ของ chronic liver disease จาก estrogen สูง (palmar erythema, spider nevi, gynecomastia)","C":"Splenomegaly ถูก แต่ hypersplenism ทำให้ <b>leukopenia</b> ไม่ใช่ leukocytosis; จะถูกถ้าคู่เป็น splenomegaly กับ pancytopenia","D":"Caput medusae ถูก (portosystemic collateral ผ่าน paraumbilical vein) แต่ polycythemia ไม่ใช่ผลของ PH (มักมี anemia จากเลือดออกและ hypersplenism); จะถูกถ้าคู่เป็น caput medusae กับ anemia","E":"Esophageal varices ถูก (collateral ที่ left gastric vein) แต่ thrombocytosis กลับทิศ; จะถูกถ้าคู่เป็น varices กับ thrombocytopenia — และ Baveno VII ใช้ plt ต่ำร่วมกับ liver stiffness คัดผู้ที่ต้องส่องหา varices"},"trap":"เลือก palmar erythema เพราะเป็น sign ของ cirrhosis ที่คุ้นเคย — แต่ไม่ใช่ผลของ <b>portal hypertension</b> และเกล็ดเลือดในตัวเลือกนี้ <b>สูง</b> ซึ่งกลับทิศ; ช้อยเป็นคู่ต้องถูกทั้งสองตัว","summary":["Portal hypertension: HVPG ปกติ 1–5 mmHg; &gt;5 = PH; ≥10 = clinically significant (CSPH) เสี่ยง varices และ decompensation; ≥12 = เสี่ยง variceal bleeding","สาเหตุแบ่งตามตำแหน่ง: prehepatic (portal vein thrombosis), intrahepatic (cirrhosis จาก HBV, HCV, alcohol, MASLD; schistosomiasis), posthepatic (Budd–Chiari, constrictive pericarditis)","อาการจาก PH: splenomegaly + hypersplenism (thrombocytopenia, leukopenia), ascites, esophageal และ gastric varices, caput medusae, rectal varices","Stigmata จาก liver dysfunction (ไม่ใช่ PH): palmar erythema, spider nevi, gynecomastia, testicular atrophy, jaundice, coagulopathy, hypoalbuminemia","Baveno VII: liver stiffness &lt;15 kPa + plt ≥150,000 ตัด CSPH ได้; ≥25 kPa บ่งชี้ CSPH; ผู้ที่ไม่เข้าเกณฑ์ตัดออกต้องคัดกรอง varices","รักษา CSPH: non-selective beta-blocker (carvedilol) ป้องกัน decompensation; varices ใหญ่ → NSBB หรือ EVL; ascites → จำกัดเกลือ + spironolactone ± furosemide","ดูข้อ 767 (portal hypertension กับ varices) และข้อ 722, 725, 729"],"notes":"ไฟล์เฉลย (หน้า 5 บท Liver + Jaundice แถว 5): <b>B</b> (ช่องคำอธิบายในไฟล์เฉลยว่าง) · <b>โน้ตผู้จดในไฟล์โจทย์:</b> ไม่มี; ต้นฉบับสะกด “Portal Hytension” (= portal hypertension); ต้นฉบับมีช้อย A, B ที่ใช้เครื่องหมาย “+” → เราเขียนเป็น “and” และแต่งช้อย C–E แบบคู่","mnemonic":"<b>PH = ม้ามโต เกล็ดเลือดต่ำ ท้องมาน เส้นเลือดขอด; estrogen สูง = ฝ่ามือแดง spider</b>","guide":"Baveno VII 2022; AASLD portal hypertension and varices guidance 2024","variants":["ผู้ป่วย HBV cirrhosis เกล็ดเลือด 80,000 ม้ามโต liver stiffness 30 kPa → CSPH เริ่ม carvedilol","ผู้ป่วย portal vein thrombosis แต่ตับปกติ มีม้ามโต varices เกล็ดเลือดต่ำ แต่ไม่มี palmar erythema หรือ spider nevi → prehepatic portal hypertension","ผู้ป่วยตับแข็งมีท้องมาน SAAG 1.8 g/dL → portal hypertension related ascites"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":11,"page2":5,"orig":"Jaundice + liver 1","stem":"A patient has painless progressive jaundice and a palpable gallbladder. Investigation confirms ampullary adenocarcinoma with no distant metastasis, and he is fit for surgery. What is the most appropriate operation?","gray":"คนไข้มีอาการ painless progressive jaundice คลำได้ gallbladder วินิฉัยเป็น Ampullary CA — A. Duodenectomy B. Pancreatoduodenectomy","opts":["Duodenectomy","Pancreatoduodenectomy","Ampullectomy","ERCP with biliary stent alone","Gastrojejunostomy alone"],"ans":1,"key":"B Pancreatoduodenectomy (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: เติมว่าไม่มี distant metastasis และผู้ป่วย fit for surgery","interp":"วินิจฉัยแล้วว่าเป็น <b>ampullary adenocarcinoma</b> ที่ไม่มี metastasis และผ่าตัดได้ → ถามการผ่าตัดมาตรฐานเพื่อหวังหายขาด (ไม่ใช่ palliative)","why":"Ampulla of Vater อยู่ในผนัง duodenum ส่วนที่ 2 ล้อมรอบด้วย head of pancreas และปลาย CBD และระบายน้ำเหลืองไปยัง peripancreatic และ pancreaticoduodenal nodes → การผ่าตัดที่ได้ R0 และเลาะต่อมน้ำเหลืองครบคือ <b>pancreaticoduodenectomy</b> (Whipple หรือ pylorus-preserving) + regional lymphadenectomy; ampullary cancer พยากรณ์ดีที่สุดในกลุ่ม periampullary เพราะเหลืองเร็วจึงพบเร็ว (5-year survival หลังผ่าตัดราว 40–60%)","wrong":{"A":"Duodenectomy (pancreas-preserving total duodenectomy) ใช้กับ duodenal adenoma หลายก้อนหรือ FAP ที่ไม่ใช่มะเร็งลุกลาม ไม่ได้เลาะ head of pancreas และต่อมน้ำเหลืองระดับที่มะเร็งต้องการ; จะถูกถ้าเป็น FAP ที่มี duodenal polyposis Spigelman IV โดยไม่มีมะเร็ง","C":"Ampullectomy (endoscopic หรือ transduodenal) ใช้กับ ampullary adenoma หรือมะเร็งระยะเริ่มมาก (Tis–T1 บางรายในผู้เสี่ยงผ่าตัดสูง) เพราะไม่ได้เลาะต่อมน้ำเหลือง; adenocarcinoma ที่ลุกลามกว่านี้มีโอกาส nodal metastasis สูง; จะถูกถ้าเป็น ampullary adenoma ไม่มี invasive component","D":"ERCP with biliary stent alone เป็น palliative หรือระบายน้ำดีก่อนผ่าตัดในบางกรณี (cholangitis, ต้องรอ neoadjuvant, bilirubin สูงมาก) ไม่ใช่การรักษาหายขาด; จะถูกถ้าผู้ป่วยมี liver metastasis หรือ unfit for surgery","E":"Gastrojejunostomy alone เป็น palliative bypass สำหรับ gastric outlet obstruction จากก้อน ไม่ได้ตัดก้อนและไม่ได้แก้เหลือง; จะถูกถ้าโจทย์เป็นมะเร็งระยะลุกลามที่อาเจียนจาก duodenal obstruction"},"trap":"คิดว่ามะเร็งอยู่ที่ ampulla (จุดเล็ก ๆ) จึงตัดแค่ ampulla หรือ duodenum — แต่ adenocarcinoma ต้องเลาะต่อมน้ำเหลืองและได้ขอบปลอดมะเร็ง จึงต้อง <b>Whipple</b> เหมือนมะเร็งหัวตับอ่อน","summary":["Periampullary tumor มี 4 แหล่ง: head of pancreas (พบมากสุด พยากรณ์แย่สุด), distal CBD, ampulla of Vater, duodenum","Ampullary cancer พยากรณ์ดีที่สุดในกลุ่มนี้เพราะเหลืองเร็ว; อาจเหลืองขึ้นลงจากก้อนเปื่อย และ occult GI bleeding (อุจจาระสีเงิน)","Courvoisier sign: คลำได้ถุงน้ำดีโตไม่เจ็บในคนเหลือง → นึกถึงมะเร็งที่อุดใต้ cystic duct มากกว่านิ่ว","ตรวจ: CT pancreas protocol, EUS, ERCP หรือ endoscopic biopsy, CA19-9","รักษาหายขาด: pancreaticoduodenectomy (Whipple หรือ PPPD) + regional lymphadenectomy; ampullectomy เฉพาะ adenoma หรือ Tis–T1 บางราย","ไม่ระบายน้ำดีก่อนผ่าตัดเป็น routine ยกเว้น cholangitis, bilirubin สูงมาก หรือต้องรอ neoadjuvant","Palliative: ERCP metal stent, duodenal stent หรือ gastrojejunostomy, chemotherapy ตาม histologic subtype (intestinal หรือ pancreatobiliary)","ดูข้อ 723, 724, 728, 730 (ภาวะเหลืองและท่อน้ำดีอื่นในชุดนี้)"],"notes":"ไฟล์เฉลย (หน้า 5 บท jaundice แถว 1): <b>B</b> (ช่องคำอธิบายในไฟล์เฉลยว่าง) · <b>โน้ตผู้จดในไฟล์โจทย์:</b> ไม่มี; ต้นฉบับสะกด “วินิฉัย” (= วินิจฉัย); บทนี้ในไฟล์โจทย์ชื่อ “Jaundice + liver” ส่วนในไฟล์เฉลยชื่อ “jaundice”; เราเติมใน stem ว่าเป็น adenocarcinoma ไม่มี distant metastasis และ fit for surgery; ต้นฉบับมีช้อย A, B → แต่งช้อย C–E","mnemonic":"","guide":"NCCN Ampullary Adenocarcinoma 2025","variants":["ผู้ป่วยเหลืองขึ้นลง ซีด อุจจาระสีเงิน ส่องกล้องพบก้อนที่ ampulla ผล biopsy เป็น adenocarcinoma CT ไม่พบ metastasis → pancreaticoduodenectomy","ผู้ป่วยส่องกล้องพบ ampullary adenoma 2 cm ไม่มี dysplasia รุนแรงหรือ invasion บน EUS ไม่ลงท่อน้ำดี → endoscopic ampullectomy","ผู้ป่วย periampullary cancer มี liver metastasis หลายก้อน เหลืองและคัน → ERCP with metal stent และ systemic chemotherapy"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":11,"page2":5,"orig":"Jaundice + liver 2","stem":"A patient has right upper quadrant pain, jaundice, hypotension and confusion. He has been resuscitated with intravenous fluids, and intravenous antibiotics have been started. What is the next most appropriate management?","gray":"คนไข้มีอาการปวดท้อง RUQ มีอาการเหลือง Hypotension และมีอาการมึน ๆ ซึม ๆ มาโรงพยายาล ได้ทำ Resuscitation ไปแล้วถามว่าทำไรต่อ — A. Cholecystectomy B. Abx C. ERCP","opts":["Emergency cholecystectomy","Continue antibiotics alone","ERCP with biliary drainage","MRCP before any intervention","HIDA scan"],"ans":2,"key":"C ERCP (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: เติมใน stem ว่าเริ่ม IV antibiotics แล้วพร้อม resuscitation (antibiotic ต้องให้ทันทีเช่นกัน) เพื่อให้ ERCP เป็นขั้นต่อไปเพียงคำตอบเดียว","interp":"ปวด RUQ + เหลือง + ความดันต่ำ + ซึมสับสน = ครบ 5 อาการของการติดเชื้อในท่อน้ำดีที่รุนแรง (organ dysfunction) → ถามขั้นต่อไปหลัง resuscitation และให้ยาฆ่าเชื้อแล้ว = <b>source control</b>","why":"<b>Reynolds pentad</b> (Charcot triad คือไข้ ปวด RUQ เหลือง + shock + altered mental status) = acute cholangitis <b>Tokyo Guidelines 2018 grade III</b> (มี organ dysfunction) → ต้องให้ organ support + antibiotics และ <b>urgent biliary drainage ทันทีที่ทำได้</b> หลังผู้ป่วยพร้อม; วิธีหลักคือ <b>ERCP</b> (sphincterotomy ± เอานิ่วออก หรือใส่ stent/nasobiliary drain) เพราะ mortality ต่ำกว่าผ่าตัดเปิดมาก; ถ้าทำ ERCP ไม่ได้ → PTBD หรือ EUS-guided drainage","wrong":{"A":"Emergency cholecystectomy ไม่ได้ระบายท่อน้ำดีที่อุดตัน (นิ่วอยู่ใน CBD) และผ่าตัดใหญ่ในภาวะ septic shock mortality สูง; ทำ laparoscopic cholecystectomy ภายหลังเมื่อ cholangitis หายแล้ว (ใน admission เดียวกันหรือภายในไม่กี่สัปดาห์) — จะถูกถ้าโจทย์เป็น acute cholecystitis grade I–II ที่ fit for surgery","B":"Continue antibiotics alone พอสำหรับ grade I (mild) ที่ตอบสนองต่อยาภายใน 24 ชม.; grade III มี organ dysfunction ยาอย่างเดียวไม่พอเพราะหนองในท่อน้ำดีที่มีแรงดันสูงไม่ถูกระบาย — จะถูกถ้าเป็น mild cholangitis ที่ไข้ลงและอาการดีขึ้นหลังให้ยา","D":"MRCP ช่วยยืนยันนิ่วใน CBD เมื่อวินิจฉัยไม่ชัด แต่ในผู้ป่วยที่วินิจฉัย cholangitis รุนแรงจาก clinical และ US แล้ว การรอ MRCP ทำให้ drainage ล่าช้า; จะถูกถ้าผู้ป่วย stable มีโอกาสนิ่วใน CBD ระดับปานกลาง (intermediate risk)","E":"HIDA scan ใช้วินิจฉัย acute cholecystitis (ไม่เห็น gallbladder) หรือ bile leak; ในผู้ป่วยเหลือง bilirubin สูงสารเภสัชรังสีขับได้ไม่ดี และไม่ได้ช่วยรักษา; จะถูกถ้าสงสัย acute cholecystitis ที่ US ไม่ชัดเจน"},"trap":"เห็นถุงน้ำดีแล้วคิดว่าต้องผ่า cholecystectomy — แต่ปัญหาของ cholangitis คือ <b>ท่อน้ำดีส่วนรวมอุดตันและมีหนองภายใต้แรงดัน</b> ต้องระบายท่อน้ำดีก่อน; อีกกับดักคือคิดว่าให้ยาฆ่าเชื้อพอในผู้ป่วยที่มี shock","summary":["Charcot triad: ไข้ (หนาวสั่น) + ปวด RUQ + เหลือง; Reynolds pentad = Charcot + hypotension + altered mental status","TG18 วินิจฉัย: systemic inflammation (ไข้หรือ WBC/CRP สูง) + cholestasis (เหลืองหรือ LFT ผิดปกติ) + imaging (ท่อน้ำดีขยายหรือเห็นสาเหตุ)","TG18 grade III: cardiovascular (ต้องใช้ vasopressor), neurologic (ซึม), PaO₂/FiO₂ &lt;300, creatinine &gt;2 mg/dL, INR &gt;1.5, plt &lt;100,000","Grade III → organ support + antibiotics + urgent biliary drainage; grade II → early drainage; grade I → antibiotics แล้ว drain ถ้าไม่ตอบสนองใน 24 ชม.","Biliary drainage: ERCP เป็นหลัก (sphincterotomy, stone extraction, stent หรือ nasobiliary drain); ล้มเหลว → PTBD หรือ EUS-guided; ผ่าตัด CBD exploration เมื่อวิธีอื่นไม่ได้","สาเหตุหลักคือนิ่วใน CBD; อื่น ๆ คือ benign stricture, มะเร็ง, stent อุดตัน, ปรสิต","หลังหาย: laparoscopic cholecystectomy ถ้ามีนิ่วในถุงน้ำดี เพื่อป้องกันการกลับเป็นซ้ำ","ดูข้อ 723, 724, 727, 730, 754 (ถุงน้ำดีและท่อน้ำดีในชุดนี้)"],"notes":"ไฟล์เฉลย (หน้า 5 บท jaundice แถว 2): <b>C</b> (ช่องคำอธิบายในไฟล์เฉลยว่าง) · <b>โน้ตผู้จดในไฟล์โจทย์:</b> ไม่มี; ต้นฉบับสะกด “มาโรงพยายาล” (= โรงพยาบาล); ต้นฉบับบอกแค่ว่า “ได้ทำ Resuscitation ไปแล้ว” → เราเติมว่าเริ่ม IV antibiotics แล้วด้วย; ช้อย A “Cholecystectomy”, B “Abx”, C “ERCP” → เกลาเป็น Emergency cholecystectomy, Continue antibiotics alone, ERCP with biliary drainage และแต่งช้อย D, E","mnemonic":"<b>Charcot 3 + shock + ซึม = Reynolds 5 → ระบายท่อน้ำดีด่วน</b>","guide":"Tokyo Guidelines 2018","variants":["ผู้ป่วยไข้หนาวสั่น เหลือง ปวด RUQ ความดันปกติ แลปไม่มี organ dysfunction ให้ antibiotics แล้วไข้ลงภายใน 24 ชม. → grade I ทำ ERCP แบบ elective หรือตามสาเหตุ","ผู้ป่วย cholangitis grade III เคยผ่าตัด Roux-en-Y gastric bypass ทำ ERCP ไม่ได้ → PTBD","ผู้ป่วยหลังรักษา cholangitis จากนิ่วใน CBD ด้วย ERCP สำเร็จ US พบนิ่วในถุงน้ำดีหลายก้อน → laparoscopic cholecystectomy"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":11,"page2":5,"orig":"Jaundice + liver 3","stem":"A patient with known hepatocellular carcinoma presents with sudden abdominal pain and hypotension. After resuscitation, contrast-enhanced CT shows hemoperitoneum with active contrast extravasation from the tumor. What is the most appropriate next step?","gray":"คนไข้เป็น HCC ที่ตรวจแล้วเจอ Extravasation ของตัวก้อน ถามว่าทำไรต่อ — A. TACE B. Surgery","opts":["TACE","Emergency hepatectomy","Radiofrequency ablation","Systemic immunotherapy","Observation alone"],"ans":0,"key":"A TACE (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ผู้ป่วย HCC ที่มี <b>active contrast extravasation จากก้อน + เลือดในช่องท้อง + ความดันต่ำ</b> → ภาวะก้อนมะเร็งตับมีเลือดออก ต้องหยุดเลือดด้วยวิธีที่ปลอดภัยและได้ผลเร็วที่สุด","why":"Ruptured HCC (3–15% ของ HCC, mortality ระยะเฉียบพลัน 25–75%) → resuscitation + แก้ coagulopathy แล้ว <b>transarterial embolization หรือ TACE</b> หยุดเลือดได้ราว 90% เป็นหัตถการ minimally invasive ไม่ต้องผ่าตัดใหญ่ในตับที่มักเป็น cirrhosis และผู้ป่วยกำลัง shock; เมื่อพ้นภาวะวิกฤตแล้วประเมิน <b>staged hepatectomy</b> ภายหลังถ้าก้อนตัดได้และ liver function ดี (ผลดีกว่าผ่าตัดฉุกเฉิน)","wrong":{"B":"Emergency hepatectomy ในผู้ป่วย shock + coagulopathy + cirrhosis มี mortality สูงมาก (สูงกว่า staged hepatectomy หลัง TAE ชัดเจน); ใช้เมื่อไม่มี interventional radiology, TAE ล้มเหลว หรือตับดีและก้อนอยู่ขอบตับตัดง่าย — จะถูกถ้าโจทย์ว่า TAE ทำไม่ได้หรือไม่สำเร็จและผู้ป่วยยังเลือดออกต่อ","C":"Radiofrequency ablation ใช้รักษา HCC ขนาดเล็ก (≤3 cm) ระยะเริ่มต้นแบบ elective; ไม่ใช่วิธีหยุดเลือดเฉียบพลันจากก้อนที่แตก และการเจาะเข็มผ่านก้อนที่เลือดออกอาจเลือดออกมากขึ้น — จะถูกถ้าเป็น HCC ก้อนเดี่ยว 2 cm Child-Pugh A ไม่มีอาการ","D":"Systemic immunotherapy (atezolizumab + bevacizumab, durvalumab + tremelimumab) ใช้กับ advanced HCC (BCLC C) ไม่หยุดเลือดเฉียบพลัน และ bevacizumab เพิ่มความเสี่ยงเลือดออก — จะถูกถ้าเป็น HCC มี portal vein invasion หรือ metastasis ที่ stable","E":"Observation alone ไม่เหมาะเมื่อยังมี active extravasation และ hypotension; อาจพิจารณา conservative เฉพาะผู้ป่วยระยะสุดท้าย Child-Pugh C ที่ไม่มีทางรักษาและเลือกรับ palliative care — จะถูกถ้าผู้ป่วย end-stage และตัดสินใจไม่รับการรักษาเชิงรุก"},"trap":"คิดว่า “เลือดออก = ผ่าตัด” — ในก้อนมะเร็งตับที่แตก การผ่าตัดฉุกเฉินในตับแข็งตายสูง <b>embolization หยุดเลือดก่อน แล้วผ่าตัดทีหลัง</b> (staged)","summary":["Ruptured HCC: ก้อนใหญ่ ตื้นใต้ capsule หรือยื่นออกนอกตับ, cirrhosis, portal hypertension เป็นปัจจัยเสี่ยง","อาการ: ปวดท้องทันที ท้องอืด ความดันต่ำ; CT เห็น hemoperitoneum, ก้อนที่ขอบตับ, active extravasation, enucleation sign","ขั้นตอน: resuscitation, แก้ coagulopathy, blood transfusion → TAE หรือ TACE หยุดเลือด (สำเร็จราว 90%)","Staged hepatectomy หลังพ้นวิกฤตถ้าก้อนตัดได้และ liver reserve พอ ผลดีกว่า emergency hepatectomy","Emergency surgery (hepatectomy, packing, hepatic artery ligation) เมื่อ TAE ไม่มีหรือล้มเหลว","ภาวะแทรกซ้อนระยะยาว: peritoneal seeding จากเซลล์มะเร็งที่หลุดในช่องท้อง","ดูข้อ 722, 725, 726 (โรคตับอื่นในชุดนี้)"],"notes":"ไฟล์เฉลย (หน้า 5 บท jaundice แถว 3): <b>A</b> (ช่องคำอธิบายในไฟล์เฉลยว่าง) · <b>โน้ตผู้จดในไฟล์โจทย์:</b> ไม่มี; ต้นฉบับบอกแค่ “ตรวจแล้วเจอ Extravasation ของตัวก้อน” → เราเติมปวดท้องทันที ความดันต่ำ resuscitation แล้ว และ CT มี hemoperitoneum ร่วมกับ active contrast extravasation (ไม่ใช้คำว่า ruptured); ช้อย B “Surgery” → เขียนเป็น Emergency hepatectomy; แต่งช้อย C–E · ในไฟล์โจทย์บท Jaundice + liver แถว 4 ว่าง (มีแค่ “A.”) ไม่ใช่ข้อ","mnemonic":"<b>มะเร็งตับแตก: อุดก่อน ตัดทีหลัง</b>","guide":"EASL Clinical Practice Guidelines: management of hepatocellular carcinoma 2018; APASL HCC 2017","variants":["ผู้ป่วย HBV cirrhosis มีก้อนตับ 8 cm ยื่นออกนอกตับ ปวดท้องทันทีความดันต่ำ CT พบเลือดในช่องท้อง → resuscitation แล้ว TAE","ผู้ป่วยหลัง TAE หยุดเลือดจากก้อนตับแตกได้ 4 สัปดาห์ ก้อนเดี่ยว Child-Pugh A FLR พอ → staged hepatectomy","โรงพยาบาลไม่มี interventional radiology ผู้ป่วยก้อนตับแตกยังความดันต่ำแม้ให้เลือด → emergency laparotomy เพื่อหยุดเลือด"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":12,"page2":5,"orig":"Jaundice + liver 5","stem":"A patient has intermittent right upper quadrant pain after meals that comes and goes. Physical examination is normal. What is the most likely diagnosis?","gray":"คนไข้มีอาการปวดท้อง RUQ หลังกินข้าว แต่ปวดไม่ตลอด มา ๆ ไป ๆ ตรวจร่างกายปกติ ถามว่าเป็นไร — A. Biliary colic","opts":["Biliary colic","Acute cholecystitis","Choledocholithiasis","Acute cholangitis","Acute pancreatitis"],"ans":0,"key":"A Biliary colic (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ปวด RUQ <b>หลังอาหาร เป็นพัก ๆ แล้วหาย</b> + ตรวจร่างกายปกติ (ไม่มีไข้ ไม่มี Murphy sign ไม่เหลือง) → แยกภาวะนิ่วในถุงน้ำดีที่ยังไม่มีการอักเสบออกจากภาวะแทรกซ้อน","why":"<b>Biliary colic</b> เกิดจากนิ่วอุด cystic duct ชั่วคราวขณะถุงน้ำดีบีบตัว (หลังอาหารมันกระตุ้น CCK) → ปวดลิ้นปี่หรือ RUQ แบบคงที่ 30 นาทีถึง 6 ชม. แล้วหายเมื่อนิ่วหลุดกลับ; ไม่มีไข้ WBC และ LFT ปกติ ตรวจท้องระหว่างไม่ปวดปกติ Murphy sign ลบ; ยืนยันด้วย US และรักษาด้วย <b>elective laparoscopic cholecystectomy</b> เพราะ symptomatic gallstones มีโอกาสปวดซ้ำและเกิดภาวะแทรกซ้อน","wrong":{"B":"Acute cholecystitis ปวดนานกว่า 6 ชม. ต่อเนื่อง มีไข้ WBC สูง <b>Murphy sign บวก</b> และ US เห็นผนังหนา pericholecystic fluid; ตรวจร่างกายไม่ปกติ — จะถูกถ้าโจทย์มีปวด RUQ ต่อเนื่อง 1 วัน ไข้ และกดเจ็บหายใจเข้าสะดุด","C":"Choledocholithiasis มีนิ่วใน CBD ทำให้ <b>เหลือง</b> ปัสสาวะเข้ม LFT แบบ cholestasis (ALP, GGT, bilirubin สูง) และ CBD ขยาย; จะถูกถ้าโจทย์มีปวดคล้ายกันร่วมกับเหลืองและ bilirubin สูง","D":"Acute cholangitis มี Charcot triad คือไข้ ปวด RUQ เหลือง ตรวจร่างกายไม่ปกติชัดเจน; จะถูกถ้าโจทย์มีไข้หนาวสั่นร่วมกับเหลือง","E":"Acute pancreatitis ปวดลิ้นปี่รุนแรงต่อเนื่องร้าวทะลุหลัง คลื่นไส้อาเจียน lipase สูงเกิน 3 เท่า; ไม่ได้หายเป็นพัก ๆ; จะถูกถ้าโจทย์เป็นปวดลิ้นปี่ทะลุหลังต่อเนื่องและ lipase สูง"},"trap":"คำว่า “colic” ทำให้นึกว่าปวดบิดเป็นจังหวะเหมือน renal colic — biliary colic จริง ๆ ปวด <b>คงที่</b> นานหลายสิบนาทีถึงชั่วโมงแล้วหายไป; ถ้าปวดนานเกิน 6 ชม. หรือมีไข้ต้องคิดถึง cholecystitis","summary":["Spectrum ของนิ่วถุงน้ำดี: asymptomatic → biliary colic → acute cholecystitis; นิ่วหลุดลง CBD → choledocholithiasis, cholangitis, gallstone pancreatitis","Biliary colic: ปวดคงที่ 30 นาทีถึง 6 ชม. หลังอาหารมัน มักกลางคืน ไม่มีไข้ ตรวจร่างกายและแลปปกติ","Acute cholecystitis: ปวดนานกว่า 6 ชม., ไข้, Murphy sign, WBC สูง; US ผนังหนากว่า 4 mm, pericholecystic fluid, sonographic Murphy","US เป็นการตรวจแรก (sensitivity สำหรับนิ่วในถุงน้ำดีกว่า 95%)","Symptomatic gallstones → elective laparoscopic cholecystectomy; asymptomatic ส่วนใหญ่ไม่ต้องผ่าตัด (ยกเว้น porcelain GB, polyp ≥10 mm, นิ่ว &gt;3 cm ในบางแนวทาง)","ระหว่างรอผ่าตัด: NSAIDs บรรเทาปวด, เลี่ยงอาหารมัน","ดูข้อ 728, 754 (ภาวะแทรกซ้อนของถุงน้ำดีและท่อน้ำดี) และข้อ 723, 727"],"notes":"ไฟล์เฉลย (หน้า 5 บท jaundice แถว 5): <b>A</b> (ช่องคำอธิบายในไฟล์เฉลยว่าง) · ไฟล์โจทย์แถว 4 ของบท Jaundice + liver ว่าง (มีแค่ “A.”) และไฟล์เฉลยบท jaundice ก็ไม่มีแถว 4 (มีแถว 1, 2, 3, 5) — ข้อนี้คือแถว 5 ในทั้งสองไฟล์ · <b>โน้ตผู้จดในไฟล์โจทย์:</b> ไม่มี; ต้นฉบับมีช้อยเดียว “A. Biliary colic” (น่าจะเป็นช้อยที่เป็นคำตอบ) → แต่งช้อย B–E","mnemonic":"<b>Colic &lt;6 ชม. ตรวจปกติ; cholecystitis &gt;6 ชม. ไข้ Murphy บวก</b>","guide":"EASL Clinical Practice Guidelines on the prevention, diagnosis and treatment of gallstones 2016","variants":["หญิงอายุ 40 ปี ปวด RUQ หลังกินอาหารมัน 2 ชม.แล้วหาย เป็นซ้ำหลายครั้ง US พบนิ่วในถุงน้ำดีหลายก้อน ผนังไม่หนา → elective laparoscopic cholecystectomy","ผู้ป่วยปวด RUQ ต่อเนื่อง 18 ชม. ไข้ 38.5°C Murphy sign บวก → acute cholecystitis","ผู้ป่วยปวด RUQ แล้วเหลือง bilirubin 5 mg/dL ALP สูง US พบ CBD 10 mm → choledocholithiasis ทำ ERCP"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":12,"page2":5,"orig":"Acute abdomen 1","stem":"Which of the following is NOT a differential diagnosis of acute appendicitis?","gray":"ข้อใดไม่ใช่ ddx ของ acute appendicitis — A. Meckel’s Diverticulitis B. Acute renal failure","opts":["Meckel's diverticulitis","Acute renal failure","Right ureteric stone","Mesenteric adenitis","Right ovarian torsion"],"ans":1,"key":"B Acute renal failure (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ถามแบบ NOT — ต้องหาภาวะที่ <b>ไม่ทำให้ปวดท้องน้อยขวาเฉียบพลัน</b> เลียนแบบไส้ติ่งอักเสบ","why":"<b>Acute renal failure (AKI)</b> เป็นภาวะไตทำงานลดลงที่แสดงด้วย creatinine สูงและปัสสาวะออกน้อย ไม่ได้ทำให้ปวดท้องน้อยขวาเฉพาะที่ จึงไม่อยู่ใน differential diagnosis ของ RLQ pain; ส่วนช้อยอื่นล้วนทำให้ปวด RLQ เฉียบพลันได้ทั้งหมด (GI, GU, gynecologic)","wrong":{"A":"Meckel's diverticulitis อยู่ที่ ileum ห่างจาก ileocecal valve ราว 60 cm (2 ฟุต) อักเสบแล้วปวด RLQ หรือรอบสะดือเหมือนไส้ติ่งอักเสบทุกประการ — ถ้าผ่าตัดแล้วไส้ติ่งปกติต้องสำรวจ ileum หา Meckel's เสมอ; จะเป็นคำตอบถ้าโจทย์ถามสาเหตุที่ต้องหาเมื่อผ่าตัดพบไส้ติ่งปกติ","C":"Right ureteric stone ปวดบิดร้าวจากเอวลงขาหนีบ ปัสสาวะมีเลือด และถ้านิ่วอยู่ distal ureter ปวด RLQ ได้ — เป็น DDx สำคัญ; ในทางกลับกัน ไส้ติ่งอักเสบที่อยู่ติด ureter ก็ทำให้มีเม็ดเลือดแดงหรือขาวในปัสสาวะได้; จะเป็นคำตอบถ้าโจทย์ถามสาเหตุ RLQ pain ที่มี hematuria","D":"Mesenteric adenitis ต่อมน้ำเหลืองใน mesentery ของลำไส้เล็กส่วนปลายอักเสบหลัง URI หรือ Yersinia ในเด็ก ปวด RLQ เหมือนไส้ติ่งอักเสบ — เป็น DDx ที่พบบ่อยในเด็ก; จะเป็นคำตอบถ้าโจทย์เป็นเด็กเพิ่งเป็นหวัด ปวด RLQ และ US เห็นต่อมน้ำเหลืองโตหลายต่อม","E":"Right ovarian torsion ปวด RLQ ทันทีรุนแรงร่วมคลื่นไส้อาเจียนในหญิงที่มี ovarian mass — DDx ทาง gynecology ที่ต้องรีบผ่าตัด; จะเป็นคำตอบถ้าโจทย์เป็นหญิงสาวปวดทันทีหลังออกกำลังกายและ Doppler ไม่มี flow"},"trap":"ช้อยลวงใช้ชื่อโรคที่ฟังดูน่ากลัวและเกี่ยวกับไต (ARF) ทำให้ลังเลกับ ureteric stone — ให้แยกว่าโรคใด <b>ทำให้ปวดเฉพาะที่ใน RLQ</b> ได้จริง ไตวายไม่ใช่อาการปวด","summary":["DDx ของ RLQ pain แบ่งตามระบบ: GI (Meckel's diverticulitis, mesenteric adenitis, Crohn's ileitis, cecal diverticulitis, gastroenteritis, typhlitis), GU (ureteric stone, pyelonephritis, UTI), gyn (ectopic pregnancy, PID, ovarian torsion, ruptured ovarian cyst, mittelschmerz, endometriosis)","หญิงวัยเจริญพันธุ์ทุกรายต้องตรวจ urine pregnancy test","Alvarado score และ AIR score ช่วยจัดกลุ่มเสี่ยง; เด็กและหญิงตั้งครรภ์ใช้ US ก่อน ผู้ใหญ่ใช้ CT เมื่อไม่แน่ใจ","Meckel's diverticulum: rule of 2 (2% ของประชากร, 2 ฟุตจาก ileocecal valve, ยาว 2 นิ้ว, มี ectopic tissue 2 ชนิดคือ gastric และ pancreatic)","ผ่าตัดพบไส้ติ่งปกติ → สำรวจ ileum หา Meckel's, mesentery, อวัยวะสืบพันธุ์ในหญิง, cecum","รักษาไส้ติ่งอักเสบ: appendectomy (laparoscopic เป็นมาตรฐาน); uncomplicated บางรายรักษาด้วย antibiotics ได้","ดูข้อ 696, 732 (ไส้ติ่งอักเสบและภาวะแทรกซ้อน)"],"notes":"ไฟล์เฉลย (หน้า 5 บท acute abdomen แถว 1): <b>B</b> (ช่องคำอธิบายในไฟล์เฉลยว่าง) · <b>โน้ตผู้จดในไฟล์โจทย์:</b> ไม่มี; ต้นฉบับมีช้อย A “Meckel’s Diverticulitis”, B “Acute renal failure” → แต่งช้อย C–E (ภาวะที่เป็น DDx จริงทั้งหมด)","mnemonic":"<b>Meckel rule of 2: 2% · 2 ฟุต · 2 นิ้ว · 2 ชนิดเนื้อเยื่อ</b>","guide":"WSES Jerusalem guidelines on diagnosis and treatment of acute appendicitis 2020","variants":["เด็กอายุ 8 ปี เพิ่งเป็นหวัด ปวด RLQ ไข้ต่ำ US ไส้ติ่งปกติ เห็นต่อมน้ำเหลืองใน mesentery โตหลายต่อม → mesenteric adenitis","ผ่าตัดผู้ป่วยสงสัยไส้ติ่งอักเสบแต่พบไส้ติ่งปกติ → สำรวจ ileum ราว 60 cm จาก ileocecal valve หา Meckel's diverticulum","หญิงอายุ 25 ปี ปวด RLQ ประจำเดือนขาด 7 สัปดาห์ ความดันต่ำ → ruptured ectopic pregnancy ตรวจ urine pregnancy test ก่อนเสมอ"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":12,"page2":5,"orig":"Acute abdomen 2","stem":"A patient has had symptoms resembling appendicitis for several days. A 4-cm mass is palpable in the right lower quadrant, and CT shows a 4-cm rim-enhancing fluid collection next to the cecum. He is stable without generalized peritonitis. What is the most appropriate management?","gray":"คนไข้มีอาการคล้าย appendicitis แต่มีอาการมานานหลายวัน คลำได้ก้อนที่ RLQ ขนาด 4 cm ถามว่าทำไรต่อ — A. ABx + drainage B. ABx C. (ว่าง)","opts":["IV antibiotics plus percutaneous drainage","IV antibiotics alone","Observation without antibiotics","Urgent colonoscopy to exclude cancer","Emergency right hemicolectomy"],"ans":0,"key":"A ABx + drainage (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: เติม CT finding ว่ามี rim-enhancing fluid collection 4 cm (abscess) — ถ้าเป็น phlegmon ไม่มี collection ตอบ antibiotics alone (ช้อย B)","interp":"อาการคล้ายไส้ติ่งอักเสบมาหลายวัน (มาช้า) + คลำได้ก้อน RLQ + CT เห็น <b>fluid collection ที่ขอบ enhance ขนาด 4 cm</b> + stable ไม่มี generalized peritonitis → ภาวะแทรกซ้อนเฉพาะที่ของไส้ติ่งแตก ถามการรักษาเริ่มต้น","why":"ไส้ติ่งแตกแล้วร่างกายห่อหุ้มไว้เป็น <b>periappendiceal abscess</b> (2–10% ของผู้ป่วย) ผู้ป่วย stable → การรักษาแบบ nonoperative คือ <b>IV antibiotics + percutaneous drainage</b> เมื่อ abscess ขนาดใหญ่กว่าราว 3 cm และเจาะได้ (ก้อนเล็กกว่านี้หรือ phlegmon ให้ยาอย่างเดียว); การผ่าตัดทันทีในก้อนอักเสบติดกันแน่นมีโอกาสต้องตัดลำไส้มากขึ้น — แม้ WSES 2020 ระบุว่า laparoscopic appendectomy ในมือผู้ชำนาญเป็นทางเลือกได้","wrong":{"B":"IV antibiotics alone เหมาะกับ <b>appendiceal phlegmon</b> (ก้อนอักเสบไม่มี collection) หรือ abscess ขนาดเล็กไม่ถึงราว 3 cm; abscess 4 cm ยาอย่างเดียวมีโอกาสล้มเหลวสูงกว่าเพราะยาเข้าหนองได้ไม่ดี — จะถูกถ้า CT เห็นแค่ phlegmon ไม่มี fluid collection","C":"Observation without antibiotics ไม่เหมาะเพราะเป็นการติดเชื้อในช่องท้องที่ต้องให้ยาเสมอ; ใช้ได้เฉพาะไม่ใช่การติดเชื้อ — จะถูกถ้าโจทย์เป็น mesenteric adenitis ในเด็กที่ไม่มีหนองหรือภาวะแทรกซ้อน","D":"Urgent colonoscopy ห้ามทำในระยะอักเสบเฉียบพลันเพราะเสี่ยงทะลุ; ควรทำ colonoscopy หรือ CT ซ้ำภายหลัง (หลายสัปดาห์) ในผู้ป่วยอายุมากกว่า 40 ปี เพราะ abscess รอบไส้ติ่งสัมพันธ์กับ neoplasm สูงขึ้น — จะถูกถ้าโจทย์ถามการตรวจติดตามหลังหายในผู้ป่วยอายุ 55 ปี","E":"Emergency right hemicolectomy เป็นการผ่าตัดเกินจำเป็นในผู้ป่วย stable และ morbidity สูง; ใช้เมื่อมี generalized peritonitis, sepsis ที่ไม่ดีขึ้น, cecum เน่า หรือสงสัยมะเร็งชัดเจน — จะถูกถ้าผ่าตัดพบฐานไส้ติ่งและ cecum เน่าจนเย็บไม่ได้"},"trap":"รีบผ่าตัดตัดไส้ติ่งทันทีเหมือนไส้ติ่งอักเสบทั่วไป — ในผู้ป่วยมาช้าที่มีก้อนหุ้ม (abscess หรือ phlegmon) และ stable การรักษา <b>แบบไม่ผ่าตัดก่อน</b> ปลอดภัยกว่า; ต้องแยกให้ได้ว่ามีหนองให้เจาะ (abscess) หรือเป็นแค่ phlegmon","summary":["Complicated appendicitis: perforation, phlegmon, abscess, generalized peritonitis","มาช้าหลายวัน + ก้อน RLQ → CT แยก phlegmon กับ abscess","Abscess ใหญ่กว่าราว 3 cm และ stable → IV antibiotics + percutaneous drainage (US หรือ CT guided); phlegmon หรือ abscess เล็ก → antibiotics อย่างเดียว","Generalized peritonitis หรือ sepsis ไม่ดีขึ้น → ผ่าตัดทันที (laparoscopic appendectomy, washout)","WSES 2020: laparoscopic appendectomy ใน abscess ทำได้ในมือผู้ชำนาญ; interval appendectomy ไม่ทำ routine ในผู้ใหญ่อายุน้อย (ทำเมื่อปวดซ้ำ)","อายุมากกว่า 40 ปีหลังรักษา abscess แบบ nonoperative → colonoscopy และ CT ติดตามเพราะเสี่ยง appendiceal หรือ colonic neoplasm","ดูข้อ 696, 731 (ไส้ติ่งอักเสบและ RLQ pain)"],"notes":"ไฟล์เฉลย (หน้า 5 บท acute abdomen แถว 2): <b>A</b> (ช่องคำอธิบายในไฟล์เฉลยว่าง) · <b>โน้ตผู้จดในไฟล์โจทย์:</b> ไม่มี; ช้อย C ในต้นฉบับมีแค่ “C.” ว่าง; ต้นฉบับไม่ได้บอกผล CT → เราเติมว่า CT พบ rim-enhancing fluid collection 4 cm ติด cecum และผู้ป่วย stable ไม่มี generalized peritonitis; ช้อย A “ABx + drainage”, B “ABx” → เขียนเต็มเป็น IV antibiotics plus percutaneous drainage และ IV antibiotics alone; แต่งช้อย C–E","mnemonic":"<b>หนอง &gt;3 cm เจาะ + ยา; phlegmon ยาอย่างเดียว</b>","guide":"WSES Jerusalem guidelines on diagnosis and treatment of acute appendicitis 2020","variants":["ผู้ป่วยปวด RLQ มา 6 วัน คลำได้ก้อน CT พบ inflammatory mass ไม่มี fluid collection stable → IV antibiotics alone","ผู้ป่วยอายุ 58 ปี หลังรักษา periappendiceal abscess ด้วยการเจาะระบายและยาจนหาย → colonoscopy และ CT ติดตามเพื่อตัด neoplasm","ผู้ป่วยปวดท้องมา 4 วัน ไข้สูง ท้องแข็งทั่วไป ความดันต่ำ CT พบไส้ติ่งแตก free fluid ทั่วช่องท้อง → resuscitation, antibiotics และผ่าตัดทันที"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":13,"page2":5,"orig":"Acute abdomen 3","img":"q78c_53","imgNote":"ภาพรังสีช่องท้องท่านอนหงาย (supine) มีลำไส้ขยายตัวมาก — ลายน้ำ LearningRadiology.com ที่มุมขวาล่าง","stem":"An elderly man presents with abdominal distension, colicky pain and obstipation. His plain abdominal radiograph is shown. What is the most likely diagnosis?","gray":"[รูป plain film ช่องท้อง] — A. caecum volvulus B. Sigmoid volvulus","opts":["Cecal volvulus","Sigmoid volvulus","Acute colonic pseudo-obstruction","Small bowel obstruction","Toxic megacolon"],"ans":1,"key":"B Sigmoid volvulus (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"อ่าน plain film: ห่วงลำไส้ขยายขนาดใหญ่มากรูปตัว U กลับหัว กินพื้นที่ตั้งแต่อุ้งเชิงกรานขึ้นไปถึงช่องท้องส่วนบน ผนังสองข้างของห่วงชิดกันตรงกลาง และลำไส้ใหญ่ด้านซ้ายมีแก๊สและอุจจาระ → ภาวะลำไส้ใหญ่ส่วนที่มี mesentery ยาวบิดตัว","why":"<b>Sigmoid volvulus</b> พบในผู้สูงอายุ ติดเตียง ท้องผูกเรื้อรัง โรคทางระบบประสาท หรือ psychiatric; plain film เห็นห่วง sigmoid ขยายมากรูปตัว U กลับหัว (<b>coffee bean หรือ bent inner tube sign</b>) ที่เกิดจาก closed loop ผนังด้านในสองข้างชิดกันเป็นเส้นกลาง ยอดชี้ขึ้นไปทางขวาบนหรือใต้กระบังลมซ้าย และยอดอยู่สูงกว่า transverse colon (<b>northern exposure sign</b>); CT เห็น whirl sign; ไม่มี peritonitis → endoscopic detorsion + rectal tube แล้วทำ elective sigmoidectomy ใน admission เดียวกัน","wrong":{"A":"Cecal volvulus พบในคนอายุน้อยกว่า cecum ขยายแล้วย้ายตำแหน่ง <b>ยอดชี้ไปทางซ้ายบน (LUQ)</b> มี air-fluid level เดียว ลำไส้ใหญ่ส่วนปลายแฟบ และลำไส้เล็กขยาย; รักษาด้วยการผ่าตัด (right hemicolectomy) เพราะ endoscopic detorsion ไม่ได้ผล — จะถูกถ้าภาพเห็นลำไส้รูปไตหรือ coffee bean ที่ LUQ ร่วมกับลำไส้เล็กขยาย","C":"Acute colonic pseudo-obstruction ลำไส้ใหญ่ขยายทั่วไป (cecum, ascending, transverse) <b>ไม่มีห่วงบิด</b> และมักมีแก๊สถึง rectum ไม่มี transition point; พบในผู้ป่วยหลังผ่าตัดหรือ ICU — จะถูกถ้าภาพเป็นแบบในข้อ 734","D":"Small bowel obstruction เห็นลำไส้เล็กขยาย (&gt;3 cm) อยู่ตรงกลาง มี valvulae conniventes พาดเต็มความกว้าง step-ladder และลำไส้ใหญ่แฟบ ไม่ใช่ห่วงลำไส้ใหญ่ขนาดยักษ์; จะถูกถ้าภาพเห็นลำไส้เล็กเรียงเป็นขั้นบันไดในผู้ป่วยเคยผ่าตัดช่องท้อง","E":"Toxic megacolon เกิดใน IBD หรือ C. difficile colitis ผู้ป่วยมีไข้ ชีพจรเร็ว systemic toxicity transverse colon ขยายกว่า 6 cm ผนังบวม haustra หาย (thumbprinting) ไม่มีห่วงบิด; จะถูกถ้าโจทย์เป็นผู้ป่วย ulcerative colitis ถ่ายเป็นเลือด ไข้สูง และ transverse colon ขยาย"},"trap":"สับสน cecal กับ sigmoid volvulus — ให้ดู <b>ทิศของยอดห่วง</b>: sigmoid ชี้ขึ้นไปทางขวาบนหรือใต้กระบังลมซ้ายโดยฐานอยู่ในอุ้งเชิงกรานซ้าย, cecal ฐานอยู่ RLQ แล้วยอดชี้ไป LUQ; และ cecal ต้องผ่าตัด ไม่ใช่ส่องกล้องคลายบิด","summary":["Sigmoid volvulus: ผู้สูงอายุ ติดเตียง ท้องผูกเรื้อรัง โรคระบบประสาท Chagas disease; ท้องอืดมาก ปวดบิด ไม่ถ่ายไม่ผายลม","Plain film: ห่วง sigmoid ขยายรูป U กลับหัว (coffee bean, bent inner tube), northern exposure sign, ไม่มีแก๊สใน rectum; contrast enema เห็น bird's beak; CT เห็น whirl sign","ไม่มี peritonitis หรือ ischemia → endoscopic detorsion (flexible sigmoidoscopy) + rectal tube สำเร็จราว 70–90%","หลัง detorsion เป็นซ้ำได้ราว 60% → elective sigmoidectomy ใน admission เดียวกันถ้าผู้ป่วยผ่าตัดได้","Gangrene, perforation, peritonitis หรือส่องกล้องคลายบิดไม่สำเร็จ → ผ่าตัดฉุกเฉิน sigmoidectomy (Hartmann procedure ถ้าสภาพไม่ดี)","Cecal volvulus: อายุน้อยกว่า, ยอดชี้ LUQ, ลำไส้เล็กขยาย → right hemicolectomy (ไม่แนะนำ endoscopic detorsion)","ดูข้อ 734 (ลำไส้ใหญ่ขยายแบบ functional) และข้อ 719, 720"],"notes":"ไฟล์เฉลย (หน้า 5 บท acute abdomen แถว 3): <b>B</b> (ช่องคำอธิบายในไฟล์เฉลยว่าง) · <b>โน้ตผู้จดในไฟล์โจทย์:</b> ไม่มีข้อความโจทย์เลย มีแค่รูป plain film ช่องท้อง (มีลายน้ำ “LearningRadiology.com (C) All Rights Reserved” ที่มุมขวาล่าง) และช้อย 2 ช้อย “A. caecum volvulus B. Sigmoid volvulus” → เราแต่งเป็นเคสสั้น (ชายสูงอายุ ท้องอืด ปวดบิด ไม่ถ่ายไม่ผายลม) และแต่งช้อย C–E; ช้อย A สะกดแบบอังกฤษ caecum → เขียนเป็น Cecal volvulus","mnemonic":"<b>Sigmoid = ผู้สูงอายุ ส่องคลายได้; Cecal = คนอายุน้อยกว่า ต้องผ่า</b>","guide":"ASCRS clinical practice guidelines for colonic volvulus and acute colonic pseudo-obstruction 2021; ASGE 2020","variants":["ชายอายุ 80 ปี อยู่บ้านพักคนชรา ท้องอืดมาก plain film เห็นห่วงลำไส้รูป U กลับหัวขนาดใหญ่จากอุ้งเชิงกรานซ้าย ไม่มี peritonitis → flexible sigmoidoscopic detorsion + rectal tube แล้ว elective sigmoidectomy","หญิงอายุ 40 ปี ปวดท้องและท้องอืด plain film เห็นลำไส้ขยายรูปไตที่ LUQ ร่วมกับลำไส้เล็กขยาย → cecal volvulus ผ่าตัด right hemicolectomy","ผู้ป่วย sigmoid volvulus ส่องกล้องพบ mucosa ดำคล้ำ → ischemia ผ่าตัดฉุกเฉิน Hartmann procedure"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":13,"page2":5,"orig":"Acute abdomen 4","img":"q78c_54","imgNote":"ภาพรังสีช่องท้อง (scout/AP) ของผู้ป่วยที่มีสาย ECG และลวดเย็บกระดูกอกจากการผ่าตัดหัวใจ เห็นลำไส้ขยายหลายตำแหน่ง","stem":"A patient in the ICU after cardiac surgery develops progressive abdominal distension. Electrolytes are being corrected. His abdominal radiograph is shown. What is the most likely diagnosis?","gray":"[รูป scout/AP ช่องท้อง] — A. sigmoid volvulus B. Ogilvie","opts":["Sigmoid volvulus","Ogilvie syndrome","Cecal volvulus","Small bowel obstruction","Gallstone ileus"],"ans":1,"key":"B Ogilvie (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"บริบทผู้ป่วย ICU หลังผ่าตัดหัวใจ (เห็นลวดเย็บกระดูกอกและสาย ECG ในภาพ) + ท้องอืดมากขึ้น + ภาพเห็นลำไส้ใหญ่ขยายกระจายทั่วไปหลายส่วนโดยไม่มีห่วงบิดเดี่ยว → ภาวะลำไส้ใหญ่ขยายแบบ <b>functional</b> ไม่ใช่ mechanical","why":"<b>Ogilvie syndrome (acute colonic pseudo-obstruction)</b> เกิดจาก autonomic imbalance (parasympathetic ลด sympathetic เด่น) พบในผู้ป่วยสูงอายุ หลังผ่าตัด (หัวใจ, ortho, คลอด), ICU, sepsis, electrolyte ผิดปกติ (K, Mg, Ca), opioid หรือ anticholinergic; ภาพเห็นลำไส้ใหญ่ขยายทั่วไป (cecum, ascending, transverse) มักมีแก๊สลงไปถึง rectum ไม่มี transition point หรือห่วงบิด; เสี่ยงแตกเมื่อ cecum &gt;12 cm หรือขยายนานกว่า 6 วัน; รักษา conservative 24–48 ชม. → neostigmine → colonoscopic decompression → ผ่าตัดถ้า perforation หรือ ischemia","wrong":{"A":"Sigmoid volvulus เห็นห่วง sigmoid ขนาดยักษ์รูป U กลับหัวเดี่ยวจากอุ้งเชิงกรานซ้าย (coffee bean) และไม่มีแก๊สใน rectum ไม่ใช่ลำไส้ขยายกระจายหลายส่วน; มักพบในผู้สูงอายุท้องผูกเรื้อรังติดเตียง — จะถูกถ้าภาพเป็นแบบในข้อ 733","C":"Cecal volvulus เห็น cecum ขยายเป็นก้อนเดี่ยวรูปไตย้ายไปอยู่ LUQ ร่วมกับลำไส้เล็กขยายและลำไส้ใหญ่ส่วนปลายแฟบ; จะถูกถ้าภาพเห็นห่วงขยายเดี่ยวที่ LUQ และผู้ป่วยอายุน้อยกว่า","D":"Small bowel obstruction เห็นลำไส้เล็กขยายตรงกลางมี valvulae conniventes พาดเต็มความกว้าง เรียงเป็นขั้นบันได และลำไส้ใหญ่แฟบ; ในภาพนี้ลำไส้ใหญ่ขยายด้วย — จะถูกถ้าภาพเห็นแต่ลำไส้เล็กขยายและไม่มีแก๊สในลำไส้ใหญ่","E":"Gallstone ileus เกิดจากนิ่วก้อนใหญ่ผ่าน cholecystoduodenal fistula ไปอุดที่ terminal ileum: Rigler triad = pneumobilia + SBO + นิ่วนอกตำแหน่ง (มักที่ RLQ); พบในหญิงสูงอายุ — จะถูกถ้าภาพเห็นแก๊สในท่อน้ำดีร่วมกับลำไส้เล็กขยาย"},"trap":"เห็นลำไส้ใหญ่ขยายมากแล้วคิดว่าเป็น volvulus — ให้ดูบริบท (หลังผ่าตัด, ICU) และ <b>รูปแบบการขยาย</b>: Ogilvie ขยายต่อเนื่องหลายส่วนไม่มีห่วงบิดและมีแก๊สถึง rectum; ต้องตัด mechanical obstruction ด้วย CT ก่อนให้ neostigmine เสมอ","summary":["Acute colonic pseudo-obstruction: ลำไส้ใหญ่ขยายเฉียบพลันโดยไม่มีสิ่งอุดตัน กลไก autonomic imbalance","ปัจจัยเสี่ยง: ผู้สูงอายุ หลังผ่าตัด (หัวใจ, ortho, ผ่าคลอด), ICU, sepsis, electrolyte ผิดปกติ, opioid, anticholinergic, โรคระบบประสาท","ภาพ: ลำไส้ใหญ่ขยายทั่วไป เด่นที่ cecum และ right colon ไม่มี transition point; CT หรือ water-soluble contrast enema ยืนยันว่าไม่มี mechanical obstruction","เสี่ยงแตกเมื่อ cecum &gt;12 cm หรือขยายนานกว่า 6 วัน","Conservative 24–48 ชม.: NPO, NG tube, rectal tube, แก้ K และ Mg, หยุด opioid และ anticholinergic, เปลี่ยนท่าบ่อย ๆ","ไม่ดีขึ้น → neostigmine 2 mg IV (monitor ECG) → colonoscopic decompression → ผ่าตัดถ้า perforation, ischemia หรือวิธีอื่นล้มเหลว (cecostomy, colectomy)","ดูข้อ 720 (neostigmine), ข้อ 733 (sigmoid volvulus) และข้อ 719"],"notes":"ไฟล์เฉลย (หน้า 5 บท acute abdomen แถว 4): <b>B</b> (ช่องคำอธิบายในไฟล์เฉลยว่าง) · <b>โน้ตผู้จดในไฟล์โจทย์:</b> ไม่มีข้อความโจทย์เลย มีแค่รูปภาพรังสีช่องท้อง (scout/AP) และช้อย 2 ช้อย “A. sigmoid volvulus B. Ogilvie” → เราแต่งเป็นเคสสั้นโดยอาศัยข้อมูลที่อ่านได้จากรูป (ลวดเย็บกระดูกอกและสาย ECG = ผู้ป่วยหลังผ่าตัดหัวใจใน ICU) และแต่งช้อย C–E; ช้อย B “Ogilvie” → Ogilvie syndrome · ในไฟล์โจทย์บท Acute abdomen แถว 5 ว่าง (มีแค่ “A.”) ไม่ใช่ข้อ; ไฟล์เฉลยบท acute abdomen มีแถว 1–4","mnemonic":"<b>Ogilvie = ICU + หลังผ่าตัด + ลำไส้ใหญ่ขยายทั้งแถบ ไม่มีบิด</b>","guide":"ASGE acute colonic pseudo-obstruction and colonic volvulus 2020; ASCRS colonic volvulus and ACPO 2021","variants":["หญิงหลังผ่าตัดคลอดวันที่ 2 ท้องอืดมาก K 2.9 CT พบลำไส้ใหญ่ขยายทั่วไป cecum 9 cm ไม่มี transition point → conservative แก้ K หยุด opioid","ผู้ป่วยหลังผ่าตัดเปลี่ยนข้อเข่า ลำไส้ใหญ่ขยาย cecum 13 cm conservative 48 ชม.ไม่ดีขึ้น → neostigmine 2 mg IV","ผู้ป่วย pseudo-obstruction มีไข้ ท้องแข็ง CT พบ free air → ผ่าตัดฉุกเฉิน"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":14,"page2":5,"orig":"Stomach 1","stem":"Which patient is the most appropriate candidate for bariatric surgery?","gray":"candidate bariatic surgery — A. Mr.Moon bmi 36 with osa B. Female bmi38 housewife C. Mr. Manu bussiness-man with hypertension BMI 38 D. Mr. Something Weight 60 kg is undergoing tummy tug","opts":["Man with BMI 36 and obstructive sleep apnea","Pregnant housewife with BMI 38","Businessman with hypertension, BMI 38 and untreated alcohol use disorder","Man weighing 60 kg scheduled for abdominoplasty","Woman with BMI 24 seeking cosmetic weight loss"],"ans":0,"key":"A Mr.Moon bmi 36 with osa (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ ต้นฉบับ B (BMI 38) และ C (BMI 38 + hypertension) ก็เข้าเกณฑ์ผ่าตัดตาม ASMBS/IFSO 2022 (BMI ≥35 ไม่ว่ามีโรคร่วมหรือไม่) และ C เข้าเกณฑ์ NIH 1991 ด้วย — เติมข้อห้ามในช้อย B (ตั้งครรภ์) และ C (untreated alcohol use disorder) ให้เหลือคำตอบเดียว","interp":"ถามว่าใคร <b>เข้าข้อบ่งชี้และไม่มีข้อห้าม</b> ของ metabolic and bariatric surgery — ต้องดูทั้ง BMI โรคร่วม และข้อห้าม (ตั้งครรภ์ สารเสพติด) ไม่ใช่ดูแค่ตัวเลข BMI","why":"ชาย BMI 36 ที่มี <b>obstructive sleep apnea</b> (obesity-related comorbidity) เข้าเกณฑ์ทั้งแบบเก่า (NIH 1991: BMI ≥35 + comorbidity) และแบบใหม่ (<b>ASMBS/IFSO 2022: BMI ≥35 ไม่ว่ามีโรคร่วมหรือไม่</b>) และไม่มีข้อห้าม; การผ่าตัดช่วยให้ OSA ดีขึ้นหรือหายในผู้ป่วยส่วนใหญ่","wrong":{"B":"หญิงตั้งครรภ์ BMI 38 แม้ BMI เข้าเกณฑ์ แต่ <b>การตั้งครรภ์เป็นข้อห้าม</b> ของ bariatric surgery (และควรเลี่ยงการตั้งครรภ์ 12–18 เดือนหลังผ่าตัดเพราะน้ำหนักลดเร็วและขาดสารอาหาร); ต้นฉบับเขียนแค่ “Female bmi38 housewife” ซึ่งถ้าไม่ตั้งครรภ์ก็เข้าเกณฑ์ ASMBS/IFSO 2022 — จะถูกถ้าไม่ได้ตั้งครรภ์และไม่มีข้อห้ามอื่น","C":"BMI 38 + hypertension เข้าเกณฑ์ทั้ง NIH 1991 และ ASMBS/IFSO 2022 แต่ <b>untreated alcohol use disorder (substance abuse ที่ยังไม่รักษา) เป็นข้อห้าม</b> เพราะเสี่ยงติดสุรามากขึ้นหลังผ่าตัด (โดยเฉพาะ sleeve และ bypass ที่ดูดซึมแอลกอฮอล์เร็ว) และติดตามไม่ได้; ต้นฉบับ C ไม่มีข้อห้ามนี้ — จะถูกถ้าไม่มีปัญหาสุราหรือรักษาจนหยุดดื่มได้แล้ว","D":"น้ำหนัก 60 kg ที่จะทำ abdominoplasty (tummy tuck) เป็น <b>body contouring</b> ตัดผิวหนังและไขมันส่วนเกินหน้าท้อง ไม่ใช่ bariatric surgery และน้ำหนักนี้ไม่ใช่ obesity; จะถูกถ้าโจทย์ถามการผ่าตัดเสริมหลังน้ำหนักลดมากหลัง bariatric surgery จนผิวหนังหย่อน","E":"BMI 24 อยู่ในเกณฑ์ปกติแม้สำหรับคนเอเชีย ไม่เข้าเกณฑ์ใดเลย การผ่าตัดเพื่อความงามไม่ใช่ข้อบ่งชี้; จะถูกถ้า BMI ≥27.5 ในชาวเอเชียที่มี metabolic disease คุมไม่ได้ (ASMBS/IFSO 2022 ให้พิจารณาได้)"},"trap":"ยึดเกณฑ์เก่า NIH 1991 (BMI ≥40 หรือ ≥35 + comorbidity) อย่างเดียว — เกณฑ์ปัจจุบัน ASMBS/IFSO 2022 ลดลงเป็น BMI ≥35 ไม่ว่ามีโรคร่วม และ ≥30 ถ้ามี metabolic disease (ชาวเอเชีย ≥27.5); ข้อสอบจึงต้องตัดสินด้วย <b>ข้อห้าม</b> เช่น ตั้งครรภ์ และ substance abuse ที่ยังไม่รักษา","summary":["ASMBS/IFSO 2022: แนะนำผ่าตัดเมื่อ BMI ≥35 ไม่ว่ามีโรคร่วมหรือไม่; พิจารณาเมื่อ BMI 30–34.9 ที่มี metabolic disease; ชาวเอเชียพิจารณาเมื่อ BMI ≥27.5","เกณฑ์เดิม NIH 1991: BMI ≥40 หรือ ≥35 ร่วมกับ obesity-related comorbidity (T2DM, HT, OSA, dyslipidemia, NAFLD, osteoarthritis)","ข้อห้าม: ตั้งครรภ์หรือวางแผนตั้งครรภ์ในเร็ว ๆ นี้, substance หรือ alcohol abuse ที่ยังไม่รักษา, โรคจิตเวชรุนแรงที่ควบคุมไม่ได้ (MDD, psychosis), ไม่สามารถติดตามหรือปรับพฤติกรรมได้, operative risk สูงมาก","การผ่าตัดหลัก: sleeve gastrectomy, Roux-en-Y gastric bypass; อื่น ๆ OAGB, BPD-DS","ประโยชน์: น้ำหนักลด excess weight loss ราว 60–70%, T2DM remission, OSA และ HT ดีขึ้น, ลด mortality","หลังผ่าตัดเลี่ยงตั้งครรภ์ 12–18 เดือน; เสริมวิตามินตลอดชีวิต (B12, iron, calcium, vitamin D); เสี่ยง alcohol use disorder เพิ่มขึ้นหลัง RYGB","Abdominoplasty และ body contouring = ศัลยกรรมตกแต่ง ไม่ใช่ bariatric surgery","ดูข้อ 736 (กระเพาะอาหาร)"],"notes":"ไฟล์เฉลย (หน้า 5 บท stomach แถว 1): <b>A</b> (ช่องคำอธิบายในไฟล์เฉลยว่าง) · <b>โน้ตผู้จดในไฟล์โจทย์:</b> ไม่มีโน้ตแยก แต่ผู้จดตั้งชื่อเล่นในช้อยเอง “Mr.Moon”, “Mr. Manu”, “Mr. Something” (ตามต้นฉบับ); ต้นฉบับสะกด “bariatic” (= bariatric), “bussiness-man”; ช้อย D “tummy tug” = tummy tuck หรือ abdominoplasty · สิ่งที่เราปรับ: ช้อย B เติม “Pregnant” (ต้นฉบับ “Female bmi38 housewife”) และช้อย C เติม “untreated alcohol use disorder” (ต้นฉบับ “Mr. Manu bussiness-man with hypertension BMI 38”) เพื่อให้เหลือคำตอบเดียว; ตัดชื่อเล่นออกจากช้อย; แต่งช้อย E","mnemonic":"<b>เกณฑ์ใหม่ 35 / 30 / เอเชีย 27.5; ห้าม: ท้อง เหล้ายา จิตเวชคุมไม่ได้</b>","guide":"ASMBS/IFSO indications for metabolic and bariatric surgery 2022","variants":["หญิงอายุ 35 ปี BMI 37 ไม่มีโรคร่วม ลดน้ำหนักด้วยวิธีอื่นไม่สำเร็จ → เข้าเกณฑ์ bariatric surgery ตาม ASMBS/IFSO 2022","ชายไทยอายุ 45 ปี BMI 29 มี T2DM คุมไม่ได้ทั้งที่ใช้ยาหลายตัว → พิจารณา metabolic surgery ได้ตามเกณฑ์ชาวเอเชีย","ผู้ป่วย BMI 42 มีโรคซึมเศร้ารุนแรงที่ยังไม่ได้รักษา → รักษาโรคจิตเวชก่อน ยังไม่ควรผ่าตัด"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":14,"page2":5,"orig":"Stomach 2","stem":"A patient with dyspeptic symptoms undergoes endoscopy, and a rapid urease test on a gastric biopsy is positive. What is the most likely diagnosis?","gray":"อาการ gastritis urease test positive — A. h. Pylori gastritis B. Atopic gastitis","opts":["H. pylori gastritis","Autoimmune atrophic gastritis","NSAID gastropathy","Bile reflux gastritis","Eosinophilic gastritis"],"ans":0,"key":"A h. Pylori gastritis (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"Rapid urease test (CLO test) บวก = มีเชื้อที่สร้าง urease ในเยื่อบุกระเพาะ → ระบุสาเหตุของ gastritis ได้ทันที","why":"<b>Helicobacter pylori</b> สร้างเอนไซม์ <b>urease</b> ย่อย urea เป็น NH₃ + CO₂ แอมโมเนียทำให้ pH ในน้ำยาทดสอบสูงขึ้นจนสี indicator เปลี่ยน (เหลือง → ชมพูแดง) = rapid urease test บวก (sensitivity ราว 90% specificity ราว 95%); จึงวินิจฉัย <b>H. pylori gastritis</b> และให้ eradication therapy","wrong":{"B":"Autoimmune atrophic gastritis เกิดจาก antibody ต่อ parietal cell และ intrinsic factor ทำลาย corpus และ fundus → achlorhydria, vitamin B12 deficiency (pernicious anemia); urease test ไม่บวกเพราะไม่ใช่การติดเชื้อ — จะถูกถ้าโจทย์มี B12 ต่ำ macrocytic anemia anti-intrinsic factor บวก","C":"NSAID gastropathy เกิดจากยายับยั้ง COX-1 ลด prostaglandin ป้องกันเยื่อบุ เห็น erosion หรือแผลหลายตำแหน่ง ไม่มีเชื้อ → urease test ลบ; จะถูกถ้าโจทย์มีประวัติกิน NSAID ปวดข้อเรื้อรังและ urease test ลบ","D":"Bile reflux gastritis พบหลังผ่าตัดกระเพาะ (Billroth II, gastrojejunostomy) หรือ cholecystectomy น้ำดีไหลย้อนเห็นน้ำดีในกระเพาะและเยื่อบุแดง; urease test ไม่บวก — จะถูกถ้าโจทย์มีประวัติผ่าตัด Billroth II และอาเจียนเป็นน้ำดี","E":"Eosinophilic gastritis วินิจฉัยด้วย biopsy พบ eosinophil จำนวนมากในเยื่อบุ สัมพันธ์กับภูมิแพ้ ไม่ใช่การติดเชื้อ; จะถูกถ้าโจทย์มีประวัติภูมิแพ้ peripheral eosinophilia และ biopsy พบ eosinophil &gt;30 ตัวต่อ HPF"},"trap":"ลืมว่า urease test ลบลวงได้เมื่อเพิ่งกิน <b>PPI (หยุด 2 สัปดาห์), antibiotics หรือ bismuth (หยุด 4 สัปดาห์)</b> หรือมีเลือดออกในกระเพาะ — ผลบวกเชื่อถือได้สูง แต่ผลลบในภาวะเหล่านี้ยังตัดเชื้อไม่ได้","summary":["H. pylori: gram-negative spiral มี flagella สร้าง urease; สาเหตุหลักของ chronic gastritis, peptic ulcer, gastric adenocarcinoma, MALT lymphoma","การตรวจผ่านกล้อง: rapid urease test, histology, culture (ทดสอบความไวยา); ไม่ผ่านกล้อง: urea breath test, stool antigen, serology (บอกไม่ได้ว่าติดเชื้ออยู่)","ก่อนตรวจ: หยุด PPI 2 สัปดาห์, antibiotics และ bismuth 4 สัปดาห์ เพื่อเลี่ยงผลลบลวง","Eradication (Maastricht VI 2022): bismuth quadruple 14 วัน (PPI + bismuth + tetracycline + metronidazole) เป็นตัวเลือกหลักในพื้นที่ดื้อ clarithromycin สูง; หรือเลือกตามผลความไวยา","ยืนยันการกำจัดเชื้อด้วย UBT หรือ stool antigen อย่างน้อย 4 สัปดาห์หลังจบยา","Autoimmune gastritis: anti-parietal cell และ anti-intrinsic factor, B12 deficiency, เสี่ยง gastric NET และ adenocarcinoma","ดูข้อ 735 (กระเพาะอาหาร)"],"notes":"ไฟล์เฉลย (หน้า 5 บท stomach แถว 2): <b>A</b> (ช่องคำอธิบายในไฟล์เฉลยว่าง) · <b>โน้ตผู้จดในไฟล์โจทย์:</b> ไม่มี; ช้อย B ต้นฉบับเขียน “Atopic gastitis” น่าจะหมายถึง atrophic gastritis → เราใช้ Autoimmune atrophic gastritis; ช้อย A “h. Pylori gastritis” → H. pylori gastritis; ต้นฉบับเขียนสั้น “อาการ gastritis urease test positive” → เราทำเป็นเคสสั้น (dyspepsia ส่องกล้องทำ rapid urease test จาก biopsy); แต่งช้อย C–E · ในไฟล์โจทย์บท Stomach and Duodenum แถว 3 ว่าง (มีแค่ “A.”) ไม่ใช่ข้อ","mnemonic":"<b>Urease → NH₃ → pH สูง → สีชมพู = H. pylori</b>","guide":"Maastricht VI/Florence consensus 2022; ACG clinical guideline: treatment of Helicobacter pylori infection 2024","variants":["ผู้ป่วยแผล duodenal ulcer ทำ rapid urease test ลบ แต่กิน omeprazole มาตลอด 1 เดือน → ผลลบลวงได้ ส่ง histology หรือหยุด PPI 2 สัปดาห์แล้วตรวจ UBT","ผู้ป่วยได้ bismuth quadruple therapy ครบ 14 วัน → ตรวจ UBT ยืนยันการกำจัดเชื้ออย่างน้อย 4 สัปดาห์หลังจบยา","หญิงอายุ 60 ปี ซีด MCV 115 ส่องกล้องพบเยื่อบุ corpus บาง anti-intrinsic factor บวก → autoimmune atrophic gastritis"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"","page":14,"page2":5,"orig":"Breast 1","stem":"A woman with right breast cancer has undergone breast-conserving surgery. She refuses postoperative radiotherapy. Which benefit will she lose?","gray":"คนไข้เป็น breast cancer ปฏิเสธ posop RT จะสูญเสียประโยชน์อะไร — A. Local recurrence of right breast B. Growing of cancer in left breast","opts":["Reduction of local recurrence in the right breast","Prevention of a new cancer in the left breast","Avoidance of systemic therapy","Prevention of distant metastasis in every patient","Better cosmetic result"],"ans":0,"key":"A Local recurrence of right breast (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: เติมใน stem ว่าเป็นมะเร็งเต้านมขวาที่ทำ breast-conserving surgery แล้ว (ต้นฉบับไม่บอกชนิดผ่าตัด แต่ช้อยพูดถึง right/left breast)","interp":"ถามบทบาทของ <b>adjuvant radiotherapy หลัง breast-conserving surgery</b> — ประโยชน์หลักของรังสีรักษาคือ local control ในเต้านมข้างที่ผ่าตัด","why":"หลัง BCS ยังมีเซลล์มะเร็งตกค้างระดับจุลภาคในเนื้อเต้านมที่เหลือ รังสีรักษาทั้งเต้า (whole breast irradiation) จึง <b>ลด local recurrence ในเต้านมข้างเดิม</b> ได้ราวครึ่งหนึ่ง — EBCTCG 2011: recurrence ใด ๆ ใน 10 ปีลดจาก 35% เหลือ 19% และลด breast cancer death ใน 15 ปี (ป้องกัน recurrence ได้ 4 ราย ≈ ลดการเสียชีวิตได้ 1 ราย); BCS + RT จึงได้ผลรอดชีวิตเท่ากับ mastectomy ถ้าปฏิเสธ RT จะเสียประโยชน์ข้อนี้","wrong":{"B":"รังสีรักษาฉายเฉพาะเต้านมข้างที่เป็นมะเร็ง <b>ไม่ได้ป้องกันมะเร็งใหม่ในเต้านมอีกข้าง</b>; การลดความเสี่ยงมะเร็งเต้านมข้างตรงข้ามมาจาก endocrine therapy (tamoxifen, aromatase inhibitor) หรือ contralateral prophylactic mastectomy ในผู้มี BRCA mutation — จะถูกถ้าโจทย์ถามประโยชน์ของ endocrine therapy ใน HR-positive","C":"รังสีรักษาเป็นการรักษาเฉพาะที่ <b>ไม่ได้ทดแทน systemic therapy</b> (chemotherapy, endocrine, anti-HER2) ซึ่งตัดสินจาก biology ของก้อนและระยะโรค; จะถูกถ้าโจทย์ถามว่ารังสีรักษาช่วยให้เลี่ยงการผ่าตัด mastectomy ได้","D":"RT ลด breast cancer death ได้บ้างจากการลด local recurrence แต่ไม่ได้ป้องกัน distant metastasis ในผู้ป่วยทุกราย; การควบคุม micrometastasis ทั่วร่างกายเป็นบทบาทของ systemic therapy — จะถูกถ้าโจทย์ถามบทบาทของ adjuvant chemotherapy ใน triple-negative","E":"รังสีรักษามักทำให้รูปลักษณ์ของเต้านม <b>แย่ลงเล็กน้อย</b> (fibrosis, ผิวหนังเปลี่ยนสี, เต้านมหดเล็กลง) ไม่ใช่ดีขึ้น; การปฏิเสธ RT จึงไม่ได้เสีย cosmetic benefit — จะถูกถ้าโจทย์ถามข้อดีของ BCS เทียบกับ mastectomy"},"trap":"คิดว่ารังสีรักษาป้องกันมะเร็งได้ทั้งตัวหรือป้องกันเต้านมอีกข้าง — RT เป็น <b>local therapy</b> ประโยชน์หลักคือ local control ในเต้านมข้างที่ผ่าตัด (และลดการเสียชีวิตได้บางส่วนผ่านการลด recurrence)","summary":["Breast-conserving therapy = BCS (lumpectomy ขอบไม่มีมะเร็งติดหมึก) + whole breast irradiation; ผลรอดชีวิตเท่ากับ mastectomy","EBCTCG 2011: RT หลัง BCS ลด recurrence 10 ปีจาก 35% เหลือ 19% และลด breast cancer death 15 ปีจาก 25% เหลือ 21%","Regimen ปัจจุบัน: hypofractionation 40 Gy ใน 15 fractions หรือ 26 Gy ใน 5 fractions (FAST-Forward) ± tumor bed boost ในผู้อายุน้อยหรือเสี่ยงสูง","ละเว้น RT ได้ในผู้ป่วยกลุ่มเสี่ยงต่ำ: อายุ ≥65–70 ปี HR-positive HER2-negative ก้อน ≤2–3 cm N0 ที่ได้ endocrine therapy (PRIME II, CALGB 9343) แลกกับ local recurrence สูงขึ้นเล็กน้อยโดย survival ไม่ต่าง","ข้อห้าม RT: ตั้งครรภ์, เคยฉายรังสีบริเวณเดิม, connective tissue disease รุนแรงบางชนิด → อาจต้อง mastectomy แทน","RT ไม่ป้องกันมะเร็งเต้านมอีกข้าง ไม่แทน systemic therapy และ cosmesis มักแย่ลงเล็กน้อย","ดูข้อ 739 (รังสีรักษาหลัง BCS) และข้อ 738"],"notes":"ไฟล์เฉลย (หน้า 5 บท breast แถว 1): <b>A</b> (ช่องคำอธิบายในไฟล์เฉลยว่าง) · <b>โน้ตผู้จดในไฟล์โจทย์:</b> ไม่มี; ต้นฉบับเขียน “ปฏิเสธ posop RT” (= postoperative radiotherapy) แต่ไม่บอกชนิดการผ่าตัดและข้างของมะเร็ง → เราเติมว่าเป็นมะเร็งเต้านมขวาที่ทำ breast-conserving surgery แล้ว (ช้อยในต้นฉบับพูดถึง right breast และ left breast); ช้อย A “Local recurrence of right breast” → Reduction of local recurrence in the right breast, ช้อย B “Growing of cancer in left breast” → Prevention of a new cancer in the left breast; แต่งช้อย C–E","mnemonic":"<b>RT = Regional (local) control ไม่ใช่ทั้งตัว ไม่ใช่อีกข้าง</b>","guide":"NCCN Breast Cancer 2025; EBCTCG meta-analysis (Lancet) 2011","variants":["หญิงอายุ 45 ปี มะเร็งเต้านมซ้าย 2 cm N0 ทำ lumpectomy ขอบปลอดมะเร็ง → whole breast irradiation 40 Gy ใน 15 fractions ร่วมกับ systemic therapy ตาม biology","หญิงอายุ 74 ปี มะเร็งเต้านม 1.5 cm ER-positive HER2-negative N0 ทำ BCS และจะกิน endocrine therapy 5 ปี → พิจารณาละเว้นรังสีรักษาได้","หญิงตั้งครรภ์ไตรมาสแรกเป็นมะเร็งเต้านมระยะเริ่มต้น ต้องการผ่าตัดทันที → ฉายรังสีระหว่างตั้งครรภ์ไม่ได้ พิจารณา mastectomy หรือเลื่อน RT ไปหลังคลอด"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง — ภาพเป็น hamartoma แบบตำรา (ก้อนขอบชัด มีเส้นขอบบาง ภายในผสมไขมันกับเนื้อเต้านม) และประวัติก้อนคงที่ 7 ปีเข้ากับ benign lesion","page":14,"page2":5,"orig":"Breast 2","stem":"A woman has a breast mass that has remained the same size for 7 years. Her mammogram is shown. What is the most likely diagnosis?","gray":"Female, has mass in the breast that remain same size for 7 years , mammogram show this, almost like ”breast in breast tissue” [รูป screenshot mammogram] — A. harmartoma B. Lipoma C. Fibroadenoma D. Phyllodes","img":"q78c_58","imgNote":"Mammogram ท่า RMLO (ครอปจาก screenshot — ตัดชื่อเว็บและคำบรรยายใต้ภาพออกแล้ว)","opts":["Hamartoma","Lipoma","Fibroadenoma","Phyllodes tumor","Fat necrosis"],"ans":0,"key":"A harmartoma (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ก้อนเต้านมที่<b>ขนาดคงที่นานถึง 7 ปี</b> = ธรรมชาติแบบ benign โตช้าหรือไม่โตเลย; ภาพ mammogram ท่า RMLO เห็นก้อนรีขนาดใหญ่ <b>ขอบชัดมาก มีเส้นขอบบาง ๆ ล้อมรอบ</b> และภายในก้อนมีลายเนื้อเยื่อเต้านม (fibroglandular) ปนกับไขมัน หน้าตาเหมือนเนื้อเต้านมอีกชิ้นหนึ่งซ้อนอยู่ในเต้านม — ต้องตีความ pattern นี้เองจากภาพ","why":"<b>Breast hamartoma (fibroadenolipoma)</b> คือก้อนที่ประกอบด้วยส่วนประกอบปกติของเต้านม (ไขมัน, fibrous stroma, ท่อและ lobule) อยู่รวมกันอย่างไม่เป็นระเบียบ ล้อมด้วย <b>pseudocapsule บาง</b> → mammogram เห็นก้อนรีขอบเรียบชัด มีเส้นขอบ radiopaque บาง ๆ และภายในเป็น <b>ความทึบผสม (fat ปน soft tissue)</b> = sign <b>\"breast within a breast\"</b> ซึ่งแทบจะ pathognomonic → จัดเป็น <b>BI-RADS 2 (benign)</b> ไม่ต้อง biopsy ถ้าภาพชัดเจน; ทางคลินิกมักคลำได้ก้อนนุ่มหรือคลำไม่ได้เลย ไม่เจ็บ ขนาดคงที่นาน; รักษา<b>ไม่ต้องตัดถ้าไม่โตและไม่มีอาการ</b> ตัดออกเมื่อโต ทำให้เต้านมผิดรูป หรือวินิจฉัยไม่ชัด (พบมะเร็งเกิดในก้อนได้น้อยมาก)","wrong":{"B":"Lipoma → ก้อนที่เป็น<b>ไขมันล้วน radiolucent ทั้งก้อน</b> มี capsule บาง ไม่มีเนื้อ fibroglandular ปนอยู่ข้างใน (BI-RADS 2 เช่นกัน); จะถูกถ้าภาพเป็นก้อนดำโปร่งทั้งก้อนล้อมด้วยเส้นขอบบาง","C":"Fibroadenoma → ก้อนรีหรือ lobulated ขอบชัด <b>ความทึบเท่าหรือมากกว่าเนื้อเต้านมสม่ำเสมอ</b> ไม่มีไขมันในก้อน พบบ่อยในหญิงอายุน้อย 15–35 ปี (ในหญิงสูงอายุที่ก้อนเสื่อมอาจมี popcorn calcification); จะถูกถ้าโจทย์เป็นหญิงอายุ 20 ปี ก้อนเรียบ เคลื่อนที่ได้ US เป็น oval hypoechoic wider-than-tall","D":"Phyllodes tumor → ก้อนที่<b>โตเร็ว</b>และมักใหญ่ (&gt;3–4 cm) พบช่วงอายุ 40–50 ปี mammogram เป็นก้อน lobulated ทึบ ไม่มีไขมันปน รักษาด้วย wide excision margin ≥1 cm; จะถูกถ้าโจทย์บอกว่าก้อนโตขึ้นชัดเจนในไม่กี่เดือน","E":"Fat necrosis → เกิดหลัง<b>บาดเจ็บ ผ่าตัด หรือฉายรังสี</b> mammogram เป็น oil cyst (ก้อนไขมันโปร่ง) มักมี rim หรือ eggshell calcification และอาจดึงรั้งผิวหนังเลียนแบบมะเร็ง; จะถูกถ้าโจทย์มีประวัติอุบัติเหตุที่เต้านมหรือหลัง BCS แล้วเห็น oil cyst มีหินปูนขอบ"},"trap":"เห็นก้อนใหญ่ขอบชัดแล้วตอบ fibroadenoma ทันที — ต้องดูเนื้อในก้อน: fibroadenoma ทึบสม่ำเสมอ ส่วน hamartoma มีไขมันปนเนื้อเต้านมเหมือนเต้านมเล็ก ๆ อยู่ในแคปซูล; และอย่าสับสนกับ lipoma ซึ่งโปร่งดำทั้งก้อน","summary":["<b>Hamartoma (fibroadenolipoma)</b> = ก้อน benign ประกอบด้วยไขมัน, fibrous tissue และ glandular tissue ล้อมด้วย pseudocapsule บาง พบได้ทุกวัย มักอายุ &gt;35 ปี","Mammogram: ก้อนรีขอบชัด มีเส้นขอบบาง ภายในความทึบผสม fat กับ soft tissue = <b>\"breast within a breast\"</b> → BI-RADS 2; US เป็นก้อนขอบชัด echogenicity ผสม","ทางคลินิก: นุ่ม ไม่เจ็บ เคลื่อนที่ได้หรือคลำไม่ได้ ขนาดคงที่นาน; ไม่ต้องตัดถ้าภาพชัดและไม่โต ตัดเมื่อโต มีอาการ หรือวินิจฉัยไม่แน่","ก้อนที่มีไขมันในเต้านม (fat-containing lesions) เกือบทั้งหมดเป็น benign: lipoma (โปร่งล้วน), hamartoma (ผสม), oil cyst จาก fat necrosis, intramammary lymph node (มี fatty hilum), galactocele","Fibroadenoma: หญิงอายุน้อย ก้อนเรียบ เคลื่อนที่ได้ ความทึบสม่ำเสมอ; ≥40 ปี หรือโต หรือ &gt;2–3 cm พิจารณาตัด","Phyllodes tumor: อายุ 40–50 ปี โตเร็ว ก้อนใหญ่ → wide excision margin ≥1 cm ไม่ต้องทำ axillary staging","ดูข้อ 737, 739 (บท breast ในชุดนี้)"],"notes":"ไฟล์เฉลย บท breast แถว 2: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับในไฟล์โจทย์: ผู้จดบรรยายรูปไว้ว่า <b>\"almost like ”breast in breast tissue”\"</b> — เราไม่ใส่คำนี้ใน stem เพราะเป็น sign ที่ผู้สอบต้องตีความจากภาพเอง<br>รูปในไฟล์โจทย์เป็น <b>screenshot จาก Google Lens</b> ของภาพใน SpringerLink ซึ่งมีหัวเว็บ \"SpringerLink\" และคำบรรยายใต้ภาพ <b>\"Hamartoma | SpringerLink\"</b> (บอกคำตอบ) — เราครอปตัดส่วนนั้นออก เหลือเฉพาะ mammogram ท่า RMLO<br>ต้นฉบับสะกดช้อย A ว่า \"harmartoma\" (เราเขียน Hamartoma), ช้อย D \"Phyllodes\" (เราเขียน Phyllodes tumor); ช้อย E (Fat necrosis) แต่งเพิ่ม","mnemonic":"<b>ไขมันล้วน = lipoma, ไขมันปนเต้านม = hamartoma (breast within a breast), ทึบล้วน = fibroadenoma</b>","guide":"ACR BI-RADS Atlas 5th ed. 2013","variants":["หญิงอายุ 50 ปี mammogram คัดกรองพบก้อนรี radiolucent ทั้งก้อน มีเส้นขอบบางล้อมรอบ ไม่มีเนื้อทึบภายใน วินิจฉัยและจัดการอย่างไร → lipoma, BI-RADS 2, routine screening","หญิงอายุ 45 ปี เคยประสบอุบัติเหตุเข็มขัดนิรภัยกดเต้านมเมื่อ 1 ปีก่อน mammogram พบก้อนไขมันโปร่งมีหินปูนเป็นวงขอบ → fat necrosis (oil cyst) ไม่ต้องผ่าตัด","หญิงอายุ 42 ปี ก้อนเต้านมโตจาก 2 cm เป็น 6 cm ใน 4 เดือน core biopsy เป็น fibroepithelial lesion with stromal overgrowth → phyllodes tumor รักษาด้วย wide excision margin ≥1 cm"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ C เมื่อเติมข้อมูลแล้ว ความมั่นใจปานกลางถึงสูง — ต้นฉบับให้แค่ 4 cm กับ LN positive ซึ่งในทางปฏิบัติปัจจุบันหลายสถาบันจะเลือก <b>neoadjuvant (ช้อย A)</b> ได้เช่นกัน โดยเฉพาะ HER2+ หรือ TNBC หรือเมื่อต้องการ downstage รักแร้เพื่อเลี่ยง ALND (cN1 → ycN0 แล้วทำ SLNB แบบ dual tracer); คีย์ตอบ C จึงเติม stem ให้เป็นกรณีที่ upfront BCS ดีที่สุด: luminal A-like (pCR ต่ำ), เต้านมใหญ่, node ยืนยันด้วย FNA (ข้อห้าม SLNB ตามสไลด์), ต้องการเก็บเต้า → wide excision + ALND + RT; ถ้าโจทย์ให้ HER2 3+ หรือ triple negative ให้ตอบ A; ถ้ามีข้อห้าม BCS ให้ตอบ B; สอดคล้องกับข้อสอบชุด 77C (ก้อน 5 cm กับ node ผิดปกติ → FNA node ก่อน), 77A และ 77D (locally advanced → neoadjuvant) และ 76D (matted nodes → mastectomy + ALND)","page":15,"page2":6,"orig":"Breast 3","stem":"A 55-year-old postmenopausal woman has a 4-cm mass in a large right breast. Core biopsy shows invasive ductal carcinoma, ER and PR positive, HER2 negative, with low Ki-67. A palpable axillary node is positive for metastasis on fine-needle aspiration. Staging shows no distant metastasis. She wishes to preserve her breast. What is the most appropriate management?","gray":"breast mass 4 cm. LN positive — A. neoadjuvant B. Mastectomy + ALND C. wide excision +","opts":["Neoadjuvant systemic therapy","Mastectomy with axillary dissection","Wide excision with axillary dissection and radiotherapy","Wide excision with sentinel node biopsy alone","Endocrine therapy alone without surgery"],"ans":2,"key":"C wide excision + (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","kimg":["k78c_59"],"flag":"⚠ ต้นฉบับ T2 (4 cm) N+ โดยไม่บอก subtype — neoadjuvant (ช้อย A) ก็ถูกได้ โดยเฉพาะ HER2+/TNBC หรือก้อนใหญ่เทียบขนาดเต้านม; เติมใน stem ให้ตรงกับเหตุผลของคีย์: HR+/HER2−, Ki-67 ต่ำ, เต้านมใหญ่ (ทำ BCS ได้), ต่อมน้ำเหลืองยืนยันด้วย FNA, ต้องการเก็บเต้านม → upfront BCS + ALND + RT","interp":"มะเร็งเต้านม <b>cT2 (4 cm) cN1</b> (ต่อมน้ำเหลืองคลำได้และ FNA ยืนยัน) ไม่มี distant metastasis = stage IIB; subtype <b>luminal A-like</b> (ER/PR+, HER2−, Ki-67 ต่ำ) ซึ่งตอบสนองต่อ chemotherapy ก่อนผ่าตัดน้อย; <b>เต้านมใหญ่</b> → ก้อน 4 cm เทียบกับขนาดเต้านมยังทำ BCS ได้สวย; ผู้ป่วย<b>อยากเก็บเต้านม</b> → ต้องเลือกทั้งการจัดการเต้านม การจัดการรักแร้ และการฉายรังสีให้ถูก","why":"ตามสไลด์ในไฟล์เฉลย: (1) <b>เต้านม</b> — ไม่มีข้อห้าม BCS (ไม่ได้ตั้งครรภ์, ไม่มี diffuse microcalcification, ไม่ใช่ multicentric, margin ทำได้) → <b>wide excision</b>; ข้อบ่งชี้ preoperative systemic therapy (inoperable T4/&gt;N2, HER2+ หรือ TNBC ที่ ≥T2 หรือ ≥N1, N+ ที่น่าจะกลายเป็น cN0, ก้อนใหญ่เทียบเต้านมแต่อยากเก็บเต้า) ไม่เข้าเกณฑ์เด่นในรายนี้ เพราะเป็น HR+/HER2− Ki-67 ต่ำ ซึ่ง <b>pCR จาก neoadjuvant chemotherapy ต่ำมาก (&lt;10%)</b> และเต้านมใหญ่พอทำ BCS ได้ทันที; (2) <b>รักแร้</b> — <b>palpable pathologic LN ที่ยืนยันด้วย FNA/CNB เป็นข้อห้ามของ SLNB</b> → <b>axillary dissection</b> (level I–II); (3) <b>รังสี</b> — ข้อบ่งชี้ RT ตามสไลด์: BCS, pN+, T3+, margin &lt;1 mm → หลัง BCS <b>ต้องฉาย whole-breast RT</b> และในรายนี้ pN+ จึงฉาย regional nodal irradiation ร่วม; หลังผ่าตัดให้ adjuvant endocrine therapy (aromatase inhibitor ในวัยหมดประจำเดือน นาน 7.5–10 ปีเมื่อ N+) ± chemotherapy ตามจำนวน node และ genomic assay (สไลด์: postmenopause ให้ chemo เมื่อ RS &gt;25 หรือ N2)","wrong":{"A":"Neoadjuvant systemic therapy → เป็นทางเลือกที่ถูกได้ในต้นฉบับที่ไม่บอก subtype: เหมาะเมื่อ <b>HER2+ หรือ TNBC ที่ ≥cT2 หรือ cN1</b> (ได้ pCR สูง และถ้ามี residual disease ได้เปลี่ยนยา T-DM1 หรือ capecitabine), ก้อนใหญ่เทียบขนาดเต้านมแต่อยากทำ BCS, ต้องการ downstage รักแร้จาก cN1 เป็น ycN0 เพื่อเลี่ยง ALND หรือ inoperable (T4, cN2–3); ในรายนี้ luminal A-like ตอบสนองต่อ chemo น้อย จึงไม่ใช่คำตอบที่ดีที่สุด — ถ้าโจทย์ให้ HER2 3+ หรือ triple negative จะตอบช้อยนี้","B":"Mastectomy with axillary dissection → ผ่าตัดได้ผลทางมะเร็งเท่ากับ BCS + RT แต่เสียเต้านมโดยไม่จำเป็น; จะถูกเมื่อ<b>มีข้อห้าม BCS</b> (ฉายรังสีระหว่างตั้งครรภ์, diffuse suspicious microcalcifications, โรคกระจายหลายจุดจนได้ผลทางมะเร็งหรือความสวยงามไม่ดี, margin บวกกระจายหลังตัดซ้ำ, homozygous ATM mutation), ก้อนใหญ่เทียบเต้านมเล็ก หรือผู้ป่วยเลือกเอง","D":"Wide excision with sentinel node biopsy alone → SLNB ใช้กับ <b>cN0</b> เท่านั้น ต่อมน้ำเหลืองที่คลำได้และ FNA ยืนยันแล้วเป็นข้อห้ามของ SLNB ตามสไลด์ อีกทั้งช้อยนี้ไม่มีการฉายรังสีหลัง BCS; จะถูก (ร่วมกับ whole-breast RT) ถ้าโจทย์เป็น cT1–2 cN0 และ SLNB พบ 1–2 node ตามเกณฑ์ ACOSOG Z0011 ซึ่งไม่ต้อง ALND","E":"Endocrine therapy alone without surgery → primary endocrine therapy ใช้ใน<b>ผู้สูงอายุมากหรือโรคร่วมรุนแรงจนผ่าตัดไม่ได้</b> และเป็น HR+; หญิง 55 ปีที่แข็งแรงควรได้รับการผ่าตัดเพื่อหวังหายขาด; จะถูกถ้าโจทย์เป็นหญิงอายุ 90 ปี ER+ ที่ไม่พร้อมผ่าตัด"},"trap":"ตอบ neoadjuvant ทุกครั้งที่เห็น T2N1 — ข้อบ่งชี้ neoadjuvant ขึ้นกับ subtype และเป้าหมาย (HER2+/TNBC ได้ประโยชน์มาก, luminal A-like ได้น้อย); อีกกับดักคือเลือก SLNB ทั้งที่ต่อมน้ำเหลืองคลำได้และ FNA บวกแล้ว และลืมว่า BCS ต้องตามด้วย RT เสมอ","summary":["Work up: core needle biopsy + IHC (ER, PR, HER2, Ki-67) ก่อนวางแผนรักษาเสมอใน T2, N+ หรือผู้ที่อยากทำ BCS; ต่อมน้ำเหลืองที่ผิดปกติให้ US + FNA หรือ core biopsy","Preoperative systemic therapy เมื่อ: inoperable (T4, cN2–3, inflammatory), HER2+ หรือ TNBC ที่ ≥cT2 หรือ cN1, cN+ ที่หวังให้เป็น ycN0 เพื่อเลี่ยง ALND, ก้อนใหญ่เทียบเต้านมแต่อยากทำ BCS, ต้องเลื่อนผ่าตัด","ข้อห้าม BCS: ฉายรังสีขณะตั้งครรภ์, diffuse suspicious microcalcifications, โรคกระจายจนได้ผลไม่ดี, margin บวกกระจาย, homozygous ATM mutation → total mastectomy","รักแร้: cN0 → SLNB (dual technique หลัง neoadjuvant); SLN negative หรือ micrometastasis → ไม่ต้อง ALND; 1–2 SLN บวกใน cT1–2 N0 ที่ไม่ได้ neoadjuvant และจะฉายรังสี → ไม่ต้อง ALND; palpable node ยืนยันแล้ว, IBC, cN2, หา SLN ไม่เจอ → ALND","RT หลังผ่าตัด: ทุกราย BCS, pN+, T3 ขึ้นไป, margin &lt;1 mm; BCS + RT ได้ overall survival เท่ากับ mastectomy","Systemic therapy ตาม subtype: HR+/HER2− → endocrine (premenopause tamoxifen หรือ ovarian suppression + AI; postmenopause AI) ± chemo ตาม genomic score; HER2+ → chemo + trastuzumab ± pertuzumab, residual → T-DM1; TNBC → pembrolizumab + chemo, residual → capecitabine; BRCA1/2 high-risk → olaparib 1 ปี","ดูข้อ 737 (RT หลัง BCS), 58 (บท breast)"],"notes":"ไฟล์เฉลย บท breast แถว 3: <b>C</b> + ช่องคำอธิบายเป็น<b>รูปสไลด์</b> (ถอดครบดังนี้)<br>หัวสไลด์ <b>TREATMENT OF BREAST CANCER</b><br>• <b>IHC from CNB for treatment planing</b> — T2, N+ve, or desire BCS<br>• <b>Need for preoperative systemic therapy ?</b> 1.Inoperable breast cancer •T4 or &gt;N2 2.HER2+ve, or TNBC •&gt;T2 or &gt;N1 3.N+ve likely to becone cN0 4.Large tumor relative to breast size, desires for BCS 5.Delayed surgery<br>• <b>Breast management</b> — <b>Contraindication for breast conserving surgery?</b> •RT during pregnancy •Diffuse suspicious or malignant microcalcifications •Widespred disease can’t achieves oncologic/cosmatic result •Diffusely positive pathologic margins •Homozygous ATM mutation → ลูกศรไป <b>Total mastectomy</b> / ถ้าไม่มี → <b>Wide excision</b><br>• กล่อง <b>Indication for RT ?</b> •BCS •pN+ve •T3+ •Margin &lt; 1 mm<br>• <b>Omit systemic therapy?</b> •Size&lt;0.5cm, pN0 → <b>Systemic therapy</b><br>• <b>Axillary staging</b> — <b>Contraindication for SLN?</b> •Palpable pathologic LN confirm by FNA/CNB •IBC or cN2 → <b>Axillary dissection</b>; ถ้าไม่มี → <b>SLNB</b> (Dual technique in post neoadjuvant) → Negative / Micrometastase → <b>No ALND</b>; 1-2 LN +ve ที่ •No NAC •cT1-2,N0 •RT planned → <b>No ALND</b> (นอกนั้น → Axillary dissection); Can’t indentify → <b>Axillary dissection</b><br>• ตาราง <b>Systemic therapy</b> (Subtype / Chemotherapy / AntiHER2 / Endocrine / Residual afterNAC / M1):<br>— HR+ HER2−: Premenop. chemo \"In RS &gt; 15, N+ve\", Postmenop. \"In RS &gt; 25, N2\"; Endocrine: premenop \"Tamoxifen or ovarain suppression + Aromatase inhibitor\", postmenop \"Aromatase inhibitor\", \"7.5-10yr in N+ve\"; Residual \"Cont. endocrine therapy\"; M1 \"AI or Fulvestrant + CKD4/6 inhibitor\"<br>— HER2+ve: chemo \"•Docetaxel + Cyclophos.(TC) / Dose-dense AC followed by Paclitaxel(ddAC-T) / •Pacitaxel •Docetaxel+Carbopaltin(TCH)\"; AntiHER2 \"Neratinib(adjuvant) / Trastuzumab + Pertuzumab (N+)\"; Residual \"Ado-transtuzumab emtansine (T-DM1)\"; M1 \"Pertuzumab+ Transtuzumab+ Docetaxel / Fam-transtuzumab deruxtecan-nxki\"<br>— TNBC: chemo \"Stage II ,III Pembrolizumab + Carboplatin + Paclitaxel\"; Residual \"Cont. Pembrolizumab / Capecitabine\"; M1 \"•Antracyclines •Taxanes •Anti-metabolites •Microtubule\"<br>— BRCA1/2 mutation: TNBC (Indication: pT2 or N1 after adjuvant / Residual after NAC), HR +ve HER2 −ve (N2 after adjuvant / Residual after NAC, CPS+EG &gt; 3) → \"Olaparib 1 yr\"<br>— Favorable histologies (•Pure tubular •Pure mucinous •Pure cribriform •Encapsulated or solid papillary carcinoma) mostly HR +ve, HER2 −ve subtype: \"+/- Chemotherapy in pN+ve\", \"Endocrine therapy in Size&gt;3cm, pN+ve\"<br>ลงชื่อ <b>FB: Surgeonvivor</b> (คงคำสะกดตามสไลด์)<br>ต้นฉบับในไฟล์โจทย์: ช้อย C เขียนว่า <b>\"wide excision +\"</b> จดไม่จบ → เราเขียนเต็มเป็น Wide excision with axillary dissection and radiotherapy ตามเหตุผลในสไลด์; ช้อย D, E แต่งเพิ่ม; stem ต้นฉบับมีแค่ \"breast mass 4 cm. LN positive\" — อายุ วัยหมดประจำเดือน subtype ขนาดเต้านม การยืนยัน node และความต้องการเก็บเต้านมเป็นข้อมูลที่เราเติม","mnemonic":"<b>BCS = ต้องฉาย RT เสมอ; node คลำได้ + FNA บวก = ALND ไม่ใช่ SLNB; neoadjuvant คุ้มสุดใน HER2+ กับ TNBC</b>","guide":"NCCN Breast Cancer 2025","variants":["หญิงอายุ 40 ปี ก้อน 3.5 cm ที่เต้านม core biopsy เป็น IDC ER−, PR−, HER2 3+ ต่อมน้ำเหลืองรักแร้ FNA บวก ควรทำอะไรต่อ → neoadjuvant chemotherapy + trastuzumab + pertuzumab แล้วผ่าตัด; ถ้ามี residual disease เปลี่ยนเป็น T-DM1","หญิงอายุ 60 ปี ก้อน 2 cm cN0 ทำ lumpectomy + SLNB พบ 1 ใน 3 node บวก จะฉาย whole-breast RT ต้องทำ ALND หรือไม่ → ไม่ต้อง (เกณฑ์ ACOSOG Z0011: cT1–2 N0, 1–2 SLN บวก, ไม่ได้ neoadjuvant, มี RT)","หญิงอายุ 50 ปี มะเร็งเต้านม 3 cm แต่ mammogram พบ diffuse suspicious microcalcifications ทั่วเต้านม การผ่าตัดเต้านมที่เหมาะสม → total mastectomy"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูงในแง่แนวคำตอบ (การให้สารน้ำเป็นการรักษาหลักระยะแรก) — แต่คำว่า \"Aggressive\" ในต้นฉบับขัดกับหลักฐานปัจจุบัน: WATERFALL trial 2022 พบว่า aggressive resuscitation เพิ่ม fluid overload โดยไม่ลด severity, ACG 2024 จึงแนะนำ moderate goal-directed fluid ด้วย Lactated Ringer; เราจึงเขียนช้อยเป็น Early intravenous fluid resuscitation; สอดคล้องกับข้อสอบชุด 77C ที่ถามการรักษา acute pancreatitis (IV fluid, analgesia, nutrition)","page":16,"page2":6,"orig":"Spleen and Pancreas 1","stem":"A patient has epigastric pain that worsens when lying supine and improves when leaning forward, with vomiting. Serum lipase is markedly elevated. He is not jaundiced, and liver function tests are normal. What is the next management?","gray":"คนไข้มีอาการเจ็บปวด epigastric นอนแล้วแย่ลง เอนมาข้างหน้าแล้วดีขึ้น คนไข้มีอาการอ้วกด้วย ถาม management ต่อไป — A. Aggressive Fluid resuscitation B. ERCP","opts":["Early intravenous fluid resuscitation","Urgent ERCP with sphincterotomy","Emergency laparotomy","Prophylactic intravenous carbapenem","Total parenteral nutrition"],"ans":0,"key":"A Aggressive Fluid resuscitation (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: ช้อยต้นฉบับเขียน \"Aggressive\" แต่หลักฐานปัจจุบัน (WATERFALL 2022, ACG 2024) แนะนำ moderate goal-directed fluid — ช้อยของเราเขียน \"Early intravenous fluid resuscitation\"; เติมใน stem ว่า lipase สูงมาก ไม่เหลือง LFT ปกติ (ตัดข้อบ่งชี้ ERCP)","interp":"ปวดลิ้นปี่ที่<b>แย่ลงเมื่อนอนหงาย ดีขึ้นเมื่อโน้มตัวไปข้างหน้า</b> ร่วมกับอาเจียน และ lipase สูงมาก → เข้าได้กับการอักเสบของอวัยวะ retroperitoneum บริเวณลิ้นปี่; <b>ไม่เหลืองและ LFT ปกติ</b> = ไม่มีหลักฐานของท่อน้ำดีอุดตันหรือ cholangitis → คำถามคือการรักษาเบื้องต้นที่สำคัญที่สุดในชั่วโมงแรก ๆ","why":"หัวใจของการรักษา acute pancreatitis ระยะแรกคือ <b>early intravenous fluid resuscitation</b> เพราะการอักเสบทำให้เกิด capillary leak, third spacing และ hypovolemia ซึ่งลด pancreatic microcirculation จนเกิด necrosis; แนะนำ <b>Lactated Ringer</b> (ดีกว่า NSS ในแง่ลด SIRS) แบบ <b>moderate goal-directed</b>: bolus 10 mL/kg ถ้ามี hypovolemia แล้ว <b>1.5 mL/kg/h</b> ปรับตาม HR, BP, urine output ≥0.5 mL/kg/h, BUN และ Hct ประเมินซ้ำที่ 12, 24, 48 และ 72 ชม.; การให้แบบ aggressive (20 mL/kg bolus + 3 mL/kg/h) ใน <b>WATERFALL trial 2022</b> เพิ่ม fluid overload (20.5% เทียบ 6.3%) โดยไม่ลด moderately severe หรือ severe pancreatitis จนต้องยุติการศึกษา; ร่วมกับ analgesia (opioid ใช้ได้), เริ่ม<b>กินทางปากภายใน 24–72 ชม.</b> เมื่อทนได้ และไม่ให้ antibiotic ป้องกัน","wrong":{"B":"Urgent ERCP with sphincterotomy → ERCP ภายใน 24 ชม. ทำเฉพาะ <b>acute pancreatitis ร่วม cholangitis</b> (ไข้ เหลือง ปวด RUQ) หรือมี <b>persistent CBD obstruction</b>; ในรายนี้ไม่เหลือง LFT ปกติ ERCP ไม่ช่วยและเพิ่มความเสี่ยง post-ERCP pancreatitis; จะถูกถ้าโจทย์มีไข้ bilirubin สูง และ US เห็น CBD ขยายพร้อมนิ่ว","C":"Emergency laparotomy → ผ่าตัดเร่งด่วนไม่มีบทบาทในระยะแรก และเพิ่มอัตราตาย; necrosectomy ใช้เมื่อ infected necrosis โดย step-up approach (percutaneous หรือ endoscopic drainage ก่อน) และรอ ≥4 สัปดาห์ให้ walled-off; จะถูกถ้าโจทย์เป็น abdominal compartment syndrome ที่ไม่ตอบสนองการรักษาอื่น หรือ bowel perforation","D":"Prophylactic intravenous carbapenem → guideline ปัจจุบัน<b>ไม่แนะนำ antibiotic ป้องกัน</b>แม้ใน severe หรือ necrotizing pancreatitis เพราะไม่ลด infected necrosis หรืออัตราตาย; จะถูกเมื่อสงสัย <b>infected necrosis</b> (ไข้หรือแย่ลงหลัง 7–10 วัน, gas ใน necrotic collection บน CT) หรือมี cholangitis หรือการติดเชื้อนอกตับอ่อน","E":"Total parenteral nutrition → ให้เฉพาะเมื่อ<b>กินหรือให้ enteral nutrition ไม่ได้</b> หลายวัน; enteral (oral, NG หรือ NJ) ดีกว่าเพราะรักษา gut barrier ลด infected necrosis และ multiorgan failure; จะถูกถ้าโจทย์บอกว่ามี prolonged ileus หรือ intolerance ต่อ enteral feeding ต่อเนื่อง"},"trap":"เลือก ERCP เพราะคิดว่าสาเหตุน่าจะเป็นนิ่ว — ERCP ไม่ใช่การรักษา pancreatitis แต่ใช้เมื่อมี cholangitis หรือท่ออุดตันต่อเนื่องเท่านั้น; อีกกับดักคือคิดว่ายิ่งให้น้ำมากยิ่งดี ซึ่งหลักฐานปัจจุบันพบว่าให้แบบ aggressive เกิด fluid overload","summary":["วินิจฉัย acute pancreatitis (revised Atlanta 2012) เมื่อมี 2 ใน 3: ปวดท้องเข้าได้, lipase หรือ amylase ≥3 เท่าของ ULN, imaging เข้าได้","Fluid: Lactated Ringer แบบ moderate goal-directed (bolus 10 mL/kg ถ้า hypovolemia แล้ว 1.5 mL/kg/h) ปรับตาม HR, MAP, urine output, BUN, Hct; aggressive เพิ่ม fluid overload (WATERFALL 2022)","Analgesia เพียงพอ (opioid ใช้ได้), early oral feeding ภายใน 24–72 ชม. เมื่อทนได้ (low-fat solid diet), ถ้ากินไม่ได้ใช้ enteral nutrition ทาง NG หรือ NJ ก่อน TPN","ไม่ให้ prophylactic antibiotics; ให้เมื่อสงสัย infected necrosis หรือมีการติดเชื้ออื่น","ERCP ภายใน 24 ชม. เฉพาะ cholangitis; persistent biliary obstruction ทำแบบ semi-elective; gallstone pancreatitis ชนิด mild ควรทำ cholecystectomy ใน admission เดียวกัน","CECT ไม่จำเป็นตอนแรกถ้าวินิจฉัยได้ ใช้เมื่อวินิจฉัยไม่ชัดหรือไม่ดีขึ้นหลัง 48–72 ชม.; US หานิ่วในถุงน้ำดีทุกราย","Severity: mild ไม่มี organ failure; moderately severe organ failure &lt;48 ชม. หรือ local complication; severe = persistent organ failure &gt;48 ชม.","ดูข้อ 742 (การวินิจฉัย acute pancreatitis), 61"],"notes":"ไฟล์เฉลย บท spleen แถว 1: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับในไฟล์โจทย์มีช้อยแค่ 2 ตัว: A. <b>Aggressive</b> Fluid resuscitation B. ERCP — เราเปลี่ยนถ้อยคำช้อย A เป็น Early intravenous fluid resuscitation ให้ตรงกับคำแนะนำปัจจุบัน (ไม่เปลี่ยนแนวคำตอบ) และช้อย C–E แต่งเพิ่ม<br>stem ต้นฉบับไม่มีค่า lipase, ภาวะเหลือง และ LFT — เราเติมเพื่อให้วินิจฉัยได้และตัดข้อบ่งชี้ ERCP; ไม่ใส่ชื่อโรคใน stem","mnemonic":"<b>ระยะแรกของ pancreatitis: \"น้ำ ยาแก้ปวด อาหาร\" (LR moderate, analgesia, early feeding) — ไม่ใช่ ERCP ไม่ใช่ antibiotic</b>","guide":"ACG acute pancreatitis 2024; revised Atlanta 2012","variants":["ชายอายุ 45 ปี ดื่มสุราหนัก ปวดลิ้นปี่ทะลุหลัง 12 ชม. lipase 2,000 U/L ชีพจร 118 BP 100/60 ควรให้สารน้ำอย่างไร → LR bolus 10 mL/kg แล้ว 1.5 mL/kg/h ประเมินซ้ำตาม HR, urine output, BUN","หญิงอายุ 55 ปี gallstone pancreatitis วันที่ 2 มีไข้ 39°C เหลือง bilirubin 6 mg/dL US พบ CBD 12 mm ควรทำอะไร → urgent ERCP ภายใน 24 ชม.","ผู้ป่วย necrotizing pancreatitis วันที่ 14 มีไข้และแย่ลง CT พบ gas ใน walled-off necrosis ควรทำอะไร → antibiotic ที่เข้า necrosis ได้ แล้ว step-up drainage (endoscopic หรือ percutaneous) เมื่อ walled-off"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง — ประวัติตัดม้ามร่วมกับ meningitis และผื่นทั่วตัวคือ OPSI; สอดคล้องกับข้อสอบชุด 76D และ 77A ที่ถามเชื้อและวัคซีนหลัง splenectomy","page":16,"page2":6,"orig":"Spleen and Pancreas 2","stem":"A patient who had a splenectomy now presents with signs of meningitis and a red rash spreading over the body. What is the most likely diagnosis?","gray":"คนไข้ตัด spleen ไป ตอนนี้มีอาการ meningitis มีผื่นแดงขึ้นตามตัว ถามว่าเป็นไร — A. Massive post-splenectomy infection B. Autoimmune disease","opts":["Overwhelming post-splenectomy infection","Autoimmune disease","Drug allergy","Viral exanthem","Thrombotic thrombocytopenic purpura"],"ans":0,"key":"A Massive post-splenectomy infection (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ผู้ป่วย<b>ไม่มีม้าม</b> (asplenia) มาด้วยอาการเยื่อหุ้มสมองอักเสบ (ไข้ ปวดศีรษะ คอแข็ง ซึม) ร่วมกับผื่นแดงกระจายทั่วตัว → ต้องนึกถึงการติดเชื้อรุนแรงแบบ fulminant sepsis จากเชื้อมีแคปซูลที่ม้ามเคยกำจัด และผื่นจาก DIC หรือ meningococcemia","why":"<b>Overwhelming post-splenectomy infection (OPSI)</b> คือ fulminant sepsis ในผู้ไม่มีม้าม เพราะสูญเสีย splenic macrophage ที่จับเชื้อที่ถูก opsonize น้อย และ IgM memory B cell ที่สร้าง antibody ต่อ polysaccharide capsule → เชื้อ<b>มีแคปซูล</b>: <b>Streptococcus pneumoniae (50–90%)</b>, Neisseria meningitidis, Haemophilus influenzae type b, Capnocytophaga canimorsus (หลังสุนัขกัด) รวมถึง babesia และ malaria รุนแรงขึ้น; อาการเริ่มคล้ายไข้หวัดแล้วลุกลามเป็น septic shock, <b>DIC</b> (petechiae, purpura fulminans), meningitis และ Waterhouse–Friderichsen syndrome ภายในไม่กี่ชั่วโมง; <b>อัตราตายราว 50%</b>; เสี่ยงสูงสุดใน<b>เด็ก</b>และ<b>2 ปีแรกหลังผ่าตัด</b> แต่เสี่ยงตลอดชีวิต และสูงกว่าเมื่อตัดม้ามจากโรคเลือด (thalassemia, lymphoma) มากกว่าจาก trauma; รักษาทันทีด้วย <b>ceftriaxone ± vancomycin</b> ไม่ต้องรอผลเพาะเชื้อ","wrong":{"B":"Autoimmune disease → โรค autoimmune เช่น SLE หรือ vasculitis อาจมีผื่นและเยื่อหุ้มสมองอักเสบแบบ aseptic ได้ แต่ไม่สัมพันธ์กับประวัติตัดม้าม และไม่ได้เกิดแบบเฉียบพลันรุนแรง; จะถูกถ้าโจทย์เป็นหญิงสาวมี malar rash, ข้ออักเสบ, ANA บวก และ anti-dsDNA บวก","C":"Drug allergy → ผื่นแพ้ยาเป็น maculopapular หรือ urticaria หลังได้ยา 1–2 สัปดาห์ อาจมีไข้ (DRESS) แต่ไม่ทำให้เกิดอาการ meningitis; จะถูกถ้าโจทย์บอกว่าเพิ่งเริ่มยาใหม่ เช่น allopurinol หรือ carbamazepine แล้วมีผื่นและ eosinophilia","D":"Viral exanthem → ไวรัสบางชนิด (enterovirus) ทำให้ผื่นร่วม aseptic meningitis ได้ แต่อาการไม่รุนแรงแบบ fulminant และในผู้ไม่มีม้าม ไข้ทุกครั้งต้องถือว่าเป็น OPSI จนกว่าจะพิสูจน์ได้ว่าไม่ใช่; จะถูกถ้าโจทย์เป็นเด็กมีไข้ต่ำ ผื่นแดงจาง ๆ ทั่วตัว คอแข็งเล็กน้อย CSF lymphocyte เด่น โดยไม่มีประวัติตัดม้าม","E":"Thrombotic thrombocytopenic purpura → มี petechiae/purpura และอาการทางสมองได้ (pentad: fever, MAHA, thrombocytopenia, neurologic, renal) แต่สาเหตุคือ ADAMTS13 ต่ำ ไม่ใช่การติดเชื้อ และไม่ทำให้คอแข็ง; จะถูกถ้าโจทย์ให้ schistocytes, LDH สูง, platelet ต่ำ และ coagulation ปกติ"},"trap":"มองเป็นแค่ meningitis หรือผื่นธรรมดา — ประวัติตัดม้ามคือกุญแจ: ไข้ในผู้ไม่มีม้ามเป็น medical emergency ต้องให้ antibiotic ทันที; และอย่าลืมว่าความเสี่ยงไม่หายไปเมื่อเวลาผ่านไปหลายปี","summary":["OPSI = fulminant sepsis ในผู้ไม่มีม้าม อัตราตายราว 50%; อุบัติการณ์ตลอดชีวิตราว 3–5% ในเด็ก ต่ำกว่าในผู้ใหญ่; เสี่ยงสูงสุดในเด็ก ใน 2 ปีแรก และเมื่อตัดม้ามเพราะโรคเลือด","เชื้อมีแคปซูล: S. pneumoniae (50–90%), N. meningitidis, H. influenzae type b; Capnocytophaga canimorsus หลังสุนัขกัด; malaria และ babesia รุนแรงขึ้น","อาการ: prodrome คล้ายไข้หวัด → septic shock, DIC, purpura fulminans, meningitis, adrenal hemorrhage ในไม่กี่ชั่วโมง; peripheral smear มี Howell–Jolly bodies","รักษา: ceftriaxone (หรือ cefotaxime) ± vancomycin IV ทันที ร่วมกับ sepsis bundle","วัคซีน: pneumococcal conjugate (PCV20 หรือ PCV21 หรือ PCV15 ตามด้วย PPSV23), MenACWY 2 dose ห่าง 8 สัปดาห์ กระตุ้นทุก 5 ปี, MenB, Hib 1 dose, influenza ทุกปี","เวลาให้วัคซีน: elective splenectomy ≥2 สัปดาห์ก่อนผ่าตัด; ผ่าตัดฉุกเฉิน ให้ ≥14 วันหลังผ่าตัด (หรือก่อนกลับบ้านถ้ากลัวไม่มาตามนัด)","ป้องกันเพิ่ม: standby antibiotic (amoxicillin-clavulanate) ให้กินทันทีเมื่อมีไข้, daily prophylaxis ในเด็กอย่างน้อยถึงอายุ 5 ปี และ 1–2 ปีแรกหลังผ่าตัด, บัตรประจำตัว asplenia, ให้ความรู้เรื่องสุนัขกัดและการเดินทางไปพื้นที่ malaria","ดูข้อ 740, 742 (บท spleen and pancreas)"],"notes":"ไฟล์เฉลย บท spleen แถว 2: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับในไฟล์โจทย์มีช้อยแค่ 2 ตัว: A. <b>Massive</b> post-splenectomy infection B. Autoimmune disease — เราใช้ชื่อมาตรฐาน <b>Overwhelming</b> post-splenectomy infection ในช้อย A (ความหมายเดียวกัน) และช้อย C–E แต่งเพิ่ม","mnemonic":"<b>เชื้อแคปซูลหลังตัดม้าม \"SHiN\": S. pneumoniae, H. influenzae, N. meningitidis</b> (+ Capnocytophaga หลังสุนัขกัด)","guide":"Sabiston 21st ed.; CDC adult immunization schedule 2025","variants":["ชายอายุ 30 ปี ตัดม้ามจากอุบัติเหตุเมื่อ 3 ปีก่อน ถูกสุนัขกัดที่มือ 2 วันต่อมามีไข้สูง ความดันต่ำ purpura ทั่วตัว เชื้อที่น่าคิดถึง → Capnocytophaga canimorsus","ผู้ป่วยจะทำ elective splenectomy จาก ITP ที่ไม่ตอบสนองต่อยา ควรให้วัคซีนเมื่อใดและชนิดใด → ≥2 สัปดาห์ก่อนผ่าตัด: pneumococcal, MenACWY, MenB, Hib","ผู้ป่วยทำ emergency splenectomy จาก splenic rupture ควรให้วัคซีนเมื่อใด → ≥14 วันหลังผ่าตัด (หรือก่อนกลับบ้านถ้าไม่แน่ใจว่าจะมาตามนัด)"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง — ข้อคล้ายข้อสอบชุด 77A (ปวดทะลุหลัง 6 ชม. → amylase/lipase ยืนยัน)","page":16,"page2":6,"orig":"Spleen and Pancreas 3","stem":"A patient has had symptoms resembling acute pancreatitis for 6 hours. Which investigation is most appropriate to confirm the diagnosis?","gray":"คนไข้มีอาการคล้าย ๆ Acute pancreatitis เป็นมา 6 ชม. ถามว่าตรวจไรดี — A. ตรวจ Lipase and amylase B. CTA C. (ว่าง)","opts":["Serum lipase and amylase","CT angiography","Contrast-enhanced CT of the abdomen now","MRCP","ERCP"],"ans":0,"key":"A ตรวจ Lipase and amylase (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ผู้ป่วยมีอาการเข้าได้กับ acute pancreatitis มาเพียง <b>6 ชม.</b> ถามการตรวจเพื่อ<b>ยืนยันการวินิจฉัย</b> — ต้องเลือกการตรวจที่ไว ทำได้ทันที และเหมาะกับระยะแรก ไม่ใช่การตรวจหาสาเหตุหรือภาวะแทรกซ้อน","why":"ตาม <b>revised Atlanta 2012</b> วินิจฉัย acute pancreatitis เมื่อมี 2 ใน 3: (1) ปวดท้องเข้าได้ (ปวดลิ้นปี่เฉียบพลันรุนแรงมักร้าวทะลุหลัง), (2) <b>serum lipase หรือ amylase ≥3 เท่าของ ULN</b>, (3) imaging เข้าได้ → เมื่อมีอาการแล้ว การตรวจเลือด lipase/amylase จึงพอยืนยันได้โดยไม่ต้อง imaging; <b>lipase</b> จำเพาะกว่าและสูงนานกว่า (8–14 วัน) amylase ขึ้นเร็วใน 6–12 ชม. แต่ลดลงใน 3–5 วัน และสูงได้จากสาเหตุอื่น (parotitis, bowel perforation, ectopic pregnancy, macroamylasemia); ระดับเอนไซม์<b>ไม่บอก severity</b>; CECT ในชั่วโมงแรก ๆ ยังไม่เห็น necrosis (ประเมินได้ดีที่สุดหลัง 72–96 ชม.) จึงใช้เมื่อวินิจฉัยไม่ชัดหรืออาการไม่ดีขึ้นหลัง 48–72 ชม.","wrong":{"B":"CT angiography → ใช้ดู<b>หลอดเลือด</b> เช่น acute mesenteric ischemia, aortic dissection หรือ pseudoaneurysm ที่เป็นภาวะแทรกซ้อนระยะหลังของ pancreatitis (เลือดออกใน collection); จะถูกถ้าโจทย์เป็นผู้ป่วย AF ปวดท้องรุนแรงเกินตรวจร่างกาย หรือผู้ป่วย pancreatitis สัปดาห์ที่ 3 มี Hb ลดลงฉับพลัน","C":"Contrast-enhanced CT of the abdomen now → ไม่จำเป็นในระยะแรกถ้าอาการและเอนไซม์เข้าได้; CT ที่ทำเร็วเกินไปประเมิน necrosis ต่ำกว่าความจริง และได้สารทึบรังสีในผู้ป่วยที่อาจ hypovolemia; จะถูกเมื่อ<b>วินิจฉัยไม่ชัด</b> (ต้องแยก perforated viscus หรือ mesenteric ischemia) หรือ<b>ไม่ดีขึ้นหลัง 48–72 ชม.</b> เพื่อดู necrosis และ collection","D":"MRCP → ใช้ดู<b>ท่อน้ำดีและท่อตับอ่อน</b> หา CBD stone ที่ US ไม่เห็น, pancreas divisum, IPMN หรือหาสาเหตุใน idiopathic pancreatitis; ไม่ใช่การตรวจยืนยันการวินิจฉัย; จะถูกถ้าโจทย์เป็น gallstone pancreatitis ที่ LFT ผิดปกติปานกลาง สงสัย CBD stone","E":"ERCP → เป็นหัตถการรักษา ไม่ใช่การวินิจฉัย และเสี่ยงทำให้ pancreatitis แย่ลง; ใช้เมื่อมี cholangitis (ภายใน 24 ชม.) หรือท่อน้ำดีอุดตันต่อเนื่อง; จะถูกถ้าโจทย์มีไข้ เหลือง และ CBD ขยายจากนิ่ว"},"trap":"สั่ง CT ทันทีเพราะอยากเห็นตับอ่อน — ในระยะแรก CT ไม่จำเป็นถ้าอาการกับเอนไซม์เข้าได้ และยังเห็น necrosis ไม่ชัด; อีกกับดักคือใช้ระดับ amylase/lipase บอกความรุนแรง ซึ่งไม่สัมพันธ์กัน","summary":["Revised Atlanta 2012: วินิจฉัยเมื่อมี 2 ใน 3 — อาการปวดเข้าได้, lipase หรือ amylase ≥3× ULN, imaging (CECT, MRI หรือ US) เข้าได้","Lipase: จำเพาะกว่า สูงภายใน 4–8 ชม. อยู่นาน 8–14 วัน เหมาะกับผู้มาช้าและ alcoholic pancreatitis; amylase: ขึ้นเร็ว ลดเร็วใน 3–5 วัน อาจปกติใน hypertriglyceridemia","ระดับเอนไซม์ไม่บอกความรุนแรงและไม่ใช้ติดตามการรักษา","US ช่องท้องทุกราย ตั้งแต่แรกเพื่อหานิ่วในถุงน้ำดี; ตรวจ triglyceride และ calcium หาสาเหตุ","CECT: เมื่อวินิจฉัยไม่ชัด หรือไม่ดีขึ้นหลัง 48–72 ชม.; ประเมิน necrosis ได้ดีที่สุดหลัง 72–96 ชม.","MRCP หรือ EUS: หา CBD stone ที่ความเสี่ยงปานกลาง และหาสาเหตุใน idiopathic; ERCP เป็นการรักษาเมื่อ cholangitis หรืออุดตันต่อเนื่อง","Severity: ใช้ SIRS, BUN, Hct, BISAP และ organ failure ตาม modified Marshall score; severe = organ failure &gt;48 ชม.","ดูข้อ 740 (การรักษา acute pancreatitis ระยะแรก), 61"],"notes":"ไฟล์เฉลย บท spleen แถว 3: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับในไฟล์โจทย์: A. ตรวจ Lipase and amylase B. CTA C. (ว่าง — ผู้จดพิมพ์ \"C.\" ไว้แต่ไม่ได้ใส่ข้อความ); ช้อย C–E ของเราแต่งเพิ่ม<br>stem ต้นฉบับเขียนว่า \"คนไข้มีอาการคล้าย ๆ Acute pancreatitis\" (ผู้จดจำรายละเอียดอาการไม่ได้) — เราแปลตรงตามนี้","mnemonic":"<b>Atlanta \"2 ใน 3\": ปวด + เอนไซม์ 3 เท่า + ภาพ — มีสองอย่างแรกแล้วไม่ต้อง CT</b>","guide":"revised Atlanta 2012; ACG acute pancreatitis 2024","variants":["ชายอายุ 40 ปี ปวดลิ้นปี่ทะลุหลัง 3 วัน amylase ปกติ ควรตรวจอะไรเพิ่ม → serum lipase (สูงนานกว่า amylase)","ผู้ป่วยปวดท้องรุนแรง lipase สูง 2 เท่าของ ULN แต่ตรวจร่างกายมี board-like rigidity ควรทำอะไร → CECT ช่องท้องเพื่อแยก perforated viscus เพราะการวินิจฉัยไม่ชัด","ผู้ป่วย acute pancreatitis วันที่ 4 ยังมีไข้และ organ failure ไม่ดีขึ้น ควรตรวจอะไร → CECT ช่องท้องเพื่อประเมิน necrosis และ collection"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูงเมื่อเติมรายละเอียดอาการแล้ว — ต้นฉบับมีเพียง \"อึแข็ง เจ็บก้น\" ซึ่งแยกจาก thrombosed external hemorrhoid หรือ abscess ไม่ได้ จึงเติมลักษณะปวดสัมพันธ์กับการถ่าย เลือดติดกระดาษ ไม่มีก้อน ไม่มีไข้","page":16,"page2":6,"orig":"Anorectal 1","stem":"After passing hard stools, a patient has sharp anal pain during and for about an hour after defecation, with a little bright red blood on the toilet paper. No perianal lump is palpable, and there is no fever. What is the most likely diagnosis?","gray":"ประวัติคนไข้อึแข็ง เจ็บก้น — A. acute anal fissure","opts":["Acute anal fissure","Thrombosed external hemorrhoid","Perianal abscess","Fistula in ano","Internal hemorrhoid"],"ans":0,"key":"A acute anal fissure (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: ต้นฉบับจดสั้นมาก — เติมใน stem ว่าปวดแสบขณะและหลังถ่ายราว 1 ชม. มีเลือดสดเล็กน้อยติดกระดาษ คลำไม่พบก้อน ไม่มีไข้ (แยก thrombosed external hemorrhoid/perianal abscess)","interp":"ถ่ายอุจจาระแข็งแล้ว<b>ปวดแปลบรุนแรงขณะถ่ายและปวดต่อหลังถ่ายนานราว 1 ชม.</b> มีเลือดสดเล็กน้อยติดกระดาษชำระ ไม่มีก้อนรอบทวาร ไม่มีไข้ → ปวดสัมพันธ์กับการถ่าย (ไม่ใช่ปวดตลอดเวลา) และไม่มีก้อนหรือการอักเสบติดเชื้อ","why":"<b>Anal fissure</b> = แผลฉีกตามยาวของ anoderm ใต้ dentate line (ซึ่งมี somatic innervation จึงเจ็บมาก) มักเกิดจากอุจจาระแข็งครูดผ่าน; ปวดแปลบเหมือนมีดบาด<b>ขณะถ่ายและปวดต่ออีกนาทีถึงหลายชั่วโมง</b>จาก internal anal sphincter spasm + เลือดสดเล็กน้อยติดกระดาษหรือผิวอุจจาระ; ~90% อยู่ <b>posterior midline</b> (เพราะเลือดไปเลี้ยงน้อยและแรงกดสูง) ผู้หญิงพบ anterior ได้ 10–25%; <b>acute</b> = &lt;6 สัปดาห์ ขอบแผลเรียบ; <b>chronic</b> = &gt;6–8 สัปดาห์ มี sentinel pile, hypertrophied anal papilla และเห็นเส้นใย internal sphincter ที่ก้นแผล; ตรวจโดยแหวกก้นดู (หลีกเลี่ยง DRE หรือ anoscopy ตอนเจ็บมาก); รักษา acute ด้วย <b>fiber, น้ำ, stool softener, sitz bath</b> หายราว 50% ร่วมกับ topical nitroglycerin หรือ diltiazem/nifedipine และ lidocaine","wrong":{"B":"Thrombosed external hemorrhoid → ปวดตลอดเวลาเฉียบพลันพร้อม<b>ก้อนสีม่วงคล้ำแข็งกดเจ็บที่ขอบทวาร</b> ไม่ได้ปวดเฉพาะตอนถ่าย; จะถูกถ้าโจทย์บอกว่าคลำได้ก้อนสีน้ำเงินคล้ำที่ปากทวารหลังเบ่งหนัก (มาภายใน 72 ชม. → excision)","C":"Perianal abscess → ปวดตุบ ๆ ตลอดเวลาแย่ลงเมื่อนั่ง มี<b>ไข้และก้อนบวมแดงร้อนกดเจ็บ</b> หรือ fluctuation; จะถูกถ้าโจทย์มีไข้และก้อนบวมแดงข้างทวาร → incision and drainage","D":"Fistula in ano → มี<b>หนองหรือน้ำเหลืองไหลซึม</b>จากรูเปิดภายนอกรอบทวารเรื้อรัง มักมีประวัติฝีมาก่อน ปวดไม่มาก; จะถูกถ้าโจทย์บอกว่ามีรูข้างทวารมีหนองซึมเปื้อนกางเกงหลังเคยผ่าฝี","E":"Internal hemorrhoid → <b>ไม่เจ็บ</b> (อยู่เหนือ dentate line, visceral innervation) มีเลือดสดหยดหรือพุ่งหลังถ่าย อาจมีก้อนยื่น; จะถูกถ้าโจทย์เป็นเลือดสดหยดหลังถ่ายแบบไม่เจ็บ"},"trap":"เห็นเลือดสดหลังถ่ายแล้วตอบ hemorrhoid — อาการเด่นของ fissure คือ<b>เจ็บมาก</b>ขณะและหลังถ่าย ส่วน internal hemorrhoid ไม่เจ็บ; และ fissure ที่ไม่อยู่ midline ต้องหาสาเหตุ secondary เสมอ","summary":["Anal fissure = แผลฉีกตามยาวของ anoderm ใต้ dentate line; อาการ: ปวดแปลบขณะถ่ายและปวดต่อหลังถ่าย + เลือดสดเล็กน้อยติดกระดาษ","ตำแหน่ง: posterior midline ~90%, anterior midline พบในหญิง 10–25% (โดยเฉพาะหลังคลอด); นอก midline หรือหลายแผล → นึกถึง Crohn disease, TB, HIV, syphilis, มะเร็ง","Acute &lt;6 สัปดาห์ ขอบเรียบ; chronic &gt;6–8 สัปดาห์: sentinel pile, hypertrophied anal papilla, เห็นใย internal anal sphincter, ขอบแข็ง","กลไก: internal anal sphincter hypertonia → resting pressure สูง → เลือดไปเลี้ยง posterior commissure ลด → แผลไม่หาย","รักษาขั้นแรก: fiber 25–35 g/วัน, น้ำ, stool softener, sitz bath, topical anesthetic; topical nitroglycerin 0.2–0.4% (ปวดศีรษะบ่อย) หรือ diltiazem 2%/nifedipine (ผลข้างเคียงน้อยกว่า)","Chronic ที่ไม่หาย: botulinum toxin injection หรือ <b>lateral internal sphincterotomy (LIS)</b> ซึ่งหายสูงสุด &gt;90% เสี่ยง incontinence เล็กน้อย; ระวัง LIS ในผู้หญิงหลังคลอดหรือมี sphincter อ่อน (ใช้ advancement flap แทน)","ดูข้อ 744, 747 (hemorrhoid), 68 (fistula), 65, 66"],"notes":"ไฟล์เฉลย บท anorectal แถว 1: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับในไฟล์โจทย์จดไว้สั้นมากเพียง \"ประวัติคนไข้อึแข็ง เจ็บก้น\" และมีช้อยเดียว A. acute anal fissure — รายละเอียดใน stem (ปวดขณะและหลังถ่ายราว 1 ชม., เลือดสดติดกระดาษ, ไม่มีก้อน, ไม่มีไข้) เราเติมเพื่อแยกโรคอื่น และช้อย B–E แต่งเพิ่ม","mnemonic":"<b>เจ็บ + เลือดน้อย = fissure; ไม่เจ็บ + เลือดหยด = internal hemorrhoid; เจ็บ + ก้อนม่วง = thrombosed external; เจ็บ + ไข้ + ก้อนแดง = abscess</b>","guide":"ASCRS anal fissure 2023","variants":["หญิงอายุ 30 ปี ปวดก้นขณะถ่ายมา 3 เดือน ตรวจพบแผลที่ posterior midline มี sentinel pile และเห็นใยกล้ามเนื้อที่ก้นแผล ใช้ topical diltiazem 8 สัปดาห์ไม่หาย ควรทำอะไร → lateral internal sphincterotomy หรือ botulinum toxin injection","ชายอายุ 25 ปี มีแผลที่ทวารหลายแผลอยู่ด้านข้าง ร่วมกับท้องเสียเรื้อรังและน้ำหนักลด ควรนึกถึงอะไร → Crohn disease (ส่ง colonoscopy และ biopsy)","ผู้ป่วยปวดก้นทันทีหลังเบ่งยกของหนัก คลำได้ก้อนสีม่วงคล้ำกดเจ็บที่ขอบทวาร เป็นมา 24 ชม. รักษาอย่างไร → excision of thrombosed external hemorrhoid"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูงเมื่อเติมลักษณะเลือด — ต้นฉบับบอกแค่ old man, fresh blood, painless ซึ่ง diverticular bleeding ก็เข้าได้ จึงเติมว่าเลือดปริมาณน้อย หยดหลังถ่ายเป็นซ้ำ และสัญญาณชีพปกติ; ถ้าโจทย์ให้เลือดออกมากทันทีจน hypotension ให้ตอบ diverticulosis; ในทางปฏิบัติผู้สูงอายุรายนี้ต้องได้ colonoscopy","page":16,"page2":6,"orig":"Anorectal 2","stem":"An elderly man has noticed painless bright red blood dripping into the toilet and coating the stool after defecation, in small amounts, on several occasions. His vital signs are normal. What is the most likely cause?","gray":"ถ่ายเป็นเลือดสด / An old man pass red flesh blood with stool, painless — A. hemorrhoid B. Diverticulosis C. Anal fissure","opts":["Hemorrhoids","Diverticulosis","Anal fissure","Ischemic colitis","Infectious colitis"],"ans":0,"key":"A hemorrhoid (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: diverticular bleeding ก็ painless ในผู้สูงอายุ — เติมใน stem ว่าเลือดสดปริมาณน้อย หยดหลังถ่าย/เคลือบอุจจาระ เป็นหลายครั้ง สัญญาณชีพปกติ (diverticular bleeding มักเป็นเลือดออกมากทันที)","interp":"ผู้สูงอายุถ่ายเป็น<b>เลือดสด ไม่เจ็บ ปริมาณน้อย หยดลงโถหรือเคลือบผิวอุจจาระหลังถ่าย</b> เป็นซ้ำหลายครั้ง สัญญาณชีพปกติ → ลักษณะ outlet-type bleeding (เลือดจากบริเวณ anorectum) ไม่ใช่ lower GI bleeding ปริมาณมาก","why":"<b>Internal hemorrhoids</b> อยู่เหนือ dentate line (visceral innervation) จึง<b>ไม่เจ็บ</b> และเลือดเป็น<b>สีแดงสด</b> (arterial จาก arteriovenous communication ใน anal cushion) ลักษณะ<b>หยดหรือพุ่งหลังถ่าย ติดกระดาษหรือเคลือบผิวอุจจาระ ไม่ปนในเนื้ออุจจาระ</b> ปริมาณน้อยเป็นซ้ำ ๆ อาจมีก้อนยื่นตาม Goligher grade I–IV; เป็นสาเหตุที่พบบ่อยที่สุดของ painless outlet bleeding; สำคัญมากคือ<b>ผู้สูงอายุ (≥45–50 ปี) ที่ถ่ายเป็นเลือดต้องทำ colonoscopy</b> แยก colorectal cancer และ polyp เสมอ แม้ตรวจพบ hemorrhoid แล้ว","wrong":{"B":"Diverticulosis → diverticular bleeding เป็นสาเหตุที่พบบ่อยของ lower GI bleeding ในผู้สูงอายุและก็<b>ไม่เจ็บ</b>เช่นกัน แต่ลักษณะคือ<b>เลือดออกมากทันที</b> (แดงสดหรือแดงคล้ำ ปนลิ่มเลือด) อาจมี orthostatic hypotension หยุดเองราว 75–80%; จะถูกถ้าโจทย์เป็นชายอายุ 75 ปี ถ่ายเป็นเลือดแดงคล้ำปริมาณมากทันที ชีพจรเร็ว ความดันต่ำ","C":"Anal fissure → <b>เจ็บมาก</b>ขณะและหลังถ่าย มีเลือดเล็กน้อยติดกระดาษ; จะถูกถ้าโจทย์บอกว่าปวดแปลบขณะถ่ายหลังอุจจาระแข็ง","D":"Ischemic colitis → ผู้สูงอายุที่มีโรคหลอดเลือด มี<b>ปวดท้องบิดเฉียบพลัน</b> (มักด้านซ้าย) ตามด้วยถ่ายเป็นเลือดปนอุจจาระภายใน 24 ชม. ตำแหน่ง watershed (splenic flexure, rectosigmoid junction); จะถูกถ้าโจทย์มีปวดท้องด้านซ้ายก่อนถ่ายเป็นเลือด หลัง hypotension หรือ AAA repair","E":"Infectious colitis → ถ่ายเหลวบ่อยมีมูกเลือด ไข้ ปวดบิด (Shigella, Campylobacter, EHEC, amoebiasis); จะถูกถ้าโจทย์มีไข้ ท้องเสียเป็นมูกเลือดหลายครั้งต่อวัน และ tenesmus"},"trap":"ตอบ diverticulosis เพราะเห็นคำว่า old man กับ painless — ต้องดูปริมาณและลักษณะเลือด: หยดน้อย ๆ หลังถ่ายซ้ำ ๆ = hemorrhoid; ออกมากทันทีจนสัญญาณชีพเปลี่ยน = diverticular; และอย่าหยุดแค่ hemorrhoid ในผู้สูงอายุ ต้องส่อง colonoscopy เสมอ","summary":["Painless bright red blood per rectum ปริมาณน้อย หยดหรือเคลือบผิวอุจจาระหลังถ่าย = outlet bleeding → hemorrhoid พบบ่อยที่สุด","Internal hemorrhoid (เหนือ dentate line) ไม่เจ็บ; Goligher I เลือดออกไม่ยื่น, II ยื่นแล้วกลับเอง, III ต้องดันกลับ, IV ดันไม่กลับ","External hemorrhoid (ใต้ dentate line) เจ็บเมื่อมี thrombosis","Diverticular bleeding: painless, ออกมากทันที, จาก vasa recta ที่ยืดตามคอ diverticulum, ขวาออกมากกว่าซ้าย, หยุดเอง 75–80%","LGIB ที่มี hemodynamic instability: resuscitate, ตัด UGIB (NG aspirate หรือ EGD ถ้าสงสัย), CTA ถ้ายังออก active, colonoscopy หลัง bowel prep","ผู้สูงอายุหรือ ≥45 ปีที่ถ่ายเป็นเลือด, มี iron deficiency anemia, เปลี่ยนนิสัยการขับถ่าย, น้ำหนักลด หรือประวัติครอบครัว → colonoscopy แยกมะเร็งลำไส้ใหญ่เสมอ","รักษา hemorrhoid: fiber และน้ำ, office procedure (rubber band ligation) สำหรับ I–III, hemorrhoidectomy สำหรับ III–IV หรือ mixed","ดูข้อ 747 (การรักษา hemorrhoid), 63, 75, 76"],"notes":"ไฟล์เฉลย บท anorectal แถว 2: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับในไฟล์โจทย์มีโจทย์ 2 บรรทัด: บรรทัดแรก <b>\"ถ่ายเป็นเลือดสด\"</b> และบรรทัดถัดมา <b>\"An old man pass red flesh blood with stool, painless\"</b> (\"flesh\" น่าจะหมายถึง fresh) — ช้อยต้นฉบับ A. hemorrhoid B. Diverticulosis C. Anal fissure; ช้อย D, E แต่งเพิ่ม<br>รายละเอียดใน stem เรื่องเลือดปริมาณน้อย หยดหลังถ่ายหรือเคลือบอุจจาระ เป็นหลายครั้ง และสัญญาณชีพปกติ เราเติมเพื่อแยก diverticular bleeding","mnemonic":"<b>\"หยดน้อย ซ้ำ ๆ หลังถ่าย = ริดสีดวง; ทะลักทีเดียวจนช็อก = diverticulum\"</b>","guide":"ASCRS hemorrhoids 2018","variants":["ชายอายุ 78 ปี ถ่ายเป็นเลือดแดงคล้ำปริมาณมากทันที 3 ครั้ง ไม่ปวดท้อง BP 90/60 ชีพจร 120 สาเหตุที่น่าจะเป็นที่สุด → diverticular bleeding","หญิงอายุ 70 ปี หลังผ่าตัด AAA วันที่ 2 ปวดท้องซ้ายแล้วถ่ายเป็นเลือดปนอุจจาระ สาเหตุ → ischemic colitis (sigmoid) ส่องดู sigmoidoscopy","ชายอายุ 60 ปี ถ่ายเลือดสดหยดหลังถ่ายแบบไม่เจ็บ ตรวจพบ internal hemorrhoid grade II ควรทำอะไรต่อก่อนรักษา hemorrhoid → colonoscopy แยกมะเร็งลำไส้ใหญ่"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูงเมื่อเติมเคสแล้ว — ต้นฉบับ \"MSM แผล\" อย่างเดียวกว้างมาก ถ้าเป็นแผลเฉียบพลันเจ็บ ต้องคิดถึง HSV, syphilis หรือ chancroid ก่อน จึงเติมว่าเป็นแผลเรื้อรังแข็ง 4 เดือนใน HIV+ และถามว่ามะเร็งชนิดใด","page":17,"page2":6,"orig":"Anorectal 3","stem":"A 50-year-old man who has sex with men and is HIV-positive has had a chronic, non-healing, indurated ulcer in the anal canal for 4 months. A biopsy is planned. Which cancer is most likely?","gray":"MSM แผล — A. Squamous cell carcinoma","opts":["Anal squamous cell carcinoma","Rectal adenocarcinoma","Anal melanoma","Basal cell carcinoma","Extramammary Paget disease"],"ans":0,"key":"A Squamous cell carcinoma (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ ต้นฉบับจดแค่ \"MSM แผล\" — เติมเคสใน stem (HIV+, แผลเรื้อรังแข็งที่ anal canal 4 เดือน รอ biopsy) ให้ถามมะเร็ง; ถ้าเป็นแผลเฉียบพลันเจ็บต้องคิด HSV/syphilis/chancroid ก่อน","interp":"ชายที่มีเพศสัมพันธ์กับชาย (MSM) และติดเชื้อ HIV มี<b>แผลเรื้อรังไม่หาย ขอบแข็ง ที่ anal canal นาน 4 เดือน</b> และถามว่ามะเร็งชนิดใดเป็นไปได้มากที่สุด → ต้องรู้ว่าเยื่อบุ anal canal ส่วนใหญ่เป็น squamous และปัจจัยเสี่ยงสำคัญคือ HPV ร่วมกับภูมิคุ้มกันบกพร่อง","why":"<b>Anal squamous cell carcinoma</b> เกิดจาก <b>HPV 16/18</b> (~90%) ผ่านลำดับ anal intraepithelial neoplasia (AIN หรือ LSIL → HSIL) → invasive SCC ที่ transformation zone และเยื่อบุ squamous ของ anal canal; กลุ่มเสี่ยงสูงสุดคือ <b>HIV-positive MSM</b> (อุบัติการณ์สูงกว่าประชากรทั่วไปหลายสิบเท่า) รองลงมาคือ HIV ทั่วไป, ผู้รับปลูกถ่ายอวัยวะ, ผู้หญิงที่มีประวัติ cervical/vulvar HSIL หรือมะเร็ง, สูบบุหรี่; อาการ: เลือดออก ปวด ก้อนหรือแผลแข็งเรื้อรัง คันหรือหนองซึม และคลำได้ inguinal node; วินิจฉัยด้วย biopsy; รักษาหลักคือ <b>chemoradiation แบบ Nigro protocol</b> (5-FU หรือ capecitabine + mitomycin C + RT) เก็บหูรูดได้ ผ่าตัด <b>APR</b> เก็บไว้สำหรับ persistent หรือ recurrent disease; การคัดกรองด้วย anal cytology และ high-resolution anoscopy แล้วรักษา HSIL ลดมะเร็งได้ราว 57% (<b>ANCHOR trial 2022</b>)","wrong":{"B":"Rectal adenocarcinoma → เกิดจากเยื่อบุ columnar ของ rectum ผ่าน adenoma–carcinoma sequence ไม่สัมพันธ์กับ HPV; มะเร็งที่อยู่ใน anal canal แล้วเป็น adenocarcinoma มักเป็นของ rectum ที่ลามลงมาหรือจาก anal gland ซึ่งพบน้อย; จะถูกถ้าโจทย์เป็นก้อนเหนือ dentate line ในผู้สูงอายุที่ถ่ายเป็นเลือดปนมูกและอุจจาระลำเล็กลง","C":"Anal melanoma → พบน้อยมาก (~1% ของมะเร็งทวาร) เป็นก้อนสีดำหรือ amelanotic คล้าย thrombosed hemorrhoid พยากรณ์โรคแย่มาก ไม่สัมพันธ์กับ HPV หรือ HIV; จะถูกถ้าโจทย์เป็นก้อนสีคล้ำดำที่ anal canal ซึ่ง biopsy ย้อม S-100 และ HMB-45 บวก","D":"Basal cell carcinoma → เกิดที่ผิวหนังรอบทวาร (perianal skin) ซึ่งพบน้อยมาก แผลขอบนูนมันวาว โตช้าและไม่ค่อยแพร่กระจาย; จะถูกถ้าโจทย์เป็นแผลขอบมุกที่ผิวหนังรอบทวารห่างจากขอบทวาร ไม่เกี่ยวกับ HIV","E":"Extramammary Paget disease → ผื่นแดงขอบชัด<b>คันเรื้อรัง</b>คล้ายผื่น eczema ที่ perianal skin ต้องหามะเร็งในลำไส้หรือทางเดินปัสสาวะร่วม; จะถูกถ้าโจทย์เป็นผื่นแดงมีขุยคันนานหลายเดือนรอบทวารไม่ตอบสนองต่อยาทาสเตียรอยด์ และ biopsy พบ Paget cells"},"trap":"เห็นคำว่ามะเร็งแถวทวารแล้วตอบ adenocarcinoma ตามมะเร็งลำไส้ใหญ่ — anal canal เป็น squamous epithelium มะเร็งส่วนใหญ่จึงเป็น SCC จาก HPV และการรักษาหลักคือ chemoradiation ไม่ใช่ APR","summary":["Anal SCC: HPV 16/18 → AIN/HSIL → invasive SCC; กลุ่มเสี่ยง: HIV+ MSM (สูงสุด), HIV, transplant recipient, ประวัติ HPV-related cervical/vulvar neoplasia, สูบบุหรี่, receptive anal intercourse","อาการ: เลือดออก ปวด ก้อนหรือแผลแข็งเรื้อรังที่ไม่หาย คัน หนองซึม; ตรวจ DRE, anoscopy, คลำ inguinal node; biopsy ยืนยัน","Staging: MRI pelvis (local และ node), CT chest/abdomen หรือ PET-CT, ตรวจ HIV และคัดกรองปากมดลูกในผู้หญิง","รักษา: Nigro protocol = 5-FU (หรือ capecitabine) + mitomycin C + RT 50–54 Gy → complete response ~80–90% และเก็บหูรูดได้; ประเมินผลที่ 8–26 สัปดาห์ (ยุบช้า)","APR สำหรับ persistent หรือ recurrent disease หลัง chemoRT; perianal (anal margin) T1 ขนาดเล็กอาจทำ local excision","คัดกรองกลุ่มเสี่ยงสูง: anal cytology หรือ hrHPV test → high-resolution anoscopy → รักษา HSIL (ANCHOR 2022 ลดมะเร็ง ~57%); ป้องกันด้วย HPV vaccine","แผลที่ทวารเฉียบพลันใน MSM: HSV (เจ็บ ตุ่มน้ำ), primary syphilis (ไม่เจ็บ ขอบแข็ง), chancroid, LGV proctitis","ดูข้อ 746 (condyloma จาก HPV), 63, 64"],"notes":"ไฟล์เฉลย บท anorectal แถว 3: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับในไฟล์โจทย์จดไว้เพียง <b>\"MSM แผล\"</b> และมีช้อยเดียว A. Squamous cell carcinoma — รายละเอียดใน stem (อายุ 50 ปี, HIV-positive, แผลเรื้อรังแข็งที่ anal canal 4 เดือน, รอ biopsy) เราเติมให้ถามมะเร็งได้ชัด และช้อย B–E แต่งเพิ่ม; ช้อย A เราเขียนเป็น Anal squamous cell carcinoma","mnemonic":"<b>เหนือ dentate = columnar = adenocarcinoma; ใต้ dentate = squamous = SCC จาก HPV → Nigro (chemoRT) ก่อนเสมอ</b>","guide":"NCCN Anal Carcinoma 2025; ASCRS anal squamous neoplasms 2018","variants":["ชาย MSM อายุ 45 ปี HIV-positive biopsy ก้อนที่ anal canal 3 cm เป็น SCC ไม่มี distant metastasis การรักษาหลัก → chemoradiation (5-FU + mitomycin C + RT) ตาม Nigro protocol","ผู้ป่วย anal SCC หลังครบ chemoradiation 6 เดือน ยังมีก้อนเหลืออยู่และ biopsy ยืนยันว่ายังเป็นมะเร็ง → abdominoperineal resection (salvage)","ชาย MSM อายุ 28 ปี มีแผลตื้น ๆ หลายแผลรอบทวาร เจ็บมาก นำด้วยตุ่มน้ำ 2 วัน สาเหตุที่น่าจะเป็น → HSV (ให้ acyclovir)"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูงเมื่อเติมข้อมูลแล้ว — ต้นฉบับไม่บอกตำแหน่งและขนาด ถ้าเป็นหูดเล็กที่ผิวหนังรอบทวารเท่านั้น imiquimod (ช้อย B) ก็เป็นการรักษาที่ถูกต้อง จึงเติมว่ากว้างขวางและอยู่ใน anal canal ด้วย","page":17,"page2":6,"orig":"Anorectal 4","stem":"A man has extensive perianal and intra-anal condylomata acuminata. What is the most appropriate treatment?","gray":"แผล condyloma รักษา — A. excision and coagulation B. Imiquimod cream","opts":["Surgical excision and electrocoagulation","Imiquimod cream applied to all lesions","Oral acyclovir for 10 days","Oral antibiotics for 2 weeks","Observation for spontaneous regression"],"ans":0,"key":"A excision and coagulation (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: imiquimod ใช้ได้กับ external warts ขนาดเล็ก — เติมใน stem ว่าเป็น condyloma กว้างขวางทั้งรอบทวารและใน anal canal (CDC 2021: imiquimod ไม่ใช้กับ intra-anal warts)","interp":"หูดหงอนไก่ (condylomata acuminata) จาก HPV ที่<b>กว้างขวาง</b> ทั้ง<b>รอบทวาร (perianal) และใน anal canal (intra-anal)</b> → การรักษาต้องครอบคลุมรอยโรคที่อยู่ภายใน anal canal ซึ่งยาทาที่ผู้ป่วยทาเองใช้ไม่ได้","why":"Condyloma จาก <b>HPV 6/11</b> (low-risk); ตาม CDC 2021 รอยโรคใน anal canal รักษาด้วย<b>วิธีที่แพทย์ทำ</b> ได้แก่ cryotherapy, TCA/BCA 80–90% หรือ <b>surgical removal</b>; เมื่อหูด<b>กว้างขวาง มีจำนวนมาก ก้อนใหญ่ หรือมีใน anal canal</b> วิธีที่ได้ผลและครบที่สุดคือ <b>surgical excision (scissor excision) ร่วม electrocoagulation/fulguration</b> ภายใต้ยาระงับความรู้สึก ร่วมกับ anoscopy ประเมินภายใน anal canal ทั้งหมด และ<b>ส่งชิ้นเนื้อหา dysplasia</b> (โดยเฉพาะใน HIV); ถ้ารอยโรคเป็นวงรอบทวารให้ทำเป็นระยะ (staged) เพื่อเลี่ยง anal stenosis; recurrence ราว 20–30% ต้องนัดติดตาม; ป้องกันด้วย HPV vaccine","wrong":{"B":"Imiquimod cream applied to all lesions → เป็นยาที่ผู้ป่วยทาเอง (immune response modifier) ใช้กับ <b>external anogenital warts</b> ขนาดเล็กถึงปานกลาง ทาสัปดาห์ละ 3 ครั้งนานถึง 16 สัปดาห์ แต่<b>ไม่แนะนำสำหรับ intra-anal warts</b> และได้ผลช้าเมื่อรอยโรคกว้างขวาง; จะถูกถ้าโจทย์เป็นหูดขนาดเล็กไม่กี่เม็ดที่ผิวหนังรอบทวารเท่านั้น","C":"Oral acyclovir for 10 days → เป็นยาต้าน <b>herpes simplex virus</b> ไม่มีผลต่อ HPV; จะถูกถ้าโจทย์เป็นตุ่มน้ำเจ็บแตกเป็นแผลตื้นหลายแผลรอบทวาร (genital herpes ครั้งแรก 7–10 วัน)","D":"Oral antibiotics for 2 weeks → condyloma เป็นการติดเชื้อไวรัส antibiotic ไม่ช่วย; จะถูกถ้าโจทย์เป็น LGV proctitis (doxycycline 21 วัน) หรือ syphilis (benzathine penicillin) ซึ่งเป็นแผลหรือ proctitis ไม่ใช่หูด","E":"Observation for spontaneous regression → หูดบางส่วนหายเองได้ภายใน 1 ปีในผู้ที่ภูมิคุ้มกันปกติและรอยโรคเล็ก แต่รอยโรคกว้างขวางและอยู่ใน anal canal มักไม่หาย ลุกลาม แพร่เชื้อ และอาจซ่อน dysplasia; จะถูกถ้าโจทย์เป็นหูดเม็ดเล็กไม่มีอาการและผู้ป่วยไม่ต้องการรักษา"},"trap":"เลือก imiquimod เพราะเป็นยาทาที่ง่ายและคุ้นชื่อ — ต้องดูว่ารอยโรคอยู่ในหรือนอก anal canal และกว้างเพียงใด; intra-anal หรือกว้างขวางต้องใช้วิธีที่แพทย์ทำ โดยเฉพาะ excision + fulguration และส่งชิ้นเนื้อ","summary":["Condylomata acuminata = HPV 6/11 (low-risk); ถ้ามี HPV 16/18 ร่วม เสี่ยง HSIL และมะเร็ง โดยเฉพาะใน HIV","Patient-applied (เฉพาะ external warts): imiquimod 3.75% หรือ 5%, podofilox 0.5%, sinecatechins 15%","Provider-administered: cryotherapy (ไนโตรเจนเหลว), TCA หรือ BCA 80–90%, surgical removal (scissor/shave excision, curettage, electrosurgery, laser)","Intra-anal warts: cryotherapy, TCA/BCA หรือ surgical removal; ควร anoscopy และส่งปรึกษาผู้เชี่ยวชาญ","รอยโรคกว้างขวาง ก้อนใหญ่ หรือ intra-anal → excision + fulguration ใต้ยาระงับความรู้สึก, ทำ staged ถ้าเป็นวงรอบเพื่อเลี่ยง stenosis, ส่งชิ้นเนื้อหา dysplasia","Recurrence 20–30%; Buschke–Löwenstein tumor (giant condyloma) = verrucous carcinoma โตลุกลามเฉพาะที่ → wide local excision","ป้องกัน: HPV vaccine (9-valent ครอบคลุม 6, 11, 16, 18), ถุงยางอนามัย; ตรวจคัดกรอง STI อื่นร่วม (HIV, syphilis)","ดูข้อ 745 (anal SCC จาก HPV), 63, 68"],"notes":"ไฟล์เฉลย บท anorectal แถว 4: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับในไฟล์โจทย์จดว่า <b>\"แผล condyloma รักษา\"</b> ช้อย A. excision and coagulation B. Imiquimod cream — เราเติมใน stem ว่าเป็น condyloma กว้างขวางทั้ง perianal และ intra-anal เพื่อให้เหลือคำตอบเดียว, ช้อย A เขียนเป็น Surgical excision and electrocoagulation, ช้อย C–E แต่งเพิ่ม","mnemonic":"<b>หูดนอกทวารเล็ก ๆ = ทายาเองได้; หูดในทวารหรือเยอะ = หมอจัดการ (ตัด + จี้ + ส่งชิ้นเนื้อ)</b>","guide":"CDC STI Treatment Guidelines 2021","variants":["ชายอายุ 25 ปี มีหูดหงอนไก่ 3 เม็ดขนาด 2–3 mm ที่ผิวหนังรอบทวารเท่านั้น ต้องการรักษาเองที่บ้าน → imiquimod cream สัปดาห์ละ 3 ครั้ง (หรือ podofilox)","ชาย MSM HIV-positive มีหูดหงอนไก่รอบทวาร ผลชิ้นเนื้อหลังตัดพบ HSIL ควรทำอะไรต่อ → ติดตามด้วย high-resolution anoscopy และรักษา HSIL","ผู้ป่วยมีก้อนหูดขนาดใหญ่ 8 cm ลุกลามกินเนื้อเยื่อรอบทวาร biopsy เป็น verrucous carcinoma → Buschke–Löwenstein tumor รักษาด้วย wide local excision"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ C มั่นใจสูงเมื่อมี external component ใหญ่ — ต้นฉบับอ้างถึงรูป mixed hemorrhoid ที่ไม่มีในไฟล์ จึงบรรยายใน stem; ถ้าเป็น internal hemorrhoid grade III ล้วน ASCRS 2018 ให้ลอง rubber band ligation (ช้อย A) ก่อนได้","page":17,"page2":7,"orig":"Anorectal 5","stem":"A patient has painless prolapsing hemorrhoids that must be pushed back with a finger after defecation. Examination shows combined internal hemorrhoids and a large external component. What is the most appropriate treatment?","gray":"ให้รูป mixed hemorrhoid มา โจทย์บอกว่าคนไข้ไม่เจ็บ มีก้อนยื่นออกมา ต้องเอานิ้วดันเข้าไป ถามว่าทำไรดี — A. Rubber band ligation B. Sclerosing injection C. Hemorrhoidectomy","opts":["Rubber band ligation","Sclerosing injection","Excisional hemorrhoidectomy","Topical steroid cream","Infrared coagulation"],"ans":2,"key":"C Hemorrhoidectomy (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: ต้นฉบับบอกว่า \"ให้รูป mixed hemorrhoid\" แต่ไฟล์ไม่มีรูป — บรรยายใน stem ว่ามีทั้ง internal ที่ต้องดันกลับ (grade III) และ external component ขนาดใหญ่; ถ้าเป็น internal grade III ล้วน RBL ก็ทำได้","interp":"ก้อนริดสีดวงที่<b>ยื่นออกมาและต้องใช้นิ้วดันกลับ</b> = internal hemorrhoid <b>Goligher grade III</b> ร่วมกับมี <b>external component ขนาดใหญ่</b> (mixed หรือ internal–external hemorrhoids) → ต้องเลือกการรักษาที่จัดการได้ทั้งส่วนเหนือและใต้ dentate line","why":"<b>Excisional hemorrhoidectomy</b> (Milligan–Morgan แบบเปิด หรือ Ferguson แบบปิด) ตัดทั้ง internal และ external component ออกพร้อมกัน จึงเป็นการรักษาที่เหมาะกับ <b>grade III ที่มี external component ใหญ่, grade IV, mixed hemorrhoids, thrombosed หรือ strangulated</b> และรายที่ล้มเหลวจาก office procedure; ได้ผลดีที่สุดและ recurrence ต่ำที่สุด แต่ปวดหลังผ่าตัดมากกว่า; office procedure ทั้งหลาย (rubber band ligation, sclerotherapy, infrared coagulation) ทำได้เฉพาะ<b>ส่วน internal เหนือ dentate line</b> (visceral innervation) — <b>ห้าม band หรือฉีดยาที่ external component</b> ใต้ dentate line เพราะมี somatic innervation จะเจ็บรุนแรง; stapled hemorrhoidopexy (PPH) ยก cushion กลับเข้าที่ได้แต่<b>ไม่แก้ external component</b>","wrong":{"A":"Rubber band ligation → เป็น office procedure ที่ได้ผลดีที่สุดสำหรับ internal hemorrhoid <b>grade I–II และ III บางราย</b> (รัดเหนือ dentate line ≥1–2 cm จนก้อนขาดเลือดหลุดใน 5–7 วัน) แต่แก้ external component ไม่ได้ และห้ามรัดส่วน external; จะถูกถ้าโจทย์เป็น internal hemorrhoid grade III ล้วน ไม่มี external component ใหญ่ หรือ grade II ที่เลือดออกไม่หยุดหลังใช้ fiber","B":"Sclerosing injection → ฉีด 5% phenol in almond oil หรือ sodium tetradecyl sulfate เข้า submucosa เหนือก้อน เหมาะกับ <b>grade I–II ที่มีเลือดออกเป็นหลัก</b> และผู้ที่กินยาต้านการแข็งตัวของเลือด; ใช้ไม่ได้กับก้อนยื่นมากหรือ external component; จะถูกถ้าโจทย์เป็น grade I เลือดออกซ้ำในผู้ป่วยที่กิน warfarin","D":"Topical steroid cream → ช่วยลดอาการคัน บวม ระคายเคืองชั่วคราว ไม่ทำให้ก้อนยุบหรือหาย และใช้นานทำให้ผิวบาง; จะถูกเพียงในแง่บรรเทาอาการร่วมกับ fiber ใน grade I ที่มีอาการเล็กน้อย","E":"Infrared coagulation → ใช้ความร้อนทำให้เกิด fibrosis ที่ฐานก้อน เหมาะกับ <b>grade I–II</b> ขนาดเล็ก recurrence สูงกว่า RBL; จะถูกถ้าโจทย์เป็น grade I–II ที่มีเลือดออกและต้องการหัตถการที่เจ็บน้อย"},"trap":"ดูแค่ grade III แล้วตอบ rubber band ligation — ต้องดูว่ามี external component ใหญ่หรือเป็น mixed หรือไม่ เพราะ office procedure รักษาได้เฉพาะส่วน internal; ส่วน external ต้องผ่าตัดตัดออก","summary":["Internal hemorrhoid (เหนือ dentate line) ไม่เจ็บ เลือดสด; external (ใต้ dentate line) เจ็บเมื่อ thrombosis; mixed = มีทั้งสองส่วน","Goligher: I เลือดออกไม่ยื่น, II ยื่นแล้วกลับเอง, III ต้องดันกลับ, IV ดันไม่กลับหรือยื่นตลอด","ทุก grade: fiber 25–35 g/วัน, น้ำ, หลีกเลี่ยงเบ่งและนั่งส้วมนาน; flavonoids และยาทาช่วยอาการชั่วคราว","Office procedure สำหรับ I–II และ III บางราย: rubber band ligation (ดีที่สุด), sclerotherapy, infrared coagulation; ห้ามทำใน external component; ระวัง RBL ในผู้กิน anticoagulant และภูมิคุ้มกันบกพร่อง (pelvic sepsis)","Excisional hemorrhoidectomy (Milligan–Morgan, Ferguson): grade III ที่มี external component ใหญ่, IV, mixed, strangulated, ล้มเหลวจาก office procedure; ภาวะแทรกซ้อน: ปวด, urinary retention, เลือดออก, anal stenosis, incontinence","ทางเลือกอื่น: stapled hemorrhoidopexy (ปวดน้อยกว่า recurrence สูงกว่า ไม่แก้ external), Doppler-guided hemorrhoidal artery ligation","Thrombosed external hemorrhoid มาภายใน 72 ชม. → excision; หลัง 72 ชม. → conservative","ดูข้อ 744 (painless rectal bleeding), 63"],"notes":"ไฟล์เฉลย บท anorectal แถว 5: <b>C</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับในไฟล์โจทย์เขียนว่า <b>\"ให้รูป mixed hemorrhoid มา\"</b> แต่ในไฟล์<b>ไม่มีรูป</b> — เราบรรยายเป็นข้อความใน stem แทน (มีทั้ง internal ที่ต้องดันกลับและ external component ขนาดใหญ่) โดยไม่ใช้คำว่า mixed hemorrhoid ตรง ๆ; โจทย์ต้นฉบับ: \"คนไข้ไม่เจ็บ มีก้อนยื่นออกมา ต้องเอานิ้วดันเข้าไป ถามว่าทำไรดี\"<br>ช้อยต้นฉบับ A. Rubber band ligation B. Sclerosing injection C. Hemorrhoidectomy (เราเขียน C เป็น Excisional hemorrhoidectomy); ช้อย D, E แต่งเพิ่ม","mnemonic":"<b>\"ข้างในใช้ยางรัด ข้างนอกต้องผ่า\"</b> — office procedure เหนือ dentate line เท่านั้น","guide":"ASCRS hemorrhoids 2018","variants":["ผู้ป่วยมีเลือดสดหยดหลังถ่าย ก้อนริดสีดวงยื่นออกมาขณะเบ่งแล้วกลับเข้าไปเอง ไม่มี external component การรักษาที่เหมาะสมหลังปรับ fiber แล้วไม่ดีขึ้น → rubber band ligation","ผู้ป่วยมีก้อนริดสีดวงยื่นออกมาดันไม่กลับ บวมคล้ำ ปวดมาก มีเนื้อตายบางส่วน → strangulated grade IV hemorrhoid → emergency excisional hemorrhoidectomy","หลัง hemorrhoidectomy 6 ชม. ผู้ป่วยปัสสาวะไม่ออก ท้องน้อยโป่งตึง ภาวะแทรกซ้อนที่พบบ่อยนี้คือ → urinary retention ใส่สายสวนปัสสาวะ"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง — สาเหตุส่วนใหญ่ของ fistula-in-ano คือ cryptoglandular infection; แนวเดียวกับข้อสอบชุด 76A เรื่อง perianal abscess","page":17,"page2":7,"orig":"Anorectal 6","stem":"A patient has an external opening near the anus. A probe passed through the opening enters the anal canal near the anal verge, and a fibrous tract is palpable. What is the most likely cause of this condition?","gray":"เจอรูที่ก้น เอา probe เสียบเข้าไป เข้าไปที่ anal verge พร้อมทั้งคลำได้ fibrous tract ถามว่าเกิดจากอะไร — A. Infection of Anal gland","opts":["Infection of the anal glands","Crohn disease","Tuberculosis","Trauma from hard stool","Radiation proctitis"],"ans":0,"key":"A Infection of Anal gland (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"มี<b>รูเปิดภายนอกที่ผิวหนังข้างทวาร</b> ใส่ probe แล้วทะลุเข้า anal canal และคลำได้แนว<b>ท่อเป็นพังผืด (fibrous tract)</b> ระหว่างรูภายนอกกับทวาร = มีทางเชื่อมผิดปกติระหว่าง anal canal กับผิวหนังรอบทวาร → ถามสาเหตุที่พบบ่อยที่สุดของภาวะนี้ (ต้องตีความโรคเอง)","why":"ภาวะนี้คือ fistula-in-ano ซึ่ง ~90% เกิดตาม <b>cryptoglandular theory (Parks)</b>: <b>anal gland</b> 4–10 ต่อมที่ทอดอยู่ใน intersphincteric plane และเปิดเข้า anal crypt ที่ระดับ dentate line เกิดอุดตันและ<b>ติดเชื้อ</b> → เกิด intersphincteric abscess ที่ลามไปตามช่องต่าง ๆ (perianal, ischiorectal, intersphincteric, supralevator) → เมื่อฝีแตกหรือถูกระบายออก ราว 30–50% เหลือทางเชื่อมเป็น <b>fistula</b> โดยรูภายในอยู่ที่ crypt ระดับ dentate line; แบ่งตาม <b>Parks classification</b>: intersphincteric (พบบ่อยที่สุด ~45–70%), transsphincteric (~25–30%), suprasphincteric (~5%), extrasphincteric (~1–5%); ทำนายตำแหน่งรูภายในด้วย <b>Goodsall rule</b>","wrong":{"B":"Crohn disease → เป็นสาเหตุ secondary ที่สำคัญ (perianal Crohn พบ 20–40% ของผู้ป่วย Crohn) ลักษณะ fistula <b>ซับซ้อน หลายรู</b> ร่วมกับ fissure นอก midline, skin tag บวมม่วง, anal stenosis และอาการลำไส้ (ท้องเสียเรื้อรัง น้ำหนักลด); จะถูกถ้าโจทย์เป็นชายอายุ 22 ปี ท้องเสียเรื้อรัง มี fistula หลายรูรอบทวาร","C":"Tuberculosis → fistula จาก TB พบน้อย (มากกว่าในประเทศที่ระบาดเช่นไทย) มักเป็นซ้ำหลังผ่าตัด ขอบแผลบางกระดำกระด่าง หนองใส มี TB ปอดร่วม; จะถูกถ้าโจทย์เป็น fistula ที่เป็นซ้ำหลายครั้งหลังผ่าตัด ชิ้นเนื้อพบ caseating granuloma","D":"Trauma from hard stool → อุจจาระแข็งทำให้เกิด <b>anal fissure</b> (แผลฉีกตามยาวของ anoderm) ไม่ใช่ทางเชื่อมที่มีรูภายนอก; จะถูกถ้าโจทย์ถามสาเหตุของแผลที่ posterior midline ที่เจ็บมากขณะถ่าย","E":"Radiation proctitis → ฉายรังสีบริเวณเชิงกราน (มะเร็งปากมดลูก ต่อมลูกหมาก) อาจทำให้เกิด fistula ได้ แต่มักเป็น <b>rectovaginal หรือ rectovesical fistula</b> และมีประวัติฉายรังสีชัดเจน; จะถูกถ้าโจทย์เป็นหญิงหลังฉายรังสีรักษามะเร็งปากมดลูกมีอุจจาระออกทางช่องคลอด"},"trap":"เลือก Crohn หรือ TB เพราะนึกถึงสาเหตุที่จำได้ — คำถามถามสาเหตุที่พบบ่อยที่สุด ซึ่งคือการติดเชื้อของ anal gland (cryptoglandular) ~90%; สาเหตุ secondary ต้องมีลักษณะชี้นำเพิ่ม เช่น หลายรู เป็นซ้ำ หรืออาการลำไส้","summary":["Cryptoglandular theory: anal gland ใน intersphincteric plane ติดเชื้อ → anorectal abscess → fistula-in-ano (~90%); รูภายในอยู่ที่ dentate line","ฝี: perianal (พบบ่อยสุด), ischiorectal, intersphincteric, supralevator, horseshoe (ผ่าน deep postanal space) → รักษาด้วย incision and drainage; antibiotic เพิ่มเมื่อมี cellulitis, sepsis, ภูมิคุ้มกันบกพร่อง, ลิ้นหัวใจเทียม","Parks classification: intersphincteric ~45–70%, transsphincteric ~25–30%, suprasphincteric ~5%, extrasphincteric ~1–5%","Goodsall rule: รูภายนอกอยู่หลังเส้นแนวขวาง → ทางโค้งไปเปิดที่ posterior midline; อยู่หน้าเส้น → ทางตรงแนวรัศมี (ยกเว้นรูหน้าที่ห่างขอบทวาร &gt;3 cm อาจโค้งไป posterior midline)","Imaging สำหรับ complex fistula: MRI pelvis หรือ endoanal US; EUA หา internal opening","Simple fistula (intersphincteric, low transsphincteric) → fistulotomy; complex (กล้ามเนื้อหูรูดมาก, anterior ในผู้หญิง, Crohn, เป็นซ้ำ) → draining seton, LIFT, endorectal advancement flap เพื่อรักษาหูรูด","Secondary causes: Crohn disease, TB, มะเร็ง, radiation, trauma, foreign body, HIV, actinomycosis","ดูข้อ 743 (anal fissure), 64, 67"],"notes":"ไฟล์เฉลย บท anorectal แถว 6: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับในไฟล์โจทย์: \"เจอรูที่ก้น เอา probe เสียบเข้าไป เข้าไปที่ anal verge พร้อมทั้งคลำได้ fibrous tract ถามว่าเกิดจากอะไร\" มีช้อยเดียว A. Infection of Anal gland — ช้อย B–E แต่งเพิ่ม; ไม่ใช้คำว่า fistula ใน stem","mnemonic":"<b>Goodsall: \"หน้าตรง หลังโค้ง\"</b> — รูหน้าทวารวิ่งตรงเข้า รูหลังทวารโค้งไป posterior midline","guide":"ASCRS anorectal abscess, fistula-in-ano and rectovaginal fistula 2022","variants":["ชายอายุ 40 ปี ปวดก้นตุบ ๆ 3 วัน มีไข้ คลำได้ก้อนบวมแดงร้อน fluctuation ข้างทวาร การรักษา → incision and drainage","ผู้ป่วยมีรูเปิดภายนอกที่ตำแหน่ง 5 นาฬิกา ห่างขอบทวาร 2 cm ตามกฎ Goodsall รูภายในน่าจะอยู่ที่ใด → posterior midline (6 นาฬิกา)","ผู้ป่วย fistula-in-ano ตรวจ EUA พบเป็น high transsphincteric ผ่านกล้ามเนื้อหูรูดภายนอกมากกว่าครึ่ง การรักษาที่เหมาะสม → draining seton หรือ LIFT procedure (เลี่ยง fistulotomy เพราะเสี่ยง incontinence)"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ B มั่นใจสูง — ในช้อยมีการผ่าตัดเพียงช้อยเดียว; ในทางปฏิบัติ lobectomy ก็เป็นทางเลือกได้ในก้อน 1–4 cm ความเสี่ยงต่ำ แต่ไม่อยู่ในช้อย; สอดคล้องกับข้อสอบชุด 77B (AUS ซ้ำแล้วเป็น suspicious → total thyroidectomy) และ 76C (follicular neoplasm → lobectomy)","page":17,"page2":7,"orig":"Thyroid 1","stem":"Fine-needle aspiration of a thyroid nodule is reported as Bethesda category V, suspicious for malignancy. What is the most appropriate next step?","gray":"Suspected Malignancy Bethesda V ถามว่าทำไรต่อดี — A. F/U B. Total thyroidectomy C. FNA","opts":["Follow-up ultrasound","Total thyroidectomy","Repeat FNA","Radioactive iodine ablation","Levothyroxine suppression therapy"],"ans":1,"key":"B Total thyroidectomy (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ผล FNA ก้อนไทรอยด์เป็น <b>Bethesda V (suspicious for malignancy)</b> ซึ่งมีความเสี่ยงเป็นมะเร็งสูง → ถามขั้นต่อไป ต้องรู้ว่ากลุ่ม V และ VI จัดการด้วยการผ่าตัด ไม่ใช่เจาะซ้ำหรือติดตาม","why":"Bethesda V มี <b>risk of malignancy ~74%</b> (ส่วนใหญ่เป็น papillary thyroid carcinoma) ใกล้เคียง Bethesda VI (~97%) จึงต้อง<b>ผ่าตัด</b>เพื่อวินิจฉัยและรักษา; ในช้อยที่ให้มา <b>total thyroidectomy</b> เป็นคำตอบเดียวที่เป็นการผ่าตัด; ตาม ATA 2015 ขอบเขตการผ่าตัดใน Bethesda V–VI: <b>total thyroidectomy</b> เมื่อก้อน &gt;4 cm, มี extrathyroidal extension, nodal หรือ distant metastasis, ก้อนทั้งสองข้าง, ประวัติฉายรังสีที่คอ, ประวัติครอบครัวมะเร็งไทรอยด์ หรือต้องการให้ RAI ต่อ; ส่วน <b>lobectomy</b> เลือกได้ในก้อนข้างเดียวขนาด 1–4 cm ไม่มีปัจจัยเสี่ยงข้างต้น (lobectomy ไม่อยู่ในช้อยของข้อนี้); molecular testing อาจช่วยเลือกขอบเขตการผ่าตัด","wrong":{"A":"Follow-up ultrasound → ใช้กับ <b>Bethesda II (benign)</b> ROM ~4% ติดตาม US ตามความเสี่ยงจากลักษณะ US (high suspicion ซ้ำใน 12–24 เดือน); การติดตามใน Bethesda V ปล่อยมะเร็งไว้โดยไม่รักษา; จะถูกถ้าโจทย์เป็น FNA ผล benign follicular nodule","C":"Repeat FNA → ใช้กับ <b>Bethesda I (nondiagnostic)</b> และ <b>Bethesda III (AUS)</b> (repeat FNA หรือ molecular testing); ใน Bethesda V การเจาะซ้ำไม่เปลี่ยนการจัดการเพราะความเสี่ยงสูงพอที่จะผ่าตัดอยู่แล้ว; จะถูกถ้าโจทย์เป็น FNA ผลเลือดปนไม่พอวินิจฉัย","D":"Radioactive iodine ablation → ให้<b>หลัง total thyroidectomy</b> ใน differentiated thyroid cancer ที่ความเสี่ยงปานกลางถึงสูง (remnant ablation หรือ adjuvant) หรือใช้รักษา hyperthyroidism; ไม่ใช่การรักษาก้อนก่อนผ่าตัด; จะถูกถ้าโจทย์เป็นหลัง total thyroidectomy ของ PTC ที่มี node metastasis หลายต่อม","E":"Levothyroxine suppression therapy → TSH suppression ใช้<b>หลังผ่าตัด</b>มะเร็งไทรอยด์ในกลุ่มเสี่ยงสูง; การกดก้อน benign ด้วย levothyroxine ไม่แนะนำแล้วเพราะได้ผลน้อยและเสี่ยง AF และกระดูกพรุน; จะถูกถ้าโจทย์ถามการดูแลหลัง total thyroidectomy ของมะเร็งความเสี่ยงสูง"},"trap":"เลือก repeat FNA เพราะคิดว่ายังไม่ใช่มะเร็งแน่นอน — Bethesda V มีความเสี่ยงมะเร็งราวสามในสี่ ต้องผ่าตัด; การเจาะซ้ำเป็นของ Bethesda I และ III","summary":["Bethesda 3rd ed. 2023 (ROM โดยประมาณ): I nondiagnostic ~13% → repeat FNA ภายใต้ US; II benign ~4% → ติดตาม US","III AUS ~22% → repeat FNA หรือ molecular testing หรือ diagnostic lobectomy หรือติดตาม","IV follicular neoplasm ~30% → molecular testing หรือ diagnostic lobectomy (แยก follicular carcinoma ต้องดู capsular/vascular invasion ในชิ้นเนื้อ)","V suspicious for malignancy ~74%, VI malignant ~97% → ผ่าตัด","ATA 2015: lobectomy ได้ในมะเร็งข้างเดียว 1–4 cm ไม่มี ETE ไม่มี node; total thyroidectomy เมื่อ &gt;4 cm, ETE (gross), cN1, M1, ก้อนสองข้าง, ประวัติฉายรังสี หรือประวัติครอบครัว; microcarcinoma &lt;1 cm ความเสี่ยงต่ำ active surveillance ได้","หลัง total thyroidectomy: ประเมิน ATA risk → RAI ตามความเสี่ยง, TSH suppression ตามความเสี่ยง, ติดตาม thyroglobulin และ US คอ","ดูข้อ 750 (US features ของก้อนไทรอยด์), 71, 72"],"notes":"ไฟล์เฉลย บท thyroid แถว 1: <b>B</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับในไฟล์โจทย์: A. F/U B. Total thyroidectomy C. FNA — เราเขียน A เป็น Follow-up ultrasound และ C เป็น Repeat FNA; ช้อย D, E แต่งเพิ่ม","mnemonic":"<b>Bethesda \"1 เจาะซ้ำ, 2 นัดดู, 3 เจาะซ้ำหรือ molecular, 4 lobectomy, 5–6 ผ่า\"</b>","guide":"ATA 2015; Bethesda System 3rd ed. 2023","variants":["หญิงอายุ 40 ปี ก้อนไทรอยด์ 2 cm FNA เป็น Bethesda IV (follicular neoplasm) ไม่มีต่อมน้ำเหลืองโต ควรทำอะไร → diagnostic lobectomy (หรือ molecular testing ก่อน)","หญิงอายุ 35 ปี ก้อนไทรอยด์ 1.5 cm FNA ได้เลือดปนเซลล์ไม่พอวินิจฉัย ควรทำอะไร → repeat FNA ภายใต้ US (Bethesda I)","ชายอายุ 50 ปี FNA เป็น papillary thyroid carcinoma ขนาด 5 cm ร่วมกับ lateral neck node ยืนยันด้วย FNA การผ่าตัด → total thyroidectomy + central และ lateral neck dissection"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ C มั่นใจสูง — lobulated margin ก็เป็น suspicious feature แต่คำถามคือ most suspicious ซึ่ง microcalcification มีคะแนนและความจำเพาะสูงกว่า","page":17,"page2":7,"orig":"Thyroid 2","stem":"Which ultrasound feature of a thyroid nodule is most suspicious for malignancy?","gray":"U/S lesion แบบไหน กลัวเป็นมะเร็ง — A. Spongiform B. Lobulated C. Microcalcification","opts":["Spongiform composition","Lobulated margin","Microcalcifications","Purely cystic nodule","Comet-tail artifacts"],"ans":2,"key":"C Microcalcification (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: lobulated margin (ช้อย B) ก็เป็น suspicious feature (ACR TI-RADS 2 คะแนน, ATA: irregular/microlobulated margin) — stem ถาม \"most suspicious\"; microcalcification (punctate echogenic foci) 3 คะแนนและจำเพาะต่อ PTC สูงกว่า","interp":"ถามลักษณะ US ของก้อนไทรอยด์ที่<b>บ่งชี้มะเร็งมากที่สุด</b> — ต้องรู้ว่า feature ไหนเป็น benign, ไหน suspicious และไหนมีน้ำหนักสูงสุดตาม ACR TI-RADS","why":"<b>Microcalcifications</b> (punctate echogenic foci จุดสะท้อนเสียงขนาดเล็ก &lt;1 mm ไม่มีเงา) สัมพันธ์กับ <b>psammoma bodies</b> ใน papillary thyroid carcinoma มี<b>ความจำเพาะต่อมะเร็งสูง</b> (specificity ราว 85–95%) และใน ACR TI-RADS ให้ <b>3 คะแนน</b> ซึ่งสูงสุดในหมวด echogenic foci; ลักษณะ high suspicion อื่นตาม ATA 2015: solid hypoechoic ร่วมกับ irregular (infiltrative หรือ microlobulated) margin, taller-than-wide, rim calcification ที่มี soft tissue ยื่นออก, extrathyroidal extension; lobulated margin ก็เป็นลักษณะ suspicious (TI-RADS 2 คะแนน) แต่มีน้ำหนักและความจำเพาะต่ำกว่า microcalcification","wrong":{"A":"Spongiform composition → ก้อนที่มี microcystic space เล็ก ๆ จำนวนมากเกิน 50% ของปริมาตรคล้ายฟองน้ำ เป็นลักษณะ <b>benign</b> (TI-RADS 0 คะแนน จัดเป็น TR1 ไม่ต้อง FNA; ATA very low suspicion ROM &lt;3% พิจารณา FNA เฉพาะเมื่อ ≥2 cm หรือติดตามได้); จะถูกถ้าโจทย์ถาม US feature ที่บ่งชี้ว่าเป็นก้อน benign","B":"Lobulated margin → เป็นลักษณะ suspicious ได้จริง (TI-RADS: lobulated หรือ irregular margin 2 คะแนน, ATA: microlobulated margin อยู่ใน high suspicion pattern) แต่ความจำเพาะต่อมะเร็งต่ำกว่าและคะแนนน้อยกว่า microcalcification; จะถูกถ้าโจทย์ถามว่าลักษณะขอบแบบใดน่าสงสัยมะเร็ง (เทียบกับขอบเรียบ)","D":"Purely cystic nodule → ก้อนน้ำล้วน (anechoic) เป็น <b>benign</b> ROM &lt;1% ไม่ต้อง FNA เพื่อวินิจฉัย (อาจเจาะดูดเพื่อบรรเทาอาการ); จะถูกถ้าโจทย์ถามก้อนที่ไม่ต้อง FNA","E":"Comet-tail artifacts → เกิดจาก<b>ผลึก colloid</b> ใน colloid nodule เป็นลักษณะ <b>benign</b> (large comet-tail 0 คะแนน) ต้องแยกจาก microcalcification ซึ่งไม่มีหางเงา; จะถูกถ้าโจทย์ถามลักษณะของ colloid nodule"},"trap":"สับสน comet-tail artifact (benign, ผลึก colloid) กับ microcalcification (malignant, psammoma) เพราะเป็นจุดสว่างเหมือนกัน — comet-tail มีหางสะท้อนเป็นรูปตัว V; และเลือก lobulated เพราะคิดว่าขอบไม่เรียบเสี่ยงเท่ากัน","summary":["ACR TI-RADS composition: cystic หรือ spongiform 0, mixed cystic-solid 1, solid 2","Echogenicity: anechoic 0, hyper หรือ isoechoic 1, hypoechoic 2, very hypoechoic 3","Shape: wider-than-tall 0, taller-than-wide 3; Margin: smooth หรือ ill-defined 0, lobulated หรือ irregular 2, extrathyroidal extension 3","Echogenic foci: none หรือ large comet-tail 0, macrocalcification 1, peripheral (rim) 2, punctate (microcalcification) 3","TR1 0 คะแนน, TR2 2, TR3 3, TR4 4–6, TR5 ≥7; FNA: TR3 ≥2.5 cm, TR4 ≥1.5 cm, TR5 ≥1 cm (ติดตามเมื่อ TR3 ≥1.5, TR4 ≥1, TR5 ≥0.5 cm)","ATA 2015 high suspicion (ROM 70–90%): solid hypoechoic ร่วมกับ irregular margin, microcalcification, taller-than-wide, rim calcification ที่มี soft tissue ยื่น หรือ ETE → FNA ≥1 cm","Benign patterns: purely cystic, spongiform, comet-tail artifact ของ colloid","ดูข้อ 749 (การจัดการตามผล Bethesda), 71, 72"],"notes":"ไฟล์เฉลย บท thyroid แถว 2: <b>C</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับในไฟล์โจทย์: \"U/S lesion แบบไหน กลัวเป็นมะเร็ง\" ช้อย A. Spongiform B. Lobulated C. Microcalcification — เราเติมคำให้ครบ (Spongiform composition, Lobulated margin, Microcalcifications) ไม่เปลี่ยนความหมาย; ช้อย D, E แต่งเพิ่ม","mnemonic":"<b>จุดสว่างไม่มีหาง = psammoma (มะเร็ง); จุดสว่างมีหางตัว V = colloid (benign)</b>","guide":"ACR TI-RADS 2017; ATA 2015","variants":["ก้อนไทรอยด์ 1.2 cm solid, very hypoechoic, taller-than-wide, มี punctate echogenic foci คิดคะแนน TI-RADS และการจัดการ → 2+3+3+0+3 = 11 คะแนน TR5 → FNA (≥1 cm)","ก้อนไทรอยด์ 1.8 cm spongiform ทั้งก้อน ควรทำอะไร → benign (TR1) ไม่ต้อง FNA","ก้อนไทรอยด์ cystic มีจุดสว่างที่มีหางรูปตัว V หลายจุด สิ่งนี้คืออะไร → comet-tail artifact จาก colloid crystal บ่ง benign colloid nodule"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"คีย์เขียน <b>A/B/C</b> คือยอมรับทุกสาเหตุของ primary hyperparathyroidism ซึ่งถูกในแง่ว่าทั้งสามทำให้ Ca สูง PO₄ ต่ำ PTH สูงได้ — แต่ข้อสอบ MCQ ต้องเลือกคำตอบเดียว เราตอบ <b>A (adenoma)</b> เพราะเป็นสาเหตุที่พบบ่อยที่สุด 80–85% และโจทย์ไม่มีลักษณะชี้นำ carcinoma หรือ hyperplasia; ความมั่นใจสูง; ถ้าโจทย์ให้ Ca &gt;14 mg/dL, PTH สูงมาก และคลำได้ก้อนแข็งที่คอ ให้ตอบ B; ถ้ามี MEN1/MEN2A, lithium หรือหลายต่อม ให้ตอบ C; สอดคล้องกับข้อสอบชุด 77C และ 77D (PHPT → adenoma หรือ primary HPT)","page":17,"page2":7,"orig":"Thyroid 3","stem":"A patient without chronic kidney disease has high serum calcium, low phosphate, high PTH and osteoporosis. What is the most likely cause?","gray":"คนไข้ไม่ได้เป็น CKD มี Ca สูง PO ต่ำ PTH สูง กระดูกพรุน ถามว่าเป็นไร — A. Parathyroid adenoma B. Parathyroid carcinoma C. Parathyroid hyperplasia D. Secondary hyperparathyroidism","opts":["Parathyroid adenoma","Parathyroid carcinoma","Parathyroid hyperplasia","Secondary hyperparathyroidism","Humoral hypercalcemia of malignancy"],"ans":0,"key":"A — คีย์เขียน A/B/C (Parathyroid adenoma, Parathyroid carcinoma, Parathyroid hyperplasia) (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ คีย์ให้ 3 ช้อย (ทุกสาเหตุของ primary hyperparathyroidism) — เราตอบ adenoma เพราะพบบ่อยที่สุด 80–85%; ถ้าโจทย์ให้ Ca &gt;14 mg/dL, PTH สูงมาก และคลำได้ก้อนแข็งที่คอ ตอบ carcinoma; ถ้า MEN1/MEN2A หรือ lithium หรือหลายต่อม ตอบ hyperplasia","interp":"<b>Ca สูง + PO₄ ต่ำ + PTH สูง</b> (PTH ไม่ถูกกดทั้งที่ Ca สูง) ในผู้ที่<b>ไม่มี CKD</b> ร่วมกับกระดูกพรุน = <b>primary hyperparathyroidism (PHPT)</b> → คำถามคือพยาธิสภาพของต่อมพาราไทรอยด์ที่เป็นสาเหตุ<b>บ่อยที่สุด</b>","why":"PHPT เกิดจากต่อมพาราไทรอยด์หลั่ง PTH เกินโดยอิสระ → เพิ่ม bone resorption, เพิ่ม Ca reabsorption และขับ PO₄ ที่ไต, เพิ่มการสร้าง 1,25(OH)₂D → <b>Ca สูง PO₄ ต่ำ PTH สูงหรือปกติค่อนสูง</b>; สาเหตุตามความถี่: <b>single parathyroid adenoma 80–85%</b>, four-gland hyperplasia 10–15% (สัมพันธ์กับ MEN1, MEN2A, lithium), double adenoma 2–5%, <b>parathyroid carcinoma &lt;1%</b>; คีย์ให้ A/B/C เพราะทั้งสามเป็น PHPT ได้ แต่โจทย์ไม่มีลักษณะเฉพาะของ carcinoma (Ca &gt;14 mg/dL, PTH สูงมาก 5–10 เท่า, ก้อนคลำได้ที่คอ, โรคกระดูกและไตรุนแรงพร้อมกัน) หรือ hyperplasia (กลุ่มอาการทางพันธุกรรม, lithium) จึงตอบ<b>สาเหตุที่พบบ่อยที่สุดคือ adenoma</b>; กระดูกพรุน (T-score ≤−2.5) เป็นข้อบ่งชี้ parathyroidectomy","wrong":{"B":"Parathyroid carcinoma → เป็นสาเหตุ PHPT ได้จริง (คีย์ให้ด้วย) แต่พบ<b>น้อยกว่า 1%</b>; นึกถึงเมื่อ <b>Ca &gt;14 mg/dL, PTH สูงมาก</b>, คลำได้ก้อนแข็งที่คอ, มีทั้ง bone disease (osteitis fibrosa cystica) และ renal disease พร้อมกัน หรือ hoarseness จาก RLN ถูกลุกลาม → en bloc resection รวม ipsilateral thyroid lobe; จะถูกถ้าโจทย์ให้ Ca 15 mg/dL กับก้อนแข็งติดแน่นที่คอ","C":"Parathyroid hyperplasia → เป็นสาเหตุ PHPT ได้ (คีย์ให้ด้วย) พบ 10–15% เป็นทั้งสี่ต่อม; นึกถึงเมื่อ<b>มี MEN1 (pituitary, pancreatic NET), MEN2A (MTC, pheochromocytoma), familial hyperparathyroidism หรือใช้ lithium</b> → subtotal (3½ gland) parathyroidectomy หรือ total + autotransplantation; จะถูกถ้าโจทย์มีประวัติ gastrinoma หรือ prolactinoma ร่วมด้วย","D":"Secondary hyperparathyroidism → PTH สูงจากการตอบสนองต่อ Ca ต่ำ ดังนั้น <b>Ca ต่ำหรือปกติ</b> ไม่ใช่สูง; สาเหตุ CKD (PO₄ สูง, 1,25(OH)₂D ต่ำ) หรือ vitamin D deficiency/malabsorption (PO₄ ต่ำ); โจทย์ระบุว่าไม่มี CKD และ Ca สูง จึงตัดไป; จะถูกถ้าโจทย์เป็นผู้ป่วย CKD stage 5 Ca 8.5, PO₄ 7, PTH 600","E":"Humoral hypercalcemia of malignancy → มะเร็งหลั่ง <b>PTHrP</b> (squamous cell carcinoma ของปอด ศีรษะและคอ, renal cell carcinoma) ทำให้ Ca สูง PO₄ ต่ำ แต่ <b>PTH ถูกกดต่ำ</b>; จะถูกถ้าโจทย์เป็นผู้สูบบุหรี่จัด มีก้อนในปอด Ca 14 mg/dL และ PTH ต่ำ"},"trap":"ตอบ secondary hyperparathyroidism เพราะเห็น PTH สูง — ต้องดู Ca ร่วมด้วยเสมอ: PTH สูง + Ca สูง = primary (หรือ tertiary ใน CKD); PTH สูง + Ca ต่ำหรือปกติ = secondary; Ca สูง + PTH ต่ำ = non-PTH mediated (มะเร็ง, vitamin D, granuloma)","summary":["PHPT: Ca สูง, PO₄ ต่ำหรือปกติต่ำ, PTH สูงหรือปกติค่อนสูง (ไม่ถูกกด), urine Ca ปกติหรือสูง (แยกจาก FHH ที่ urine Ca/Cr clearance ratio &lt;0.01)","สาเหตุ: single adenoma 80–85%, hyperplasia 10–15% (MEN1, MEN2A, lithium), double adenoma 2–5%, carcinoma &lt;1% (Ca &gt;14, PTH สูงมาก, ก้อนคลำได้)","อาการ: ส่วนใหญ่ไม่มีอาการ (ตรวจพบ Ca สูงโดยบังเอิญ); \"stones, bones, groans, moans\" = นิ่วไต, osteoporosis/osteitis fibrosa cystica, ปวดท้องหรือ pancreatitis หรือ peptic ulcer, อาการทางจิตประสาท","ข้อบ่งชี้ผ่าตัด (Fifth International Workshop 2022): ทุกรายที่มีอาการ; asymptomatic เมื่อ Ca &gt;1 mg/dL เหนือ ULN, BMD T-score ≤−2.5 หรือ vertebral fracture, eGFR &lt;60, urine Ca &gt;250 mg/วัน (หญิง) หรือ &gt;300 (ชาย) หรือนิ่ว/nephrocalcinosis, อายุ &lt;50 ปี","Localization (หลังวินิจฉัยทางชีวเคมีแล้ว เพื่อวางแผนผ่าตัด): US คอ, sestamibi SPECT-CT, 4D-CT หรือ F-choline PET","Minimally invasive parathyroidectomy เมื่อ localize ได้ต่อมเดียว + intraoperative PTH ลด &gt;50% ใน 10 นาที (Miami criterion); localize ไม่ได้หรือสงสัยหลายต่อม → bilateral neck exploration","หลังผ่าตัดระวัง hungry bone syndrome (Ca, PO₄, Mg ต่ำ) โดยเฉพาะ PTH สูงมากและ bone disease รุนแรง","ดูข้อ 749, 750, 752 (บท thyroid and parathyroid)"],"notes":"ไฟล์เฉลย บท thyroid แถว 3: <b>A/B/C</b> (ช่องคำอธิบายว่าง) — คีย์ให้ 3 ช้อยพร้อมกัน<br>ต้นฉบับในไฟล์โจทย์: A. Parathyroid adenoma B. Parathyroid carcinoma C. Parathyroid hyperplasia D. Secondary hyperparathyroidism (ช้อยครบ 4 ตัวตามนี้); ช้อย E (Humoral hypercalcemia of malignancy) แต่งเพิ่ม; ต้นฉบับเขียน \"PO ต่ำ\" หมายถึง phosphate ต่ำ","mnemonic":"<b>\"PTH กับ Ca ไปทางเดียวกัน (สูงทั้งคู่) = primary; สวนทางกัน = secondary\"</b>; สาเหตุ PHPT \"85-15-1\" (adenoma, hyperplasia, carcinoma)","guide":"Fifth International Workshop PHPT 2022","variants":["หญิงอายุ 60 ปี Ca 11.8 mg/dL, PTH สูง, eGFR 75, BMD T-score −2.8 ที่ radius ไม่มีอาการ ควรทำอะไร → parathyroidectomy (osteoporosis เป็นข้อบ่งชี้) หลัง localize ด้วย sestamibi หรือ US","ชายอายุ 35 ปี Ca สูง PTH สูง มีประวัติ prolactinoma และ gastrinoma พยาธิสภาพพาราไทรอยด์ที่น่าจะเป็น → four-gland hyperplasia (MEN1) → subtotal parathyroidectomy","ผู้ป่วย CKD stage 5 on dialysis Ca 8.2, PO₄ 6.8, PTH 800 pg/mL ภาวะนี้คือ → secondary hyperparathyroidism (รักษาด้วย phosphate binder, active vitamin D, cinacalcet)"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูงเมื่อแต่งเคสแล้ว — ต้นฉบับมีแค่ \"lid lag — grave\" จึงแต่งเคสให้เป็น thyrotoxicosis ร่วม diffuse goiter ในหญิงอายุน้อยซึ่ง Graves เป็นสาเหตุบ่อยที่สุด; ควรรู้ว่า lid lag ไม่จำเพาะต่อ Graves; สอดคล้องกับข้อสอบชุด 76D, 77C และ 77D (Graves)","page":18,"page2":7,"orig":"Thyroid 4","stem":"A 30-year-old woman has palpitations, heat intolerance, weight loss and a diffuse goiter. On examination, lid lag is present. What is the most likely diagnosis?","gray":"lid lag — grave (ต้นฉบับมีแค่สองคำนี้ ไม่มีตัวอักษรช้อย)","opts":["Graves disease","Hashimoto thyroiditis with hypothyroidism","Horner syndrome","Myasthenia gravis","Papillary thyroid carcinoma"],"ans":0,"key":"A grave (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: ต้นฉบับจดแค่ \"lid lag — grave\" — แต่งเคสสั้น ๆ (thyrotoxicosis + diffuse goiter + lid lag) และแต่งช้อยทั้งหมด","interp":"หญิงอายุน้อยมีอาการ <b>thyrotoxicosis</b> (ใจสั่น ทนร้อนไม่ได้ น้ำหนักลด) ร่วมกับ <b>diffuse goiter</b> และตรวจพบ <b>lid lag</b> (หนังตาบนเลื่อนตามลูกตาไม่ทันเมื่อมองลงล่าง) → ต้องรู้ว่าอาการทางตาชนิดนี้มาจากอะไร และสาเหตุของ thyrotoxicosis ที่มี diffuse goiter ในหญิงวัยนี้ที่พบบ่อยที่สุด","why":"<b>Lid lag (von Graefe sign)</b> และ lid retraction (Dalrymple sign) เกิดจาก<b>sympathetic overactivity</b> ทำให้ <b>Müller muscle</b> (superior tarsal muscle) หดตัวมาก → พบได้ใน<b>thyrotoxicosis ทุกสาเหตุ</b> และหายเมื่อคุมไทรอยด์ได้; เมื่อร่วมกับ thyrotoxicosis + <b>diffuse goiter</b> ในหญิงอายุ 20–40 ปี สาเหตุที่พบบ่อยที่สุดคือ <b>Graves disease</b> (autoimmune จาก TSH receptor antibody, TRAb, กระตุ้นต่อมให้โตทั่วทั้งต่อมและสร้างฮอร์โมนเกิน); ลักษณะที่จำเพาะต่อ Graves คือ <b>orbitopathy</b> (proptosis, periorbital edema, chemosis, ophthalmoplegia จาก inflammation ของ orbital fibroblast), pretibial myxedema, thyroid acropachy และ bruit เหนือต่อม; ยืนยันด้วย TSH ต่ำ free T4/T3 สูง + TRAb บวก หรือ radioiodine uptake สูงกระจายทั่ว","wrong":{"B":"Hashimoto thyroiditis with hypothyroidism → มี goiter ได้แต่เป็น<b>ภาวะไทรอยด์ต่ำ</b> (ขี้หนาว น้ำหนักขึ้น ท้องผูก ผิวแห้ง bradycardia) ไม่มี lid lag; ระยะแรกอาจมี hashitoxicosis ชั่วคราวได้แต่พบน้อย; จะถูกถ้าโจทย์เป็นหญิงวัยกลางคน ขี้หนาว น้ำหนักขึ้น ต่อมโตแข็งเป็นปุ่ม anti-TPO สูง TSH สูง","C":"Horner syndrome → sympathetic pathway ถูกตัด ทำให้ <b>ptosis</b> (Müller muscle อ่อนแรง) + miosis + anhidrosis = ตรงข้ามกับ lid lag/retraction; จะถูกถ้าโจทย์เป็นผู้สูบบุหรี่มี Pancoast tumor หนังตาตกข้างเดียว รูม่านตาเล็ก เหงื่อไม่ออกครึ่งหน้า","D":"Myasthenia gravis → antibody ต่อ acetylcholine receptor ทำให้ <b>ptosis และ diplopia ที่แย่ลงเมื่อใช้งาน</b> (fatigability) ดีขึ้นเมื่อพักหรือ ice pack test; ไม่ทำให้ใจสั่นน้ำหนักลด (แม้พบร่วมกับ Graves ได้บ้าง); จะถูกถ้าโจทย์เป็นหนังตาตกและเห็นภาพซ้อนตอนเย็น ดีขึ้นตอนเช้า","E":"Papillary thyroid carcinoma → มาด้วย<b>ก้อนเดี่ยวที่ต่อมไทรอยด์</b> ± ต่อมน้ำเหลืองที่คอโต การทำงานของไทรอยด์มักปกติ ไม่มีอาการ thyrotoxicosis หรือ lid lag; จะถูกถ้าโจทย์เป็นหญิงอายุ 30 ปี ก้อนแข็งที่ต่อมไทรอยด์ข้างเดียว US มี microcalcification"},"trap":"คิดว่า lid lag จำเพาะต่อ Graves — จริง ๆ พบในทุกสาเหตุของ thyrotoxicosis (toxic nodule, thyroiditis ก็มีได้); ที่จำเพาะต่อ Graves คือ orbitopathy (proptosis), pretibial myxedema และ TRAb; อีกกับดักคือสับสน lid lag (หนังตาเปิดกว้าง) กับ ptosis (หนังตาตก) ของ Horner และ myasthenia","summary":["Lid lag (von Graefe) และ lid retraction (Dalrymple) = sympathetic overactivity ต่อ Müller muscle → พบใน thyrotoxicosis ทุกสาเหตุ","Graves-specific: orbitopathy (proptosis, chemosis, periorbital edema, restrictive ophthalmopathy, optic neuropathy), pretibial myxedema, thyroid acropachy, diffuse goiter มี bruit, TRAb บวก","วินิจฉัย: TSH ต่ำ, free T4 และ/หรือ T3 สูง, TRAb บวก; ถ้าไม่ชัด radioiodine uptake สูงกระจายทั่ว (thyroiditis uptake ต่ำ, toxic nodule uptake เฉพาะจุด)","รักษาอาการ: beta-blocker (propranolol) ลดใจสั่นและ tremor","Antithyroid drugs: methimazole เป็นหลัก (PTU ใช้ใน trimester แรกของการตั้งครรภ์และ thyroid storm); ระวัง agranulocytosis และ hepatotoxicity","RAI: ได้ผลดี แต่ห้ามในตั้งครรภ์และให้นมบุตร และอาจทำให้ active orbitopathy แย่ลง (ให้ steroid ป้องกัน)","Total หรือ near-total thyroidectomy: goiter ใหญ่กดเบียด, สงสัยมะเร็งร่วม, orbitopathy ปานกลางถึงรุนแรง, ตั้งครรภ์ที่แพ้ยา, ต้องการคุมโรคเร็ว; เตรียมให้ euthyroid ก่อน (ATD + SSKI 7–10 วันลดเลือดออก)","ดูข้อ 749, 750, 751 (บท thyroid and parathyroid)"],"notes":"ไฟล์เฉลย บท thyroid แถว 4: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับในไฟล์โจทย์มีเพียง 2 คำ: ช่องโจทย์เขียน <b>\"lid lag\"</b> และช่อง Choice เขียน <b>\"grave\"</b> คำเดียว ไม่มีตัวอักษรช้อยกำกับ (ผู้จดน่าจะจดคำตอบไว้ตรง ๆ) — เราแต่งเคสสั้น ๆ (หญิง 30 ปี ใจสั่น ทนร้อนไม่ได้ น้ำหนักลด diffuse goiter และ lid lag) และแต่งช้อยทั้งหมด โดยให้ Graves disease เป็นช้อย A ตามที่ไฟล์เฉลยตอบ A; ไม่เติม proptosis หรือ bruit ใน stem","mnemonic":"<b>Lid lag = sympathetic (ทุก thyrotoxicosis); proptosis + pretibial myxedema = Graves เท่านั้น</b>","guide":"ATA hyperthyroidism 2016; EUGOGO 2021","variants":["หญิงอายุ 35 ปี ใจสั่น น้ำหนักลด ตาโปนสองข้าง มีผื่นนูนหนาที่หน้าแข้ง TSH ต่ำ free T4 สูง วินิจฉัย → Graves disease (orbitopathy + pretibial myxedema)","หญิงอายุ 28 ปี ปวดคอด้านหน้าหลังเป็นหวัด 2 สัปดาห์ ใจสั่น มี lid lag ESR สูง radioiodine uptake ต่ำ → subacute (de Quervain) thyroiditis รักษาด้วย NSAID และ beta-blocker","หญิงอายุ 40 ปี Graves disease ที่มี active moderate orbitopathy ต้องการรักษาให้หายขาด เลือกวิธีใดเลี่ยงตาแย่ลง → total thyroidectomy (หรือ RAI ร่วม steroid ป้องกัน)"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง — สอดคล้องกับข้อสอบชุด 76A, 76D และ 77A ที่ถามข้อดีหรือสิ่งที่ไม่ใช่ข้อดีของ MIS","page":18,"page2":7,"orig":"MIS + Gallstone 1","stem":"For an elderly man, what is the most important benefit of laparoscopic surgery compared with open surgery?","gray":"Most important benefit for old man laparoscopic — A. Less hospital stay & Rapid recovery B. Better cosmetic C. Less blood loss & transfusion risk","opts":["Shorter hospital stay and faster recovery","Better cosmesis","Less blood loss and transfusion risk","Shorter operative time","Lower equipment cost"],"ans":0,"key":"A Less hospital stay & Rapid recovery (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ถามข้อดีของ laparoscopic surgery ที่<b>สำคัญที่สุดสำหรับผู้สูงอายุ</b> — ต้องเลือกข้อดีที่ส่งผลต่อผลลัพธ์ทางคลินิกของกลุ่มเปราะบางนี้มากที่สุด ไม่ใช่แค่ข้อดีทั่วไป","why":"แผลเล็กทำให้ <b>ปวดน้อย ใช้ opioid น้อย ileus สั้น ลุกเดินและกินได้เร็ว</b> → ในผู้สูงอายุซึ่งมี physiologic reserve น้อย การฟื้นตัวเร็วช่วยลดภาวะแทรกซ้อนที่เป็นสาเหตุหลักของการเจ็บป่วยและเสียชีวิตหลังผ่าตัด ได้แก่ <b>pulmonary complications</b> (atelectasis, pneumonia จากการหายใจตื้นเพราะปวดแผลใหญ่), <b>DVT</b>, <b>postoperative delirium</b>, กล้ามเนื้อเสื่อมจากการนอนนาน (deconditioning) และการติดเชื้อในโรงพยาบาล → <b>นอนโรงพยาบาลสั้นลงและกลับไปช่วยเหลือตัวเองได้เร็ว</b> ซึ่งเป็นผลลัพธ์ที่สำคัญที่สุดต่อคุณภาพชีวิตและความเป็นอิสระของผู้สูงอายุ; ข้อควรระวังคือ pneumoperitoneum (CO₂ 12–15 mmHg) ลด venous return เพิ่ม SVR และเกิด hypercapnia ต้องระวังในผู้ป่วยโรคหัวใจและปอดรุนแรง","wrong":{"B":"Better cosmesis → เป็นข้อดีจริงของ MIS แต่<b>สำคัญน้อยที่สุดในผู้สูงอายุ</b> เมื่อเทียบกับการลดภาวะแทรกซ้อนและฟื้นตัวเร็ว; จะถูกถ้าโจทย์ถามข้อดีที่ผู้ป่วยหญิงอายุน้อยให้ความสำคัญ หรือถามข้อดีของ single-incision หรือ NOTES","C":"Less blood loss and transfusion risk → MIS เสียเลือดน้อยกว่าผ่าตัดเปิดเล็กน้อยในหลายหัตถการ แต่เป็น<b>ข้อดีรอง</b> และไม่ใช่ปัจจัยหลักที่เปลี่ยนผลลัพธ์ในผู้สูงอายุ; จะถูกถ้าโจทย์ถามข้อดีในผู้ป่วยที่ปฏิเสธการรับเลือด หรือในหัตถการเช่น laparoscopic partial nephrectomy หรือ hepatectomy ที่เลือดออกง่าย","D":"Shorter operative time → <b>ไม่ใช่ข้อดี</b> ของ MIS ส่วนใหญ่ใช้เวลาผ่าตัดนานกว่าผ่าตัดเปิด โดยเฉพาะช่วง learning curve; จะถูกถ้าโจทย์ถามข้อเสียของ laparoscopic surgery (ตอบในทางกลับกันว่าใช้เวลานานกว่า)","E":"Lower equipment cost → <b>ไม่ใช่ข้อดี</b> อุปกรณ์ laparoscopic ราคาสูงกว่า แม้ค่าใช้จ่ายรวมอาจชดเชยได้จากการนอนโรงพยาบาลสั้น; จะถูกถ้าโจทย์ถามข้อเสียของ MIS (ค่าอุปกรณ์สูง)"},"trap":"เลือกข้อดีที่คุ้นที่สุด (แผลสวย) โดยไม่คิดว่าโจทย์ถามเจาะจงผู้สูงอายุ; และอย่าเลือก operative time หรือ cost ซึ่งเป็นข้อเสียของ MIS","summary":["ข้อดีของ MIS: ปวดน้อย, ileus สั้น, ลุกเดินและกินเร็ว, ภาวะแทรกซ้อนทางปอดน้อย, SSI และ incisional hernia น้อยกว่า, adhesion น้อย, นอนโรงพยาบาลสั้น, กลับไปทำงานเร็ว, แผลสวย","ผู้สูงอายุได้ประโยชน์มากที่สุดจากการฟื้นตัวเร็ว: ลด pneumonia, DVT, delirium, deconditioning และการสูญเสียความสามารถในการช่วยเหลือตัวเอง","ข้อเสีย: เวลาผ่าตัดนานกว่า, อุปกรณ์แพง, learning curve, ไม่มี tactile feedback, ภาพ 2 มิติ, ภาวะแทรกซ้อนเฉพาะ (trocar injury ต่อลำไส้และหลอดเลือด, CBD injury)","สรีรวิทยาของ CO₂ pneumoperitoneum (12–15 mmHg): ลด venous return และ cardiac output, เพิ่ม SVR, hypercapnia และ respiratory acidosis, ลด renal blood flow, ดัน diaphragm ลด FRC","ข้อห้ามสัมพัทธ์: hemodynamic instability, โรคหัวใจหรือปอดรุนแรงที่ทน pneumoperitoneum ไม่ได้, coagulopathy ที่แก้ไม่ได้, adhesion มาก; การตั้งครรภ์ทำได้แต่ใช้ความดันต่ำและเทคนิคเฉพาะ","CO₂ embolism: hypotension ฉับพลัน, EtCO₂ เปลี่ยนแปลง, mill-wheel murmur → หยุด insufflation, ปล่อยแก๊ส, ท่า left lateral decubitus + Trendelenburg","ดูข้อ 754 (บท MIS + Gallstone)"],"notes":"ไฟล์เฉลย บท mis แถว 1: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับในไฟล์โจทย์: A. Less hospital stay &amp; Rapid recovery B. Better cosmetic C. Less blood loss &amp; transfusion risk — เราเกลาถ้อยคำเป็นภาษาอังกฤษที่ถูกต้อง (Shorter hospital stay and faster recovery, Better cosmesis, Less blood loss and transfusion risk) ไม่เปลี่ยนความหมาย; ช้อย D, E แต่งเพิ่ม","mnemonic":"","guide":"Sabiston 21st ed.","variants":["ข้อใดไม่ใช่ข้อดีของ laparoscopic surgery เมื่อเทียบกับการผ่าตัดเปิด → operative time สั้นกว่า (จริง ๆ นานกว่า) หรือค่าอุปกรณ์ต่ำกว่า","ระหว่าง laparoscopic cholecystectomy ผู้ป่วยความดันตกฉับพลัน EtCO₂ ลดลงทันที ได้ยิน mill-wheel murmur ภาวะนี้คือและควรทำอะไร → CO₂ embolism หยุด insufflation ปล่อยแก๊ส ท่า left lateral decubitus + Trendelenburg","ผู้ป่วยหัวใจล้มเหลวรุนแรง EF 20% ต้องผ่าตัดถุงน้ำดี ข้อกังวลของ pneumoperitoneum คืออะไร → ลด venous return และ cardiac output เพิ่ม afterload และ hypercapnia (พิจารณาความดันต่ำ หรือ percutaneous cholecystostomy)"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง — ไฟล์โจทย์ติดป้ายช้อยเป็น B แต่คีย์เขียน A ซึ่งน่าจะเป็นการพิมพ์ป้ายผิดของผู้จด (มีช้อยเดียว); ข้อเดียวกับข้อสอบชุด 76C","page":18,"page2":7,"orig":"MIS + Gallstone 2","stem":"A critically ill patient in the ICU has clinical features of acute cholecystitis, but ultrasound shows no gallstones. What is the most likely diagnosis?","gray":"มีอาการของ Acute cholecystitis แต่ตรวจแล้วไม่มี Stone ถามว่าเป็นไร — B. Acalculous cholecystitis (ช้อยเดียว ติดป้าย B)","opts":["Acalculous cholecystitis","Choledocholithiasis","Gallbladder carcinoma","Biliary colic","Gallbladder polyp"],"ans":0,"key":"A Acalculous cholecystitis (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: เติมใน stem ว่าเป็นผู้ป่วยวิกฤตใน ICU (แบบชุด 76C) — ผนังถุงน้ำดีหนาไม่มีนิ่วมีหลายสาเหตุ","interp":"ผู้ป่วย<b>วิกฤตใน ICU</b> มีอาการของถุงน้ำดีอักเสบเฉียบพลัน (ไข้ ปวด RUQ, Murphy sign, WBC สูง) แต่ US <b>ไม่พบนิ่ว</b> → ต้องนึกถึงถุงน้ำดีอักเสบที่ไม่ได้เกิดจากนิ่วอุดตัน ซึ่งสัมพันธ์กับภาวะวิกฤต","why":"<b>Acute acalculous cholecystitis (AAC)</b> คิดเป็นราว 5–10% ของ acute cholecystitis เกิดใน<b>ผู้ป่วยวิกฤต</b>: sepsis, severe trauma, burn, หลังผ่าตัดใหญ่ (โดยเฉพาะหัวใจและหลอดเลือด), ใช้ vasopressor หรือ mechanical ventilation, <b>TPN และงดอาหารนาน</b>, ได้ opioid ปริมาณมาก, รวมถึงผู้ป่วยภูมิคุ้มกันบกพร่อง (CMV, cryptosporidium ใน HIV); กลไกคือ <b>bile stasis</b> (ไม่มี CCK กระตุ้นการบีบตัว น้ำดีเข้มข้นและเป็น sludge) ร่วมกับ <b>ischemia</b> ของผนังถุงน้ำดีจาก hypoperfusion → เกิด <b>gangrene และ perforation สูง</b> (~40%) และอัตราตายสูงกว่า calculous มาก; US: ผนังหนา &gt;3.5 mm, pericholecystic fluid, sludge, ถุงน้ำดีโป่ง, sonographic Murphy (ผู้ป่วยมักบอกอาการไม่ได้), intramural gas หรือ mucosal sloughing; HIDA scan ช่วยได้ (ไม่เห็นถุงน้ำดี แต่ false positive ในผู้ป่วยงดอาหารนาน); รักษา <b>antibiotics + percutaneous cholecystostomy</b> ในผู้ป่วยที่ไม่พร้อมผ่าตัด หรือ cholecystectomy ถ้าพร้อม หรือมี gangrene/perforation","wrong":{"B":"Choledocholithiasis → นิ่วในท่อน้ำดีร่วม ทำให้<b>เหลือง ALP และ bilirubin สูง</b> US เห็น CBD ขยาย; ถ้ามีไข้ร่วมเป็น cholangitis; จะถูกถ้าโจทย์เป็นปวด RUQ เหลือง ALP สูง CBD 10 mm","C":"Gallbladder carcinoma → มักมาด้วย<b>อาการเรื้อรัง</b> ปวดท้องเรื้อรัง น้ำหนักลด เหลืองเมื่อลุกลาม US เห็นก้อนในถุงน้ำดีหรือผนังหนาไม่สม่ำเสมอลุกลามเข้าตับ สัมพันธ์กับนิ่วใหญ่และ porcelain gallbladder; จะถูกถ้าโจทย์เป็นหญิงสูงอายุน้ำหนักลด มีก้อนที่ถุงน้ำดีลามเข้าตับ","D":"Biliary colic → ปวด RUQ หรือลิ้นปี่เป็นพักหลังอาหารมัน<b>หายเองภายใน 4–6 ชม.</b> ไม่มีไข้ ไม่มี WBC สูง และ<b>ต้องมีนิ่ว</b>ในถุงน้ำดี; จะถูกถ้าโจทย์เป็นปวดหลังอาหารมันไม่กี่ชั่วโมงแล้วหาย US มีนิ่ว ผนังไม่หนา","E":"Gallbladder polyp → ติ่งเนื้อยื่นจากผนังถุงน้ำดีที่<b>ไม่เคลื่อนตามท่า</b>และไม่มีเงา มักพบโดยบังเอิญ ไม่ทำให้อาการอักเสบเฉียบพลัน; ผ่าตัดเมื่อ ≥10 mm, โตเร็ว, มีอาการ หรือมีปัจจัยเสี่ยงมะเร็ง; จะถูกถ้าโจทย์เป็น US พบติ่งเนื้อ 12 mm ไม่เคลื่อนที่ ไม่มีเงา"},"trap":"US ไม่พบนิ่วแล้วตัดถุงน้ำดีอักเสบทิ้ง — ในผู้ป่วยวิกฤต AAC เกิดได้โดยไม่มีนิ่วและอันตรายกว่า; ผู้ป่วยมักใส่ท่อหายใจบอกอาการไม่ได้ จึงต้องสงสัยเมื่อมีไข้หรือ sepsis ที่หาสาเหตุไม่ได้ร่วมกับ LFT ผิดปกติ","summary":["AAC 5–10% ของ acute cholecystitis; ปัจจัยเสี่ยง: critically ill, sepsis, trauma, burn, หลังผ่าตัดใหญ่, vasopressor, ventilator, TPN, NPO นาน, opioid ขนาดสูง, ภูมิคุ้มกันบกพร่อง","กลไก: bile stasis + gallbladder wall ischemia ± การติดเชื้อทุติยภูมิ → gangrene, empyema, perforation สูง; อัตราตายสูง (ส่วนหนึ่งจากโรคพื้นฐาน)","US (ข้างเตียง ICU): ผนังหนา &gt;3.5 mm, pericholecystic fluid, sludge, distension, sonographic Murphy, intramural gas; CT ช่วยดู complication; HIDA ไม่เห็นถุงน้ำดี (false positive ใน NPO นาน, TPN)","Tokyo Guidelines 2018 วินิจฉัย acute cholecystitis: A local sign (Murphy, RUQ mass/pain/tenderness) + B systemic inflammation (ไข้, CRP, WBC) + C imaging","รักษา: antibiotics ครอบคลุม gram-negative และ anaerobe; ผู้ป่วยไม่พร้อมผ่าตัด → percutaneous cholecystostomy; พร้อมผ่าตัดหรือ gangrene/perforation → cholecystectomy","ป้องกันใน ICU: ให้ enteral feeding เร็วเมื่อทำได้ (กระตุ้นการบีบตัวของถุงน้ำดี), ลด TPN ที่ไม่จำเป็น, รักษา perfusion","ดูข้อ 723, 724, 727, 728, 730 (โรคทางเดินน้ำดีในชุดนี้)"],"notes":"ไฟล์เฉลย บท mis แถว 2: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับในไฟล์โจทย์มี<b>ช้อยเดียว</b>คือ \"B. Acalculous cholecystitis\" (ติดป้ายเป็น B ทั้งที่ไม่มีช้อย A) แต่ไฟล์เฉลยตอบ <b>A</b> — เราจัดให้ Acalculous cholecystitis เป็นช้อย A ตามคีย์ และช้อย B–E แต่งเพิ่ม<br>โจทย์ต้นฉบับ \"มีอาการของ Acute cholecystitis แต่ตรวจแล้วไม่มี Stone ถามว่าเป็นไร\" — เราเติมว่าเป็นผู้ป่วยวิกฤตใน ICU และตรวจด้วย ultrasound","mnemonic":"<b>AAC ใน ICU: \"Sick, Starved, Stasis\"</b> — ป่วยหนัก งดอาหาร/TPN น้ำดีคั่ง","guide":"Tokyo Guidelines 2018","variants":["ชายอายุ 65 ปี ไฟไหม้ 40% TBSA ได้ TPN มา 10 วัน มีไข้และ WBC สูง US พบถุงน้ำดีโป่ง ผนังหนา 6 mm มี sludge ไม่มีนิ่ว ยังต้องใช้ vasopressor การรักษา → antibiotics + percutaneous cholecystostomy","ผู้ป่วยหลังผ่าตัดหัวใจใน ICU มีไข้ไม่ทราบสาเหตุ ALP และ bilirubin สูงขึ้นเล็กน้อย ควรตรวจอะไรข้างเตียงเพื่อหาสาเหตุทางช่องท้อง → bedside US ถุงน้ำดีหา acalculous cholecystitis","ผู้ป่วยหลังทำ percutaneous cholecystostomy จาก AAC อาการดีขึ้นและพร้อมผ่าตัด ควรทำอะไรต่อ → พิจารณา interval cholecystectomy หรือ cholangiogram ผ่านสายแล้วถอดสายถ้าไม่มีนิ่วและท่อเปิดดี"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ D มั่นใจสูง — locally advanced (cT4b N+) ต้องได้ neoadjuvant ก่อนผ่าตัด; สอดคล้องกับข้อสอบชุด 76D (หลัง neoadjuvant แล้วก้อนยังติด prostate → en bloc resection)","page":18,"page2":7,"orig":"Colorectal tumor 1","stem":"A 4-cm rectal adenocarcinoma lies 3 cm above the puborectalis muscle. Imaging shows the tumor extending through the rectal wall and abutting the uterus and cervix, with positive lymph nodes. There is no distant metastasis. What is the most appropriate management?","gray":"rectal mass size 4 cm above puborectalis muscle 3 cm, tumor invade serosa, abut uterus and cervix ด้วย with positive lymph node, management? — A. LAR chemotaradiation B. Abdominalperineal resection with chemoradiation C. LAR++TME D. Neoadjuvant then surgery E. AR with mesocolic resection","opts":["LAR with chemoradiation","Abdominoperineal resection with chemoradiation","LAR with total mesorectal excision","Neoadjuvant therapy, then surgery","Anterior resection with mesocolic excision"],"ans":3,"key":"D Neoadjuvant then surgery (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"มะเร็ง rectum ส่วน<b>กลางถึงล่าง</b> (อยู่เหนือ puborectalis 3 cm) ที่<b>ทะลุผนังลำไส้และชิดมดลูกกับปากมดลูก</b> (cT4b) ร่วมกับ<b>ต่อมน้ำเหลืองบวก</b> (N+) ไม่มีการแพร่กระจายไกล = <b>locally advanced rectal cancer</b> → ถามลำดับการรักษาที่ถูกต้อง","why":"Locally advanced rectal cancer (<b>cT3–T4 และ/หรือ N+</b>, หรือ mesorectal fascia ถูกคุกคาม) ต้องได้ <b>neoadjuvant therapy ก่อนผ่าตัด</b> เพื่อ downstage ก้อน ทำให้ได้ R0 margin และลด local recurrence (German CAO/ARO/AIO-94: preoperative chemoRT ลด local recurrence เทียบ postoperative); แนวทางปัจจุบันนิยม <b>total neoadjuvant therapy (TNT)</b> = long-course chemoRT (50.4 Gy + capecitabine หรือ 5-FU) หรือ short-course RT (5×5 Gy) ร่วมกับ systemic chemotherapy (FOLFOX หรือ CAPOX) ก่อนผ่าตัด (<b>RAPIDO</b>, <b>PRODIGE 23</b>) → restaging ด้วย MRI → ผ่าตัด <b>TME</b> ซึ่งในรายที่ก้อนยังติดมดลูกต้องทำ <b>en bloc multivisceral resection</b> (posterior pelvic exenteration รวม hysterectomy) เพื่อ R0; ชนิดการผ่าตัด (LAR หรือ APR) ขึ้นกับ distal margin และการลุกลามหูรูด; ถ้าตอบสนองสมบูรณ์ทางคลินิก (cCR) พิจารณา <b>watch-and-wait</b> ได้ในบางราย (OPRA)","wrong":{"A":"LAR with chemoradiation → ถ้าหมายถึง<b>ผ่าตัดก่อนแล้วค่อยให้ chemoRT</b> (adjuvant) จะเพิ่ม local recurrence และ toxicity มากกว่า neoadjuvant และก้อน cT4b ที่ชิดมดลูกอาจตัดไม่ได้ R0; จะถูก (ในแง่ adjuvant) ถ้าโจทย์เป็นผู้ป่วยที่ผ่าตัดไปแล้วโดยไม่ได้ neoadjuvant และพยาธิพบ pT3N1 หรือ CRM บวก","B":"Abdominoperineal resection with chemoradiation → APR ทำเมื่อก้อน<b>ลุกลามหูรูดหรือ levator ani</b> หรือไม่สามารถได้ distal margin ที่ปลอดภัยโดยเก็บหูรูด; ก้อนนี้อยู่เหนือ puborectalis 3 cm อาจเก็บหูรูดได้ และการระบุ APR ตั้งแต่แรกก่อน neoadjuvant ข้ามขั้นตอนสำคัญ; จะถูกถ้าโจทย์เป็นก้อนที่ลุกลาม external sphincter หลัง neoadjuvant","C":"LAR with total mesorectal excision → เป็น<b>การผ่าตัดมาตรฐาน</b>สำหรับมะเร็ง rectum ส่วนกลางและบน แต่ใน locally advanced (cT4b, N+) การผ่าตัดทันทีโดยไม่ได้ neoadjuvant เสี่ยง CRM บวกและ local recurrence สูง; จะถูกถ้าโจทย์เป็น <b>cT1–T2 N0</b> (early rectal cancer) ที่ไม่ต้อง neoadjuvant","E":"Anterior resection with mesocolic excision → <b>complete mesocolic excision (CME)</b> เป็นหลักการผ่าตัดของ<b>มะเร็ง colon</b> ไม่ใช่ rectum (rectum ใช้ total mesorectal excision); และ high anterior resection ใช้กับก้อนส่วน rectosigmoid หรือ upper rectum; จะถูกถ้าโจทย์เป็นมะเร็ง sigmoid colon หรือ right colon (CME + central vascular ligation)"},"trap":"เลือกการผ่าตัดทันทีเพราะเห็นช้อยที่มีคำว่า TME ซึ่งเป็นมาตรฐาน — แต่ต้องดู stage ก่อน: T3–4 หรือ N+ ต้อง neoadjuvant ก่อนเสมอ; และอย่าสับสน mesorectal (rectum) กับ mesocolic (colon) excision","summary":["Staging มะเร็ง rectum: colonoscopy + biopsy, MRI pelvis (T, N, CRM, EMVI, ระยะจาก anal verge และหูรูด), CT chest/abdomen/pelvis หา metastasis, CEA","Early (cT1–T2 N0): ผ่าตัด TME ทันที (LAR หรือ APR); cT1 บางรายทำ local excision (TAMIS หรือ TEM)","Locally advanced (cT3–T4 และ/หรือ N+, MRF threatened): neoadjuvant ก่อน — TNT = chemoRT หรือ short-course RT + FOLFOX หรือ CAPOX (RAPIDO, PRODIGE 23)","หลัง neoadjuvant → restaging MRI → TME; cT4b ที่ติดอวัยวะข้างเคียง → en bloc multivisceral resection เพื่อ R0","cCR หลัง TNT → watch-and-wait ได้ในบางราย (OPRA) ติดตามด้วย MRI, endoscopy และ DRE อย่างใกล้ชิด","LAR เมื่อได้ distal margin ≥1–2 cm และหูรูดปกติ (มักทำ diverting ileostomy ชั่วคราว); APR เมื่อก้อนลุกลามหูรูดหรือ levator หรือเก็บหูรูดไม่ได้","Colon cancer ต่างกัน: ผ่าตัด CME + central vascular ligation ก่อน แล้ว adjuvant chemo ใน stage III และ stage II ความเสี่ยงสูง; neoadjuvant chemo ใช้ใน T4 บางราย","ดูข้อ 756 (MRI ในมะเร็ง rectum), 77, 64"],"notes":"ไฟล์เฉลย บท colorectal แถว 1: <b>D</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับในไฟล์โจทย์มีช้อยครบ 5 ตัว สะกดตามต้นฉบับ: \"A. LAR <b>chemotaradiation</b> B. <b>Abdominalperineal</b> resection with chemoradiation C. <b>LAR++TME</b> D. Neoadjuvant then surgery E. AR with mesocolic resection\" — เราเกลาเป็น LAR with chemoradiation, Abdominoperineal resection with chemoradiation, LAR with total mesorectal excision, Neoadjuvant therapy, then surgery, Anterior resection with mesocolic excision (ไม่เปลี่ยนความหมาย)<br>stem ต้นฉบับเขียนว่า <b>\"tumor invade serosa\"</b> — rectum ส่วนกลางและล่างไม่มี serosa (อยู่ใต้ peritoneal reflection) จึงเขียนเป็น extending through the rectal wall; ต้นฉบับไม่ได้ระบุ distant metastasis และชนิดชิ้นเนื้อ — เราเติม adenocarcinoma และไม่มี distant metastasis","mnemonic":"<b>มะเร็ง rectum: \"T3–4 หรือ N+ → ฉายก่อน ผ่าทีหลัง\"; rectum = mesoRECTAL, colon = mesoCOLIC</b>","guide":"NCCN Rectal Cancer 2025","variants":["ชายอายุ 60 ปี มะเร็ง rectum ห่าง anal verge 10 cm MRI เป็น cT2N0 CT ไม่มี metastasis การรักษา → LAR with TME (ไม่ต้อง neoadjuvant)","หญิงอายุ 55 ปี มะเร็ง rectum cT3N1 หลังได้ TNT ครบ MRI และ endoscopy ไม่พบก้อนเหลือ (cCR) ทางเลือกที่เก็บอวัยวะได้ → watch-and-wait ติดตามใกล้ชิด","ชายอายุ 70 ปี มะเร็ง rectum ห่าง anal verge 2 cm ลุกลาม external anal sphincter หลัง neoadjuvant chemoRT การผ่าตัด → abdominoperineal resection"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ B มั่นใจสูง — หน้าที่หลักของ pelvic MRI คือ local staging ของมะเร็ง rectum","page":19,"page2":7,"orig":"Colorectal tumor 2","stem":"A man with hematochezia and tenesmus is diagnosed with rectal cancer. What is the main role of pelvic MRI in this setting?","gray":"Patient with hematochezia and tenesmus. He was diagnosed with cancer. What is the role of pelvic MRI in colorectal cancer — A. Detect sites of metastasis, including liver, lung, …. B. Check depth of local tumor invasion? C. (ว่าง)","opts":["Detect metastases in the liver and lung","Assess the depth of local tumor invasion","Obtain a tissue diagnosis","Screen for synchronous proximal colon tumors","Detect peritoneal carcinomatosis throughout the abdomen"],"ans":1,"key":"B Check depth of local tumor invasion? (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ชายถ่ายเป็นเลือดร่วมกับ<b>เบ่งถ่ายไม่สุด (tenesmus)</b> ซึ่งบ่งว่ารอยโรคอยู่ใน rectum และได้รับการวินิจฉัยเป็นมะเร็ง rectum แล้ว → ถามบทบาทหลักของ <b>pelvic MRI</b> ในการวางแผนรักษา","why":"<b>MRI pelvis (rectal protocol, high-resolution)</b> เป็นการตรวจมาตรฐานสำหรับ <b>local staging</b> ของมะเร็ง rectum: ประเมิน<b>ความลึกของการลุกลาม (T stage)</b> โดยวัดระยะที่ก้อนลุกลามเกิน muscularis propria เป็นมิลลิเมตร, ระยะจาก<b>mesorectal fascia หรือ circumferential resection margin (CRM)</b> (≤1 mm = threatened), <b>extramural venous invasion (EMVI)</b>, mesorectal และ lateral pelvic lymph nodes, การลุกลามหูรูดและ levator ani, ระยะจาก anal verge และ anorectal junction → ใช้ตัดสินว่าต้อง neoadjuvant หรือไม่และวางแผนการผ่าตัด (LAR หรือ APR หรือ en bloc); ใช้ <b>restaging หลัง neoadjuvant</b> เพื่อประเมินการตอบสนอง (ycT, ymrTRG) และพิจารณา watch-and-wait; ERUS แม่นยำกว่าใน T1 เทียบ T2 สำหรับ early lesion","wrong":{"A":"Detect metastases in the liver and lung → การหา distant metastasis ใช้ <b>CT chest, abdomen และ pelvis with contrast</b> (MRI ตับใช้เมื่อ CT ไม่ชัดหรือวางแผนผ่าตัดตับ, PET-CT ในบางราย); pelvic MRI ไม่ครอบคลุมปอดและตับ; จะถูกถ้าโจทย์ถามบทบาทของ CT chest/abdomen ใน staging","C":"Obtain a tissue diagnosis → การวินิจฉัยทางพยาธิวิทยาได้จาก <b>colonoscopy หรือ sigmoidoscopy พร้อม biopsy</b>; MRI เป็นภาพไม่ได้ชิ้นเนื้อ; จะถูกถ้าโจทย์ถามบทบาทของ colonoscopy","D":"Screen for synchronous proximal colon tumors → synchronous cancer พบ 3–5% และ polyp พบบ่อยกว่านั้น ต้องตรวจด้วย <b>complete colonoscopy</b> ก่อนผ่าตัด (หรือ CT colonography ถ้าก้อนอุดตันจนส่องผ่านไม่ได้ แล้ว colonoscopy ภายใน 3–6 เดือนหลังผ่าตัด); จะถูกถ้าโจทย์ถามเหตุผลที่ต้องส่อง colonoscopy ตลอดลำไส้","E":"Detect peritoneal carcinomatosis throughout the abdomen → pelvic MRI เห็นเฉพาะเชิงกราน การประเมิน peritoneal disease ใช้ CT ช่องท้อง (ไวต่ำสำหรับก้อนเล็ก), PET-CT หรือ diagnostic laparoscopy; จะถูกถ้าโจทย์ถามบทบาทของ diagnostic laparoscopy ในมะเร็งที่สงสัยแพร่ในช่องท้อง"},"trap":"เลือกการหา metastasis เพราะคิดว่า MRI เป็นการตรวจที่ละเอียดที่สุดสำหรับทุกอย่าง — pelvic MRI มีหน้าที่หลักเรื่อง local staging (T, CRM, EMVI, N) ส่วน distant staging ใช้ CT; และจำว่า pelvic MRI ใช้กับมะเร็ง rectum ไม่ใช่มะเร็ง colon","summary":["Staging มะเร็ง rectum ครบชุด: colonoscopy + biopsy (และหา synchronous lesion), MRI pelvis (local staging), CT chest/abdomen/pelvis (distant staging), CEA","MRI pelvis ประเมิน: T stage (ระยะลุกลามเกิน muscularis propria เป็น mm; T3a &lt;1, T3b 1–5, T3c 5–15, T3d &gt;15 mm), CRM หรือ MRF (≤1 mm = threatened), EMVI, mesorectal และ lateral pelvic nodes, หูรูดและ levator, ความสูงของก้อน","ผล MRI ตัดสินการรักษา: cT1–2 N0 CRM ปลอดภัย → ผ่าตัดเลย; cT3–4, N+, MRF threatened, EMVI บวก → neoadjuvant (TNT)","Restaging MRI หลัง neoadjuvant: ประเมิน ymrT, MRF, tumor regression grade และ cCR สำหรับ watch-and-wait","ERUS: แยก T1 กับ T2 ใน early lesion ได้ดีกว่า เหมาะเมื่อพิจารณา local excision; ประเมิน CRM และก้อนใหญ่ได้ไม่ดี","Tenesmus และอุจจาระลำเล็กบ่งรอยโรคที่ rectum หรือ sigmoid ส่วนล่าง; ผู้สูงอายุที่ถ่ายเป็นเลือดต้อง colonoscopy เสมอ","ดูข้อ 755 (การรักษา locally advanced rectal cancer), 77, 64"],"notes":"ไฟล์เฉลย บท colorectal แถว 2: <b>B</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับในไฟล์โจทย์: ช้อย A เขียน \"Detect sites of metastasis, including liver, lung, <b>….</b>\" (ลงท้ายด้วยจุดไข่ปลา ผู้จดจำไม่ครบ), ช้อย B เขียน \"Check depth of local tumor invasion<b>?</b>\" (มีเครื่องหมาย ? ท้ายช้อย — ผู้จดไม่แน่ใจถ้อยคำ), C. (ว่าง — พิมพ์ \"C.\" ไว้ไม่มีข้อความ); ช้อย C–E ของเราแต่งเพิ่ม<br>stem ต้นฉบับเขียนว่า \"role of pelvic MRI in <b>colorectal cancer</b>\" — pelvic MRI ใช้ local staging ของมะเร็ง <b>rectum</b> (อาการ tenesmus ก็บ่ง rectum) เราจึงเขียนเป็น rectal cancer","mnemonic":"<b>\"MRI ดูข้างใน (เชิงกราน), CT ดูข้างนอก (ปอด ตับ), กล้องดูทั้งท่อ (biopsy + synchronous)\"</b>","guide":"NCCN Rectal Cancer 2025; ESGAR rectal MRI recommendations 2018","variants":["ผู้ป่วยมะเร็ง rectum MRI pelvis พบก้อนห่าง mesorectal fascia 0.5 mm และมี EMVI บวก ควรทำอะไรต่อ → neoadjuvant therapy (MRF threatened) ก่อนผ่าตัด","ผู้ป่วยมะเร็ง rectum ต้องการประเมินว่ามีการแพร่กระจายไปตับและปอดหรือไม่ ควรตรวจอะไร → CT chest, abdomen และ pelvis with contrast","ผู้ป่วยก้อนที่ rectum ขนาด 2 cm ต้องการแยก T1 กับ T2 เพื่อพิจารณา local excision การตรวจที่เหมาะ → endorectal ultrasound (ร่วมกับ MRI)"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง — เป็นข้อเดียวกับข้อสอบชุด 76D เรื่องเดียวกัน (pigmented macules + small bowel obstruction → hamartomatous polyp); ที่ติด ⚠ เพียงเพราะต้นฉบับอ้างรูปที่ไม่มีในไฟล์ เราจึงบรรยายลักษณะในรูปเป็นข้อความแทน","page":19,"page2":7,"orig":"Colorectal tumor 3","stem":"A young patient has multiple dark bluish-brown pigmented macules on the lips and buccal mucosa. Colonoscopy shows multiple polyps. What type of polyp is most likely?","gray":"ให้รูปริมฝีปากฟ้ามา ถามว่าเป็นไร ตรง AC — A. harmartomatus polyp","opts":["Hamartomatous polyp","Adenomatous polyp","Hyperplastic polyp","Inflammatory polyp","Submucosal lipoma"],"ans":0,"key":"A harmartomatus polyp (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: ต้นฉบับบอก \"ให้รูปริมฝีปากฟ้า\" แต่ไฟล์ไม่มีรูป — บรรยายใน stem เป็น pigmented macules ที่ริมฝีปากและกระพุ้งแก้ม (แบบชุด 76D)","interp":"ผู้ป่วยอายุน้อยมี <b>จุดสีเข้มคล้ำอมฟ้าที่ริมฝีปากและกระพุ้งแก้ม</b> (mucocutaneous pigmentation) ร่วมกับ <b>polyp หลายตัวในทางเดินอาหาร</b> → ต้องนึกถึง polyposis syndrome ที่มีรอยดำที่เยื่อบุช่องปากเป็นเอกลักษณ์ แล้วตอบชนิด histology ของ polyp","why":"Mucocutaneous pigmentation (ริมฝีปาก กระพุ้งแก้ม นิ้วมือ ฝ่ามือฝ่าเท้า มักขึ้นตั้งแต่วัยเด็กและจางลงเมื่อโต ยกเว้นที่กระพุ้งแก้ม) + GI polyposis = <b>Peutz-Jeghers syndrome</b> (autosomal dominant, germline mutation ของ <b>STK11/LKB1</b> บน 19p13.3) ซึ่ง polyp เป็น <b>hamartomatous polyp</b>: เยื่อบุปกติเรียงบนแกน <b>smooth muscle ที่แตกแขนงแบบต้นไม้ (arborizing)</b> งอกจาก muscularis mucosae; พบมากสุดที่ <b>ลำไส้เล็กโดยเฉพาะ jejunum</b> รองลงมาคือ colon และกระเพาะ → ทำให้เกิด <b>intussusception</b>/small bowel obstruction (เสี่ยงราวครึ่งหนึ่งก่อนอายุ 20) และเลือดออกเรื้อรังจนซีด","wrong":{"B":"Adenomatous polyp เป็น neoplastic polyp ที่พบใน sporadic adenoma และ <b>FAP</b> (APC) ซึ่งมี extraintestinal finding เป็น CHRPE, osteoma, desmoid, epidermoid cyst (Gardner) ไม่มีรอยดำที่ริมฝีปาก; จะถูกถ้าโจทย์ให้ polyp นับร้อยถึงพันตัวใน colon ในวัยรุ่นและประวัติครอบครัวเป็นมะเร็งลำไส้ใหญ่อายุน้อย","C":"Hyperplastic polyp มักเล็ก &lt;5 mm อยู่ rectosigmoid ไม่มีอาการ ไม่สัมพันธ์กับรอยดำในช่องปาก; จะถูกถ้าโจทย์เป็น polyp เล็ก ๆ ที่ rectum พบโดยบังเอิญจาก screening colonoscopy หรือ serrated polyposis syndrome","D":"Inflammatory polyp หรือ pseudopolyp เกิดจากเยื่อบุที่เหลือหลังการอักเสบเรื้อรัง พบใน ulcerative colitis หรือ Crohn disease ไม่ใช่ genetic syndrome; จะถูกถ้าโจทย์เป็นผู้ป่วย IBD มานานแล้วส่องกล้องพบ polyp จำนวนมากในตำแหน่งที่เคยอักเสบ","E":"Submucosal lipoma เป็นก้อนสีเหลืองนุ่ม กดแล้วยุบ (cushion sign) อยู่ใต้ mucosa มักเดี่ยว ทำให้ intussusception ในผู้ใหญ่ได้แต่ไม่เกี่ยวกับรอยดำที่ริมฝีปาก; จะถูกถ้าโจทย์ให้ก้อนเดี่ยวสีเหลืองที่ cecum หรือ ascending colon กับ CT density เป็นไขมัน"},"trap":"เห็นคำว่า polyp หลายตัวแล้วตอบ adenomatous polyp เพราะนึกถึง FAP อันดับแรก — จุดที่ตัดสินคือ <b>รอยดำที่ริมฝีปาก/กระพุ้งแก้ม</b> ซึ่งบ่ง PJS (hamartomatous); อีกกับดักคือคิดว่า hamartoma ไม่มีความเสี่ยงมะเร็ง ซึ่ง PJS มี lifetime cancer risk สูงมากทั้งในและนอกทางเดินอาหาร","summary":["<b>Peutz-Jeghers syndrome</b>: autosomal dominant, STK11/LKB1; mucocutaneous pigmentation (ริมฝีปาก กระพุ้งแก้ม นิ้ว) + hamartomatous polyps ทั่วทางเดินอาหาร มากสุดที่ jejunum","Histology: hamartomatous polyp มี arborizing smooth muscle จาก muscularis mucosae คลุมด้วยเยื่อบุปกติ (อาจพบ pseudoinvasion จนแปลผลผิดเป็นมะเร็ง)","อาการ: ปวดท้องเป็นพัก ๆ จาก <b>intussusception</b> ลำไส้เล็ก, small bowel obstruction, GI bleeding และซีดจากขาดธาตุเหล็ก; ตัด polyp ลำไส้เล็กที่ใหญ่ราว 15–20 mm ขึ้นไปเพื่อป้องกัน intussusception (device-assisted enteroscopy หรือ intraoperative enteroscopy)","Cancer risk ตลอดชีวิตสูง: breast, colorectal, pancreas, gastric, small bowel, ovary (sex cord tumor with annular tubules), cervix (gastric-type adenocarcinoma), testis (Sertoli cell tumor ทำให้ gynecomastia)","Surveillance (ESGE 2019): เริ่ม EGD + colonoscopy ที่อายุราว 8 ปี และ capsule endoscopy หรือ MR enterography ตรวจลำไส้เล็ก; ถ้าพบ polyp ตรวจซ้ำทุก 1–3 ปี ถ้าไม่พบเริ่มใหม่ที่อายุ 18; ต่อมาเฝ้าระวัง breast และ pancreas ในผู้ใหญ่","Hamartomatous polyposis อื่น: <b>juvenile polyposis</b> (SMAD4, BMPR1A; SMAD4 ร่วม HHT ได้), <b>Cowden/PTEN hamartoma tumor syndrome</b> (trichilemmoma, macrocephaly, มะเร็ง breast/thyroid/endometrium), Cronkhite-Canada (ไม่ถ่ายทอด ผู้สูงอายุ ผมร่วง เล็บผิดรูป ผิวคล้ำ)","Laugier-Hunziker syndrome มีรอยดำที่ริมฝีปากเหมือนกันแต่ไม่มี polyp — ต้องส่องกล้องแยก","ดูข้อ 700, 702, 755, 756 (colorectal carcinogenesis, polyp และ colorectal tumor)"],"notes":"ไฟล์เฉลย บท colorectal แถว 3: <b>A</b> (ช่องคำอธิบายว่าง)<br>ไฟล์โจทย์: ผู้จดเขียน \"ให้รูปริมฝีปากฟ้ามา ถามว่าเป็นไร <b>ตรง AC</b>\" = ข้อนี้ตรงกับข้อสอบเก่า (AC) — แต่<b>ในไฟล์ไม่มีรูป</b> เราจึงบรรยายเป็น pigmented macules ที่ริมฝีปากและกระพุ้งแก้มใน stem และเติม \"colonoscopy shows multiple polyps\" ให้ถามชนิด polyp ได้<br>ต้นฉบับมีช้อยเดียว \"A. harmartomatus polyp\" (สะกด harmartomatus ตามต้นฉบับ) — ช้อย B–E แต่งเพิ่ม (ชุดเดียวกับข้อสอบชุด 76D เรื่องเดียวกัน)","mnemonic":"<b>ปากดำ ลำไส้เล็กพันกัน</b> = Peutz-Jeghers: pigmentation + hamartoma ที่ jejunum + intussusception","guide":"ESGE polyposis syndromes 2019; ACG hereditary GI cancer syndromes 2015","variants":["เด็กชายอายุ 12 ปี ปวดท้องบิดเป็นพัก ๆ อาเจียน มีจุดสีดำที่ริมฝีปากและนิ้วมือ CT พบ target sign ที่ jejunum → jejunojejunal intussusception จาก hamartomatous polyp ของ PJS","หญิงอายุ 30 ปี เป็น PJS ควรเฝ้าระวังมะเร็งใดนอกทางเดินอาหารบ้าง → breast, pancreas, ovary, cervix (gastric-type adenocarcinoma)","วัยรุ่นมี polyp ใน colon มากกว่า 100 ตัว ร่วมกับ osteoma ที่ขากรรไกร → adenomatous polyp ใน FAP/Gardner syndrome แนะนำ prophylactic proctocolectomy"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูงสำหรับเคสที่แต่ง — ข้อสอบจริงอาจถาม investigation แรกของ CLTI ซึ่งถ้ามีช้อย arterial duplex ultrasound หรือ ABI/toe pressure อาจเป็นคำตอบได้ เราจึงตั้ง stem ให้ ABI มาแล้วและถามภาพเพื่อวางแผน revascularization และไม่ใส่ arterial duplex เป็นช้อย","page":19,"page2":7,"orig":"Vascular 1","stem":"A 70-year-old man with diabetes has ischemic rest pain and a non-healing toe ulcer. His ankle–brachial index is 0.35. Which investigation is most appropriate to plan revascularization?","gray":"CLTI investigation — A. CTA","opts":["CT angiography","Plain radiograph of the leg","Venous duplex ultrasound","D-dimer","MRI of the lumbar spine"],"ans":0,"key":"A CTA (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: ต้นฉบับจดแค่ \"CLTI investigation\" — แต่งเคส (rest pain + แผลไม่หาย + ABI 0.35) และถามภาพสำหรับวางแผน revascularization; arterial duplex ก็ใช้ได้แต่ไม่ใส่เป็นช้อย","interp":"ปวดขาขณะพัก + แผลที่นิ้วเท้าไม่หาย + ABI 0.35 = <b>chronic limb-threatening ischemia (CLTI)</b> ซึ่งต้องทำ revascularization — คำถามคือต้องใช้ <b>anatomic imaging</b> อะไรเพื่อดูตำแหน่งและความยาวของรอยตีบตัน (inflow, outflow, runoff) ไว้เลือกวิธีรักษา","why":"เมื่อวินิจฉัย CLTI ทาง hemodynamic แล้ว (ABI &lt;0.4 ตรงกับ WIfI ischemia grade 3) ขั้นต่อไปคือ <b>arterial imaging</b> เพื่อวางแผน endovascular หรือ bypass: Global Vascular Guidelines 2019 แนะนำ <b>duplex ultrasound เป็นภาพแรก</b> แล้วตามด้วย <b>CTA หรือ MRA</b> เมื่อต้องการแผนที่หลอดเลือดทั้งขาตั้งแต่ aortoiliac ถึง tibial/pedal ก่อน intervention และ <b>catheter angiography (DSA)</b> เป็นมาตรฐานโดยเฉพาะ infrapopliteal disease หรือหลอดเลือดมีหินปูนมาก — ในช้อยนี้มีเพียง <b>CT angiography</b> ที่ให้ข้อมูล anatomy ของ arterial tree ได้ (ข้อควรระวัง: contrast ในผู้ป่วย CKD และหินปูนทำให้ประเมิน tibial vessel ยาก)","wrong":{"B":"Plain radiograph ของขาใช้ดู <b>osteomyelitis</b>, gas ในเนื้อเยื่อ, foreign body หรือหินปูนของหลอดเลือด แต่ไม่บอกตำแหน่งรอยตีบ; จะถูกถ้าโจทย์ถามการตรวจแผลเบาหวานที่สงสัยติดเชื้อลงกระดูก (probe-to-bone บวก)","C":"Venous duplex ใช้วินิจฉัย DVT/venous reflux และใช้ <b>vein mapping</b> ประเมิน great saphenous vein เป็น conduit ก่อนทำ bypass แต่ไม่ใช่ภาพที่บอก arterial anatomy; จะถูกถ้าโจทย์ถามการเตรียมหลอดเลือดดำสำหรับ bypass หลังรู้ตำแหน่งรอยโรคแล้ว","D":"D-dimer ใช้คัดกรองเพื่อตัด VTE ในผู้ป่วย pretest probability ต่ำ ไม่มีบทบาทใน CLTI; จะถูกถ้าโจทย์เป็นขาบวมข้างเดียวที่ Wells score unlikely","E":"MRI lumbar spine ใช้เมื่อสงสัย <b>neurogenic claudication</b> จาก lumbar spinal stenosis (ปวดเมื่อยืนนาน ดีขึ้นเมื่อก้มหรือนั่ง ชีพจรปกติ ABI ปกติ); จะถูกถ้าโจทย์ให้ ABI ปกติร่วมอาการปวดขาเวลาเดินที่ต้องนั่งก้มจึงหาย"},"trap":"ผู้ป่วยเบาหวานมักมี <b>medial calcinosis</b> ทำให้ ABI สูงเท็จ (&gt;1.40) — ABI ปกติหรือสูงไม่ได้ตัด CLTI ต้องดู toe pressure/TBI หรือ TcPO₂; อีกกับดักคือคิดว่า CLTI รักษาด้วย exercise therapy แบบ claudication ได้ ซึ่งไม่ใช่ CLTI ต้อง revascularization","summary":["CLTI (GVG 2019) = PAD + ischemic rest pain, หรือ tissue loss (แผลไม่หาย &gt;2 สัปดาห์, gangrene) ร่วมกับ hemodynamic: ABI &lt;0.4, ankle pressure &lt;50 mmHg, toe pressure &lt;30 mmHg, TcPO₂ &lt;30 mmHg","เบาหวานหรือ CKD: ABI อาจสูงเท็จจากหลอดเลือดแข็ง → ใช้ toe pressure หรือ TBI (&lt;0.7 ผิดปกติ)","Staging ด้วย <b>WIfI</b> (Wound, Ischemia, foot Infection) ประเมินความเสี่ยงตัดขาและประโยชน์ของ revascularization; GLASS ใช้จัด anatomic complexity","Anatomic imaging: duplex ultrasound ก่อน → CTA หรือ MRA วางแผน → DSA เมื่อทำ intervention หรือ tibial/pedal disease; เตรียม vein mapping ถ้าจะทำ bypass","Revascularization: BEST-CLI 2022 — ผู้ที่มี single-segment GSV ดี bypass ดีกว่า endovascular ใน major adverse limb event หรือตาย; BASIL-2 2023 — infrapopliteal disease กลุ่ม endovascular-first ได้ผล amputation-free survival ดีกว่า vein bypass","Best medical therapy ทุกราย: เลิกบุหรี่, high-intensity statin, antiplatelet ± rivaroxaban 2.5 mg bid, คุมเบาหวานและ BP, wound care และ offloading, ควบคุมการติดเชื้อ","Primary amputation เมื่อขาเสียหายจนรักษาไม่ได้ ติดเชื้อรุนแรงคุมไม่ได้ หรือผู้ป่วยติดเตียงที่ไม่ได้ประโยชน์จากการเปิดหลอดเลือด","ดูข้อ 683, 759, 760, 761, 762 (vascular; 82 = claudication ซึ่งเป็น PAD ระยะก่อน CLTI)"],"notes":"ไฟล์เฉลย บท vas แถว 1: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับจดแค่ \"CLTI investigation\" กับช้อยเดียว \"A. CTA\" — เราแต่งเคสใน stem (ชายเบาหวาน rest pain + แผลนิ้วเท้า + ABI 0.35) และถามการตรวจเพื่อวางแผน revascularization ให้เหลือคำตอบเดียว; ช้อย B–E แต่งเพิ่ม","mnemonic":"<b>CLTI = Rest pain + Ulcer + ABI &lt;0.4</b> → แผนที่หลอดเลือด: Duplex → CTA/MRA → DSA","guide":"Global Vascular Guidelines on CLTI 2019","variants":["ชายเบาหวานอายุ 68 ปี มีแผลที่ส้นเท้า 1 เดือน ABI 1.45 → ABI ไม่น่าเชื่อถือจากหลอดเลือดแข็ง ตรวจ toe pressure หรือ TBI ต่อ","ผู้ป่วย CLTI มี GSV ข้างเดียวกันขนาดดี รอยโรคเป็น long-segment SFA occlusion และ popliteal ต่อเนื่อง ความเสี่ยงผ่าตัดต่ำ → femoropopliteal bypass ด้วย GSV","ผู้ป่วยติดเตียง มี wet gangrene ทั้งเท้าพร้อม sepsis → guillotine amputation ควบคุมการติดเชื้อก่อน แล้วทำ definitive amputation"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง — สอดคล้องกับข้อสอบชุด 77B และ 76C เรื่องเดียวกัน (เกณฑ์ผ่าตัดในชาย 5.5 cm)","page":19,"page2":7,"orig":"Vascular 2","stem":"An asymptomatic man has an infrarenal abdominal aortic aneurysm measuring 5.8 cm. He is fit for surgery. What is the most appropriate management?","gray":"AAA male 5.8cm — A. surgery","opts":["Elective aneurysm repair","Ultrasound surveillance every 6 months","Beta-blocker therapy alone","Repeat ultrasound in 3 years","Repair only when it reaches 7 cm"],"ans":0,"key":"A surgery (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ชายไม่มีอาการ มี infrarenal AAA ขนาด <b>5.8 cm</b> และแข็งแรงพอผ่าตัด → เกินเกณฑ์ผ่าตัดในผู้ชาย (5.5 cm) ความเสี่ยงแตกต่อปีสูงกว่าความเสี่ยงจากการผ่าตัดแล้ว","why":"ESVS 2024 แนะนำ <b>elective repair</b> เมื่อ AAA ในชาย <b>≥5.5 cm</b>, ในหญิง <b>≥5.0 cm</b>, โตเร็ว <b>≥1 cm/ปี</b> หรือมีอาการ (ปวดท้อง/หลัง, กดเจ็บ) — เพราะเมื่อขนาดเกิน 5.5 cm อัตราแตกต่อปีสูงขึ้นชัด (ราว 3–15%/ปีที่ 5.0–5.9 cm และ 10–20%/ปีที่ 6.0–6.9 cm) ขณะที่ทดลอง UKSAT และ ADAM ไม่พบประโยชน์ของการผ่าตัดเร็วในขนาด 4.0–5.5 cm; วิธีผ่าตัดเลือก <b>EVAR</b> (early mortality ต่ำกว่า แต่ต้องตรวจติดตามตลอดชีวิตและ reintervention มากกว่า) หรือ <b>open repair</b> ตาม anatomy (neck length, angulation, access) และความแข็งแรงของผู้ป่วย","wrong":{"B":"Ultrasound ทุก 6 เดือนเป็นช่วงติดตามของ AAA ขนาด 5.0–5.4 cm (ทุก 3–6 เดือน) ยังไม่ถึงเกณฑ์ผ่าตัด; จะถูกถ้าโจทย์ให้ AAA ในชายขนาด 5.2 cm ไม่มีอาการ","C":"Beta-blocker <b>ไม่ชะลอการโต</b>ของ AAA และไม่ลดการแตก; การรักษาด้วยยาที่แนะนำคือเลิกบุหรี่ statin antiplatelet และคุม BP เพื่อลด cardiovascular event; จะถูกเพียงในแง่ perioperative medication ของผู้ที่ใช้ยาอยู่แล้วหรือมีข้อบ่งชี้ทางหัวใจ","D":"Ultrasound ทุก 3 ปีเป็นช่วงติดตามของ AAA ขนาด 3.0–3.9 cm; จะถูกถ้าโจทย์ให้ AAA 3.5 cm จาก screening","E":"รอจนถึง 7 cm เพิ่มความเสี่ยงแตกสูงมาก (อาจถึง 20–40%/ปีที่ขนาด 7 cm ขึ้นไป) ทั้งที่ผู้ป่วยแข็งแรงพอผ่าตัด; ไม่ใช่เกณฑ์ในแนวทางใด จะพอยอมรับเฉพาะผู้ป่วยความเสี่ยงผ่าตัดสูงมากหรืออายุขัยสั้นที่ตัดสินใจร่วมกันว่าไม่ผ่าตัด"},"trap":"จำเกณฑ์ผิดเป็น 5.0 cm สำหรับทุกคน หรือสับสนว่าผู้หญิงต้องรอ 5.5 cm — ผู้หญิงหลอดเลือดเล็กกว่าและแตกที่ขนาดเล็กกว่า จึงใช้ 5.0 cm; อีกกับดักคือคิดว่า beta-blocker ชะลอการโตได้","summary":["Screening: ชายอายุ 65 ปีครั้งเดียวด้วย ultrasound (USPSTF: ชาย 65–75 ปีที่เคยสูบบุหรี่); AAA = aorta ≥3.0 cm","Surveillance (ESVS 2024): 3.0–3.9 cm ทุก 3 ปี, 4.0–4.9 cm ทุกปี, ≥5.0 cm ทุก 3–6 เดือน","เกณฑ์ผ่าตัด: ชาย ≥5.5 cm, หญิง ≥5.0 cm, โต ≥1 cm/ปี, มีอาการ, หรือ saccular aneurysm/ruptured","EVAR vs open: EVAR early mortality ต่ำกว่า (ราว 1–2% vs 3–5%) แต่ต้อง imaging surveillance ตลอดชีวิตจาก endoleak/migration; long-term survival ใกล้เคียงกัน; open repair เหมาะผู้ป่วยอายุน้อย แข็งแรง anatomy ไม่เหมาะ EVAR","Medical therapy: เลิกบุหรี่ (ชะลอการโตได้), statin, antiplatelet, คุม BP — beta-blocker และ doxycycline ไม่ชะลอการโต","Ruptured AAA: ปวดท้อง/หลัง + hypotension + ก้อนเต้นตามชีพจร → permissive hypotension (SBP 70–90) และส่งผ่าตัดทันที; EVAR ถ้า anatomy เหมาะ","ดูข้อ 683, 758, 760, 761, 762 (vascular)"],"notes":"ไฟล์เฉลย บท vas แถว 2: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับจดสั้น ๆ \"AAA male 5.8cm\" ช้อยเดียว \"A. surgery\" — stem ทำเป็นเคสสั้น ๆ (ชายไม่มีอาการ infrarenal AAA 5.8 cm แข็งแรงพอผ่าตัด); ช้อย B–E แต่งเพิ่ม","mnemonic":"<b>ชาย 5.5 หญิง 5.0 โตปีละ 1</b> → ผ่า","guide":"ESVS AAA 2024","variants":["หญิงอายุ 72 ปี AAA 5.1 cm ไม่มีอาการ แข็งแรงดี → elective repair (เกณฑ์หญิง ≥5.0 cm)","ชายอายุ 70 ปี AAA จาก 4.3 เป็น 5.4 cm ใน 1 ปี → โต ≥1 cm/ปี ส่ง elective repair","ชายอายุ 66 ปี screening พบ aorta 3.4 cm → ultrasound ซ้ำทุก 3 ปี เลิกบุหรี่ และคุมปัจจัยเสี่ยง"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A ความมั่นใจปานกลางถึงสูง — ถ้าคำถามจริงคือ definitive management ของ IIb คำตอบควรเป็น emergency thrombectomy/embolectomy แต่ช้อย B ต้นฉบับกำหนด \"within 48 hours\" ซึ่งช้าเกิน จึงผิดอยู่ดี; การให้ heparin IV ทันทีเป็นขั้นแรกที่ถูกเสมอ สอดคล้องกับข้อสอบชุด 77C เรื่องเดียวกัน (AF + กางนิ้วไม่ได้ → embolectomy) และชุด 76D (ALI ไม่มี motor deficit → CTA)","page":19,"page2":7,"orig":"Vascular 3","stem":"A patient has acute arterial occlusion of the leg with sensory loss and mild motor weakness, classified as Rutherford class IIb. What is the most appropriate immediate management?","gray":"Acute arterial occlusion motor deficit class IIb — A. heparin IV B. thrombectomy within 48 hours","opts":["Intravenous heparin bolus","Thrombectomy within 48 hours","Aspirin and observation","Primary amputation","Warfarin with outpatient follow-up"],"ans":0,"key":"A heparin IV (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: stem ถาม immediate management — class IIb ต้อง revascularization ด่วนภายในชั่วโมง (ราว 6 ชม.) ไม่ใช่ภายใน 48 ชม. (ช้อย B ผิดที่เวลา) และ heparin ให้ทันทีที่วินิจฉัย","interp":"Acute limb ischemia ที่มี <b>sensory loss + motor weakness</b> = Rutherford <b>IIb (immediately threatened)</b> → ขายังรักษาได้ถ้าเปิดหลอดเลือดทันที; คำถามคือสิ่งที่ต้องทำ <b>ทันที</b> และต้องดูกรอบเวลาที่ช้อยให้","why":"เมื่อวินิจฉัย ALI ทุก class ที่ยังรักษาขาได้ ให้ <b>unfractionated heparin IV bolus ทันที</b> (80 U/kg หรือ 5,000–10,000 U) แล้วตามด้วย infusion เพื่อหยุดการลุกลามของ thrombus ไป collateral และ microcirculation ระหว่างเตรียมรักษา; class IIb ต้อง <b>revascularization ฉุกเฉินภายในไม่กี่ชั่วโมง</b> (กล้ามเนื้อทนขาดเลือดได้ราว 4–6 ชม.) โดยมักเลือก <b>surgical embolectomy/thrombectomy</b> เพราะ catheter-directed thrombolysis ใช้เวลานานเกินไป — ช้อย B \"within 48 hours\" ช้าเกินจนกล้ามเนื้อตายและอาจต้องตัดขา","wrong":{"B":"Thrombectomy ถูกวิธีสำหรับ IIb แต่ <b>กรอบเวลา 48 ชม. ผิด</b> — ต้องทำเร่งด่วนภายในชั่วโมงหลังให้ heparin; จะถูกถ้าช้อยเป็น emergency thrombectomy หรือ embolectomy ทันที","C":"Aspirin แล้วสังเกตอาการไม่เพียงพอใน ALI ทุก class ขาจะตายจาก thrombus ลุกลาม; aspirin เป็นยาระยะยาวใน chronic PAD ไม่ใช่การรักษา acute occlusion","D":"Primary amputation สำหรับ <b>class III (irreversible)</b>: ชาหมด อัมพาต กล้ามเนื้อแข็ง (rigor) ไม่ได้ยินทั้ง arterial และ venous Doppler — การเปิดหลอดเลือดในระยะนี้เสี่ยง reperfusion syndrome รุนแรง; จะถูกถ้าโจทย์ให้ขาแข็งเป็นจ้ำม่วงคงที่ ขยับไม่ได้","E":"Warfarin แบบผู้ป่วยนอกเป็นการป้องกัน embolism ระยะยาว (AF) หลังรักษาแล้ว ไม่ใช่ immediate management และ onset ช้าหลายวัน; จะถูกถ้าโจทย์ถามการป้องกันการเกิดซ้ำหลัง embolectomy ในผู้ป่วย AF (หรือ DOAC)"},"trap":"เห็นช้อย thrombectomy แล้วเลือกทันทีเพราะรู้ว่า IIb ต้องผ่าตัด — แต่ \"within 48 hours\" ช้าเกินไป; และอย่าลืมว่า heparin ให้ทันทีก่อนส่ง imaging หรือห้องผ่าตัดเสมอ (ถ้าไม่มีข้อห้าม)","summary":["อาการ 6P: pain, pallor, pulselessness, poikilothermia, paresthesia, paralysis — paresthesia และ paralysis บ่งความรุนแรง","Rutherford: <b>I viable</b> (ไม่มี sensory/motor loss, ได้ยิน arterial Doppler); <b>IIa marginally threatened</b> (ชาเล็กน้อยที่นิ้ว ไม่มี motor deficit); <b>IIb immediately threatened</b> (ชาเกินนิ้ว ปวดขณะพัก อ่อนแรงเล็กน้อยถึงปานกลาง ไม่ได้ยิน arterial Doppler); <b>III irreversible</b> (ชาหมด อัมพาต rigor ไม่ได้ยินทั้ง arterial และ venous)","ทุกรายที่ขายังรักษาได้: UFH 80 U/kg bolus + infusion ทันที, ให้สารน้ำ, แก้ปวด","I และ IIa: มีเวลาทำ imaging (CTA) และเลือก catheter-directed thrombolysis หรือ endovascular ได้; IIb: revascularization ฉุกเฉิน มักเป็น surgical embolectomy/thrombectomy ด้วย Fogarty catheter; III: amputation","Embolus (AF, MI, valvular) เทียบ thrombosis in situ (PAD เดิม): embolus เริ่มทันที ขาอีกข้างชีพจรปกติ ไม่มีประวัติ claudication","หลัง reperfusion เฝ้าระวัง <b>compartment syndrome</b> (ขาดเลือด &gt;4–6 ชม. พิจารณา prophylactic four-compartment fasciotomy), hyperkalemia, myoglobinuria และ AKI","หาแหล่ง embolus: ECG, echocardiography, แล้ว anticoagulation ระยะยาว","ดูข้อ 721, 758, 759, 761, 762 (41 = mesenteric embolus จาก AF กลไกเดียวกัน)"],"notes":"ไฟล์เฉลย บท vas แถว 3: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับจด \"Acute arterial occlusion motor deficit class IIb\" ช้อย A. heparin IV, B. thrombectomy within 48 hours — เราแปลง stem เป็นเคส (sensory loss + mild motor weakness = Rutherford IIb) และใส่ \"immediate management\" ให้ตรงกับคีย์ heparin; ช้อย C–E แต่งเพิ่ม","mnemonic":"<b>ขายังขยับได้นิดหน่อย = IIb = Heparin แล้วผ่าเดี๋ยวนี้</b> (ไม่ใช่ 48 ชม.)","guide":"ESVS acute limb ischaemia 2020; 2024 ACC/AHA PAD guideline","variants":["ชาย AF ไม่ได้กินยากันเลือดแข็ง ขาซ้ายปวดเฉียบพลัน 3 ชม. ชาถึงข้อเท้า กระดกนิ้วเท้าได้น้อยลง → heparin IV แล้ว emergency Fogarty embolectomy","ผู้ป่วย ALI ปวดและเย็นที่เท้า ไม่มี sensory loss หรือ motor deficit ได้ยิน Doppler ที่ dorsalis pedis อ่อน ๆ → class I/IIa ให้ heparin แล้วทำ CTA วางแผน","หลัง embolectomy ที่ขาขาดเลือด 8 ชม. ผู้ป่วยปวดน่องรุนแรงเมื่อเหยียดนิ้วเท้า น่องตึงแข็ง → compartment syndrome ทำ four-compartment fasciotomy"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูงเมื่อ pretest probability สูง — ถ้าข้อสอบจริงไม่ได้ให้ข้อมูลความเสี่ยง (มีแค่ \"ลงจากเครื่องบิน สงสัย DVT\") บางคนอาจตอบ D-dimer ตามหลักใช้คัดกรองกลุ่มเสี่ยงต่ำ เราจึงเติม pretest probability สูงให้เหลือคำตอบเดียว; สอดคล้องกับข้อสอบชุด 76A และ 77A เรื่องเดียวกัน (หลังบินนาน ขาบวมข้างเดียว → duplex หรือ PE)","page":19,"page2":7,"orig":"Vascular 4","stem":"A woman who arrived by a long-haul flight yesterday now has unilateral swelling, tenderness and warmth of the left calf. Her clinical pretest probability for DVT is high. What is the most appropriate investigation?","gray":"คนไข้ลงมาจากเครื่องบิน สงสัย DVT ทำไรดี — A. Venous Duplex ultrasound B. D-Dimer C. CTA D. Trendelunberg","opts":["Venous duplex ultrasound","D-dimer","CT angiography","Trendelenburg test","Contrast venography"],"ans":0,"key":"A Venous Duplex ultrasound (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: เติม unilateral calf swelling + clinical pretest probability สูง (ถ้า pretest probability ต่ำ ให้ตรวจ D-dimer ก่อน — ช้อย B)","interp":"เดินทางโดยเครื่องบินระยะไกล (นั่งนาน = venous stasis) แล้วน่องข้างเดียวบวม กดเจ็บ อุ่น + <b>pretest probability สูง</b> → ถามการตรวจวินิจฉัย DVT ซึ่งขึ้นกับ pretest probability ว่าจะเริ่มด้วย imaging หรือ D-dimer","why":"ผู้ป่วยที่ <b>DVT likely</b> (Wells ≥2 หรือ pretest probability สูง) ให้ตรวจ <b>compression venous duplex ultrasound</b> โดยตรง (proximal หรือ whole-leg) เพราะ D-dimer ลบในกลุ่มนี้ก็ไม่พอตัด DVT (negative predictive value ลดลงเมื่อ prevalence สูง) — ASH 2018 แนะนำ ultrasound ก่อน D-dimer ในกลุ่ม high pretest probability; NICE NG158: DVT likely ทำ proximal leg vein ultrasound ภายใน 4 ชม. (ถ้าทำไม่ได้ให้ตรวจ D-dimer และให้ interim anticoagulation ก่อน) โดย non-compressible vein คือเกณฑ์วินิจฉัยหลัก","wrong":{"B":"D-dimer sensitivity สูงแต่ specificity ต่ำ ใช้ <b>ตัด</b> DVT ใน pretest probability ต่ำหรือ unlikely (Wells ≤1) ถ้าลบก็จบได้ ถ้าบวกค่อยทำ ultrasound; จะถูกถ้าโจทย์ให้ Wells score unlikely","C":"CT angiography เป็นการตรวจหลอดเลือดแดง; ภาวะที่ต้องใช้ CT คือสงสัย <b>PE</b> (CT pulmonary angiography) เมื่อมีหอบเหนื่อย เจ็บหน้าอก หัวใจเต้นเร็ว; จะถูกถ้าโจทย์เป็นผู้ป่วยหลังบินนานที่หอบเหนื่อยเฉียบพลันและ SpO₂ ต่ำ","D":"Trendelenburg test (Brodie-Trendelenburg) ทดสอบ <b>ลิ้นที่ saphenofemoral junction และ perforator</b> ใน varicose veins ไม่ได้วินิจฉัย DVT; จะถูกถ้าโจทย์ถามการตรวจร่างกายแยก superficial กับ perforator incompetence ในเส้นเลือดขอด","E":"Contrast venography เคยเป็น gold standard แต่ invasive ใช้ contrast และอาจกระตุ้น thrombosis ปัจจุบันแทบไม่ใช้; จะถูกถ้าโจทย์ถาม gold standard แบบดั้งเดิม หรือ ultrasound ทำไม่ได้/ไม่ชัด"},"trap":"เลือก D-dimer เพราะจำว่าเป็นการตรวจแรกของ DVT — ใช้เฉพาะกลุ่ม unlikely; กลุ่ม likely ต้อง imaging เลย และ D-dimer สูงได้จากหลายภาวะ (ตั้งครรภ์ ผ่าตัด มะเร็ง สูงอายุ) จึงไม่ใช้ยืนยันโรค","summary":["ปัจจัยเสี่ยง (Virchow triad): stasis (นั่งนาน เดินทาง &gt;4 ชม. ติดเตียง), endothelial injury (ผ่าตัด trauma), hypercoagulability (มะเร็ง ตั้งครรภ์ estrogen thrombophilia)","Wells DVT: active cancer, paralysis หรือเข้าเฝือก, ติดเตียง &gt;3 วันหรือผ่าตัดใหญ่ใน 12 สัปดาห์, กดเจ็บตามแนว deep vein, ขาบวมทั้งขา, น่องโตกว่าอีกข้าง &gt;3 cm, pitting edema, collateral superficial veins, เคยเป็น DVT; ลบ 2 ถ้ามีโรคอื่นที่น่าเป็นพอกัน","Wells ≥2 (likely) → compression ultrasound; ≤1 (unlikely) → D-dimer ก่อน ลบตัด DVT ได้ บวกทำ ultrasound","Proximal ultrasound ลบแต่ยังสงสัยมาก → ตรวจ D-dimer หรือทำ ultrasound ซ้ำใน 6–8 วัน (NICE) หรือทำ whole-leg ultrasound","สงสัย PE → CTPA (หรือ V/Q scan ในไตวาย ตั้งครรภ์); venography เป็น gold standard เดิมที่ invasive","รักษา: DOAC (rivaroxaban, apixaban) หรือ LMWH ตามด้วย warfarin อย่างน้อย 3 เดือนสำหรับ provoked DVT","ดูข้อ 683, 758, 759, 760, 762 (vascular)"],"notes":"ไฟล์เฉลย บท vas แถว 4: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับ: \"คนไข้ลงมาจากเครื่องบิน สงสัย DVT ทำไรดี\" ช้อย A–D (ต้นฉบับสะกด <b>\"Trendelunberg\"</b> — เราเขียน Trendelenburg test); เราเติมใน stem ว่ามีน่องซ้ายบวม กดเจ็บ อุ่นข้างเดียว และ pretest probability สูง เพื่อให้ตอบ duplex ได้ข้อเดียว; ช้อย E แต่งเพิ่ม","mnemonic":"<b>Likely → Look (ultrasound), Unlikely → D-dimer</b>","guide":"ASH VTE diagnosis 2018; NICE NG158 2020","variants":["หญิงอายุ 35 ปี ปวดน่องเล็กน้อยหลังวิ่ง ไม่บวม Wells score 0 → ตรวจ D-dimer ถ้าลบตัด DVT ได้","ชายหลังบิน 12 ชม. มีขาซ้ายบวม แล้วหอบเหนื่อยเฉียบพลัน HR 120 SpO₂ 90% BP ปกติ → CT pulmonary angiography","ผู้ป่วยเส้นเลือดขอดที่ขา ยกขาให้เลือดไหลออก กดที่ขาหนีบแล้วยืน เส้นเลือดไม่โป่งจนปล่อยมือ → saphenofemoral junction incompetence (Trendelenburg test บวก)"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ D มั่นใจสูง — สอดคล้องกับข้อสอบชุด 77D เรื่องเดียวกัน (claudication → exercise + medical therapy)","page":20,"page2":7,"orig":"Vascular 5","stem":"A 60-year-old patient has calf pain after walking 100 meters, every time he walks a long distance, relieved by rest. There is no rest pain or tissue loss. What is the most appropriate initial management?","gray":"60 yo patient, present เดิน 100 เมตรแล้วเจ็บ เป็นทุกครั้งที่เดินนาน ๆ ถามว่าหมอจะทำไรดี — A. Revascularization B. Endovas C. LMWH D. Exercise and …. E. Thrombolytic","opts":["Immediate surgical revascularization","Endovascular stenting of the artery","Therapeutic LMWH for 3 months","Supervised exercise and best medical therapy","Catheter-directed thrombolytic therapy"],"ans":3,"key":"D Exercise and …. (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ปวดน่องเมื่อเดินระยะเท่าเดิม (100 เมตร) หายเมื่อพัก ไม่มี rest pain หรือแผล = <b>intermittent claudication</b> จาก chronic PAD ระยะคงที่ → ถามการรักษาเริ่มต้น","why":"Claudication มีความเสี่ยงตัดขาต่ำ (major amputation ใน 5 ปี &lt;5%) แต่เสี่ยง <b>MI/stroke/cardiovascular death สูง</b> → การรักษาเริ่มต้นคือ <b>guideline-directed medical therapy</b> (เลิกบุหรี่, high-intensity statin, antiplatelet aspirin หรือ clopidogrel ± rivaroxaban 2.5 mg bid ในกลุ่มที่เลือดออกต่ำ, คุม BP และเบาหวาน) ร่วมกับ <b>supervised exercise therapy</b> 30–45 นาทีต่อครั้ง อย่างน้อย 3 ครั้งต่อสัปดาห์ นานอย่างน้อย 12 สัปดาห์ (เดินจนปวดปานกลาง พัก แล้วเดินต่อ) ซึ่งเพิ่มระยะเดินได้ชัด ± <b>cilostazol</b> (ห้ามใน heart failure); revascularization พิจารณาเมื่ออาการ <b>จำกัดชีวิตประจำวัน</b> แม้ได้ GDMT + exercise แล้ว 3–6 เดือน","wrong":{"A":"Surgical revascularization ไม่ใช่การรักษาเริ่มต้นของ claudication เพราะความเสี่ยงตัดขาต่ำและมีความเสี่ยงจากการผ่าตัด; จะถูกถ้าโจทย์เป็น CLTI (rest pain, แผล, gangrene) หรือ lifestyle-limiting claudication ที่ล้มเหลวจากการรักษาด้วยยาและ exercise และ anatomy เหมาะกับ bypass","B":"Endovascular stenting ใช้เมื่อ claudication จำกัดชีวิตประจำวันหลังได้ GDMT + supervised exercise แล้วไม่ดีขึ้น (โดยเฉพาะ aortoiliac lesion) ไม่ใช่ทำทันที; จะถูกถ้าโจทย์ให้ claudication ที่สะโพก ก้นจากรอยตีบ iliac artery สั้น ๆ ที่ยังเดินได้ไม่ถึง 50 เมตรหลังรักษาครบ","C":"LMWH รักษา VTE ไม่มีบทบาทใน chronic PAD; จะถูกถ้าโจทย์เป็น DVT ในผู้ป่วยมะเร็งหรือ acute limb ischemia ระหว่างรอผ่าตัด (ใช้ UFH)","E":"Thrombolysis ใช้ใน <b>acute limb ischemia</b> class I–IIa (เริ่มภายใน 14 วัน) หรือ graft thrombosis ไม่ใช่ claudication เรื้อรัง และเสี่ยงเลือดออก; จะถูกถ้าโจทย์เป็นขาขาดเลือดเฉียบพลันที่ไม่มี motor deficit"},"trap":"เห็นอาการขาดเลือดแล้วรีบเลือก revascularization — claudication รักษาด้วย exercise + ยาก่อนเสมอ; การแยกจาก CLTI คือมี rest pain หรือ tissue loss หรือไม่; และต้องแยกจาก neurogenic claudication (ปวดเวลายืนนาน ดีขึ้นเมื่อนั่งก้ม ชีพจรปกติ)","summary":["Intermittent claudication: ปวดกล้ามเนื้อขาเมื่อเดินระยะคงที่ หายเมื่อพักไม่กี่นาที; ตำแหน่งปวดบอกระดับรอยโรค (ก้น/สะโพก = aortoiliac, น่อง = femoropopliteal)","วินิจฉัยด้วย <b>resting ABI ≤0.90</b>; 0.91–0.99 borderline; &gt;1.40 noncompressible (ใช้ TBI); ABI ปกติแต่อาการชัด → exercise ABI","GDMT: เลิกบุหรี่, high-intensity statin, antiplatelet (aspirin หรือ clopidogrel), rivaroxaban 2.5 mg bid + aspirin ในผู้ที่เสี่ยงเลือดออกต่ำ, ACEI/ARB, คุมเบาหวาน, ดูแลเท้า","Supervised exercise therapy: 30–45 นาที ≥3 ครั้ง/สัปดาห์ ≥12 สัปดาห์; ทางเลือก structured home-based exercise","Cilostazol (PDE3 inhibitor) เพิ่มระยะเดิน ห้ามใน heart failure ทุกระดับ","Revascularization ใน claudication เมื่อ lifestyle-limiting และตอบสนองไม่พอต่อ GDMT + exercise; ไม่ทำเพื่อป้องกันการลุกลามเป็น CLTI","Natural history: ส่วนใหญ่คงที่, ราว 1 ใน 5 แย่ลง, major amputation น้อย แต่ cardiovascular mortality สูง","ดูข้อ 758, 759, 760, 761 (vascular; 78 = CLTI ระยะที่ต้อง revascularization)"],"notes":"ไฟล์เฉลย บท vas แถว 5: <b>D</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับช้อย D จดไม่จบ <b>\"Exercise and ….\"</b> — เราเขียนเป็น \"Supervised exercise and best medical therapy\"; ช้อยอื่นแปลจากต้นฉบับ (A. Revascularization → Immediate surgical revascularization, B. Endovas → Endovascular stenting of the artery, C. LMWH → Therapeutic LMWH for 3 months, E. Thrombolytic → Catheter-directed thrombolytic therapy); stem เติม \"relieved by rest\" และ \"no rest pain or tissue loss\" ให้ชัดว่าเป็น claudication","mnemonic":"<b>Claudication = เดินก่อน ผ่าทีหลัง</b>; CLTI = ผ่าก่อน","guide":"2024 ACC/AHA PAD guideline; ESC peripheral arterial and aortic diseases 2024","variants":["ชายสูบบุหรี่ ปวดน่องเมื่อเดิน 200 เมตร ABI 0.7 ยังไม่เคยรักษา → เลิกบุหรี่ statin antiplatelet และ supervised exercise therapy 12 สัปดาห์","ผู้ป่วย claudication ที่ได้ exercise + ยาครบ 6 เดือนแล้วยังเดินได้ไม่ถึง 50 เมตร ทำงานไม่ได้ CTA พบ common iliac stenosis สั้น → endovascular stenting","ผู้ป่วยปวดขาสองข้างเมื่อยืนหรือเดินลงเนิน ดีขึ้นเมื่อนั่งก้มตัว ชีพจรเท้าปกติ ABI 1.1 → neurogenic claudication ทำ MRI lumbar spine"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ D มั่นใจสูง — สอดคล้องกับข้อสอบชุด 76D เรื่องเดียวกัน (definitive chemoradiation) และต่างจากข้อสอบชุด 76A, 77A, 77B ที่ผู้ป่วยแข็งแรงพอผ่าตัด (T2N0 → esophagectomy)","page":20,"page2":7,"orig":"Esophagus 1","stem":"A patient has resectable T2N0 esophageal cancer but has severe COPD and multiple other comorbidities that make him medically unfit for esophagectomy. What is the most appropriate treatment?","gray":"คนไข้เป็นมะเร็ง Esophagus T2N0 Resectable แต่คนไข้มี severe COPD และ Comorbid อื่น ๆ เยอะ ถามว่ารักษาไงดี — A. ใส่ stent B. Neoadjuvant + Sx C. Surgery D. Definitive chemoradiation","opts":["Esophageal stent","Neoadjuvant therapy, then surgery","Esophagectomy alone","Definitive chemoradiation","Best supportive care alone"],"ans":3,"key":"D Definitive chemoradiation (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"มะเร็งหลอดอาหาร T2N0 ที่ <b>ผ่าตัดได้ทางเทคนิค</b> แต่ผู้ป่วย <b>ไม่แข็งแรงพอผ่าตัด</b> (severe COPD + โรคร่วมมาก) → ต้องเลือกการรักษาเพื่อหายขาดที่ไม่ต้องผ่าตัด","why":"Esophagectomy เป็นผ่าตัดใหญ่ที่ต้องเข้าช่องอกและท้อง (Ivor Lewis หรือ McKeown) มี pulmonary complication สูงมาก ผู้ป่วย severe COPD จึงเป็น medically inoperable → NCCN แนะนำ <b>definitive chemoradiation</b> (50–50.4 Gy ร่วมกับ chemotherapy เช่นสูตร carboplatin/paclitaxel, FOLFOX หรือ cisplatin/5-FU) เป็นการรักษาเพื่อหายขาดสำหรับผู้ป่วยที่ผ่าตัดไม่ได้หรือปฏิเสธผ่าตัด รวมถึง cervical esophageal cancer; โดยเฉพาะ SCC ตอบสนองต่อ chemoradiation ดี (pathologic complete response ราว 49% ในกลุ่ม SCC ของทดลอง CROSS)","wrong":{"A":"Esophageal stent เป็น <b>palliation</b> ของ dysphagia ในโรคระยะแพร่กระจายหรือผู้ที่อายุขัยสั้น ไม่ใช่การรักษาเพื่อหายขาด; จะถูกถ้าโจทย์เป็น metastatic esophageal cancer ที่กลืนอะไรไม่ได้หรือมี tracheoesophageal fistula (covered stent)","B":"Neoadjuvant chemoradiation (CROSS) หรือ perioperative FLOT สำหรับ adenocarcinoma แล้วผ่าตัด เป็นมาตรฐานของ T3–T4a หรือ N+ (และ T2N0 high risk) <b>ในผู้ที่ผ่าตัดได้</b> แต่ผู้ป่วยรายนี้ผ่าตัดไม่ได้; จะถูกถ้าโจทย์เป็นผู้ป่วยแข็งแรงที่เป็น T3N1","C":"Esophagectomy alone เหมาะกับผู้ที่ <b>แข็งแรง</b> และเป็น T1b–T2N0 low risk (ก้อน &lt;3 cm well differentiated); จะถูกถ้าโจทย์ให้ผู้ป่วยไม่มีโรคร่วมที่เป็น T2N0 ตามข้อสอบชุด 76A, 77A, 77B เรื่องเดียวกัน","E":"Best supportive care อย่างเดียวสำหรับผู้ที่ performance status แย่มาก (ECOG 3–4) หรือปฏิเสธการรักษาทุกอย่าง; ผู้ป่วยรายนี้ยังได้ประโยชน์จาก chemoradiation เพื่อหายขาดได้; จะถูกถ้าโจทย์เป็นผู้ป่วยติดเตียงที่มีโรคแพร่กระจาย"},"trap":"เห็น \"resectable\" แล้วตอบ surgery ทันที — resectable คือ <b>ตัวโรค</b> ผ่าได้ แต่ <b>ตัวผู้ป่วย</b> (operability) ต้องผ่าได้ด้วย; ผู้ป่วยที่ผ่าตัดไม่ได้ทางการแพทย์ยังมีทางรักษาเพื่อหายขาดด้วย definitive chemoradiation ไม่ใช่แค่ stent","summary":["Staging: EGD + biopsy → CT chest/abdomen, PET-CT, EUS (T และ N), bronchoscopy เมื่อก้อนอยู่ระดับ carina ขึ้นไป","Tis/T1a: endoscopic resection (EMR/ESD) ± ablation; T1b–T2N0 low risk ในผู้แข็งแรง: esophagectomy","T2N0 high risk, T3–T4a, N+: neoadjuvant chemoradiation (CROSS: carboplatin/paclitaxel + 41.4 Gy) แล้วผ่าตัด; adenocarcinoma ใช้ perioperative FLOT ได้ (ทดลอง ESOPEC: FLOT ดีกว่า CROSS ด้าน survival)","Definitive chemoradiation 50–50.4 Gy: ผู้ป่วยผ่าตัดไม่ได้ทางการแพทย์ ปฏิเสธผ่าตัด cervical esophagus หรือ SCC ที่เลือกเฝ้าดูหลังตอบสนองครบ","T4b หรือ metastatic: systemic therapy (chemotherapy + immunotherapy ตาม PD-L1/HER2) และ palliation dysphagia ด้วย stent หรือ RT","SCC พบมากในเอเชียรวมไทย สัมพันธ์บุหรี่ แอลกอฮอล์ อยู่กลางถึงบน; adenocarcinoma สัมพันธ์ GERD, Barrett, อ้วน อยู่ distal/EGJ","ดูข้อ 764, 765, 766, 768 (esophagus; 85 = มะเร็งหลอดอาหารกับเสียงแหบ)"],"notes":"ไฟล์เฉลย บท eso แถว 1: <b>D</b> (ช่องคำอธิบายว่าง)<br>ช้อยต้นฉบับ A. ใส่ stent, B. Neoadjuvant + Sx, C. Surgery, D. Definitive chemoradiation แปลเป็นอังกฤษ (C. Surgery → Esophagectomy alone); stem เติมคำว่า medically unfit for esophagectomy ตามความหมายของต้นฉบับ \"severe COPD และ Comorbid อื่น ๆ เยอะ\"; ช้อย E แต่งเพิ่ม","mnemonic":"<b>Resectable ≠ Operable</b>: โรคผ่าได้แต่คนผ่าไม่ไหว → definitive chemoradiation","guide":"NCCN Esophageal and EGJ Cancers 2025","variants":["ชายอายุ 58 ปี แข็งแรงดี เป็น SCC กลางหลอดอาหาร T3N1M0 → neoadjuvant chemoradiation แล้ว esophagectomy","ผู้ป่วย SCC ที่ cervical esophagus ห่าง cricopharyngeus 3 cm → definitive chemoradiation (เลี่ยง laryngectomy)","ผู้ป่วยมะเร็งหลอดอาหารแพร่ไปตับ กลืนน้ำลายไม่ได้ ไอทุกครั้งที่ดื่มน้ำ esophagogram พบ tracheoesophageal fistula → covered esophageal stent (± airway stent)"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง — ข้อคล้ายข้อสอบชุด 77B, 77D เรื่องเดียวกัน (progressive dysphagia → EGD/CA esophagus) และชุด 76C","page":20,"page2":7,"orig":"Esophagus 2","stem":"A patient has progressive dysphagia, first to solids and now even to liquids. A barium swallow is inconclusive. What is the next investigation?","gray":"คนไข้อาการกลืนอาหารลำบากมากขึ้นเรื่อย ๆ ตอนแรกกิน solid หลัง ๆ เหลือแค่ liquid ตรวจ barium swallowing แล้ว inconclusive ถามว่าทำไรต่อ — A. EGD B. Esophageal manometry C. CT","opts":["EGD","Esophageal manometry","CT of the chest","Repeat barium swallow","24-hour pH monitoring"],"ans":0,"key":"A EGD (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"กลืนลำบาก <b>แย่ลงเรื่อย ๆ</b> จากอาหารแข็งไปถึงของเหลว = ลักษณะของ <b>mechanical obstruction ที่ลุกลาม</b> (มะเร็ง, peptic stricture) และ barium ไม่ให้คำตอบ → ต้องการการตรวจที่เห็นรอยโรคโดยตรงและตัดชิ้นเนื้อได้","why":"<b>EGD</b> เป็นการตรวจหลักของ dysphagia ทุกราย โดยเฉพาะเมื่อมี alarm features (อาการลุกลาม อายุมาก น้ำหนักลด เลือดออก ซีด) เพราะเห็นเยื่อบุโดยตรง <b>ตัด biopsy</b> ยืนยันมะเร็งได้ และรักษาบางภาวะได้ในครั้งเดียว (dilate stricture, เอา food bolus ออก, biopsy หา eosinophilic esophagitis); barium swallow เป็นเพียง adjunct ช่วยดู anatomy ที่ซับซ้อน (diverticulum, ring, stricture ยาว) — ASGE แนะนำให้ส่องกล้องเป็นการตรวจแรกหรือถัดไปในผู้ป่วย esophageal dysphagia","wrong":{"B":"Esophageal manometry ใช้วินิจฉัย <b>motility disorder</b> (achalasia, spasm) และต้องทำ <b>หลัง</b> EGD ตัด mechanical obstruction แล้ว; จะถูกถ้าโจทย์ให้ EGD ปกติแล้วมีกลืนลำบากทั้งของแข็งและของเหลวตั้งแต่แรก (ดูข้อ 766)","C":"CT chest ใช้ <b>staging</b> หลังได้ผล biopsy ว่าเป็นมะเร็งแล้ว (ร่วมกับ PET-CT, EUS) หรือดูการกดเบียดจากภายนอก แต่ไม่ได้ชิ้นเนื้อ; จะถูกถ้าโจทย์ให้ biopsy เป็น SCC แล้วถามการตรวจระยะโรค","D":"Barium ซ้ำไม่ได้ข้อมูลเพิ่มและไม่ได้ชิ้นเนื้อ ทำให้วินิจฉัยช้า; จะพอเป็นคำตอบถ้าโจทย์สงสัย Zenker diverticulum ก่อนส่องกล้อง (เสี่ยงทะลุ) หรือต้องการ timed barium esophagram ใน achalasia","E":"24-hour pH monitoring ใช้ยืนยัน GERD ที่ EGD ปกติ ไม่ตอบรอยโรคที่ทำให้อุดกั้น; จะถูกถ้าโจทย์เป็นแสบร้อนกลางอกที่ไม่ตอบสนอง PPI และ EGD ปกติ หรือก่อนผ่าตัด fundoplication"},"trap":"เห็นคำว่า barium inconclusive แล้วเลือก manometry เพราะนึกถึง achalasia — ลำดับ \"แข็งก่อนแล้วเหลว\" แบบลุกลามคือ mechanical obstruction ต้อง EGD ก่อน; แม้สงสัย achalasia ก็ต้อง EGD ตัด pseudoachalasia ก่อน manometry","summary":["Oropharyngeal dysphagia (เริ่มกลืนไม่ได้ สำลัก ไอ ไหลออกจมูก) → videofluoroscopic swallow study; esophageal dysphagia (ติดหลังกลืน) → EGD","Mechanical: เริ่มที่ของแข็งแล้วลุกลามถึงของเหลว (มะเร็ง, peptic stricture, ring/web, eosinophilic esophagitis)","Motility: ของแข็งและของเหลวพร้อมกันตั้งแต่แรก (achalasia, spastic disorder, scleroderma)","EGD + biopsy เป็น investigation of choice; biopsy หลายตำแหน่ง (≥6 ชิ้น) ช่วยวินิจฉัยมะเร็งและ eosinophilic esophagitis","หลังยืนยันมะเร็ง: staging ด้วย CT, PET-CT, EUS; manometry ทำเมื่อ EGD ไม่พบรอยโรคอุดกั้น","Alarm features: อายุ &gt;50–60 ปี, น้ำหนักลด, odynophagia, GI bleeding, ซีด, ลุกลามเร็ว → ส่องกล้องเร็ว","ดูข้อ 763, 765, 766 (86 = dysphagia ที่ EGD ปกติ → manometry; 83, 85 = มะเร็งหลอดอาหาร)"],"notes":"ไฟล์เฉลย บท eso แถว 2: <b>A</b> (ช่องคำอธิบายว่าง)<br>ช้อยต้นฉบับ A. EGD, B. Esophageal manometry, C. CT (เราเขียน CT of the chest); ช้อย D, E แต่งเพิ่ม","mnemonic":"<b>แข็งไปเหลว = ก้อนขวาง (mechanical) → ส่องก่อน</b>; แข็งเหลวพร้อมกัน = กล้ามเนื้อ (motility) → manometry หลังส่อง","guide":"ASGE role of endoscopy in dysphagia 2014; NCCN Esophageal and EGJ Cancers 2025","variants":["ชายอายุ 65 ปี ดื่มเหล้า สูบบุหรี่ กลืนลำบากลุกลาม 3 เดือน น้ำหนักลด 8 kg → EGD + biopsy (สงสัย SCC หลอดอาหาร)","ชายอายุ 25 ปี มีประวัติภูมิแพ้ อาหารติดคอเป็นครั้งคราว EGD พบ ring หลายวงและร่องตามยาว → biopsy หา eosinophilic esophagitis (≥15 eos/hpf)","หญิงอายุ 40 ปี กลืนลำบากทั้งของแข็งและของเหลวมา 2 ปี น้ำหนักคงที่ EGD ปกติ → high-resolution manometry"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"คีย์ตอบ A — ความมั่นใจต่ำถึงปานกลาง เพราะต้นฉบับไม่ได้บอกว่าถามอะไร: ถ้าข้อสอบจริงถาม \"most likely\" ว่ามะเร็งชนิดหรือตำแหน่งไหนทำให้เสียงแหบ คำตอบที่ถูกตาม anatomy คือ SCC ส่วนคอหรือส่วนอกตอนบน (ซึ่งต้นฉบับไม่ได้จดไว้) และคีย์ A จะผิด; เราจึงตั้งคำถามเป็น LEAST likely ซึ่งเป็นการตีความเดียวที่ทำให้คีย์ A ถูกต้อง; สอดคล้องกับข้อสอบชุด 77C เรื่องเดียวกัน (hoarseness = RLN invasion)","page":20,"page2":7,"orig":"Esophagus 3","stem":"A patient with esophageal cancer has dysphagia and hoarseness of voice. Which tumor is LEAST likely to cause this presentation?","gray":"CA Esophagus มี dysphagia มี Hoarseness of voice — A. Adenocarcinoma of distal esophagus B. Leiomyosarcoma of esophagus","opts":["Adenocarcinoma of the distal esophagus","Leiomyosarcoma of the upper thoracic esophagus","Squamous cell carcinoma of the upper thoracic esophagus","Squamous cell carcinoma at the level of the aortic arch","Squamous cell carcinoma of the cervical esophagus"],"ans":0,"key":"A Adenocarcinoma of distal esophagus (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ ต้นฉบับไม่ได้จดว่าถามอะไร — ตีความเป็น \"LEAST likely\" ให้สอดคล้องกับคีย์ (มะเร็งส่วนปลายไกลจาก recurrent laryngeal nerve) และเติมตำแหน่ง upper thoracic ในช้อย B; ถ้าข้อสอบจริงถาม \"most likely\" คำตอบต้องเป็น SCC ส่วนบน/กลาง ซึ่งไม่มีในต้นฉบับ (คีย์ A จะผิด)","interp":"เสียงแหบในมะเร็งหลอดอาหาร = <b>recurrent laryngeal nerve (RLN)</b> ถูกก้อนลุกลามหรือต่อมน้ำเหลืองกด → ต้องดูว่าก้อนชนิดและตำแหน่งใด <b>อยู่ไกล RLN ที่สุด</b>","why":"RLN ซ้ายอ้อมใต้ <b>aortic arch</b> (ระดับราว T4–T5 ที่ aortopulmonary window) ส่วน RLN ขวาอ้อมใต้ <b>right subclavian artery</b> แล้วทั้งสองขึ้นไปใน tracheoesophageal groove ข้างหลอดอาหารส่วนคอและส่วนอกตอนบน → ก้อนที่ <b>cervical, upper thoracic หรือระดับ aortic arch</b> (มักเป็น SCC ซึ่งเป็นชนิดหลักในเอเชียและไทย) หรือต่อมน้ำเหลืองบริเวณนั้นทำให้เสียงแหบได้ และมักบ่งว่าโรคลุกลามเฉพาะที่มากจนผ่าตัดไม่ได้; ส่วน <b>adenocarcinoma อยู่ distal esophagus/EGJ</b> (Barrett, GERD, อ้วน) อยู่ใต้ระดับที่ RLN อ้อมกลับขึ้น จึงทำให้เสียงแหบน้อยที่สุด","wrong":{"B":"Leiomyosarcoma พบน้อยมาก แต่ถ้าก้อนอยู่ที่ <b>upper thoracic esophagus</b> ก็โตกดเบียด RLN ได้เช่นเดียวกับก้อนอื่นในตำแหน่งนั้น; จะเป็นคำตอบถ้าถามชนิดมะเร็งหลอดอาหารที่พบน้อยที่สุดในช้อย หรือถ้าช้อยไม่ระบุตำแหน่ง","C":"SCC หลอดอาหารส่วนอกตอนบนอยู่ติด tracheoesophageal groove ที่ RLN ทั้งสองข้างวิ่งผ่าน จึงทำให้เสียงแหบได้บ่อย; จะเป็นคำตอบถ้าโจทย์ถาม most likely","D":"SCC ระดับ aortic arch อยู่ตรงตำแหน่งที่ <b>left RLN</b> อ้อมใต้ arch จึงทำให้ left vocal cord palsy ได้ (ต่อมน้ำเหลือง aortopulmonary window ก็กดได้); จะเป็นคำตอบถ้าโจทย์ถามตำแหน่งที่ทำให้ left RLN palsy","E":"SCC ส่วนคออยู่ติด RLN และกล่องเสียงโดยตรง ทำให้เสียงแหบได้เร็ว และมักรักษาด้วย definitive chemoradiation; จะเป็นคำตอบถ้าโจทย์ถาม most likely ร่วมกับก้อนใต้ cricopharyngeus"},"trap":"รีบตอบโดยไม่สังเกตคำว่า LEAST — ให้คิดจาก anatomy ของ RLN: ก้อนยิ่งอยู่สูงยิ่งเสี่ยงเสียงแหบ; adenocarcinoma ส่วนปลายไกลที่สุด; อีกกับดักคือคิดว่าเสียงแหบเป็นอาการระยะแรก ซึ่งจริง ๆ บ่งโรคลุกลามมาก","summary":["SCC: พบมากสุดทั่วโลกและในเอเชีย/ไทย, ปัจจัยเสี่ยงบุหรี่ แอลกอฮอล์ อาหารร้อน nitrosamine achalasia caustic injury, อยู่ส่วนกลางถึงบน","Adenocarcinoma: พบมากในประเทศตะวันตก, ปัจจัยเสี่ยง GERD, Barrett esophagus, อ้วน, ชาย, อยู่ distal esophagus/EGJ","RLN: ซ้ายอ้อมใต้ aortic arch, ขวาอ้อมใต้ right subclavian artery → มะเร็งส่วนคอ ส่วนอกตอนบน ระดับ arch หรือ nodal metastasis กดทำให้เสียงแหบ","อาการลุกลามเฉพาะที่: hoarseness (RLN), ไอสำลักขณะดื่มน้ำ (tracheoesophageal fistula), Horner syndrome, เจ็บหน้าอก, hematemesis จาก aortoesophageal fistula","เสียงแหบ = vocal cord palsy มักบ่ง T4b หรือ nodal disease ที่ลุกลาม → ส่วนใหญ่ไม่ผ่าตัด รักษาด้วย definitive chemoradiation หรือ palliative","ตรวจ laryngoscopy ยืนยัน vocal cord palsy; bronchoscopy เมื่อก้อนระดับ carina ขึ้นไปเพื่อดูการลุกลามเข้าหลอดลม","ดูข้อ 763, 764 (มะเร็งหลอดอาหารและการตรวจ dysphagia)"],"notes":"ไฟล์เฉลย บท eso แถว 3: <b>A</b> (ช่องคำอธิบายว่าง)<br><b>ต้นฉบับไม่ได้จดว่าคำถามคืออะไร</b> มีแค่ \"CA Esophagus มี dysphagia มี Hoarseness of voice\" กับช้อย A. Adenocarcinoma of distal esophagus และ B. Leiomyosarcoma of esophagus — เราตีความคำถามเป็น <b>\"LEAST likely\"</b> ให้สอดคล้องกับคีย์ A, เติมตำแหน่ง \"upper thoracic\" ในช้อย B ให้เหลือคำตอบเดียว, และแต่งช้อย C–E เป็น SCC ในตำแหน่งที่ทำให้เสียงแหบได้","mnemonic":"<b>ยิ่งสูงยิ่งแหบ</b>: cervical, upper thoracic, ระดับ arch → RLN; distal adeno → ไม่แหบ","guide":"NCCN Esophageal and EGJ Cancers 2025; Sabiston 21st ed.","variants":["ชายอายุ 62 ปี เป็น SCC หลอดอาหารที่ 24 cm จาก incisor มีเสียงแหบ laryngoscopy พบ left vocal cord palsy → ก้อนหรือต่อมน้ำเหลืองกด left RLN บ่งโรคลุกลาม ส่วนใหญ่ไม่ผ่าตัด","ผู้ป่วยมะเร็งหลอดอาหารส่วนกลาง ไอสำลักทุกครั้งที่ดื่มน้ำ และปอดอักเสบซ้ำ → tracheoesophageal fistula ใส่ covered stent","ชายอ้วน GERD นาน 20 ปี มี Barrett esophagus กลืนลำบากลุกลาม → adenocarcinoma ส่วนปลายหรือ EGJ"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูงเมื่อ EGD ทำแล้ว — ถ้าข้อสอบจริงไม่ได้บอกว่าส่องกล้องแล้ว แนวทาง ACG 2020 ให้ทำ EGD ก่อนเพื่อตัด pseudoachalasia (ข้อสอบชุด 76C เรื่องเดียวกันตอบ EGD) แต่ในทางปฏิบัติเมื่อถามการตรวจยืนยัน achalasia คำตอบคือ manometry ตามข้อสอบชุด 76A, 77A, 77C, 77D เรื่องเดียวกัน เราจึงเติม EGD ปกติใน stem ให้ไม่ขัดกัน","page":20,"page2":7,"orig":"Esophagus 4","stem":"A patient has dysphagia to both solids and liquids with regurgitation of undigested food. A barium swallow shows no abnormality, and upper endoscopy shows no mucosal lesion or mechanical obstruction. What is the next investigation?","gray":"ให้อาการ Achalasia มา ทำ barium แล้วไม่เจอไรเลย ถามว่าทำไรต่อ — A. Esophageal manometry B. EGD C. EUS D. CT","opts":["Esophageal manometry","EGD","EUS","CT of the chest","24-hour pH monitoring"],"ans":0,"key":"A Esophageal manometry (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: เติมใน stem ว่าส่องกล้อง (EGD) แล้วไม่พบรอยโรค/การอุดตัน — คลังตอบให้ทำ EGD ก่อนเสมอเพื่อตัด pseudoachalasia (ชุด 76C); ถ้ายังไม่ได้ EGD ช้อย B จะเป็นคำตอบ","interp":"กลืนลำบาก <b>ทั้งของแข็งและของเหลว</b> + สำรอกอาหารที่ไม่ย่อย = อาการของ <b>motility disorder</b>; barium ปกติ และ EGD ไม่พบรอยโรคหรือการอุดกั้น → ต้องการการตรวจที่วัดการบีบตัวของหลอดอาหารและการคลายตัวของ LES","why":"<b>High-resolution esophageal manometry</b> เป็น <b>gold standard</b> ในการวินิจฉัย achalasia และ motility disorder อื่น (Chicago Classification v4.0): <b>IRP สูง</b> (LES คลายตัวไม่ได้) + <b>100% failed peristalsis</b> = type I (ไม่มี pressurization) หรือ type II (panesophageal pressurization ≥20% ของการกลืน), ส่วน <b>premature (spastic) contraction</b> ≥20% = type III; barium อาจ <b>ปกติ</b> ในระยะแรก (ความไวราว 2 ใน 3) จึงไม่ตัดโรค; ก่อนทำ manometry ต้องมี <b>EGD</b> ตัด mechanical obstruction และ <b>pseudoachalasia</b> จากมะเร็ง EGJ ก่อนเสมอ ซึ่งผู้ป่วยรายนี้ทำแล้ว","wrong":{"B":"EGD ต้องทำ <b>ก่อน</b> manometry เพื่อตัดมะเร็งที่ EGJ (pseudoachalasia) และ stricture แต่ในโจทย์นี้ทำแล้วไม่พบรอยโรค การส่องซ้ำไม่ได้ข้อมูลการบีบตัว; จะถูกถ้าโจทย์ยังไม่ได้ส่องกล้อง (ข้อสอบชุด 76C เรื่องเดียวกันตอบ EGD ก่อน)","C":"EUS ใช้เมื่อ <b>สงสัย pseudoachalasia</b> (อายุมาก น้ำหนักลดมาก อาการเกิดเร็ว &lt;1 ปี ส่องกล้องดันผ่าน LES ยาก) เพื่อหาก้อนใต้เยื่อบุหรือนอกผนัง และใช้ staging มะเร็ง; จะถูกถ้าโจทย์ให้ผู้สูงอายุน้ำหนักลดเร็วที่ manometry เข้าได้กับ achalasia","D":"CT chest ใช้หาก้อนนอกหลอดอาหารที่กดเบียดหรือ staging มะเร็ง และเห็นหลอดอาหารขยายใน achalasia ระยะท้ายได้ แต่ไม่ใช่การตรวจวินิจฉัย motility; จะถูกถ้าโจทย์สงสัย pseudoachalasia จากมะเร็งที่อื่น (ปอด, gastric cardia)","E":"24-hour pH monitoring ใช้วินิจฉัย GERD และประเมินกรดไหลย้อนหลังรักษา achalasia (โดยเฉพาะหลัง POEM); ใน achalasia อาจได้ผลบวกลวงจากอาหารค้างหมักเป็นกรด; จะถูกถ้าโจทย์เป็นแสบร้อนกลางอกที่ไม่ตอบสนอง PPI และ EGD ปกติ"},"trap":"คิดว่า barium ปกติแล้วตัด achalasia ได้ — barium ไวไม่พอในระยะแรก; และอย่าข้าม EGD ไปทำ manometry เลย เพราะ pseudoachalasia จากมะเร็ง EGJ ให้ภาพ manometry เหมือน achalasia ได้","summary":["Achalasia: สูญเสีย inhibitory neurons ใน myenteric (Auerbach) plexus → LES คลายตัวไม่ได้ + aperistalsis; ในอเมริกาใต้มีสาเหตุจาก Chagas disease","อาการ: dysphagia ทั้งของแข็งและของเหลว, สำรอกอาหารไม่ย่อย, เจ็บอก, น้ำหนักลด, ไอสำลักกลางคืน","ลำดับการตรวจ: EGD (ตัด pseudoachalasia) → high-resolution manometry (gold standard) → timed barium esophagram (bird's beak, ประเมินการระบาย)","Chicago v4.0: IRP สูง + 100% failed peristalsis = type I หรือ II (II ตอบสนองการรักษาดีที่สุด); spastic contraction ≥20% = type III (ตอบสนอง POEM ดีกว่า)","รักษา: POEM, laparoscopic Heller myotomy + Dor fundoplication, pneumatic dilation; Botox injection สำหรับผู้ที่ผ่าตัดไม่ได้","Achalasia เพิ่มความเสี่ยง SCC หลอดอาหาร; pseudoachalasia คิดเมื่ออายุ &gt;60 ปี อาการ &lt;1 ปี น้ำหนักลดมาก","ดูข้อ 764, 763, 765 (84 = dysphagia แบบลุกลาม → EGD ก่อน)"],"notes":"ไฟล์เฉลย บท eso แถว 4: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับ: \"ให้อาการ Achalasia มา ทำ barium แล้วไม่เจอไรเลย ถามว่าทำไรต่อ\" — ผู้จดไม่ได้จดอาการจริงไว้ เราบรรยายอาการ (dysphagia ทั้งของแข็งและของเหลว + regurgitation ของอาหารไม่ย่อย) โดยไม่ใส่คำว่า achalasia และ<b>เติมว่าส่องกล้องแล้วไม่พบรอยโรค</b> เพื่อให้คีย์ manometry เป็นคำตอบเดียว; ช้อยต้นฉบับ A–D (D. CT → CT of the chest); ช้อย E แต่งเพิ่ม","mnemonic":"<b>ส่องก่อน วัดแรงทีหลัง</b>: EGD → Manometry → Timed barium","guide":"ACG achalasia 2020; Chicago Classification v4.0 2021","variants":["หญิงอายุ 35 ปี กลืนลำบากทั้งของแข็งและของเหลว 1 ปี สำรอกอาหารเก่า ยังไม่เคยตรวจอะไร → EGD ก่อนเพื่อตัดรอยโรคอุดกั้นและ pseudoachalasia","ชายอายุ 72 ปี กลืนลำบาก 4 เดือน น้ำหนักลด 10 kg manometry เข้าได้กับ achalasia ส่องกล้องดันผ่าน EGJ ยาก → สงสัย pseudoachalasia ทำ EUS หรือ CT","Manometry พบ IRP สูง 100% failed peristalsis และ panesophageal pressurization ≥20% ของการกลืน → achalasia type II ตอบสนองดีต่อ pneumatic dilation, Heller myotomy หรือ POEM"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ B มั่นใจสูง — ถ้ามีช้อย antibiotic prophylaxis ก็ถือว่าให้ประโยชน์ด้าน mortality ชัดเจนเช่นกัน แต่ไม่อยู่ในช้อยของต้นฉบับ; สอดคล้องกับข้อสอบชุด 77C เรื่องเดียวกัน (variceal bleeding → somatostatin analogue)","page":20,"page2":7,"orig":"Esophagus 5","stem":"A patient with advanced chronic liver disease presents with hematemesis. After initial resuscitation, which drug would benefit the patient most?","gray":"ให้ประวัติคนไข้ที่มีโรคตับยม ๆ มา มีอาการอ้วกเป็นเลือด มาหาหมอ หมอ resuscitation แล้ว Which of the following would most benefit the patient — a. PPI b. Octreotide c. Propranolol","opts":["Proton pump inhibitor","Octreotide","Propranolol","Tranexamic acid","Vitamin K alone"],"ans":1,"key":"B Octreotide (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ผู้ป่วย <b>โรคตับเรื้อรังระยะท้าย</b> อาเจียนเป็นเลือด → ต้องคิดถึง <b>acute variceal hemorrhage</b> จาก portal hypertension ก่อน; ถามยาที่ให้ประโยชน์มากที่สุดหลัง resuscitation (ก่อนหรือระหว่างรอส่องกล้อง)","why":"Baveno VII แนะนำให้เริ่ม <b>vasoactive drug ทันทีที่สงสัย variceal bleeding</b> ก่อนส่องกล้อง: terlipressin, somatostatin หรือ <b>octreotide</b> (50 µg IV bolus แล้ว 50 µg/ชม.) ต่อเนื่อง <b>2–5 วัน</b> — octreotide ทำให้ splanchnic vasoconstriction ลด portal venous inflow และ portal pressure ช่วยหยุดเลือดและลด rebleeding; ร่วมกับ <b>antibiotic prophylaxis</b> (ceftriaxone 1 g/วัน ไม่เกิน 7 วัน ลด infection, rebleeding และ mortality — ไม่อยู่ในช้อย), EVL ภายใน 12 ชม. หลัง resuscitation, restrictive transfusion (ให้เลือดเมื่อ Hb ≤7 เป้าหมาย 7–8 g/dL) และ pre-emptive TIPS ภายใน 72 ชม. ในผู้ป่วยเสี่ยงสูง (Child C 10–13 หรือ Child B &gt;7 ที่มี active bleeding ขณะส่องกล้อง)","wrong":{"A":"PPI ให้ empirical ได้ก่อนส่องกล้องเพราะยังไม่รู้ว่าเป็น peptic ulcer หรือไม่ (ผู้ป่วยตับแข็งก็เป็นแผลได้) และให้ช่วงสั้นหลัง EVL ลด post-banding ulcer แต่ <b>ไม่ลด portal pressure</b> ไม่ช่วยหยุดเลือดจาก varices; จะถูกถ้าโจทย์เป็นผู้ป่วยไม่มีโรคตับที่กิน NSAID แล้ว UGIB","C":"Propranolol (NSBB) ใช้ <b>ป้องกัน</b> variceal bleeding (primary ใน varices ใหญ่ หรือ secondary ร่วมกับ EVL หลังหยุดเลือด) แต่ <b>ห้ามให้ช่วงเลือดออกเฉียบพลัน</b> เพราะลด BP และ HR ทำให้ compensate shock ไม่ได้; จะถูกถ้าโจทย์ถามการป้องกันเลือดออกซ้ำหลังหยุดเลือดแล้ว (หรือ carvedilol)","D":"Tranexamic acid <b>ไม่ลด mortality</b> ใน GI bleeding (HALT-IT 2020) และเพิ่ม VTE ไม่แนะนำในทั้ง variceal และ non-variceal bleeding; จะถูกในบริบท trauma ภายใน 3 ชม. (CRASH-2) หรือ postpartum hemorrhage","E":"Vitamin K แก้ INR ในโรคตับเรื้อรังไม่ได้เพราะตับสร้าง factor ไม่ได้ (ไม่ใช่ขาด vitamin K) และ INR ไม่สะท้อนความเสี่ยงเลือดออกในตับแข็ง; ไม่ช่วยหยุดเลือดจาก varices; จะถูกถ้าโจทย์เป็นผู้ป่วย obstructive jaundice หรือกิน warfarin เกินขนาด"},"trap":"เลือก propranolol เพราะจำว่า beta-blocker ใช้กับ varices — ใช้ <b>ป้องกัน</b> ไม่ใช่ช่วงเลือดออก; อีกกับดักคือให้เลือดมากจน Hb สูง ทำให้ portal pressure ขึ้นและเลือดออกซ้ำ (restrictive transfusion ดีกว่า)","summary":["Acute variceal hemorrhage: resuscitation (2 large-bore IV, restrictive transfusion Hb 7–8 g/dL, ป้องกันสำลักด้วย intubation ถ้าซึมหรือเลือดออกมาก)","Vasoactive drug ทันที: terlipressin, somatostatin หรือ octreotide 50 µg bolus + 50 µg/ชม. 2–5 วัน","Antibiotic prophylaxis: ceftriaxone 1 g/วัน ≤7 วัน (ลด infection, rebleeding, mortality)","EVL ภายใน 12 ชม.; gastric varices (GOV2, IGV1) → cyanoacrylate injection; ควร erythromycin ก่อนส่องกล้องเพื่อให้กระเพาะว่าง","เลือดไม่หยุด: balloon tamponade (Sengstaken-Blakemore) หรือ self-expandable metal stent เป็น bridge → rescue TIPS; pre-emptive TIPS ภายใน 72 ชม. ในกลุ่มเสี่ยงสูง","ป้องกันซ้ำ: NSBB (propranolol, nadolol, carvedilol) + EVL ซ้ำจน varices หาย; ไม่ใช้ TXA และไม่ใช้ FFP แก้ INR","ดูข้อ 726, 768 (46 = portal hypertension; 88 = UGIB จาก Mallory-Weiss tear)"],"notes":"ไฟล์เฉลย บท eso แถว 5: <b>B</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับใช้ตัวพิมพ์เล็ก a. PPI b. Octreotide c. Propranolol (เราเรียงเป็น A–C); \"โรคตับยม ๆ\" = โรคตับระยะท้าย → stem เขียน advanced chronic liver disease; ผู้จดไม่ได้จดรายละเอียดประวัติจริงไว้; ช้อย D, E แต่งเพิ่ม; ข้อนี้อยู่ในบท Esophagus ของต้นฉบับ","mnemonic":"<b>เลือดออกจาก varices = \"VAST\"</b>: Vasoactive, Antibiotic, Sclero/band (EVL ภายใน 12 ชม.), TIPS ถ้าไม่หยุด","guide":"Baveno VII 2022; AASLD portal hypertension guidance 2024","variants":["ผู้ป่วยตับแข็ง Child B อาเจียนเลือดสด BP 90/60 หลังให้สารน้ำและ octreotide แล้ว ควรให้ยาใดอีกเพื่อลด mortality → ceftriaxone 1 g/วัน","ผู้ป่วยตับแข็ง varices ขนาดใหญ่ ไม่เคยมีเลือดออก → NSBB (carvedilol หรือ propranolol) หรือ EVL เพื่อ primary prophylaxis","ผู้ป่วย variceal bleeding ได้ octreotide และ EVL 2 ครั้งแล้วยังอาเจียนเลือดต่อเนื่อง → balloon tamponade เป็น bridge แล้ว rescue TIPS"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง — เป็นข้อเดียวกับข้อสอบชุด 77B และคล้ายชุด 76C เรื่องเดียวกัน; ติด ⚠ เพียงเพราะต้นฉบับอ้างรูปที่ไม่มีในไฟล์","page":21,"page2":7,"orig":"Esophagus 6","stem":"After drinking alcohol at a party, a woman vomited many times and finally vomited blood. Upper endoscopy shows a single longitudinal mucosal laceration at the gastroesophageal junction. What is the diagnosis?","gray":"ให้รูป esophagus ที่มี longitudinal tear มา ให้ประวัติไปปาร์ตี้ ดื่มเหล้า แล้วอ้วกหลายรอบมา สุดท้ายอ้วกเป็นเลือด ถามว่าเป็นไร — A. Mallory weiss tear","opts":["Mallory-Weiss tear","Boerhaave syndrome","Esophageal varices","Reflux esophagitis","Esophageal cancer"],"ans":0,"key":"A Mallory weiss tear (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: ต้นฉบับบอก \"ให้รูป\" แต่ไฟล์ไม่มีรูป — บรรยายผล EGD ใน stem","interp":"ลำดับเหตุการณ์ <b>อาเจียนหลายครั้งก่อน แล้วค่อยอาเจียนเป็นเลือด</b> หลังดื่มเหล้า + EGD พบรอยฉีกตามยาวที่ <b>เยื่อบุ</b> บริเวณ GE junction → แรงดันในกระเพาะเพิ่มฉับพลันขณะ retching ทำให้เยื่อบุฉีก","why":"<b>Mallory-Weiss tear</b> = รอยฉีกตามยาวที่ <b>mucosa/submucosa</b> (ไม่ทะลุทุกชั้น) บริเวณ GE junction มักอยู่ฝั่ง gastric cardia ด้าน lesser curvature จากการ retching/อาเจียนรุนแรง (แอลกอฮอล์ hyperemesis) พบราว 5–15% ของ upper GI bleeding; เลือด <b>หยุดเองราว 80–90%</b> → ดูแลด้วย resuscitation + PPI; ถ้ายังมี active bleeding ขณะส่องกล้อง ทำ <b>endoscopic hemostasis</b> (epinephrine injection ร่วมกับ hemoclip หรือ band ligation); ต่างจาก Boerhaave ที่ทะลุทุกชั้นและมาด้วยเจ็บหน้าอกรุนแรงมากกว่าเลือดออก","wrong":{"B":"Boerhaave syndrome = <b>ทะลุทุกชั้น</b> (transmural) มักที่ left posterolateral distal esophagus หลังอาเจียนรุนแรง มาด้วยเจ็บหน้าอกรุนแรง subcutaneous emphysema (Mackler triad: อาเจียน + เจ็บหน้าอก + ลมใต้ผิวหนัง) sepsis เลือดออกไม่มาก ห้ามส่องกล้องเป็นการตรวจแรก ให้ CT หรือ water-soluble contrast esophagogram; จะถูกถ้าโจทย์ให้เจ็บหน้าอกรุนแรงหลังอาเจียน มี crepitus ที่คอ และ pneumomediastinum","C":"Esophageal varices ทำให้อาเจียนเลือดปริมาณมากในผู้ป่วยตับแข็งหรือ portal hypertension (ดูข้อ 767) ไม่ได้เกิดหลังอาเจียนหลายครั้ง EGD เห็นหลอดเลือดโป่งเป็นเส้นนูน; จะถูกถ้าโจทย์ให้ประวัติดื่มเหล้าเรื้อรังมีท้องมาน ม้ามโต spider nevi แล้วอาเจียนเลือดทันที","D":"Reflux esophagitis ทำให้แสบร้อนกลางอกเรื้อรัง EGD พบ mucosal break หลายรอยที่ distal esophagus (LA classification) เลือดออกมักน้อยและเรื้อรัง; จะถูกถ้าโจทย์เป็นแสบร้อนกลางอกหลังอาหารนานหลายเดือนและ EGD พบ erosion หลายแห่ง","E":"Esophageal cancer มาด้วยกลืนลำบากลุกลามและน้ำหนักลด EGD เห็นก้อนหรือแผลขอบนูน เลือดออกมักเรื้อรัง; จะถูกถ้าโจทย์ให้ชายสูงอายุสูบบุหรี่ดื่มเหล้ากลืนลำบากหลายเดือน"},"trap":"สับสน Mallory-Weiss กับ Boerhaave เพราะเกิดหลังอาเจียนเหมือนกัน — <b>MW = เลือดออก (mucosa ฉีก)</b>; <b>Boerhaave = เจ็บอก ลมรั่ว sepsis (ทะลุทุกชั้น)</b>; และลำดับ \"อาเจียนปกติก่อนแล้วจึงมีเลือด\" ช่วยแยกจาก varices ที่อาเจียนเป็นเลือดตั้งแต่แรก","summary":["Mallory-Weiss: retching รุนแรง → mucosal laceration ตามยาวที่ GE junction (gastric side, lesser curve) → hematemesis หลังอาเจียนหลายครั้ง","ปัจจัยเสี่ยง: binge drinking, hyperemesis gravidarum, hiatal hernia, chemotherapy-induced vomiting","ส่วนใหญ่ (80–90%) หยุดเอง → resuscitation, PPI, antiemetic; active bleeding → epinephrine injection + hemoclip หรือ band ligation; angiographic embolization ถ้าส่องกล้องไม่สำเร็จ","Boerhaave: transmural rupture ที่ left posterolateral distal esophagus, Mackler triad, pneumomediastinum, left pleural effusion → CT/water-soluble esophagogram, NPO, broad-spectrum antibiotics, ผ่าตัดซ่อมภายใน 24 ชม. หรือ stent ตามสภาพ","UGIB ทั่วไป: Glasgow-Blatchford score ≤1 จำหน่ายผู้ป่วยนอกได้; ส่องกล้องภายใน 24 ชม.; Forrest Ia, Ib, IIa, IIb ทำ endoscopic therapy","ดูข้อ 767 (UGIB จาก varices ในผู้ป่วยโรคตับ)"],"notes":"ไฟล์เฉลย บท eso แถว 6: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับเขียน \"<b>ให้รูป</b> esophagus ที่มี longitudinal tear มา\" แต่<b>ในไฟล์ไม่มีรูป</b> — เราบรรยายผล EGD ใน stem (single longitudinal mucosal laceration at the GE junction); ต้นฉบับมีช้อยเดียว \"A. Mallory weiss tear\"; ช้อย B–E แต่งเพิ่ม (ชุดเดียวกับข้อสอบชุด 77B เรื่องเดียวกัน)","mnemonic":"<b>Mallory = Mucosa (เลือด), Boerhaave = Burst (ทะลุ)</b>","guide":"ACG upper GI and ulcer bleeding 2021; ESGE NVUGIH 2021","variants":["ชายอายุ 45 ปี ดื่มเหล้าหนัก อาเจียนรุนแรงแล้วเจ็บหน้าอกด้านซ้ายเฉียบพลัน คลำได้ crepitus ที่คอ CXR พบ pneumomediastinum และ left pleural effusion → Boerhaave syndrome ทำ CT/water-soluble esophagogram","หญิงตั้งครรภ์ 10 สัปดาห์ แพ้ท้องรุนแรง อาเจียนหลายครั้งแล้วมีเลือดสดปน สัญญาณชีพปกติ → Mallory-Weiss tear ส่วนใหญ่หยุดเอง ให้ PPI และ antiemetic","ส่องกล้องพบ Mallory-Weiss tear ที่ยังมีเลือดพุ่ง → epinephrine injection ร่วมกับ hemoclip"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ E มั่นใจสูง — ข้อเดียวกับข้อสอบชุด 77C และสอดคล้องกับชุด 77A เรื่องเดียวกัน (cornea rejection ต่ำสุด)","page":21,"page2":8,"orig":"Transplant 1","stem":"Which organ cannot be transplanted from a living donor?","gray":"Which cannot be transplanted from living donor — A. Lung B. Small bowel C. Pancreas D. Liver E. Cornea","opts":["Lung","Small bowel","Pancreas","Liver","Cornea"],"ans":4,"key":"E Cornea (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ถามอวัยวะหรือเนื้อเยื่อที่ <b>ได้จากผู้บริจาคที่เสียชีวิตแล้วเท่านั้น</b> — อวัยวะที่บริจาคขณะมีชีวิตได้คืออวัยวะที่มีคู่ หรือแบ่งเอาบางส่วนออกได้โดยผู้บริจาคยังมีชีวิตปกติ","why":"<b>Cornea</b> ได้จาก <b>deceased donor เท่านั้น</b> เพราะการเอากระจกตาออกทำให้ผู้บริจาคตาบอด (เก็บดวงตาหรือกระจกตาภายในไม่กี่ชั่วโมงหลังเสียชีวิต และบริจาคได้แม้จากผู้ที่หัวใจหยุดเต้นแล้ว); ส่วนอวัยวะอื่นในช้อยทำ <b>living donation</b> ได้ทั้งหมด: liver (right/left lobe หรือ left lateral segment เพราะตับงอกใหม่ได้), lung (lobar transplant ใช้ผู้บริจาค 2 คนคนละ lobe), pancreas (distal segment) และ small bowel (ileum ยาวราว 150–200 cm); นอกจากนี้ไต (อวัยวะที่บริจาคขณะมีชีวิตบ่อยที่สุด) และมดลูกก็บริจาคขณะมีชีวิตได้","wrong":{"A":"Lung: <b>living donor lobar lung transplantation</b> ทำได้ โดยผู้บริจาค 2 คนให้ lower lobe คนละข้าง (ทำมากในญี่ปุ่น) ใช้ในผู้รับตัวเล็กหรือเด็กที่รอ deceased donor ไม่ทัน; จะเป็นคำตอบถ้าถามอวัยวะที่ต้องใช้ผู้บริจาคมีชีวิต 2 คนต่อผู้รับหนึ่งคน","B":"Small bowel: living donation ทำได้ โดยตัด <b>ileum ส่วนปลายราว 150–200 cm</b> (เก็บ terminal ileum และ ileocecal valve ของผู้บริจาคไว้) แต่ทำน้อย; จะเป็นคำตอบถ้าถามอวัยวะที่ rejection สูงที่สุดเพราะมี lymphoid tissue มาก","C":"Pancreas: living donation ทำได้ด้วย <b>distal pancreatectomy</b> (body และ tail) มักทำร่วมกับไตจากผู้บริจาคคนเดียวกัน แต่เสี่ยงผู้บริจาคเป็นเบาหวานภายหลัง จึงทำน้อย; จะเป็นคำตอบถ้าถาม living donation ที่ทำน้อยที่สุดเพราะผลเสียต่อผู้บริจาค","D":"Liver: <b>living donor liver transplantation</b> ทำได้แพร่หลาย (right lobe ให้ผู้ใหญ่, left lateral segment ให้เด็ก) เพราะตับงอกใหม่ได้ภายในไม่กี่สัปดาห์; เป็นรูปแบบหลักในเกาหลี ญี่ปุ่น และใช้มากในเด็ก; จะเป็นคำตอบถ้าถามอวัยวะที่งอกใหม่หลังบริจาคได้"},"trap":"เลือก lung หรือ pancreas เพราะคิดว่าเป็นอวัยวะที่ \"ขาดไม่ได้\" — ทั้งสองแบ่งบางส่วนบริจาคได้; ข้อเดียวในช้อยที่บริจาคขณะมีชีวิตไม่ได้คือ cornea","summary":["Living donation ได้: kidney (บ่อยที่สุด), liver (lobe หรือ segment), lung lobe (ผู้บริจาค 2 คน), distal pancreas, small bowel segment, uterus","Deceased donation เท่านั้น: heart, cornea, ทั้ง pancreas หรือทั้งปอด, ลิ้นหัวใจ, ผิวหนังในเชิงเนื้อเยื่อ (tissue bank)","Cornea: avascular และ immune privileged → rejection ต่ำที่สุด ไม่ต้อง HLA matching ในผู้รับทั่วไป; เก็บได้จาก deceased donor ที่หัวใจหยุดเต้นแล้ว (ไม่จำเป็นต้องสมองตาย)","Living donor ต้องประเมินความสมัครใจ ไม่มีการซื้อขาย อธิบายความเสี่ยงผู้บริจาค และผ่านคณะกรรมการตามกฎหมายและข้อบังคับของแต่ละประเทศ","Small bowel มี lymphoid tissue มาก → rejection และ graft-versus-host disease สูง; cornea rejection ต่ำสุด","ดูข้อ 770, 771, 772, 774 (transplantation)"],"notes":"ไฟล์เฉลย บท transplant แถว 1: <b>E</b> (ช่องคำอธิบายว่าง)<br>ช้อยต้นฉบับครบ A–E (Lung, Small bowel, Pancreas, Liver, Cornea) ใช้ตรงตามต้นฉบับ; ข้อเดียวกับข้อสอบชุด 77C เรื่องเดียวกัน (ช้อยตรงกันทุกตัว)","mnemonic":"<b>ตาให้ได้ตอนตายเท่านั้น</b>: cornea = deceased only","guide":"Sabiston 21st ed.","variants":["เด็กอายุ 1 ปี เป็น biliary atresia ที่ Kasai ไม่สำเร็จ แม่เลือดกรุ๊ปเดียวกันต้องการบริจาค → living donor liver transplantation ด้วย left lateral segment","อวัยวะปลูกถ่ายชนิดใดมีอัตรา rejection สูงที่สุดเพราะมี lymphoid tissue มาก → small bowel","อวัยวะใดปลูกถ่ายแล้ว rejection ต่ำที่สุดโดยไม่ต้อง HLA matching → cornea"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"ไม่มีคีย์ในไฟล์เฉลย (เขียน \"-\") เราตอบ B ความมั่นใจปานกลาง — A, D, E ผิดชัดเจนตามความรู้ทั่วไป ส่วน B กับ C ต้นฉบับกำกวม: ถ้าอ่าน B ตามตัวอักษรว่า \"แบ่งตับผู้ใหญ่ให้เด็ก 2 คน\" ก็ทำได้ในบางกรณีแต่ไม่ใช่มาตรฐาน ส่วน C ถ้าผู้ออกข้อสอบตั้งใจบริบทไทย (deceased donation ในไทยส่วนใหญ่เป็น DBD) อาจถือว่า C ต้นฉบับ \"Deceased is brain death\" ถูก; เราเกลา B ให้ถูกตามจริงและเกลา C ให้ผิดชัดเพราะมี DCD เพื่อให้เหลือคำตอบเดียว","page":21,"page2":8,"orig":"Transplant 2","stem":"Which statement about liver transplantation is correct?","gray":"ข้อใดถูกเกี่ยวกับ liver transplant — A. ส่วนใหญ่เป็น living donor B. Adult liver can split in 2 for children C. Diceased is brain death D. Warm ischemia better than cold ischemia E. Decrease donor, by definition, means heart stop beating","opts":["Most liver transplants come from living donors","One adult deceased-donor liver can be split into two grafts, one for a child","Every deceased donor must be brain dead","Warm ischemia is tolerated better than cold ischemia","A deceased donor by definition has a heart that has stopped beating"],"ans":1,"key":"ไม่มีเฉลยในไฟล์ (เฉลยโดย Claude) — คีย์เขียน \"-\" (ไม่ได้ให้คำตอบ)","flag":"⚠ ไม่มีคำตอบในไฟล์เฉลย — ช้อย B และ C ต้นฉบับกำกวม: เกลา B ให้ถูกตามจริง (split liver = left lateral segment ให้เด็ก + extended right lobe ให้ผู้ใหญ่) และเกลา C เป็น \"every deceased donor must be brain dead\" ซึ่งผิดเพราะมี DCD","interp":"ข้อแบบ \"ข้อใดถูก\" เรื่องพื้นฐานของ liver transplantation: แหล่งผู้บริจาค (living vs deceased), split liver, ประเภท deceased donor (DBD vs DCD) และ ischemia time","why":"<b>Split liver transplantation</b>: ตับจาก deceased donor ผู้ใหญ่ 1 อันแบ่งเป็น 2 graft ได้ — มาตรฐานคือ <b>left lateral segment (segment II–III) ให้เด็ก</b> และ <b>extended right lobe (segment I, IV–VIII) ให้ผู้ใหญ่</b> (หรือ full right/left split ให้ผู้ใหญ่ 2 คน) ทำให้ใช้ตับ 1 อันรักษาผู้รับได้ 2 คน เพิ่มจำนวน graft โดยเฉพาะเด็กที่หาตับขนาดเหมาะได้ยาก; ช้อยนี้จึงเป็นข้อเดียวที่ถูกตามจริง","wrong":{"A":"ทั่วโลกตับปลูกถ่ายราว <b>80% มาจาก deceased donor</b> (ในอเมริกาและยุโรป living donor เพียงราว 5–10%) — living donor เด่นเฉพาะประเทศที่ deceased donation น้อย เช่นเกาหลี ญี่ปุ่น ฮ่องกง อินเดีย; ในไทยส่วนใหญ่เป็น deceased donor ผ่านศูนย์รับบริจาคอวัยวะสภากาชาดไทย และใช้ living donor มากในเด็ก; จะถูกถ้าโจทย์ถามบริบทของประเทศในเอเชียตะวันออกบางประเทศ","C":"Deceased donor มี 2 ชนิด: <b>DBD</b> (donation after brain death, หัวใจยังเต้น) และ <b>DCD</b> (donation after circulatory death เช่น Maastricht III ที่ถอดเครื่องช่วยหายใจแล้วรอหัวใจหยุด) → \"ทุกรายต้องสมองตาย\" จึงผิด; จะถูกถ้าโจทย์ถามว่าผู้บริจาคชนิด heart-beating ต้องผ่านการวินิจฉัยสมองตาย","D":"<b>Warm ischemia</b> (ช่วงขาดเลือดที่อุณหภูมิร่างกาย) ทำลายตับ <b>รุนแรงกว่า cold ischemia มาก</b> — ตับทน functional warm ischemia ได้ราว 30 นาที ขณะที่ cold storage ใน UW หรือ HTK ทนได้ราว 8–12 ชม.; warm ischemia นานทำให้ primary nonfunction และ <b>ischemic cholangiopathy</b> (โดยเฉพาะ DCD); จะถูกถ้ากลับเป็น \"cold ischemia tolerated better\"","E":"\"By definition หัวใจหยุดเต้น\" ใช้ได้เฉพาะ DCD — DBD หัวใจยังเต้นอยู่ขณะผ่าตัดเก็บอวัยวะ (heart-beating donor) และเป็นแหล่งหลักของ deceased donation; จะถูกถ้าโจทย์ถามนิยามของ DCD"},"trap":"เลือก C เพราะในไทยผู้บริจาคที่เสียชีวิตส่วนใหญ่เป็นสมองตาย — แต่ความจริงทั่วไปมี DCD ด้วย; และอ่านช้อย D สลับกัน — warm ischemia อันตรายกว่า cold ischemia","summary":["แหล่ง graft: deceased donor (DBD, DCD) เป็นหลักทั่วโลก; living donor (right lobe ผู้ใหญ่, left lobe หรือ left lateral segment เด็ก) เด่นในเอเชียตะวันออก","Split liver: ตับผู้ใหญ่ 1 อัน → left lateral segment ให้เด็ก + extended right lobe ให้ผู้ใหญ่ (หรือผู้ใหญ่ 2 คน); reduced-size liver = ตัดตับให้เล็กลงสำหรับผู้รับคนเดียว","DBD = สมองตาย หัวใจยังเต้น; DCD = หัวใจหยุดเต้นแล้วจึงเก็บอวัยวะ (Maastricht III: withdrawal of life support) เสี่ยง ischemic cholangiopathy มากกว่า","Warm ischemia (ตับทนได้ราว 30 นาที) อันตรายกว่า cold ischemia (ทนได้ราว 8–12 ชม. ใน UW หรือ HTK); machine perfusion ช่วยยืดเวลาและประเมิน graft","Graft-to-recipient weight ratio ≥0.8% ใน living donor เพื่อเลี่ยง small-for-size syndrome; ผู้บริจาคต้องเหลือตับราว 30–35% ขึ้นไป","Allocation ใช้ MELD (MELD 3.0) หรือ PELD ในเด็ก; ข้อบ่งชี้หลัก: decompensated cirrhosis, HCC ภายใน Milan criteria, acute liver failure, biliary atresia ในเด็ก","ดูข้อ 769, 771, 774 (transplantation)"],"notes":"ไฟล์เฉลย บท transplant แถว 2: คอลัมน์คำตอบเขียน <b>\"-\"</b> (ไม่ได้ให้คำตอบ, ช่องคำอธิบายว่าง) → เราเฉลยเอง<br>ต้นฉบับสะกด <b>\"Diceased\"</b> (ช้อย C) และ <b>\"Decrease donor\"</b> (ช้อย E) = deceased donor; ช้อย A ต้นฉบับเป็นภาษาไทย \"ส่วนใหญ่เป็น living donor\"; ช้อย B ต้นฉบับ \"Adult liver can split in 2 for children\" กำกวม (อ่านได้ว่าแบ่งให้เด็ก 2 คน) เราเกลาให้ตรงกับความจริงว่าแบ่ง 2 graft โดยหนึ่งใน graft ให้เด็ก; ช้อย C ต้นฉบับ \"Diceased is brain death\" เกลาเป็น \"Every deceased donor must be brain dead\"","mnemonic":"<b>Warm = Worse</b>; deceased มี 2 แบบ <b>B</b>rain (DBD) กับ <b>C</b>irculatory (DCD)","guide":"Sabiston 21st ed.","variants":["ตับจากผู้บริจาคสมองตายอายุ 25 ปี น้ำหนัก 70 kg ขณะที่ในรายชื่อรอมีเด็กอายุ 2 ปีและผู้ใหญ่ 1 คน → split liver: left lateral segment ให้เด็ก และ extended right lobe ให้ผู้ใหญ่","ผู้ป่วยหลังปลูกถ่ายตับจาก DCD มี bile duct stricture หลายตำแหน่งในตับใน 3 เดือน → ischemic cholangiopathy จาก warm ischemia","ผู้ป่วย ICU ที่ไม่เข้าเกณฑ์สมองตาย ญาติตัดสินใจถอดเครื่องช่วยหายใจและประสงค์บริจาคอวัยวะ → donation after circulatory death (Maastricht III)"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง — สอดคล้องกับข้อสอบชุด 76C เรื่องเดียวกัน (donor management หลังสมองตาย)","page":21,"page2":8,"orig":"Transplant 3","stem":"A patient with a severe head injury in the ICU is being considered as a potential deceased organ donor. What is the first and most important step?","gray":"initial step that most important in donor transplant — A. ดูว่าสมองตายจริง B. HLA mismatch","opts":["Confirm brain death by standard criteria","HLA matching","Crossmatch with potential recipients","Call the recipient in for surgery","Proceed directly to organ retrieval"],"ans":0,"key":"A ดูว่าสมองตายจริง (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ผู้ป่วยบาดเจ็บสมองรุนแรงใน ICU อาจเป็น <b>potential deceased donor</b> → ขั้นแรกและสำคัญที่สุดก่อนทุกขั้นตอนของการบริจาคคือยืนยันว่าผู้ป่วยเสียชีวิตแล้วตามกฎหมาย (สมองตาย) ตามเกณฑ์มาตรฐาน","why":"Deceased donation ต้องยึด <b>dead donor rule</b> — ต้อง <b>วินิจฉัยสมองตายให้ถูกต้องตามเกณฑ์ก่อน</b> โดยแพทย์ที่ไม่เกี่ยวข้องกับทีมปลูกถ่าย: (1) prerequisite: รู้สาเหตุที่ทำให้สมองเสียหายถาวร, ตัด confounder ได้แก่ hypothermia, ยากดประสาท/ยาหย่อนกล้ามเนื้อ, metabolic/endocrine disturbance, shock; (2) <b>coma</b> ไม่ตอบสนองต่อสิ่งเร้า; (3) <b>absent brainstem reflexes</b> (pupil, corneal, oculocephalic, oculovestibular, gag, cough); (4) <b>apnea test</b> ไม่หายใจเองเมื่อ PaCO₂ ≥60 mmHg (หรือเพิ่ม ≥20 mmHg จาก baseline ในผู้ที่ CO₂ คั่งเรื้อรัง) — จากนั้นจึงขอความยินยอมจากญาติ, donor management, ตรวจ ABO, HLA, crossmatch และจัดสรรอวัยวะ","wrong":{"B":"HLA matching ทำ <b>หลัง</b> ยืนยันสมองตายและได้รับความยินยอมแล้ว ใช้ในการจัดสรร (สำคัญมากในไต น้อยในตับและหัวใจ); จะถูกถ้าโจทย์ถามปัจจัยที่สัมพันธ์กับ graft survival ของ kidney transplant","C":"Crossmatch ตรวจ preformed antibody ของผู้รับต่อเซลล์ผู้บริจาค ทำก่อนผ่าตัดปลูกถ่ายไตหรือตับอ่อนเพื่อป้องกัน hyperacute rejection แต่ทำหลังกระบวนการยืนยันการเสียชีวิต; จะถูกถ้าโจทย์ถามการตรวจก่อนผ่าตัดปลูกถ่ายไตเพื่อป้องกัน hyperacute rejection","D":"เรียกผู้รับมาผ่าตัดทำหลังจัดสรรอวัยวะและผล crossmatch เข้ากันได้ ถ้าเรียกก่อนยืนยันสมองตายถือว่าผิดลำดับและผิดจริยธรรม; จะถูกเมื่อได้ graft และผล crossmatch ลบแล้ว","E":"เก็บอวัยวะโดยไม่ยืนยันการเสียชีวิตและไม่ได้รับความยินยอมผิดทั้งกฎหมายและจริยธรรม (ละเมิด dead donor rule); การเก็บอวัยวะเป็นขั้นสุดท้ายของกระบวนการ"},"trap":"ตอบ HLA matching เพราะนึกถึงความสำคัญด้าน immunology — แต่คำถามคือ <b>ขั้นแรก</b>ของการเป็นผู้บริจาค ต้องยืนยันการเสียชีวิตก่อน; และทีมปลูกถ่ายต้องไม่เป็นผู้วินิจฉัยสมองตายเอง (conflict of interest)","summary":["ลำดับ deceased donation (DBD): ระบุ potential donor → วินิจฉัยสมองตายตามเกณฑ์ → แจ้งญาติและขอความยินยอม → donor management → ตรวจ ABO, HLA, serology → allocation และ crossmatch → organ retrieval","Prerequisite: สาเหตุชัดและถาวร (head injury, ICH, hypoxic brain injury), ตัด hypothermia, ยา, metabolic, shock","Clinical: coma, absent brainstem reflexes ทั้งหมด, apnea test (PaCO₂ ≥60 mmHg หรือเพิ่ม ≥20 จาก baseline โดยไม่มีการหายใจ)","Ancillary test (cerebral blood flow study, EEG) ใช้เมื่อทำการตรวจทางคลินิกหรือ apnea test ไม่ครบ","Donor management: MAP ≥60–65 mmHg ด้วย fluid และ vasopressor, ระวัง diabetes insipidus (desmopressin), hypothermia, coagulopathy, hormone replacement ตามความจำเป็น","ผู้วินิจฉัยสมองตายต้องไม่ใช่ทีมปลูกถ่าย; ในไทยปฏิบัติตามประกาศแพทยสภาเรื่องเกณฑ์การวินิจฉัยสมองตาย","ดูข้อ 769, 770, 774 (transplantation)"],"notes":"ไฟล์เฉลย บท transplant แถว 3: <b>A</b> (ช่องคำอธิบายว่าง)<br>ช้อยต้นฉบับ A. ดูว่าสมองตายจริง (ภาษาไทย → Confirm brain death by standard criteria), B. HLA mismatch (→ HLA matching); stem เป็นภาษาอังกฤษแบบหัก ๆ \"initial step that most important in donor transplant\" เราทำเป็นเคสสั้น ๆ (ผู้ป่วยบาดเจ็บสมองรุนแรงใน ICU ที่เป็น potential donor); ช้อย C–E แต่งเพิ่ม","mnemonic":"<b>Dead first, donate later</b>: ยืนยันตายก่อน แล้วค่อยขอ ค่อยจับคู่","guide":"AAN/AAP/CNS/SCCM brain death determination 2023","variants":["ผู้ป่วยบาดเจ็บสมอง อุณหภูมิกาย 33 °C ไม่ตอบสนอง ไม่มี brainstem reflex → แก้ hypothermia ก่อนจึงประเมินสมองตาย","ผู้บริจาคสมองตายมีปัสสาวะออก 500 mL/ชม. Na 158 → diabetes insipidus ให้ desmopressin และทดแทนสารน้ำ","แพทย์ทีมปลูกถ่ายไตเสนอจะวินิจฉัยสมองตายเองเพื่อให้รวดเร็ว → ไม่เหมาะสม ผู้วินิจฉัยต้องไม่ใช่ทีมปลูกถ่าย"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง — ถ้าไม่เติม RhD-matched คำตอบที่ถูกยังเป็น alloimmunization เหมือนเดิม (anti-D ก็เป็น alloantibody จากการตั้งครรภ์) แต่จะไม่ใช่ minor antigen เราจึงเติมให้ชัด; ต่างจากข้อสอบชุด 77D เรื่องเดียวกันที่ถามผล lymphocyte crossmatch ในการปลูกถ่ายไต (anti-HLA)","page":21,"page2":8,"orig":"Transplant 4","stem":"A woman who has had multiple pregnancies needs a red cell transfusion. The crossmatch is incompatible with multiple donor units even though they are ABO- and RhD-matched, and HLA compatibility is not the issue. What is the most likely cause?","gray":"multiple pregnancy ต้องรับ blood transfusion แล้วพบ incompatible with multiple donors ,ABO group match, HLA compatible — A. allorecognition (Autoimmunization?) to minor red blood cell antigen","opts":["Alloimmunization to minor red cell antigens","ABO incompatibility","Anti-HLA antibodies against donor leukocytes","IgA deficiency","Bacterial contamination of the units"],"ans":0,"key":"A allorecognition (Autoimmunization?) to minor red blood cell antigen (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","flag":"⚠ เล็กน้อย: เติม RhD-matched ใน stem (anti-D ก็เป็น alloimmunization จากการตั้งครรภ์)","interp":"หญิงตั้งครรภ์หลายครั้ง (ได้รับ RBC ของทารกผ่านรก = sensitization) แล้ว <b>crossmatch ไม่เข้ากับเลือดหลายถุง</b> ทั้งที่ ABO และ RhD ตรงกัน และไม่ใช่ปัญหา HLA → ต้องเป็น antibody ต่อ RBC antigen ระบบอื่นที่ไม่ใช่ ABO/RhD","why":"การตั้งครรภ์ การรับเลือด หรือการปลูกถ่าย ทำให้ร่างกายสัมผัส RBC antigen แปลกปลอม → สร้าง <b>alloantibody ต่อ minor (non-ABO, non-D) red cell antigen</b> เช่น Rh อื่น (anti-E, anti-c), Kell (anti-K), Kidd (anti-Jkᵃ), Duffy (anti-Fyᵃ) → antibody screen ด้วย <b>indirect antiglobulin test</b> เป็นบวก และ crossmatch ไม่เข้ากับเลือดหลายถุงเพราะ antigen เหล่านี้พบบ่อยในประชากร; จัดการด้วย <b>antibody identification</b> แล้วหาเลือดที่ <b>antigen-negative</b> และ crossmatch เข้ากันได้ — ถ้าไม่ตรวจพบอาจเกิด <b>delayed hemolytic transfusion reaction</b> (โดยเฉพาะ Kidd ซึ่ง titer ลดจนตรวจไม่พบแล้วเพิ่มขึ้นใหม่หลังได้รับเลือด)","wrong":{"B":"ABO incompatibility ถูกตัดตั้งแต่โจทย์บอกว่าหมู่เลือด ABO ตรงกัน; ถ้าเกิดจริงจะมี acute intravascular hemolysis รุนแรงเกือบทันที (ไข้ หนาวสั่น ปวดหลัง hemoglobinuria DIC) ซึ่งมักเกิดจากความผิดพลาดในการระบุตัวผู้ป่วย; จะถูกถ้าโจทย์เป็นการให้เลือดผิดคนแล้วมีอาการภายในไม่กี่นาที","C":"Anti-HLA จากการตั้งครรภ์ทำให้ <b>platelet refractoriness</b>, febrile non-hemolytic transfusion reaction และ positive <b>lymphocyte</b> crossmatch ในการปลูกถ่ายอวัยวะ (ข้อสอบชุด 77D เรื่องเดียวกัน) แต่ RBC แทบไม่มี HLA antigen จึงไม่ทำให้ RBC crossmatch ไม่เข้ากัน; anti-HLA/HNA ใน plasma ของผู้บริจาคหญิงที่ตั้งครรภ์หลายครั้งยังเป็นสาเหตุ TRALI; จะถูกถ้าโจทย์เป็นเกล็ดเลือดไม่ขึ้นหลังรับเกล็ดเลือดหลายครั้ง","D":"IgA deficiency ที่มี anti-IgA ทำให้ <b>anaphylaxis</b> ทันทีหลังเริ่มให้เลือด (ไม่มีไข้ ความดันตก หายใจลำบาก) ไม่ทำให้ crossmatch ไม่เข้ากัน → ให้ washed RBC หรือเลือดจากผู้บริจาคที่ขาด IgA; จะถูกถ้าโจทย์เป็น anaphylaxis ภายในไม่กี่นาทีแรกของการให้เลือด","E":"Bacterial contamination (พบบ่อยใน platelet ที่เก็บอุณหภูมิห้อง) ทำให้ไข้สูง หนาวสั่น shock ระหว่างหรือหลังให้เลือด ไม่เกี่ยวกับ crossmatch; จะถูกถ้าโจทย์เป็นไข้สูงและความดันตกขณะรับเกล็ดเลือด"},"trap":"เลือก anti-HLA เพราะรู้ว่าการตั้งครรภ์หลายครั้งกระตุ้น HLA sensitization — ถูกในบริบท <b>ปลูกถ่ายอวัยวะ/เกล็ดเลือด</b> แต่ RBC crossmatch ขึ้นกับ RBC antigen; และอย่าสับสน alloimmunization (ต่อ antigen คนอื่น) กับ autoimmunization (ต่อ antigen ตนเอง ซึ่งจะ DAT บวกและ panel บวกทุกตัว)","summary":["Sensitization ต่อ RBC antigen: ตั้งครรภ์, รับเลือดบ่อย (thalassemia, sickle cell), ปลูกถ่าย","Pretransfusion testing: ABO/RhD typing + antibody screen (IAT) + crossmatch (immediate spin หรือ antiglobulin crossmatch เมื่อ screen บวก)","Clinically significant alloantibodies: Rh (D, E, c, C, e), Kell, Kidd, Duffy, Ss — ต้องให้ antigen-negative blood; Kidd สัมพันธ์ delayed hemolytic transfusion reaction","Anti-HLA: platelet refractoriness (ให้ HLA-matched platelet), FNHTR (ลดด้วย leukoreduction), positive lymphocyte crossmatch ในการปลูกถ่าย","Autoantibody (warm AIHA): DAT บวก, panel บวกทุกเซลล์รวม autocontrol — ต่างจาก alloantibody ที่ autocontrol ลบ","IgA deficiency + anti-IgA → anaphylaxis → washed products; TRALI สัมพันธ์ anti-HLA/HNA ใน plasma ของผู้บริจาคหญิงที่ตั้งครรภ์หลายครั้ง","ดูข้อ 686, 687, 688, 689, 773 (hemostasis และ transfusion)"],"notes":"ไฟล์เฉลย บท transplant แถว 4: <b>A</b> (ช่องคำอธิบายว่าง)<br>ช้อยต้นฉบับมีช้อยเดียว \"A. allorecognition <b>(Autoimmunization?)</b> to minor red blood cell antigen\" — วงเล็บ \"(Autoimmunization?)\" เป็นโน้ตสงสัยของผู้จดเอง; คำที่ถูกคือ <b>alloimmunization</b> (ไม่ใช่ autoimmunization) ช้อยของเราจึงเขียน \"Alloimmunization to minor red cell antigens\" โดยไม่มีวงเล็บ; stem ต้นฉบับ \"multiple pregnancy ต้องรับ blood transfusion แล้วพบ incompatible with multiple donors, ABO group match, HLA compatible\" — เราเติม RhD-matched ให้ตัด anti-D ออก; ช้อย B–E แต่งเพิ่ม; ข้อนี้อยู่ในบท Transplantation + Immunology ของต้นฉบับ","mnemonic":"<b>Kidd ทำร้ายทีหลัง (delayed)</b>; HLA → เกล็ดเลือดและอวัยวะ, minor RBC antigen → RBC crossmatch","guide":"AABB Technical Manual 21st ed. 2023","variants":["ผู้ป่วย thalassemia รับเลือดทุกเดือน ครั้งนี้ crossmatch ไม่เข้ากับเลือดหลายถุง antibody identification พบ anti-E และ anti-c → ให้เลือดที่ E และ c negative","หญิงหลังรับเลือด 7 วัน มีไข้ ตัวเหลือง Hb ลดลง DAT บวก → delayed hemolytic transfusion reaction (มักจาก anti-Jkᵃ)","ผู้ป่วย AML รับเกล็ดเลือดหลายครั้งแล้ว corrected count increment ต่ำซ้ำ ๆ → alloimmune platelet refractoriness จาก anti-HLA ให้ HLA-matched platelet"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง","page":22,"page2":8,"orig":"Transplant 5","stem":"A bleeding patient needs emergency red cell transfusion before his blood group is known. Which red cells are safest?","gray":"rbc transfusion ไม่ทราบหมู่เลือด ให้อันไหนปลอดภัยสุด — A. o negative B. Ab positive C. Positive","opts":["Group O RhD-negative red cells","Group AB RhD-positive red cells","Group A RhD-positive red cells","Group B RhD-negative red cells","Group AB RhD-negative red cells"],"ans":0,"key":"A o negative (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ต้องให้ RBC ฉุกเฉินโดย <b>ยังไม่รู้หมู่เลือดผู้ป่วย</b> → เลือก RBC ที่ไม่มี antigen ซึ่งจะถูก antibody ที่มีอยู่แล้วในผู้รับทำลาย (anti-A, anti-B) และไม่กระตุ้น anti-D = universal donor RBC","why":"<b>Group O RBC</b> ไม่มี A และ B antigen บนผิวเซลล์ จึงไม่ถูก anti-A/anti-B ตามธรรมชาติในผู้รับทุกหมู่ทำลาย (ไม่เกิด acute hemolytic reaction จาก ABO) = <b>universal donor ของ RBC</b>; เลือก <b>RhD-negative</b> เพื่อไม่ให้ผู้รับที่เป็น RhD-negative สร้าง anti-D ซึ่งสำคัญที่สุดใน <b>หญิงวัยเจริญพันธุ์</b> (ป้องกัน hemolytic disease of the fetus and newborn ในครรภ์ต่อไป) → O RhD-negative จึงปลอดภัยที่สุดเมื่อไม่ทราบหมู่เลือด; ควรเก็บตัวอย่างเลือดส่ง group และ crossmatch <b>ก่อน</b>เริ่มให้ แล้วเปลี่ยนเป็น type-specific เลือดโดยเร็ว","wrong":{"B":"AB RBC มีทั้ง A และ B antigen → ผู้รับหมู่ O, A, B ซึ่งมี anti-A หรือ anti-B จะทำลายเซลล์จนเกิด acute hemolytic reaction; AB เป็น <b>universal recipient</b> ของ RBC และ <b>universal donor ของ plasma</b>; จะถูกถ้าโจทย์ถาม plasma ที่ให้ได้เมื่อไม่ทราบหมู่เลือด","C":"A RBC มี A antigen → ผู้รับหมู่ O และ B มี anti-A ทำลายเซลล์ได้; RhD-positive ยังเสี่ยง anti-D ในผู้รับ RhD-negative; จะถูกถ้าผู้ป่วยทราบแล้วว่าเป็นหมู่ A RhD-positive (type-specific)","D":"B RBC มี B antigen → ผู้รับหมู่ O และ A มี anti-B ทำลายเซลล์ได้ แม้เป็น RhD-negative ก็ไม่ปลอดภัยเมื่อไม่ทราบหมู่ ABO; จะถูกถ้าผู้ป่วยทราบแล้วว่าเป็นหมู่ B RhD-negative","E":"AB RhD-negative ยังมีทั้ง A และ B antigen จึงเกิด ABO hemolysis ได้ในผู้รับหมู่ O, A, B เช่นเดียวกับ AB positive; จะถูกเพียงในผู้รับที่ทราบแล้วว่าเป็นหมู่ AB RhD-negative"},"trap":"สับสนว่า AB เป็น universal donor — <b>AB = universal recipient ของ RBC แต่ universal donor ของ plasma</b>; O กลับกัน (O RBC ให้ได้ทุกคน, O plasma มี anti-A และ anti-B); และ O RhD-positive ใช้ได้ในชายหรือหญิงหมดประจำเดือนเมื่อ O negative ขาด","summary":["Universal donor RBC = group O (ไม่มี A, B antigen); RhD-negative สำคัญในหญิงวัยเจริญพันธุ์และเด็กหญิงเพื่อป้องกัน anti-D และ HDFN","ชายและหญิงหลังหมดประจำเดือนใช้ O RhD-positive ได้เมื่อ O RhD-negative ขาด (RhD-negative พบน้อยมากในคนไทย &lt;1%)","Universal donor plasma = group AB (ไม่มี anti-A, anti-B); บางระบบใช้ low-titer group A plasma ในภาวะฉุกเฉิน","ลำดับในภาวะฉุกเฉิน: emergency release O RBC → type-specific (ABO/RhD ตรง ราว 10–15 นาที) → fully crossmatched (ราว 45–60 นาที)","เก็บตัวอย่างเลือดส่ง group และ crossmatch ก่อนให้เลือด uncrossmatched เสมอ","Massive transfusion protocol: RBC : plasma : platelet ประมาณ 1:1:1 + TXA ใน trauma ภายใน 3 ชม., แก้ hypothermia, hypocalcemia, acidosis","ดูข้อ 688, 772, 686, 687, 689 (8 = resuscitation ด้วยเลือด; 92 = alloimmunization)"],"notes":"ไฟล์เฉลย บท transplant แถว 5: <b>A</b> (ช่องคำอธิบายว่าง)<br>ช้อยต้นฉบับ A. o negative (ตัวพิมพ์เล็ก), B. Ab positive (= AB positive), C. <b>\"Positive\"</b> (ผู้จดเขียนแค่ Positive ไม่ได้บอกหมู่ ABO) → เราเขียน Group A RhD-positive red cells; ช้อย D, E แต่งเพิ่ม; ข้อนี้อยู่ในบท Transplantation + Immunology ของต้นฉบับ","mnemonic":"<b>O ให้ทุกคน (RBC), AB รับทุกคน (RBC) แต่ AB ให้ plasma ทุกคน</b>","guide":"ATLS 10th ed.; AABB Technical Manual 21st ed. 2023","variants":["หญิงอายุ 25 ปี อุบัติเหตุรถจักรยานยนต์ shock class III ยังไม่ทราบหมู่เลือด → O RhD-negative RBC (ป้องกัน anti-D ในหญิงวัยเจริญพันธุ์)","ผู้ป่วยต้องการ plasma ฉุกเฉินโดยยังไม่ทราบหมู่เลือด → AB plasma","ชายอายุ 60 ปี เลือดออกมาก O RhD-negative ในคลังหมด → O RhD-positive RBC ใช้ได้"]},
  {"set":"MDCU78","ro":"RoC","file":"78CQ","kfile":"78CK","opinion":"เห็นด้วยกับคีย์ A มั่นใจสูง — สอดคล้องกับข้อสอบชุด 77B เรื่องเดียวกัน (eGFR 18 → ประเมินปลูกถ่ายไต) และชุด 77A (DM1 + ESRD → SPK)","page":22,"page2":8,"orig":"Transplant 6","stem":"A man with type 1 diabetes has diabetic nephropathy. When is kidney transplantation indicated?","gray":"คนไข้ DM1 จะทำ Kidney transplant เมื่อไหร่ — A. ESRD B. (ว่าง)","opts":["When he reaches end-stage renal disease","As soon as diabetes is diagnosed","When microalbuminuria first appears","When HbA1c exceeds 9%","When diabetic retinopathy is detected"],"ans":0,"key":"A ESRD (คีย์ในไฟล์ Key MCQ 78 RoC by MDCU78)","interp":"ถามข้อบ่งชี้ของ <b>kidney transplantation</b> ในผู้ป่วยเบาหวานชนิดที่ 1 ที่มี diabetic nephropathy — ข้อบ่งชี้ขึ้นกับ <b>ระดับการทำงานของไต</b> ไม่ใช่ตัวโรคเบาหวานหรือ complication อื่น","why":"Kidney transplantation เป็น renal replacement therapy ที่ดีที่สุดสำหรับ <b>ESRD (CKD G5, eGFR &lt;15)</b> หรือใกล้ ESRD — survival และคุณภาพชีวิตดีกว่า dialysis; KDIGO 2020 แนะนำให้ <b>ส่งประเมินเพื่อปลูกถ่ายเมื่อ eGFR &lt;30</b> (อย่างน้อย 6–12 เดือนก่อนคาดว่าจะต้อง dialysis) และทำ <b>preemptive living donor transplant</b> ได้เมื่อ <b>eGFR &lt;20</b> ที่แย่ลงต่อเนื่อง; ใน <b>DM1 + ESRD</b> ทางเลือกที่ดีที่สุดคือ <b>simultaneous pancreas–kidney transplant (SPK)</b> ซึ่งแก้ทั้งไตวายและเบาหวาน หรือ pancreas after kidney (PAK) หลังได้ไตจาก living donor","wrong":{"B":"การวินิจฉัยเบาหวานไม่ใช่ข้อบ่งชี้ปลูกถ่ายไต เพราะไตยังทำงานปกติ ความเสี่ยงจากการผ่าตัดและ immunosuppression มากกว่าประโยชน์; จะถูกถ้าถามข้อบ่งชี้ของ pancreas transplant alone ใน DM1 ที่มี hypoglycemia unawareness รุนแรงซ้ำ ๆ (ไม่ใช่ปลูกถ่ายไต)","C":"Microalbuminuria (albuminuria 30–300 mg/g) เป็นระยะแรกของ diabetic kidney disease → รักษาด้วยคุมน้ำตาล คุม BP, ACEI/ARB, SGLT2 inhibitor (ใน DM2) เพื่อชะลอการเสื่อม ไม่ใช่ปลูกถ่าย; จะถูกถ้าโจทย์ถามจุดเริ่ม ACEI/ARB","D":"HbA1c สูงบ่งการคุมน้ำตาลไม่ดี → ปรับ insulin, ใช้ CGM หรือ insulin pump ไม่ใช่ข้อบ่งชี้ปลูกถ่ายไต; จะถูกถ้าโจทย์ถามการปรับการรักษาเบาหวาน","E":"Diabetic retinopathy เป็น microvascular complication ที่มักมาพร้อม nephropathy แต่ไม่ใช่ข้อบ่งชี้ปลูกถ่ายไต รักษาด้วย laser หรือ anti-VEGF; จะถูกถ้าโจทย์ถามการส่งพบจักษุแพทย์"},"trap":"คิดว่าต้องรอจนเริ่ม dialysis แล้วจึงปลูกถ่าย — <b>preemptive transplant</b> (ก่อนต้อง dialysis) ได้ผลดีที่สุด จึงควรส่งประเมินตั้งแต่ eGFR &lt;30; และใน DM1 อย่าลืมว่า SPK ดีกว่าปลูกถ่ายไตอย่างเดียว","summary":["ข้อบ่งชี้ kidney transplant: ESRD (CKD G5) หรือ CKD ระยะท้ายที่คาดว่าจะต้อง dialysis; ส่งประเมินเมื่อ eGFR &lt;30","Preemptive living donor transplant ได้เมื่อ eGFR &lt;20 และแย่ลงต่อเนื่องใน 6–12 เดือน (KDIGO 2020) — ผลดีกว่าการเริ่ม dialysis ก่อน","DM1 + ESRD: <b>SPK</b> ดีที่สุด (กำจัดความต้องการ insulin ป้องกัน recurrent nephropathy ใน graft); PAK หลังได้ไตจาก living donor","Pancreas transplant alone: DM1 ที่ไตยังดีแต่มี hypoglycemia unawareness รุนแรงหรือคุมน้ำตาลไม่ได้แม้รักษาเต็มที่","ข้อห้ามสำคัญ: มะเร็งที่ยังไม่หาย, การติดเชื้อที่ยังไม่ได้รักษา, โรคหัวใจรุนแรงที่แก้ไขไม่ได้, ไม่ร่วมมือการรักษา, อายุขัยสั้น","ก่อนปลูกถ่ายต้องประเมิน cardiovascular disease โดยเฉพาะผู้ป่วยเบาหวาน (coronary disease ที่ไม่มีอาการพบบ่อย)","ดูข้อ 769, 770, 771 (transplantation)"],"notes":"ไฟล์เฉลย บท transplant แถว 6: <b>A</b> (ช่องคำอธิบายว่าง)<br>ต้นฉบับมีช้อย A. ESRD และ <b>ช้อย B ว่าง</b> (ผู้จดเขียน \"B.\" แต่ไม่ได้เติม); stem ต้นฉบับ \"คนไข้ DM1 จะทำ Kidney transplant เมื่อไหร่\" — เราเติม \"has diabetic nephropathy\"; ช้อย B–E แต่งเพิ่ม","mnemonic":"<b>ส่งตอน 30 ผ่าตอน 20 (preemptive) ช้าสุดที่ 15</b>; DM1 = ไตกับตับอ่อนไปด้วยกัน (SPK)","guide":"KDIGO transplant candidate 2020","variants":["ชายเบาหวานชนิดที่ 1 อายุ 35 ปี eGFR 18 ลดลงต่อเนื่อง ยังไม่ dialysis มีพี่ชายพร้อมบริจาคไต → preemptive living donor kidney transplant (หรือพิจารณา PAK ภายหลัง)","หญิง DM1 อายุ 30 ปี ESRD กำลังทำ hemodialysis ไม่มี living donor → simultaneous pancreas–kidney transplant จาก deceased donor","ผู้ป่วย DM1 ไตปกติ มี hypoglycemia unawareness หมดสติซ้ำหลายครั้งแม้ใช้ CGM และ insulin pump → พิจารณา pancreas transplant alone หรือ islet transplantation"]}
);
